function setTemporalRange(from, to) {
  appState.filters.temporal.dateFrom = from;
  appState.filters.temporal.dateTo = to;
}

function clearChipFilters() {
  Object.values(appState.filters.chips).forEach(entry => {
    entry.included.clear();
    entry.excluded.clear();
    entry.includedFromPreset?.clear();
    entry.excludedFromPreset?.clear();
    entry.mode = 'neutral';
  });
  Object.values(appState.filters.comboFilters || {}).forEach(entry => {
    entry.included.clear();
    entry.excluded.clear();
  });
  // Reset customChips slots (sub-task 5). matchMode preserved — it's a display
  // preference (any/all toggle position), not a filter value.
  for (const key of Object.keys(appState.filters.customChips || {})) {
    const entry = appState.filters.customChips[key];
    if (!entry) continue;
    entry.mode = 'neutral';
    entry.included.clear();
    entry.excluded.clear();
    entry.includedFromPreset?.clear();
    entry.excludedFromPreset?.clear();
  }
  // Sync mode buttons for all keys after clearing
  Object.keys(appState.filters.chips).forEach(key => _syncChipModeButtons(key));
}

// Compute which mode buttons should be visually active for a chip filter group.
// Mirrors the preset tune panel rules:
//   - NEUTRE active ⟺ both Sets empty AND mode === 'neutral'
//   - INCLUDE active ⟺ included.size > 0  OR  mode === 'include'
//   - EXCLUDE active ⟺ excluded.size > 0  OR  mode === 'exclude'
// Resolves a filter key to its state entry. Native keys land in
// appState.filters.chips; the 'custom:<key>' namespace (sub-task 3)
// routes to appState.filters.customChips[<key>]. Returns null when
// the entry has not been initialized yet — callers must guard.
function _resolveChipEntry(filterKey) {
  if (typeof filterKey === 'string' && filterKey.startsWith('custom:')) {
    const k = filterKey.slice(7);
    return appState.filters.customChips?.[k] ?? null;
  }
  return appState.filters.chips[filterKey] ?? null;
}

function _chipModeFlags(filterKey) {
  const entry = _resolveChipEntry(filterKey);
  if (!entry) return { neutral: true, include: false, exclude: false };
  const bothEmpty = entry.included.size === 0 && entry.excluded.size === 0;
  return {
    neutral: bothEmpty && entry.mode === 'neutral',
    include: entry.included.size > 0 || entry.mode === 'include',
    exclude: entry.excluded.size > 0 || entry.mode === 'exclude',
  };
}

// Update the 3 mode buttons (NEUTRE / EXCLURE / INCLURE) for a given filter key.
function _syncChipModeButtons(filterKey) {
  const flags = _chipModeFlags(filterKey);
  document.querySelectorAll(`.chip-mode-btn[data-key="${filterKey}"]`).forEach(btn => {
    btn.classList.toggle('active', !!flags[btn.dataset.mode]);
  });
}

// Per-key click-mode setter. Independent for each filter group.
// Used by the [Neutral / Exclude / Include] buttons in the sidebar.
function setChipMode(filterKey, mode) {
  if (mode !== 'neutral' && mode !== 'include' && mode !== 'exclude') return;
  const entry = _resolveChipEntry(filterKey);
  if (!entry) return;
  _ensureFromPresetSets(entry);
  if (mode === 'neutral') {
    // NEUTRE = destructive reset of this group's filter (live + preset).
    invalidateFilterCache();
    entry.included.clear();
    entry.excluded.clear();
    entry.includedFromPreset.clear();
    entry.excludedFromPreset.clear();
    entry.mode = 'neutral';
    _syncChipModeButtons(filterKey);
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    // Dim was wiped → tune panel mirrors it.
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
    return;
  }
  // include / exclude → just set click-mode for this group, non-destructive
  entry.mode = mode;
  _lastChipMode = mode; // propagate to future neutral groups
  _syncChipModeButtons(filterKey);
  // Mode change shows up in the po-mode-row of the tune panel — re-render.
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
}

function resetExclusionState(nextState = {}) {
  appState.filters.exclusions.m15Exclude = [...(nextState.m15Exclude || [])];
  appState.filters.exclusions.h4Exclude = [...(nextState.h4Exclude || [])];
  appState.filters.exclusions.sessionExclude = [...(nextState.sessionExclude || [])];
  appState.filters.exclusions.dayExclude = [...(nextState.dayExclude || [])];
}

