// Mutable runtime preset list — loaded from localStorage if persisted, else seeded
// from DEFAULT_PRESETS. CRUD operations (create/rename/delete) mutate this array
// and persist via savePresetsList().
let PRESETS = DEFAULT_PRESETS.map(p => ({ ...p }));

function loadPresetsList() {
  try {
    const raw = localStorage.getItem(PRESET_LS_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed) || !parsed.length) return;
    // Validate every entry has at least an id + label
    PRESETS = parsed
      .filter(p => p && typeof p.id === 'number' && typeof p.label === 'string')
      .map(p => ({ ...p, description: p.description || '' }));
    // Legacy migration: assign order = sorted-by-id index for presets without
    // an order field. Preserves the existing visual order for upgraders.
    const needsMigration = PRESETS.some(p => typeof p.order !== 'number');
    if (needsMigration) {
      const sortedById = [...PRESETS].sort((a, b) => a.id - b.id);
      sortedById.forEach((p, idx) => { p.order = idx; });
    }
    PRESETS.sort((a, b) => a.order - b.order);
  } catch(e) { console.warn('[presets] load failed:', e.message); }
}

function savePresetsList() {
  try { localStorage.setItem(PRESET_LS_KEY, JSON.stringify(PRESETS)); } catch(e) {}
}

// Return max(existing id) + 1 — ids are stable and never recycled, so all
// LS-keyed state (snapshots, overrides, live filters) stays coherent even
// after a preset is deleted. The PRESET_MAX cap applies to the number of
// active presets, not to the id space.
function _nextPresetId() {
  if (PRESETS.length >= PRESET_MAX) return -1;
  const maxId = PRESETS.reduce((m, p) => Math.max(m, p.id), -1);
  return maxId + 1;
}

/** Visual display number for a preset id: contiguous P0, P1, P2... based on
 *  the preset's position in the sorted PRESETS array. Decouples the label the
 *  user sees from the internal id — internal ids stay stable (all persisted
 *  state in presetSnapshots / presetOverrides / presetLiveFilters is keyed on
 *  id), but the sidebar numbering stays gapless after a deletion. */
function _getPresetDisplayNum(id) {
  const sorted = [...PRESETS].sort((a, b) => {
    const oa = typeof a.order === 'number' ? a.order : a.id;
    const ob = typeof b.order === 'number' ? b.order : b.id;
    return oa - ob;
  });
  const idx = sorted.findIndex(p => p.id === id);
  return idx === -1 ? id : idx;
}

// Backwards-compat shim (tests/legacy code may still reference PRESET_DESCRIPTIONS).
const PRESET_DESCRIPTIONS = new Proxy({}, {
  get(_, key) {
    const id = parseInt(key, 10);
    if (Number.isNaN(id)) return '';
    return PRESETS.find(p => p.id === id)?.description || '';
  },
});
const MOBILE_PRESET_IDS = [null, 1, 2, 3, 4, 5];
