// ══════════════════════════════════════════════════════
// TRADE TABLE
// ══════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════
// TABLE SORT STATE
// ══════════════════════════════════════════════════════
let tableSort = { col: 'date', dir: 'desc' };

function setSort(col, dir) {
  tableSort = { col, dir };
  updateSortButtons();
  const filtered = getFiltered();
  renderTable(filtered);
}

function cycleSortCol(col) {
  if (tableSort.col === col) {
    tableSort.dir = tableSort.dir === 'asc' ? 'desc' : 'asc';
  } else {
    tableSort.col = col;
    tableSort.dir = col === 'r' ? 'desc' : 'asc';
  }
  updateSortButtons();
  const filtered = getFiltered();
  renderTable(filtered);
}

function updateSortButtons() {
  const { col, dir } = tableSort;
  // Reset all buttons
  document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
  const id = `sort-${col}-${dir}`;
  const el = document.getElementById(id);
  if (el) el.classList.add('active');
  // Update column header arrows
  const cols = ['date','pair','outcome','r'];
  cols.forEach(c => {
    const arrow = document.getElementById('tharr-' + c);
    const th = arrow?.parentElement;
    if (!arrow) return;
    if (tableSort.col === c) {
      arrow.textContent = tableSort.dir === 'asc' ? ' ↑' : ' ↓';
      th?.classList.add('sort-active');
    } else {
      arrow.textContent = '';
      th?.classList.remove('sort-active');
    }
  });
}

// ══════════════════════════════════════════════════════
// TRADE TABLE RENDERER
// ══════════════════════════════════════════════════════
function renderTable(trades) {
  const tbody = document.getElementById('trade-tbody');
  if (!tbody) return;
  _setText('trade-count', trades.length + ' trades');

  if (!trades.length) {
    tbody.innerHTML = `<tr><td colspan="10" style="padding:0">
      <div class="widget-empty-state">
        <div class="widget-empty-state-icon">∅</div>
        <div>${EMPTY_STATE_MSG}</div>
      </div>
    </td></tr>`;
    return;
  }

  const _tlPairSz    = tc('--typo-tl-pair-size');
  const _tlSetupSz   = tc('--typo-tl-setup-size');
  const _tlSessionSz = tc('--typo-tl-session-size');
  const _tlDaySz     = tc('--typo-tl-day-size');
  const _tlObsSz     = tc('--typo-tl-obs-size');

  // Sort
  const { col, dir } = tableSort;
  const sorted = [...trades].sort((a, b) => {
    let va = a[col], vb = b[col];
    if (col === 'date') { va = va || ''; vb = vb || ''; }
    if (col === 'pair' || col === 'outcome') { va = (va || '').toLowerCase(); vb = (vb || '').toLowerCase(); }
    if (col === 'r') { va = Number(va) || 0; vb = Number(vb) || 0; }
    if (va < vb) return dir === 'asc' ? -1 : 1;
    if (va > vb) return dir === 'asc' ? 1 : -1;
    if (col === 'date') {
      const h = (a.hour ?? 99) - (b.hour ?? 99);
      if (h !== 0) return h;
      const aIsLoss = isLoser(a);
      const bIsLoss = isLoser(b);
      if (aIsLoss && !bIsLoss) return dir === 'asc' ? -1 : 1;
      if (!aIsLoss && bIsLoss) return dir === 'asc' ?  1 : -1;
    }
    return 0;
  });

  const ocClass = { TP: 'oc-tp', SL: 'oc-sl', 'BE-TP': 'oc-betp', 'BE-SL': 'oc-besl' };
  const rowBg = { 'TP': getWinColorAlpha(.25), 'SL': getLossColorAlpha(.27), 'BE-TP': 'rgba(41,98,255,.22)', 'BE-SL': 'rgba(180,120,240,.22)' };
  const createTradeMediaButton = (url, step, emoji, title, meta) => url
    ? `<button class="trade-media-btn" data-action="open-img-lightbox"
         data-scope="#trade-tbody"
         data-img-url="${url}" data-img-step="${step}"
         data-trade-pair="${meta.safePair}" data-trade-date="${meta.safeDate}"
         data-trade-h4before="${meta.safeH4b}" data-trade-m15before="${meta.safeM15b}" data-trade-m15after="${meta.safeM15a}"
         data-trade-h4before-orig="${meta.safeH4bOrig}" data-trade-m15before-orig="${meta.safeM15bOrig}" data-trade-m15after-orig="${meta.safeM15aOrig}"
         title="${title}">${emoji}</button>`
    : '';
  const createTradeDaySeparatorRow = dateLabel => `<tr class="tt-day-sep"><td colspan="10">${dateLabel}</td></tr>`;
  const createTradeTableRow = t => {
    const dir = t.direction || '';
    const dirCol = dir === 'Achat' ? 'var(--g)' : dir === 'Vente' ? 'var(--r)' : 'var(--dim)';
    const dirHtml = dir
      ? `<span style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,9px);font-weight:700;letter-spacing:.5px;color:${dirCol}">${dir.toUpperCase()}</span>`
      : '<span style="color:var(--dim)">—</span>';
    const meta = {
      safePair: (t.pair || '').replace(/"/g, '&quot;'),
      safeDate: (t.date || '').replace(/"/g, '&quot;'),
      safeH4b: (t.imgH4Before || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
      safeM15b: (t.imgM15 || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
      safeM15a: (t.imgM15After || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
      safeH4bOrig:  (t.imgH4BeforeOrig || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
      safeM15bOrig: (t.imgM15Orig      || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
      safeM15aOrig: (t.imgM15AfterOrig || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;'),
    };
    const imgBtns = `<div class="trade-media-group">
      ${createTradeMediaButton(meta.safeH4b, 'h4Before', '📷', 'H4 Before', meta)}
      ${createTradeMediaButton(meta.safeM15b, 'm15Before', '📷', 'M15 Before', meta)}
      ${createTradeMediaButton(meta.safeM15a, 'm15After', '📸', 'M15 After', meta)}
    </div>`;
    const notionUrl = (t.notionUrl || '').trim();
    const notionBtn = notionUrl
      ? `<button class="trade-media-btn trade-link-btn" data-action="open-notion-overlay" data-notion-url="${notionUrl.replace(/"/g, '&quot;')}" title="Open in Notion">🔗</button>`
      : '';
    const _rEff = t.effectiveR ?? computeEffectiveRR(t, appState.ui.tpConfig);
    return `
    <tr class="tt-trade-row" style="background:${rowBg[t.outcome] || ''};cursor:pointer"
        data-action="open-tradelog-drawer"
        data-trade-date="${meta.safeDate}"
        data-trade-pair="${meta.safePair}"
        data-trade-hour="${t.hour ?? ''}"
        data-trade-r="${t.r /* KEEP raw trade.r — identity matching for click-to-locate. Must NOT use computeEffectiveRR (weighted value would break the lookup). */}"
        title="Open day in drawer">
      <td class="mono">${t.date || '—'}</td>
      <td><div style="display:flex;align-items:center;gap:4px">${notionBtn}<strong style="color:var(--white);font-size:${_tlPairSz}">${t.pair}</strong></div></td>
      <td class="${ocClass[t.outcome] || ''}" style="font-weight:600">${t.outcome}</td>
      <td class="r" style="color:${_rEff > 0 ? 'var(--g)' : _rEff < 0 ? 'var(--r)' : 'var(--gold)'};font-weight:600">${_rEff > 0 ? '+' : ''}${_rEff.toFixed(1)}R</td>
      <td>${dirHtml}</td>
      <td style="font-size:${_tlSetupSz};color:var(--body)">${SETUP_SHORT[t.setup] || t.setup || '—'}</td>
      <td style="font-size:${_tlSessionSz};color:var(--body)">${SESSION_SHORT[t.session] || t.session || '—'}</td>
      <td style="font-size:${_tlDaySz};color:var(--body)">${DAY_EN[t.day] || t.day || '—'}</td>
      <td style="font-size:${_tlObsSz};color:var(--body);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${(t.obstacles || []).join(', ')}">${(t.obstacles || []).slice(0, 2).join(', ')}${(t.obstacles || []).length > 2 ? ' +' + (t.obstacles.length - 2) : ''}</td>
      <td style="padding:0 4px;text-align:center">${imgBtns}</td>
    </tr>`;
  };
  // Group by date — insert day separator row between dates
  let lastDate = null;
  tbody.innerHTML = sorted.map(t => {
    let sep = '';
    if (t.date !== lastDate) {
      const dayLabel = t.day ? `${t.date} · ${DAY_EN[t.day] || t.day}` : (t.date || '—');
      sep = createTradeDaySeparatorRow(dayLabel);
      lastDate = t.date;
    }
    return sep + createTradeTableRow(t);
  }).join('');
}

// ══════════════════════════════════════════════════════
// TOPBAR + KPI UPDATE
// ══════════════════════════════════════════════════════
// Safe setter — silently skips if element doesn't exist yet
function _setText(id, val) {
  const el = document.getElementById(id);
  if (el) el.textContent = val;
}

// Swap the active v-* tone class on a topbar stat cell so colors mirror
// the Statistics Overview dynamic thresholds (red/orange/yellow/green/blue/purple).
function _setStatTone(id, toneCls) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.remove(
    'v-white','v-dim','v-green','v-red','v-gold',
    'v-orange','v-yellow','v-blue','v-purple'
  );
  if (toneCls) el.classList.add(toneCls);
}

// BE Trades KPI: count of trades matching an excluded chip in the BE
// Management filter, taken from the filtered dataset BEFORE the BE Management
// exclusion is applied. Returns 0 when no BE Management chip is excluded.
// Implementation: temporarily neutralize the BE Management entry's sets,
// compute getFiltered(), restore. Safe because JS is single-threaded.
// Trades matched by any currently-excluded BE Management chip, evaluated on
// the pre-simulation filtered dataset so the match set is independent of the
// active ORR bubble.
function _getBeMgmtChipMatchedTrades() {
  const entry = appState.filters.chips.beManagement;
  if (!entry || entry.excluded.size === 0) return new Set();

  const chipExcluded = entry.excluded;
  const savedIncluded = entry.included;
  const savedExcluded = entry.excluded;
  entry.included = new Set();
  entry.excluded = new Set();
  invalidateFilterCache();
  const dataset = _getContextFiltered(true);
  entry.included = savedIncluded;
  entry.excluded = savedExcluded;
  invalidateFilterCache();

  const matched = new Set();
  for (const t of dataset) {
    const arr = t.beManagement;
    if (!Array.isArray(arr) || !arr.length) continue;
    if (arr.some(v => chipExcluded.has(v))) matched.add(t);
  }
  return matched;
}

// BE-out trades at a given simulated TP (BE Fallback mode only — returns an
// empty Set in Strict Loss or when tp ≤ TP1). Same rMax derivation as
// computeOptimalRR.
function _getBeOutTradesAtTp(tp) {
  if (_orrSimMode !== 'be-fallback') return new Set();
  if (tp <= _SYSTEM_TP_R) return new Set();
  const base = _getContextFiltered(true);
  const out = new Set();
  for (const t of base) {
    const r    = typeof t?.r === 'number' ? t.r : NaN;
    const rrMaxRaw = t?.rrMax;
    const rMax = Number.isFinite(rrMaxRaw)
      ? rrMaxRaw
      : (Number.isFinite(r) && r > 0 ? r : null);
    if (Number.isFinite(r) && r < 0) continue;
    if (rMax === null) continue;
    if (rMax >= tp) continue;
    if (rMax < _SYSTEM_TP_R) continue;
    out.add(t);
  }
  return out;
}

// Combined BE count at a given TP: (BE-out trades at tp) ∪ (BE Mgmt chips),
// deduplicated. This is what the summary's "W / L / BE" cell shows and what
// _computeBeTradesKpi reports for the active bubble.
function _getBeColumnCountAtTp(tp) {
  const beOut = _getBeOutTradesAtTp(tp);
  const chips = _getBeMgmtChipMatchedTrades();
  const union = new Set([...beOut, ...chips]);
  return union.size;
}

function _computeBeTradesKpi() {
  const tp = appState.ui.rrMinFilter !== null ? appState.ui.rrMinFilter : _SYSTEM_TP_R;
  return _getBeColumnCountAtTp(tp);
}

function updateStats(stats) {
  if (!stats) {
    ['stat-n','stat-wr','stat-ev','stat-tot','stat-pf','stat-dd','stat-ws','stat-ls','stat-be',
     'k-n','k-wr','k-ev','k-tot','k-pf','k-dd','k-be2',
     'dd-best-run', 'dd-worst-run'].forEach(id => _setText(id, '—'));
    updateStatsWidget(null);
    return;
  }
  _setText('stat-n',  stats.n);
  _setText('stat-wr', stats.wr.toFixed(1)+'%');
  _setText('stat-ev', (stats.ev>=0?'+':'')+stats.ev.toFixed(3)+'R');
  _setText('stat-tot',(stats.totalR>=0?'+':'')+stats.totalR.toFixed(1)+'R');
  _setText('stat-pf', stats.pf>=9.99?'∞':stats.pf.toFixed(3));
  _setText('stat-dd', stats.maxDD.toFixed(1)+'R');
  _setText('stat-ws', stats.maxW);
  _setText('stat-ls', stats.maxL);
  _setText('stat-be', _computeBeTradesKpi());

  // Dynamic tone classes — same logic as Stats Overview widget
  _setStatTone('stat-n',  'v-white');
  _setStatTone('stat-tot', stats.totalR > 0 ? 'v-green' : (stats.totalR < 0 ? 'v-red' : 'v-white'));
  _setStatTone('stat-wr', _getWinRateTone(stats.wr).valueCls);
  _setStatTone('stat-ev', _svProgressTone(stats.ev, 'ev').valueCls);
  _setStatTone('stat-pf', _svProgressTone(stats.pf, 'pf').valueCls);
  _setStatTone('stat-ws', 'v-green');
  _setStatTone('stat-ls', 'v-red');
  _setStatTone('stat-dd', 'v-red');
  _setStatTone('stat-be', 'v-gold');

  // Equity widget streak stats
  _setText('dd-best-run',  stats.maxConsecProfitR !== null ? '+'+stats.maxConsecProfitR.toFixed(2)+'R' : '—');
  _setText('dd-worst-run', stats.maxConsecLossR   !== null ? stats.maxConsecLossR.toFixed(2)+'R'       : '—');

  _setText('k-n',    stats.n);
  _setText('k-n-s',  'of ' + appState.trades.items.length);
  _setText('k-wr',   stats.wr.toFixed(1)+'%');
  _setText('k-wr-s', stats.w+'W / '+stats.l+'L');
  _setText('k-ev',   (stats.ev>=0?'+':'')+stats.ev.toFixed(4)+'R');
  _setText('k-tot',  (stats.totalR>=0?'+':'')+stats.totalR.toFixed(1)+'R');
  _setText('k-tot-s','cumulative');
  _setText('k-pf',   stats.pf>=9.99?'∞':stats.pf.toFixed(3));
  _setText('k-dd',   stats.maxDD.toFixed(2)+'R');
  const beTot = stats.be_tp + stats.be_sl;
  _setText('k-be2',   beTot);
  _setText('k-be2-s', (beTot/stats.n*100).toFixed(0)+'% of total');

  updateStatsWidget(stats);
}

// ── Stats Overview Widget ──
function applyStatsOverviewBadge(badgeEl) {
  if (!badgeEl) return;
  badgeEl.textContent = '';
}

// ── KPI tooltip builder (unified .utip) ──
// Threshold legends use the same color scale as the progression micro-bars
// (see _SV_PROGRESSION_COLORS). Raw CSS vars / hex codes are inlined so the
// tooltip is self-contained HTML consumable by showUtip().
const _KPI_THRESHOLD_LEGENDS = {
  pf: [
    { color: 'var(--r)', range: '&lt; 1',     label: 'Losing' },
    { color: '#f39a3d',  range: '1 – 1.3',    label: 'Weak' },
    { color: 'var(--a)', range: '1.3 – 1.7',  label: 'Decent' },
    { color: 'var(--g)', range: '1.7 – 2.2',  label: 'Strong' },
    { color: 'var(--b)', range: '2.2 – 3',    label: 'Elite' },
    { color: '#9b6dff',  range: '&gt; 3',     label: 'Exceptional' },
  ],
  avgR: [
    { color: 'var(--r)', range: '&lt; 0',     label: 'Losing' },
    { color: '#f39a3d',  range: '0 – 0.1',    label: 'Break-even' },
    { color: 'var(--a)', range: '0.1 – 0.3',  label: 'Developing' },
    { color: 'var(--g)', range: '0.3 – 0.6',  label: 'Profitable' },
    { color: 'var(--b)', range: '0.6 – 1.0',  label: 'Advanced' },
    { color: '#9b6dff',  range: '&gt; 1.0',   label: 'Elite' },
  ],
};

function _buildKpiTooltipBreakdown(kpiKey, stats, beStats) {
  if (!stats) return '';
  const row = (color, label, value) =>
    `<div class="utip-threshold-row">`
    + `<span class="utip-threshold-dot" style="background:${color}"></span>`
    + `<span class="utip-threshold-range" style="color:${color}">${label}</span>`
    + `<span class="utip-threshold-label" style="color:${color}">${value}</span>`
    + `</div>`;

  if (kpiKey === 'trades') {
    const total = stats.n || 0;
    if (total <= 0) return '';
    const pct = (n) => (n / total * 100).toFixed(0) + '%';
    const rows = [
      { color: 'var(--g)',                                          label: 'TP',    n: stats.cnt_tp || 0 },
      { color: '#2962ff',                                           label: 'BE-TP', n: stats.be_tp  || 0 },
      { color: '#b478f0',                                           label: 'BE-SL', n: stats.be_sl  || 0 },
      { color: 'var(--r)',                                          label: 'SL',    n: stats.cnt_sl || 0 },
    ].filter(r => r.n > 0)
     .map(r => row(r.color, r.label, `${r.n} (${pct(r.n)})`));
    return rows.length ? `<div class="utip-threshold-legend">${rows.join('')}</div>` : '';
  }

  if (kpiKey === 'totalR') {
    const grossW = (stats.avgWin  ?? 0) * (stats.w || 0);
    const grossL = -((stats.avgLoss ?? 0) * (stats.l || 0));
    const sum = grossW + grossL;
    if (sum <= 0) return '';
    const pctW = (grossW / sum * 100).toFixed(0) + '%';
    const pctL = (grossL / sum * 100).toFixed(0) + '%';
    const rows = [];
    if (grossW > 0) rows.push(row('var(--g)', 'Total R Win',  `+${grossW.toFixed(2)}R`));
    if (grossL > 0) rows.push(row('var(--r)', 'Total R Loss', `-${grossL.toFixed(2)}R`));
    return rows.length ? `<div class="utip-threshold-legend">${rows.join('')}</div>` : '';
  }

  if (kpiKey === 'winRate') {
    const total = stats.n || 0;
    if (total <= 0) return '';
    const w = stats.w || 0, l = stats.l || 0;
    const rows = [];
    if (w > 0) rows.push(row('var(--g)', 'Win',  `${w} (${(w / total * 100).toFixed(1)}%)`));
    if (l > 0) rows.push(row('var(--r)', 'Loss', `${l} (${(l / total * 100).toFixed(1)}%)`));
    return rows.length ? `<div class="utip-threshold-legend">${rows.join('')}</div>` : '';
  }

  if (kpiKey === 'beTrades') {
    const src = beStats || stats;
    const beTp = src.be_tp || 0;
    const beSl = src.be_sl || 0;
    const total = beTp + beSl;
    if (total <= 0) return '';
    const cBETP = '#2962ff';
    const cBESL = '#b478f0';
    const rows = [];
    if (beTp > 0) rows.push(row(cBETP, 'BE-TP', `${beTp} (${(beTp / total * 100).toFixed(0)}%)`));
    if (beSl > 0) rows.push(row(cBESL, 'BE-SL', `${beSl} (${(beSl / total * 100).toFixed(0)}%)`));
    return rows.length ? `<div class="utip-threshold-legend">${rows.join('')}</div>` : '';
  }

  return '';
}

function _buildKpiTooltipHtml(kpiKey, stats, beStats) {
  const raw = KPI_TITLES[kpiKey];
  if (!raw) return '';
  const sep = raw.indexOf(' — ');
  const header = sep >= 0 ? raw.slice(0, sep) : kpiKey;
  const plain  = sep >= 0 ? raw.slice(sep + 3) : raw;

  let html = `<div class="utip-header">${header}</div>`
           + `<div class="utip-plain utip-plain-wrap">${plain}</div>`;

  const breakdown = _buildKpiTooltipBreakdown(kpiKey, stats, beStats);
  if (breakdown) {
    html += `<div class="utip-divider"></div>` + breakdown;
  }

  const legend = _KPI_THRESHOLD_LEGENDS[kpiKey];
  if (legend) {
    const rows = legend.map(row =>
      `<div class="utip-threshold-row">`
      + `<span class="utip-threshold-dot" style="background:${row.color}"></span>`
      + `<span class="utip-threshold-range" style="color:${row.color}">${row.range}</span>`
      + `<span class="utip-threshold-label" style="color:${row.color}">${row.label}</span>`
      + `</div>`
    ).join('');
    html += `<div class="utip-divider"></div>`
         +  `<div class="utip-threshold-legend">${rows}</div>`;
  }
  return html;
}

// Generalization of _attachKpiTooltipHandlers: attaches the rich .utip tooltip
// to any container whose cells carry [data-kpi-key]. Used by Statistics Overview
// (.wst-cell) and by the topbar KPI strip (.ts).
function _attachKpiTooltipHandlersTo(selector, container, stats, beStats) {
  if (!container) return;
  const cells = container.querySelectorAll(selector);
  cells.forEach(cell => {
    const key = cell.dataset.kpiKey;
    if (!key) return;
    const html = _buildKpiTooltipHtml(key, stats, beStats);
    if (!html) return;
    cell.addEventListener('mouseenter', (e) => showUtip(e, html));
    cell.addEventListener('mousemove',  (e) => showUtip(e, html));
    cell.addEventListener('mouseleave', () => hideUtip());
  });
}

function _attachKpiTooltipHandlers(container, stats, beStats) {
  _attachKpiTooltipHandlersTo('.wst-cell[data-kpi-key]', container, stats, beStats);
}

function buildStatsOverviewMarkup(stats, totalCount, idPrefix = 'stats', beStats = stats) {
  const beCount = _computeBeTradesKpi();
  const pct = totalCount > 0 ? (stats.n / totalCount * 100).toFixed(0) + '%' : '—';
  const evTone = _svProgressTone(stats.ev, 'ev');
  const pfTone = _svProgressTone(stats.pf, 'pf');
  const wrTone = _getWinRateTone(stats.wr);

  const cell = (label, value, valueCls, colorCls, extraCls = '', microMarkup = '', kpiKey = '') =>
    `<div class="wst-cell ${[colorCls, extraCls].filter(Boolean).join(' ')}"${kpiKey ? ` data-kpi-key="${kpiKey}"` : ''}>
      <div class="wst-cell-label">${label}</div>
      <div class="wst-cell-main">
        <div class="wst-cell-value ${valueCls}">${value}</div>
        ${microMarkup}
      </div>
    </div>`;

  const richLbl = (name, data) =>
    `<span class="wst-cell-label-name">${name}</span><span class="wst-cell-label-data">${data}</span>`;
  // Share view shows simple labels (no rich sub-label) for cleaner export.
  const lblTrades   = idPrefix === 'share'
    ? 'Trades'
    : richLbl('Trades', `${pct} · ${stats.w}W ${stats.l}L`);
  const lblMaxL     = 'Max Loss Streak';
  const lblBE       = 'BE Trades';

  return `
    <div class="wst-grid cols-9">
      ${cell(lblTrades,         stats.n,
             'v-white', 'c-dim', 'stat-trades', '',
             'trades')}
      ${cell('Total R',         (stats.totalR>=0?'+':'')+stats.totalR.toFixed(2)+'R',
             stats.totalR > 0 ? 'v-green' : 'v-red',
             stats.totalR > 0 ? 'c-green' : 'c-red', 'stat-total-r', '',
             'totalR')}
      ${cell('Win Rate',        stats.wr.toFixed(1)+'%',
             wrTone.valueCls,
             wrTone.colorCls, 'has-micro has-winrate-micro',
             _svWinRateMicro(stats.wr, stats.w, stats.l),
             'winRate')}
      ${cell('Avg R / Trade',   (stats.ev>=0?'+':'')+stats.ev.toFixed(2)+'R',
             evTone.valueCls,
             evTone.colorCls, 'has-micro has-progression-micro',
             _svProgressionMicro(stats.ev, 'ev', idPrefix),
             'avgR')}
      ${cell('Profit Factor',   stats.pf >= 9.99 ? '∞' : stats.pf.toFixed(2),
             pfTone.valueCls,
             pfTone.colorCls, 'has-micro has-progression-micro',
             _svProgressionMicro(stats.pf, 'pf', idPrefix),
             'pf')}
      ${cell('Max Win Streak',  stats.maxW,
             'v-green', 'c-green', 'has-micro',
             _svStreakMicro(stats.maxW, 'green', idPrefix),
             'maxW')}
      ${cell(lblMaxL,           stats.maxL,
             'v-red', 'c-red', 'has-micro',
             _svStreakMicro(stats.maxL, 'red', idPrefix),
             'maxL')}
      ${cell('Max Drawdown',    stats.maxDD.toFixed(2)+'R',
             'v-red', 'c-red', 'stat-max-drawdown', '',
             'maxDD')}
      ${cell(lblBE,             beCount,
             'v-gold', 'c-gold', 'stat-be-trades', '',
             'beTrades')}
    </div>
  `;
}

function updateStatsWidget(stats) {
  const body  = document.getElementById('wst-body');
  if (!body) return;

  if (!stats) {
    body.innerHTML = '<div class="sel-empty" style="opacity:.25"><div class="sel-empty-title">No data</div></div>';
    _topbarKpiStatsRef = null;
    _topbarKpiBeStatsRef = null;
    return;
  }

  const totN = appState.trades.totalOverride !== null ? appState.trades.totalOverride : appState.trades.items.length;
  const beStats = calcStats(_getContextFiltered(false)) || { be_tp: 0, be_sl: 0 };
  body.innerHTML = buildStatsOverviewMarkup(stats, totN, 'main', beStats);
  _attachKpiTooltipHandlers(body, stats, beStats);
  // Refresh live refs so the topbar KPI tooltips reflect the current stats.
  _topbarKpiStatsRef = stats;
  _topbarKpiBeStatsRef = beStats;
  requestAnimationFrame(() => _fitStatsOverviewMicros(body));
}

function _fitStatsOverviewMicros(body) {
  if (!body) return;
  const cells = [...body.querySelectorAll('.wst-cell.has-micro')];
  cells.forEach(cell => {
    cell.classList.remove('micro-compact', 'micro-hidden');

    const valueEl = cell.querySelector('.wst-cell-value');
    const labelEl = cell.querySelector('.wst-cell-label');
    const subEl   = cell.querySelector('.wst-cell-sub');
    const mainEl  = cell.querySelector('.wst-cell-main');

    // .wst-cell-main (nowrap flex) overflows when [value | micro]
    // doesn't fit on one line. That's the compact signal.
    const mainOverflow = mainEl && (mainEl.scrollWidth > mainEl.clientWidth + 1);
    const isTight = cell.clientWidth < 140 ||
      (valueEl && valueEl.scrollWidth > valueEl.clientWidth + 1) ||
      mainOverflow;
    if (isTight) cell.classList.add('micro-compact');

    // Still overflowing after compact → hide the micro entirely.
    const stillClipped = (valueEl && valueEl.scrollWidth > valueEl.clientWidth + 1) ||
      (labelEl && labelEl.scrollWidth > labelEl.clientWidth + 1) ||
      (subEl && subEl.scrollWidth > subEl.clientWidth + 1) ||
      (mainEl && mainEl.scrollWidth > mainEl.clientWidth + 1) ||
      cell.clientWidth < 118;

    if (stillClipped) cell.classList.add('micro-hidden');
  });
}

// Share-view variant: stricter width thresholds per micro type and an
// inline display:none on the hidden micro element. The stricter thresholds
// account for SVG overflow (gauge/progression charts visually extend past
// their bounding box); the inline style survives dom-to-image's clone
// pipeline so the copy-image PNG matches the live share view exactly.
function _fitSvStatsOverviewMicros(body) {
  if (!body) return;
  const cells = [...body.querySelectorAll('.wst-cell.has-micro')];
  cells.forEach(cell => {
    const w = cell.clientWidth;
    if (w <= 0) return;

    const hasGauge       = cell.classList.contains('has-winrate-micro');
    const hasProgression = cell.classList.contains('has-progression-micro');
    const hideAt    = hasGauge ? 230 : hasProgression ? 220 : 200;
    const compactAt = 240;

    const shouldHide    = w < hideAt;
    const shouldCompact = !shouldHide && w < compactAt;

    cell.classList.toggle('micro-hidden',  shouldHide);
    cell.classList.toggle('micro-compact', shouldCompact || shouldHide);

    const microEl = cell.querySelector('.wst-cell-micro');
    if (microEl) microEl.style.display = shouldHide ? 'none' : '';
  });
}

function _fitAllStatsOverviewMicros() {
  _fitStatsOverviewMicros(document.getElementById('wst-body'));
  _fitSvStatsOverviewMicros(document.getElementById('sv-stats-body'));
}

// ══════════════════════════════════════════════════════
// MAIN RENDER
// ══════════════════════════════════════════════════════

// ── Labels and missing-field reasons used by the attention button ──
const MISSING_DATA_META = {
  'w-setup':        { label: 'Setup Performance',     field: 'M15 Type / Setup' },
  'w-session':      { label: 'Session Performance',   field: 'Session' },
  'w-day':          { label: 'Day Performance',       field: 'Day' },
  'w-heatmap':      { label: 'Session × Day Heatmap', field: 'Session + Day' },
  'w-m15':          { label: 'M15 Obstacle Performance', field: 'M15 Obstacles' },
  'w-h4':           { label: 'H4 Obstacle Performance',  field: 'H4 Obstacles' },
  'w-hour':         { label: 'Hour DST Performance',  field: 'Hour (timestamp)' },
  'w-pair-session': { label: 'Pair × Session',        field: 'Session' },
  'w-notion':       { label: 'Trade log link button', field: 'Notion URL' },
};

function hideEmptyWidgets(trades) {
  if (!_grid) {
    updateAttentionButton([]);
    return;
  }

  // When the filter yields 0 trades, SKIP the hide+compact dance entirely.
  // Each widget's render function shows a "No data matches current filters"
  // empty state in place — hiding 8 widgets and compacting the grid on top
  // of that would create an inconsistent mixed layout (some widgets vanish,
  // others show the empty message). Instead, make any previously-hidden
  // widgets visible again so the user sees a full dashboard of empty states,
  // and let the attention button still reflect CSV-level missing data.
  if (!trades.length) {
    _grid.getGridItems().forEach(item => {
      if (item.classList.contains('is-hidden')) setVisible(item, true);
    });
    // Attention button still evaluated against full dataset
    const fullItems0 = (appState && appState.trades && appState.trades.items) || [];
    const hidden0 = [];
    const h0 = fn => fullItems0.some(fn);
    const hS0 = h0(t => t.session && t.session.trim());
    const hD0 = h0(t => t.day     && t.day.trim());
    const fullRules0 = {
      'w-setup':        h0(t => t.setup    && t.setup.trim()),
      'w-session':      hS0,
      'w-day':          hD0,
      'w-heatmap':      hS0 && hD0,
      'w-m15':          h0(t => t.obstacles && t.obstacles.length > 0),
      'w-h4':           h0(t => t.h4       && t.h4.length > 0),
      'w-hour':         h0(t => t.hour != null),
      'w-pair-session': hS0,
      'w-notion':       h0(t => t.notionUrl && String(t.notionUrl).trim()),
    };
    Object.keys(fullRules0).forEach(id => {
      if (!fullRules0[id] && MISSING_DATA_META[id]) {
        hidden0.push({ id, ...MISSING_DATA_META[id] });
      }
    });
    updateAttentionButton(hidden0);
    return;
  }

  // Widget visibility evaluates against the filtered view (existing behavior),
  // but the attention button reflects CSV-level missing data — evaluated against
  // the full dataset — so filter-driven emptiness doesn't raise a false alarm.
  const fullItems = (appState && appState.trades && appState.trades.items) || trades;
  const buildRules = arr => {
    const h = fn => arr.some(fn);
    const hS = h(t => t.session && t.session.trim());
    const hD = h(t => t.day     && t.day.trim());
    return {
      'w-setup':        h(t => t.setup    && t.setup.trim()),
      'w-session':      hS,
      'w-day':          hD,
      'w-heatmap':      hS && hD,
      'w-m15':          h(t => t.obstacles && t.obstacles.length > 0),
      'w-h4':           h(t => t.h4       && t.h4.length > 0),
      'w-hour':         h(t => t.hour != null),
      'w-pair-session': hS,
      'w-notion':       h(t => t.notionUrl && String(t.notionUrl).trim()),
    };
  };
  const viewRules = buildRules(trades);
  const fullRules = buildRules(fullItems);

  // Don't hide widgets — the per-widget empty state handles the "no data" case.
  // Only track missing CSV fields for the attention button.
  const hidden = [];
  _grid.getGridItems().forEach(item => {
    const id = item.getAttribute('gs-id');
    if (!(id in viewRules)) return;
    if (!fullRules[id] && MISSING_DATA_META[id]) {
      hidden.push({ id, ...MISSING_DATA_META[id] });
    }
  });
  // Virtual entries (no grid widget) — evaluated directly from the rules map.
  if (!fullRules['w-notion'] && MISSING_DATA_META['w-notion']) {
    hidden.push({ id: 'w-notion', ...MISSING_DATA_META['w-notion'] });
  }
  updateAttentionButton(hidden);
}

// ══════════════════════════════════════════════════════
// STREAK ANALYTICS WIDGET
// ══════════════════════════════════════════════════════
let _streakTab = 'histogram';

function setStreakTab(tab) {
  _streakTab = tab;
  document.querySelectorAll('#streak-tab-btns .cc-tab').forEach(b =>
    b.classList.toggle('active', b.textContent.toLowerCase().includes(tab)));
  setVisible(document.getElementById('streak-timeline-view'), tab === 'timeline');
  setVisible(document.getElementById('streak-histogram-view'), tab === 'histogram');
  // Re-render current view with last data
  const filtered = getFiltered();
  if (tab === 'timeline')  renderStreakTimeline(filtered);
  else                     renderStreakHistogram(filtered);
}

function renderStreakAnalytics(trades) {
  if (_streakTab === 'timeline') renderStreakTimeline(trades);
  else                           renderStreakHistogram(trades);
}

// ── Timeline: all trades grouped into W/L/BE runs ──
let _streakTimelineRuns = [];
let _streakBeColorMode  = false; // false = harmonized (BE squares use win/loss color), true = detailed

function _updateStreakLegend() {
  const winLabel  = document.getElementById('stl-leg-win');
  const lossLabel = document.getElementById('stl-leg-loss');
  const betpItem  = document.getElementById('stl-leg-betp');
  const beslItem  = document.getElementById('stl-leg-besl');
  if (winLabel)  winLabel.textContent  = _streakBeColorMode ? 'TP' : 'Win';
  if (lossLabel) lossLabel.textContent = _streakBeColorMode ? 'SL' : 'Loss';
  if (betpItem)  setVisible(betpItem, _streakBeColorMode);
  if (beslItem)  setVisible(beslItem, _streakBeColorMode);
}
function renderStreakTimeline(trades) {
  const container = document.getElementById('streak-timeline-row');
  if (!container) return;
  if (!trades.length) { _streakTimelineRuns = []; renderWidgetEmptyState('streak-timeline-row'); return; }

  // Sort by date+hour
  const sorted = _sortTradesChronological(trades);

  // Group into consecutive runs
  const runs = [];
  let cur = null;
  sorted.forEach(t => {
    const sign = isWinner(t) ? 'w' : 'l';
    if (!cur || cur.sign !== sign) {
      cur = { sign, trades: [] };
      runs.push(cur);
    }
    cur.trades.push(t);
  });

  _streakTimelineRuns = runs;

  const colMap = { w:'var(--g)', l:'var(--r)', be:'var(--oc-betp)', besl:'var(--oc-besl)' };
  const outcomeColMap    = { 'TP':'var(--g)', 'SL':'var(--r)', 'BE-TP':'var(--oc-betp)', 'BE-SL':'var(--oc-besl)' };
  const harmonizedColMap = { 'TP':'var(--g)', 'SL':'var(--r)', 'BE-TP':'var(--g)',       'BE-SL':'var(--r)' };
  const activeColMap     = _streakBeColorMode ? outcomeColMap : harmonizedColMap;
  const tt = document.getElementById('stl-tooltip') || (() => {
    const el = document.createElement('div');
    el.id = 'stl-tooltip';
    el.className = 'floating-tooltip stl-tooltip is-hidden';
    document.body.appendChild(el);
    return el;
  })();

  const tpConfig = appState.ui.tpConfig;
  container.innerHTML = runs.map((run, ri) => {
    const col = colMap[run.sign];
    const totalR = run.trades.reduce((s,t) => s+computeEffectiveRR(t, tpConfig), 0);
    const squares = run.trades.map((t, ti) => {
      const sqCol = activeColMap[t.outcome] || col;
      const _rEff = t.effectiveR ?? computeEffectiveRR(t, tpConfig);
      const rStr = (_rEff >= 0 ? '+' : '') + _rEff.toFixed(1) + 'R';
      return `<div class="stl-sq"
        data-action="open-streak-timeline-drawer"
        data-run-idx="${ri}"
        data-trade-idx="${ti}"
        style="background:${sqCol};opacity:${0.5 + 0.5*(ti/Math.max(run.trades.length-1,1))}"
        data-tip="${t.date}${t.hour!=null?' '+String(t.hour).padStart(2,'0')+'h':''} · ${t.pair} · ${t.outcome} · ${rStr}"></div>`;
    }).join('');
    const lbl = run.trades.length > 1
      ? `<span class="stl-run-lbl" style="color:${col}">${run.trades.length}×${(totalR>=0?'+':'')+totalR.toFixed(1)}R</span>`
      : '';
    return `<div class="stl-run" data-run-idx="${ri}">${squares}${lbl}</div>`;
  }).join('');
}

function stlShowTip(el, e) {
  const tt = document.getElementById('stl-tooltip');
  if (!tt) return;
  tt.textContent = el.dataset.tip;
  setVisible(tt, true);
  tt.style.left = (e.clientX + 12) + 'px';
  tt.style.top  = (e.clientY - 8)  + 'px';
}
function stlHideTip() {
  const tt = document.getElementById('stl-tooltip');
  if (tt) setVisible(tt, false);
}

// ── Histogram: distribution of run lengths ──
let _streakHistChart = null;
let _streakHistRuns  = { win: [], loss: [] };
let _streakHistActiveDataset = null;
let _streakHistActiveIdx     = null;
// Returns the tooltip font size from the CSS variable (shared by all Chart.js widgets)
function _chartTipFs() {
  return parseInt(getComputedStyle(document.documentElement).getPropertyValue('--fs-monthly-tooltip')) || 9;
}

function renderStreakHistogram(trades) {
  const canvas = getByIdSafe('streakHistCanvas');
  if (!canvas) return;
  if (_streakHistChart) { _streakHistChart.destroy(); _streakHistChart = null; }
  if (!trades.length) {
    renderCanvasEmptyState('#streak-histogram-view', ['streakHistCanvas']);
    return;
  }
  clearCanvasEmptyState('#streak-histogram-view');
  if (!hasChartJs()) return;

  // Sort by date+hour
  const sorted = _sortTradesChronological(trades);

  // Build runs — BE trades act as streak-breakers (end current run, don't start one)
  const tpConfig = appState.ui.tpConfig;
  const winRuns = [], lossRuns = [];
  let curSign = 0, curTrades = [];
  const _pushRun = () => {
    if (curSign !== 0 && curTrades.length > 0) {
      const totalR = curTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig))||0), 0);
      const entry = { length: curTrades.length, trades: curTrades.slice(), totalR };
      (curSign === 1 ? winRuns : lossRuns).push(entry);
    }
  };
  sorted.forEach((t, i) => {
    const s = isWinner(t) ? 1 : -1;
    if (s !== curSign) {
      _pushRun();
      curSign = s; curTrades = [t];
    } else {
      curTrades.push(t);
    }
    if (i === sorted.length - 1) _pushRun();
  });

  _streakHistRuns = { win: winRuns, loss: lossRuns };
  const winLengths  = winRuns.map(r => r.length);
  const lossLengths = lossRuns.map(r => r.length);

  const maxLen = Math.max(...winLengths, ...lossLengths, 1);
  const labels = Array.from({length: maxLen}, (_, i) => i + 1);
  const winCounts  = labels.map(l => winLengths.filter(x => x === l).length);
  const lossCounts = labels.map(l => lossLengths.filter(x => x === l).length);

  canvas.style.width  = '100%';
  canvas.style.height = '100%';

  const _mkBorderWidths = (counts, datasetIdx) =>
    counts.map((_, i) => (_streakHistActiveDataset === datasetIdx && _streakHistActiveIdx === i) ? 3 : 0);
  const selCol = tc('--white') || '#ffffff';

  _streakHistChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: labels.map(l => l + (l === 1 ? ' trade' : ' trades')),
      datasets: [
        { label: 'Win runs',  data: winCounts,  backgroundColor: tc('--g') + 'cc', borderRadius: 3,
          borderColor: selCol, borderWidth: _mkBorderWidths(winCounts, 0) },
        { label: 'Loss runs', data: lossCounts, backgroundColor: tc('--r') + 'cc', borderRadius: 3,
          borderColor: selCol, borderWidth: _mkBorderWidths(lossCounts, 1) },
      ]
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false, animation: false,
      onClick: (ev, elements, chart) => {
        if (!elements || !elements.length) return;
        const el = elements[0];
        const datasetIdx = el.datasetIndex;
        const barIdx     = el.index;
        const targetLen  = barIdx + 1;
        const type       = datasetIdx === 0 ? 'win' : 'loss';
        const matching   = (_streakHistRuns[type] || []).filter(r => r.length === targetLen);
        if (!matching.length) return;
        _streakHistActiveDataset = datasetIdx;
        _streakHistActiveIdx     = barIdx;
        chart.data.datasets.forEach((ds, di) => {
          ds.borderWidth = ds.data.map((_, i) => (di === datasetIdx && i === barIdx) ? 3 : 0);
        });
        chart.update();
        openStreakDrawer(type, targetLen, matching);
      },
      onHover: (ev, elements) => {
        const target = ev?.native?.target;
        if (target) target.style.cursor = elements && elements.length ? 'pointer' : 'default';
      },
      plugins: {
        legend: { display: true, position: 'bottom',
          labels: { color: tc('--dim'), font: { size: parseFloat(tc('--typo-streak-legend-size')), family: '"DM Mono",monospace' }, boxWidth: 12, padding: 8 }
        },
        tooltip: { bodyFont: { size: _chartTipFs() }, titleFont: { size: _chartTipFs() }, callbacks: { label: ctx => ` ${ctx.dataset.label}: ${ctx.raw} run${ctx.raw > 1 ? 's' : ''}` } }
      },
      scales: {
        x: {
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { size: parseFloat(tc('--typo-streak-tick-size')), family: '"DM Mono",monospace' }, stepSize: 1 },
          beginAtZero: true,
        },
        y: {
          grid: { display: false },
          ticks: { color: tc('--body'), font: { size: parseFloat(tc('--typo-streak-legend-size')), family: '"DM Mono",monospace', weight: '600' } },
        }
      }
    }
  });
}

// ══════════════════════════════════════════════════════
// R DISTRIBUTION WIDGET
// ══════════════════════════════════════════════════════
let _rDistChart = null;
function renderRDist(trades) {
  const canvas = getByIdSafe('rDistCanvas');
  if (!canvas) return;
  if (_rDistChart) { _rDistChart.destroy(); _rDistChart = null; }
  const R_DIST_WRAP = '.chart-card[data-gs-id="w-rdist"] .canvas-stage';
  if (!trades.length) {
    renderCanvasEmptyState(R_DIST_WRAP, ['rDistCanvas']);
    return;
  }
  clearCanvasEmptyState(R_DIST_WRAP);
  if (!hasChartJs()) return;

  // Bucket R values
  const tpConfig = appState.ui.tpConfig;
  const rs = trades.map(t => computeEffectiveRR(t, tpConfig));
  const buckets = {};
  rs.forEach(r => {
    const key = r.toFixed(1);
    buckets[key] = (buckets[key] || 0) + 1;
  });

  const sorted = Object.entries(buckets)
    .map(([k, v]) => ({ r: parseFloat(k), n: v }))
    .sort((a, b) => a.r - b.r);

  const labels = sorted.map(d => (d.r >= 0 ? '+' : '') + d.r.toFixed(1) + 'R');
  const values = sorted.map(d => d.n);
  const colors = sorted.map(d => d.r > 0 ? tc('--g') + 'cc' : d.r < 0 ? tc('--r') + 'cc' : tc('--gold') + 'cc');

  // Stats overlay
  const mean = rs.reduce((s,r) => s+r, 0) / rs.length;
  const wins = rs.filter(r => r > 0);
  const losses = rs.filter(r => r < 0);

  canvas.removeAttribute('width');
  canvas.removeAttribute('height');

  _rDistChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels,
      datasets: [{
        data: values,
        backgroundColor: colors,
        borderRadius: 3,
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      plugins: {
        legend: { display: false },
        tooltip: { bodyFont: { size: _chartTipFs() }, titleFont: { size: _chartTipFs() }, callbacks: {
          title: ctx => ctx[0].label,
          label: ctx => ` ${ctx.raw} trade${ctx.raw > 1 ? 's' : ''} (${(ctx.raw/trades.length*100).toFixed(1)}%)`
        }}
      },
      scales: {
        x: { grid:{ color:tc('--line') }, ticks:{ color:tc('--dim'), font:{size:9,family:'"DM Mono",monospace'}, maxRotation:45 } },
        y: { grid:{ color:tc('--line') }, ticks:{ color:tc('--dim'), font:{size:9,family:'"DM Mono",monospace'}, stepSize:1 }, beginAtZero:true },
      }
    },
    plugins: [{
      id: 'rDistAnnotations',
      afterDraw(chart) {
        const { ctx, chartArea: { top, bottom }, scales: { x, y } } = chart;
        // Mean line
        const meanLabel = sorted.findIndex(d => Math.abs(d.r - mean) < 0.05);
        if (meanLabel >= 0) {
          const mx = x.getPixelForValue(meanLabel);
          ctx.save();
          ctx.strokeStyle = tc('--gold');
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 3]);
          ctx.beginPath(); ctx.moveTo(mx, top); ctx.lineTo(mx, bottom); ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = tc('--gold');
          ctx.font = '8px DM Mono, monospace';
          ctx.textAlign = 'center';
          ctx.fillText('avg ' + (mean >= 0 ? '+' : '') + mean.toFixed(2) + 'R', mx, top - 4);
          ctx.restore();
        }
      }
    }]
  });
}
// ══════════════════════════════════════════════════════
// HOUR DST PERFORMANCE WIDGET
// ══════════════════════════════════════════════════════
let _hourSort = 'canonical';

function setHourSort(mode) {
  _hourSort = mode;
  const row = document.getElementById('sort-hour');
  if (row) {
    row.querySelectorAll('.bar-sort-btn:not(.sort-sync-btn)').forEach(b =>
      b.classList.toggle('active', b.dataset.sort === mode));
  }
  renderHourBars(getFiltered());

  // Propagate to all bar charts if sync is enabled
  if (_sortSyncEnabled && !_sortSyncGuard) {
    _sortSyncGuard = true;
    const mapped = _syncedSort(mode);
    _ALL_BAR_CHARTS.forEach(c => {
      const m = _SORT_CHARTS_WITH_CANONICAL.includes(c) ? mapped.canonical : mapped.alpha;
      setBarSort(c, m);
    });
    _sortSyncGuard = false;
  }
}

function renderHourBars(trades) {
  const container = document.getElementById('bars-hour');
  if (!container) return;
  if (!trades.length) { renderWidgetEmptyState('bars-hour'); return; }

  const tpConfig = appState.ui.tpConfig;
  const groups = {};
  trades.forEach(t => {
    const hour = t.hour != null ? _parseHourValue(t.hour) : _extractTradeHour(t);
    if (hour == null) return;
    const k = hour;
    if (!groups[k]) groups[k] = { rs: [], _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
    const r = computeEffectiveRR(t, tpConfig);
    groups[k].rs.push(r);
    const arr = groups[k]._oc[t.outcome];
    if (arr) arr.push(r);
  });

  const _hrsum = a => a.reduce((s,r)=>s+r,0);
  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const valFn = d => useN ? d.n : useTotal ? d.totalR : useWR ? (d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0) : d.ev;
  const cG = tc('--g'), cA = tc('--gold') || tc('--a'), cT = tc('--t'), cR = tc('--r');
  const getCol = (v, d) => useWR ? (d.ev > 0 ? cG : d.ev < 0 ? cR : cA)
    : useN ? cA
    : barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : (v >= 0.5 ? cG : v >= 0.2 ? cA : v >= 0 ? cT : cR);

  let items = Object.entries(groups).map(([h, { rs, _oc }]) => {
    const hour = parseInt(h);
    const ev = _hrsum(rs) / rs.length;
    const totalR = _hrsum(rs);
    const label = String(hour).padStart(2,'0') + 'h';
    return {
      label, hour, _rawKey: String(hour), n: rs.length, ev, totalR,
      oc: {
        tp:   { r: _hrsum(_oc.TP),       n: _oc.TP.length },
        betp: { r: _hrsum(_oc['BE-TP']), n: _oc['BE-TP'].length },
        besl: { r: _hrsum(_oc['BE-SL']), n: _oc['BE-SL'].length },
        sl:   { r: _hrsum(_oc.SL),       n: _oc.SL.length },
      },
    };
  });

  if (!items.length) { container.innerHTML = '<div class="no-data">No data</div>'; return; }

  // Sort
  if (_hourSort === 'canonical') {
    items.sort((a,b) => a.hour - b.hour);
  } else if (_hourSort === 'volume') {
    items.sort((a,b) => b.n - a.n);
  } else if (_hourSort === 'desc') {
    items.sort((a,b) => valFn(b) - valFn(a));
  } else {
    items.sort((a,b) => valFn(a) - valFn(b));
  }

  if (barView === 'split') { renderBarsSplit('bars-hour', items, false, null); return; }

  const absMax = useWR ? 100 : useN ? (Math.max(...items.map(d => d.n)) || 1) : (Math.max(...items.map(d => Math.abs(valFn(d)))) || 1);
  const decimals = useTotal ? 1 : useWR ? 0 : useN ? 0 : 3;
  const fmtHrVal = v => useWR ? v.toFixed(0) + '%' : useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(decimals) + 'R';

  const _ocHr = d => `${d.oc.tp.n},${d.oc.tp.r.toFixed(2)},${d.oc.sl.n},${d.oc.sl.r.toFixed(2)},${d.oc.betp.n},${d.oc.betp.r.toFixed(2)},${d.oc.besl.n},${d.oc.besl.r.toFixed(2)}`;
  const _hrNetStr = d => fmtHrVal(valFn(d));
  container.innerHTML = items.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val) / absMax * 100, 100);
    const col = getCol(val, d);
    const valStr = fmtHrVal(val);
    const op = barOpacityForN(d.n);
    const nCls = _isLowVolume(d.n) ? 'bar-n bar-n-low' : 'bar-n';
    const nStr = _isLowVolume(d.n) ? ` ×${d.n} ⚠` : ` ×${d.n}`;
    return `<div class="bar-row" style="opacity:${op}" data-bar-label="${d.label}" data-bar-rawkey="${d.hour}" data-bar-n="${d.n}" data-bar-oc="${_ocHr(d)}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label">${d.label}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${col}"></div></div>
      <div class="bar-val" style="color:${col}"><span class="bar-r">${valStr}</span><span class="bar-net">${_hrNetStr(d)}</span><span class="${nCls}">${nStr}</span></div>
    </div>`;
  }).join('');
}


// ══════════════════════════════════════════════════════
// MONTHLY SECONDARY CURVE STATE
// ══════════════════════════════════════════════════════
// Independent on/off toggles — off by default
let _monthlyShow3M    = false; // 3M rolling avg
let _monthlyShowCumul = false; // cumulative R
// _monthlyCurve is kept as a plain var read by drawMonthly
let _monthlyCurve = 'none'; // 'none' | 'rolling' | 'cumul' | 'both'

function _syncMonthlyCurve() {
  if (_monthlyShow3M && _monthlyShowCumul) _monthlyCurve = 'both';
  else if (_monthlyShow3M)                  _monthlyCurve = 'rolling';
  else if (_monthlyShowCumul)               _monthlyCurve = 'cumul';
  else                                      _monthlyCurve = 'none';
}

function toggleMonthlyCurve(key) {
  if (key === 'rolling') _monthlyShow3M    = !_monthlyShow3M;
  if (key === 'cumul')   _monthlyShowCumul = !_monthlyShowCumul;
  _syncMonthlyCurve();
  document.getElementById('mc-btn-3m')   ?.classList.toggle('active', _monthlyShow3M);
  document.getElementById('mc-btn-cumul')?.classList.toggle('active', _monthlyShowCumul);
  drawMonthly(getFiltered());
}

function setMonthlyCurve(mode) {
  _monthlyShow3M    = (mode === 'rolling' || mode === 'both');
  _monthlyShowCumul = (mode === 'cumul'   || mode === 'both');
  _syncMonthlyCurve();
  document.getElementById('mc-btn-3m')   ?.classList.toggle('active', _monthlyShow3M);
  document.getElementById('mc-btn-cumul')?.classList.toggle('active', _monthlyShowCumul);
  drawMonthly(getFiltered());
}


// ══════════════════════════════════════════════════════
// PRESET COMPARISON
// ══════════════════════════════════════════════════════
let _presetCmpOpen = false;

function togglePresetCompare() {
  _presetCmpOpen = !_presetCmpOpen;
  const panel  = document.getElementById('preset-cmp-panel');
  const toggle = document.getElementById('preset-cmp-toggle');
  const header = document.getElementById('preset-cmp-header');
  if (panel)  setVisible(panel, _presetCmpOpen);
  if (toggle) toggle.textContent = _presetCmpOpen ? '▾' : '▸';
  if (header) header.setAttribute('aria-expanded', _presetCmpOpen ? 'true' : 'false');
  if (_presetCmpOpen) {
    runPresetCompare();
  } else {
    // Reset Filter differences open state on close so reopening starts fresh.
    _presetCmpDiffOpen = false;
  }
  _persistSidebarState();
}

// ── Filters accordion panel ──
let _filtersPanelOpen = false;

function _toggleFiltersPanel() {
  _filtersPanelOpen = !_filtersPanelOpen;
  const body   = document.getElementById('filters-panel-body');
  const toggle = document.getElementById('filters-panel-toggle');
  const header = document.getElementById('filters-accordion-header');
  if (body)   setVisible(body, _filtersPanelOpen);
  if (toggle) toggle.textContent = _filtersPanelOpen ? '▾' : '▸';
  if (header) header.setAttribute('aria-expanded', _filtersPanelOpen ? 'true' : 'false');
  if (_filtersPanelOpen) renderSaveButton();
  _persistSidebarState();
}

function _filtersClearAll() {
  // v2: Clear only removes LIVE chips. Preset-flagged chips survive so the
  // active preset's behavior stays intact. Matches v1 where clearing chips
  // left the preset's hard exclusions active.
  invalidateFilterCache();
  if (typeof appState.presets.activeId === 'number') {
    // Revert to the active preset's saved snapshot: wipe chip state and
    // re-hydrate from presetSnapshots. Covers the case where the user had
    // manually removed a preset chip (toggleFilter strips its fromPreset
    // flag), which "remove only live" alone would leave gone after Clear.
    _removeAllPresetChips();
    _removeAllLiveChips();
    _hydrateChipsFromSnapshot(presetSnapshots[appState.presets.activeId]);
  } else {
    clearChipFilters();
  }
  // Combos aren't preset-owned — always clear.
  Object.values(appState.filters.comboFilters || {}).forEach(entry => {
    entry.included.clear();
    entry.excluded.clear();
  });
  Object.keys(appState.filters.chips).forEach(key => _syncChipModeButtons(key));
  // Mirror the post-clear state into the active preset's live slot and
  // refresh the per-dim pills (tune panel + sidebar filter groups +
  // additional/custom filters). Without this, the golden +N pills linger
  // until the next chip click even though the underlying live chips are gone.
  _syncLiveSlotFromActiveChips();
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  render();
}

function _syncFiltersClearBtn() {
  const btn = document.getElementById('filters-clear-btn');
  if (!btn) return;
  let n = 0;
  if (typeof appState.presets.activeId === 'number') {
    // Preset active — Clear targets live chips only. Count lives to match.
    n = _getLiveFilterCount();
  } else {
    Object.values(appState.filters.chips).forEach(e => { n += e.included.size + e.excluded.size; });
    Object.values(appState.filters.customChips || {}).forEach(e => { n += e.included.size + e.excluded.size; });
  }
  Object.values(appState.filters.comboFilters || {}).forEach(e => { n += e.included.size + e.excluded.size; });
  btn.classList.toggle('is-active', n > 0);
  const cnt = document.getElementById('filters-clear-count');
  if (cnt) cnt.textContent = n;
}

// ══ v2 contextual Save button ══
// State machine (no dropdown on screen by default):
//   0 filters active + no preset              → button hidden
//   Filters active, no preset active          → "+ Save as new preset"
//   Preset active, zero live filters          → split button, Update +
//                                               Reset disabled (visual
//                                               persists so the user always
//                                               sees the Update/Save/Reset
//                                               affordance when a preset
//                                               is applied)
//   Preset active + ≥1 live filter            → split button: Update / ▼
let _saveDropdownOpen = false;
let _saveDropdownCleanup = null;

function _closeSaveDropdown() {
  _saveDropdownOpen = false;
  if (_saveDropdownCleanup) { _saveDropdownCleanup(); _saveDropdownCleanup = null; }
  renderSaveButton();
}

function renderSaveButton() {
  const host = document.getElementById('filters-save-container');
  if (!host) return;
  const liveN = _getLiveFilterCount();
  const activeId = appState.presets.activeId;
  const hasPreset = typeof activeId === 'number';
  // Divergence = additions (live chips) + removals (preset chips stripped
  // via click). Either one should light up Update/Reset so the user can
  // commit a removal or roll it back without having to re-add a chip first.
  const divergence = hasPreset ? _getPresetDivergenceCount(activeId) : 0;
  const presetLabel = hasPreset ? (PRESETS.find(p => p.id === activeId)?.label || ('P' + _getPresetDisplayNum(activeId))) : '';
  const labelSafe = _escAttr(presetLabel).slice(0, 24);

  // Drop the pending baseline-confirm if the context it was armed in no
  // longer applies (preset switched, divergence reverted, etc.). Without
  // this, the inline confirm could stick around after the user canceled
  // their edit through another path.
  if (_pendingBaselineUpdate && (!hasPreset || !_isBaselinePresetId(activeId) || divergence === 0)) {
    _pendingBaselineUpdate = false;
  }

  // Mode decision
  if (!liveN && !hasPreset) {
    host.innerHTML = '';
    host.classList.add('is-empty');
    return;
  }
  host.classList.remove('is-empty');

  if (!hasPreset) {
    // Filters live, no preset — single "Save as new" CTA.
    host.innerHTML = `<button class="filters-save-btn filters-save-new" data-action="save-as-new" type="button">+ Save as new preset</button>`;
    return;
  }

  // Preset active — the split button stays visible whether or not there are
  // live filters, so the Update/Save/Reset affordance is always discoverable.
  // Update + Reset-to-preset become disabled only when there's zero
  // divergence from the snapshot; "Save as new" is always usable because
  // cloning the preset is always meaningful.
  const idle = divergence === 0;
  const disabledAttr = idle ? ' disabled aria-disabled="true"' : '';
  const mainTitle = idle
    ? 'No live filters to save — tweak a chip to enable Update'
    : 'Commit live filters to the active preset';
  const dropdownHtml = _saveDropdownOpen ? `
    <div class="filters-save-dropdown" id="filters-save-dropdown">
      <button data-action="save-update" type="button"${disabledAttr}>↻ Update "${labelSafe}"</button>
      <button data-action="save-as-new" type="button">+ Save as new preset</button>
      <button data-action="save-reset-live" type="button"${disabledAttr}>↶ Reset to preset values</button>
    </div>` : '';

  const confirmHtml = _pendingBaselineUpdate && _isBaselinePresetId(activeId) ? `
    <div class="filters-save-confirm" role="alertdialog" aria-label="Confirm baseline update">
      <div class="filters-save-confirm-text">Update baseline "${labelSafe}"? This replaces its saved definition.</div>
      <div class="filters-save-confirm-actions">
        <button class="filters-save-confirm-cancel" data-action="cancel-baseline-update" type="button">Cancel</button>
        <button class="filters-save-confirm-ok" data-action="save-update" type="button">Confirm</button>
      </div>
    </div>` : '';

  host.innerHTML = `
    <div class="filters-save-split${idle ? ' is-idle' : ''}">
      <button class="filters-save-main" data-action="save-update" type="button"${disabledAttr} title="${mainTitle}">↻ Update "${labelSafe}"</button>
      <button class="filters-save-toggle${_saveDropdownOpen ? ' open' : ''}" data-action="save-dropdown-toggle" type="button" aria-haspopup="menu" aria-expanded="${_saveDropdownOpen ? 'true' : 'false'}" title="More options">▼</button>
    </div>
    ${confirmHtml}
    ${dropdownHtml}
  `;

  if (_saveDropdownOpen) {
    const onDocClick = (ev) => {
      if (ev.target.closest('#filters-save-dropdown')) return;
      if (ev.target.closest('.filters-save-toggle')) return;
      _closeSaveDropdown();
    };
    const onEsc = (ev) => { if (ev.key === 'Escape') _closeSaveDropdown(); };
    document.addEventListener('click', onDocClick, true);
    document.addEventListener('keydown', onEsc, true);
    _saveDropdownCleanup = () => {
      document.removeEventListener('click', onDocClick, true);
      document.removeEventListener('keydown', onEsc, true);
    };
  }
}

function _toggleSaveDropdown() {
  _saveDropdownOpen = !_saveDropdownOpen;
  if (!_saveDropdownOpen && _saveDropdownCleanup) {
    _saveDropdownCleanup();
    _saveDropdownCleanup = null;
  }
  renderSaveButton();
}

/** Re-sync every piece of UI that depends on chip fromPreset flags: sidebar
 *  chip glows, the Filters Clear count pill, the tune panel (if open), the
 *  live-filter halo/badge on the active preset, the Save button, and the
 *  active-filter pills at the top of main. Cheap vs full `render()`. */
function _refreshChipDerivedUI() {
  _refreshAllChipDisplays();
  _syncFiltersClearBtn();
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  if (typeof renderActiveFilters === 'function') {
    // getFiltered() is cached; pass the length so the count pill stays in sync.
    renderActiveFilters(getFiltered().length);
  }
  renderSaveButton();
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
}

/** Update action — promote all live chips for the active preset to fromPreset
 *  flag, then persist the snapshot. No confirmation. */
// Baseline-update confirmation: inline 2-step affordance. First click on
// Update when the active preset is a baseline arms this flag → renderSaveButton
// swaps the split for a "Update baseline? [Cancel] [Confirm]" strip right
// where the button was. Confirm proceeds with the real commit; Cancel
// clears the flag and restores the split.
let _pendingBaselineUpdate = false;

function commitLiveFiltersToActivePreset() {
  const id = appState.presets.activeId;
  if (typeof id !== 'number') return;
  // Any divergence from the snapshot counts: additions OR removals of
  // preset chips. Without removals counting, a user who strips a saved
  // chip and wants to commit that deletion would be stuck with Update
  // disabled. The snapshot is rebuilt afterward from the current state.
  if (_getPresetDivergenceCount(id) === 0) return;
  // Baseline presets (P0-P5, seeded from DEFAULT_PRESETS) are the stable
  // strategies shipped with the app. Mutating them is allowed but we gate
  // it behind an inline confirm so it can't happen by a stray Update click.
  if (_isBaselinePresetId(id) && !_pendingBaselineUpdate) {
    _pendingBaselineUpdate = true;
    _closeSaveDropdown();
    renderSaveButton();
    return;
  }
  _pendingBaselineUpdate = false;
  _commitLiveFiltersConfirmed(id);
}

function _cancelBaselineUpdate() {
  _pendingBaselineUpdate = false;
  renderSaveButton();
}

function _isBaselinePresetId(id) {
  return DEFAULT_PRESETS.some(p => p.id === id);
}

function _commitLiveFiltersConfirmed(id) {
  _promoteLiveToPreset();
  // Rebuild the snapshot from the now-fully-preset state and persist.
  presetSnapshots[id] = _buildSnapshotFromActiveChips();
  savePresetSnapshots();
  // Phase 3: les chips live viennent d'être promus → le slot live du preset
  // actif est désormais vide. On vide aussi les comboFilters car ils restent
  // toujours live (jamais promus dans le snapshot — voir commentaire plus
  // bas). Ce choix fait que cliquer Update ne "fige" pas un filtre heatmap
  // dans le preset, ce qui est intentionnel : ces filtres sont exploratoires
  // et ne font pas partie de la définition canonique d'un preset.
  presetLiveFilters[_liveKey(id)] = _blankLiveSlot();
  _clearComboFilters();
  savePresetLiveFilters();
  _closeSaveDropdown();
  invalidateFilterCache();
  _refreshChipDerivedUI();
  _flashSaveConfirm('✓ Updated');
}

/** Reset action — drop every live (non-preset) chip. Preset-flagged chips
 *  remain. No confirmation. */
function resetLiveFilters() {
  const id = appState.presets.activeId;
  if (typeof id !== 'number') return;
  if (_getPresetDivergenceCount(id) === 0) return;
  // Full revert to the saved snapshot: wipe chip state and re-hydrate.
  // This covers both live additions AND preset chips the user had stripped
  // via click (those need to be reinstated). Matches the Reset behavior in
  // the tune panel + the Clear button.
  _removeAllPresetChips();
  _removeAllLiveChips();
  _hydrateChipsFromSnapshot(presetSnapshots[id]);
  _clearComboFilters();
  presetLiveFilters[_liveKey(id)] = _blankLiveSlot();
  savePresetLiveFilters();
  invalidateFilterCache();
  Object.keys(appState.filters.chips).forEach(key => _syncChipModeButtons(key));
  _closeSaveDropdown();
  // Full render here — filtered set may have changed (dropping live chips
  // reopens previously-filtered trades), so widgets need to re-compute.
  render();
}

/** Save-as-new action — create a new preset from all currently active chips
 *  (preset-flagged + live, merged), apply it as the active preset, flash. */
function savePresetFromLive() {
  const sourceId = appState.presets.activeId;
  const id = _nextPresetId();
  if (id < 0) { alert('Maximum ' + PRESET_MAX + ' presets allowed.'); return; }

  // Phase 3 (anti-trap) : capturer AVANT toute mutation le slot live du
  // source. Raison : plus bas on fait _promoteLiveToPreset() puis applyPreset(id),
  // qui déclenche _syncLiveSlotFromActiveChips avec l'ancien activeId encore =
  // sourceId. Sans ce deep-clone pris tôt, on overwriterait le slot source
  // avec l'état post-promotion (tout glow, 0 live) → perte des live de la
  // source. Le clone capture les live "bruts" pour (a) alimenter le nouveau
  // preset en live hérités et (b) restaurer la source en fin de fonction.
  const sourceLiveClone = JSON.parse(JSON.stringify(getPresetLiveSlot(sourceId)));

  // Promouvoir tous les chips live en preset chip (captured dans snapshot).
  _promoteLiveToPreset();

  const maxOrder = PRESETS.reduce((m, p) => Math.max(m, (typeof p.order === 'number' ? p.order : -1)), -1);
  const newPreset = {
    id,
    order: maxOrder + 1,
    label: 'Custom P' + id,
    description: 'Created from filters',
    be: false,
    clear: true,
    m15Exclude: [],
    h4Exclude: [],
    sessionExclude: [],
    noBaseExclusions: true,
  };
  PRESETS.push(newPreset);
  PRESETS.sort((a, b) => a.order - b.order);
  if (!presetOverrides[id]) {
    presetOverrides[id] = {};
    SB_DIMS.forEach(d => {
      presetOverrides[id][d.key] = { mode: 'neutral', included: new Set(), excluded: new Set() };
    });
    presetOverrides[id].customChips = {};
  }
  // Snapshot du nouveau preset = état actuel (maintenant 100% glow).
  presetSnapshots[id] = _buildSnapshotFromActiveChips();
  savePresetsList();
  savePresetSnapshots();

  // Le nouveau preset hérite des live de la source (deep clone).
  presetLiveFilters[id] = sourceLiveClone;

  // Le source garde ses live originaux INTACTS — restauration via le clone
  // (car _promoteLiveToPreset a retiré leur marqueur live). Le même clone est
  // ok à réassigner ici : il n'a pas été muté entre-temps.
  presetLiveFilters[_liveKey(sourceId)] = JSON.parse(JSON.stringify(sourceLiveClone));
  savePresetLiveFilters();

  // Switch actif via applyPreset pour que l'hydratation re-fasse les live
  // hérités dans le DOM. applyPreset va appeler _syncLiveSlotFromActiveChips
  // avec activeId = sourceId AVANT le switch — mais nos slots présistés sont
  // déjà corrects, et la sync va écraser avec l'état post-promotion (tout
  // glow, 0 live). Donc on réécrase nous-mêmes à la fin. Voir anti-trap
  // ci-dessus.
  applyPreset(id);
  // Re-persister APRÈS applyPreset pour nettoyer ce que sa sync interne a
  // pu laisser dans presetLiveFilters[sourceId].
  presetLiveFilters[_liveKey(sourceId)] = JSON.parse(JSON.stringify(sourceLiveClone));
  savePresetLiveFilters();

  renderPresetList();
  refreshPresetCompareDropdowns();
  renderMobilePresetControls();
  _closeSaveDropdown();
  invalidateFilterCache();
  _refreshChipDerivedUI();
  // Auto-open the tune panel so the user can rename the fresh "Custom Pn" inline.
  setTimeout(() => {
    const btn = document.getElementById('tune-' + id);
    if (btn && typeof toggleTunePanel === 'function') {
      const evt = new Event('click');
      toggleTunePanel(id, evt);
      if (typeof _poEditPreset === 'function') _poEditPreset(id);
    }
  }, 0);
  _flashSaveConfirm('✓ Preset created');
}

function _flashSaveConfirm(text) {
  const btn = document.querySelector('.filters-save-main, .filters-save-new');
  if (!btn) return;
  const orig = btn.textContent;
  btn.textContent = text;
  btn.disabled = true;
  setTimeout(() => { btn.textContent = orig; btn.disabled = false; }, 1200);
}

function _getPresetStats(presetId) {
  const p = PRESETS.find(x => x.id === presetId);
  if (!p) return null;

  // Live-state simulation: use the preset's LIVE slot (chips + customChips +
  // comboFilters + tpConfig) rather than the snapshot. Matches what the user
  // sees in Statistics Overview when this preset is active. BE-TP / BE-SL stay
  // in (Dataset A obsolete: they behave like TP / SL — labels are visual only).
  const snap = presetSnapshots[presetId];
  const live = getPresetLiveSlot(presetId);

  // Filter source: live slot reflects snapshot+modifications after applyPreset
  // hydration, so it's canonical. Fall back to snapshot if the live slot is
  // empty (preset never activated since boot).
  const hasLiveContent = (slot) => {
    const c = slot?.chips || {};
    for (const k of Object.keys(c)) {
      if ((c[k].included?.length || 0) + (c[k].excluded?.length || 0) > 0) return true;
    }
    const cc = slot?.customChips || {};
    for (const k of Object.keys(cc)) {
      if ((cc[k].included?.length || 0) + (cc[k].excluded?.length || 0) > 0) return true;
    }
    return false;
  };
  const filterSource = hasLiveContent(live) ? live : (snap || _blankSnapshot());

  let filtered = appState.trades.items.slice();
  filtered = _filterTradesBySnapshot(filtered, filterSource);

  // Per-preset TPM. computeEffectiveRR (called by calcStats) reads the
  // tpConfigArg parameter when provided.
  const presetTpConfig = _isValidTpConfigShape(live?.tpConfig)
    ? live.tpConfig
    : (_isValidTpConfigShape(snap?.tpConfig) ? snap.tpConfig : _defaultTpConfig());

  return calcStats(filtered, presetTpConfig);
}

// Persists the open/closed state of the Filter differences <details> block
// across re-renders triggered by changing either preset select. Reset to
// false when the Compare Presets section itself is collapsed.
let _presetCmpDiffOpen = false;
let _presetCmpDiffToggleWired = false;

// One-shot wiring of a delegated 'toggle' listener on #preset-cmp-table so we
// capture user clicks on the (re-rendered) <details> element. 'toggle' does
// not bubble — capture phase is required.
function _ensurePresetCmpDiffToggleWired() {
  if (_presetCmpDiffToggleWired) return;
  const tbl = document.getElementById('preset-cmp-table');
  if (!tbl) return;
  tbl.addEventListener('toggle', (ev) => {
    const det = ev.target;
    if (det && det.classList && det.classList.contains('preset-cmp-diff')) {
      _presetCmpDiffOpen = det.open;
    }
  }, true);
  _presetCmpDiffToggleWired = true;
}

// Compares chip filters (native + custom) between two presets and returns a
// collapsible <details> block listing dimensions where included/excluded sets
// differ. Each diff row shows values present in P_A but not P_B (and vice
// versa) for a given dim×kind (kind = "incl" or "excl"). Custom chips are
// surfaced via their user-facing label when available.
function _buildPresetFilterDiff(pA, pB, idA, idB) {
  const snapA = presetSnapshots[idA];
  const snapB = presetSnapshots[idB];
  if (!snapA || !snapB) return '';

  const customProps = (typeof loadCustomProps === 'function') ? loadCustomProps() : [];
  const customLabelByKey = Object.create(null);
  for (const p of customProps) customLabelByKey[p.key] = p.name || p.label || p.key;

  const diffRows = [];

  const aChips = snapA.chips || {};
  const bChips = snapB.chips || {};
  const allDims = new Set([...Object.keys(aChips), ...Object.keys(bChips)]);
  allDims.forEach(dim => {
    const a = aChips[dim] || { included: [], excluded: [] };
    const b = bChips[dim] || { included: [], excluded: [] };
    ['included', 'excluded'].forEach(kind => {
      const setA = new Set(a[kind] || []);
      const setB = new Set(b[kind] || []);
      const onlyA = [...setA].filter(v => !setB.has(v));
      const onlyB = [...setB].filter(v => !setA.has(v));
      if (onlyA.length || onlyB.length) {
        diffRows.push({
          dim,
          dimLabel: dim,
          kind: kind === 'included' ? 'incl' : 'excl',
          onlyA,
          onlyB,
        });
      }
    });
  });

  const aCustom = snapA.customChips || {};
  const bCustom = snapB.customChips || {};
  const allCustomKeys = new Set([...Object.keys(aCustom), ...Object.keys(bCustom)]);
  allCustomKeys.forEach(key => {
    const a = aCustom[key] || { included: [], excluded: [] };
    const b = bCustom[key] || { included: [], excluded: [] };
    ['included', 'excluded'].forEach(kind => {
      const setA = new Set(a[kind] || []);
      const setB = new Set(b[kind] || []);
      const onlyA = [...setA].filter(v => !setB.has(v));
      const onlyB = [...setB].filter(v => !setA.has(v));
      if (onlyA.length || onlyB.length) {
        diffRows.push({
          dim: key,
          dimLabel: customLabelByKey[key] || key,
          kind: kind === 'included' ? 'incl' : 'excl',
          onlyA,
          onlyB,
        });
      }
    });
  });

  const hasAnyFilter = (snap) => {
    const c = snap.chips || {};
    for (const k of Object.keys(c)) {
      if ((c[k].included?.length || 0) + (c[k].excluded?.length || 0) > 0) return true;
    }
    const cc = snap.customChips || {};
    for (const k of Object.keys(cc)) {
      if ((cc[k].included?.length || 0) + (cc[k].excluded?.length || 0) > 0) return true;
    }
    return false;
  };

  const aHas = hasAnyFilter(snapA);
  const bHas = hasAnyFilter(snapB);

  let inner;
  if (!aHas && !bHas) {
    inner = `<div class="preset-cmp-diff-empty">No filters</div>`;
  } else if (!diffRows.length) {
    inner = `<div class="preset-cmp-diff-empty">Identical filters</div>`;
  } else {
    diffRows.sort((x, y) => {
      if (x.dimLabel !== y.dimLabel) return x.dimLabel.localeCompare(y.dimLabel);
      return x.kind.localeCompare(y.kind);
    });
    const rowsHtml = diffRows.map(r => {
      const a = r.onlyA.length ? r.onlyA.join(', ') : '—';
      const b = r.onlyB.length ? r.onlyB.join(', ') : '—';
      return `<div class="preset-cmp-diff-row">
        <span class="preset-cmp-diff-dim">${_escapeHtml(r.dimLabel)} (${r.kind})</span>
        <span class="preset-cmp-diff-cell" style="color:var(--gold)">${_escapeHtml(a)}</span>
        <span class="preset-cmp-diff-cell" style="color:var(--b)">${_escapeHtml(b)}</span>
      </div>`;
    }).join('');
    inner = `
      <div class="preset-cmp-diff-header">
        <span>Dimension</span>
        <span style="color:var(--gold)">P${_getPresetDisplayNum(idA)} only</span>
        <span style="color:var(--b)">P${_getPresetDisplayNum(idB)} only</span>
      </div>
      ${rowsHtml}
    `;
  }

  const openAttr = _presetCmpDiffOpen ? ' open' : '';
  return `
    <details class="preset-cmp-diff"${openAttr}>
      <summary class="preset-cmp-diff-summary">Filter differences</summary>
      <div class="preset-cmp-diff-body">${inner}</div>
    </details>
  `;
}

// Returns the visible label for a preset's TPM, mirroring the topbar TPM
// badge format. Used by Compare Presets to show TP Mode as the first table row.
function _formatPresetTpmLabel(presetId) {
  const live = (typeof getPresetLiveSlot === 'function') ? getPresetLiveSlot(presetId) : null;
  const tpc = live?.tpConfig;
  if (!tpc || !tpc.mode) return '⚓ Fixed';

  if (tpc.mode === 'fixed') {
    // Show ORR bubble value if active for this preset (mutex: an active ORR
    // bubble forces TPM to Fixed). Rendered on a second line below "Fixed"
    // — the cell HTML is injected via innerHTML so <br> works.
    const rrMin = (typeof live?.rrMinFilter === 'number') ? live.rrMinFilter : null;
    if (rrMin !== null) {
      const fmtR = v => {
        const s = (typeof v === 'number' && Number.isFinite(v)) ? v.toFixed(2) : '0';
        return s.replace(/\.?0+$/, '') + 'R';
      };
      return `⚓ Fixed<br>${fmtR(rrMin)}`;
    }
    return '⚓ Fixed';
  }

  if (tpc.mode === 'multi' && tpc.multi) {
    const m = tpc.multi;
    const n = m.tpCount === 3 ? 3 : 2;
    const parts = [];
    parts.push(Math.round(m.partials.tp1 || 0));
    parts.push(Math.round(m.partials.tp2 || 0));
    if (n === 3) parts.push(Math.round(m.partials.tp3 || 0));
    return `🪜 Multi ${parts.join('/')}`;
  }

  if (tpc.mode === 'personalised' && tpc.personalised) {
    const ps = tpc.personalised;
    const n = ps.tpCount === 3 ? 3 : 2;
    // Custom: show targets + partials. Trim trailing zeros (2.40 → 2.4, 2.0 → 2).
    const fmtR = v => {
      const s = (typeof v === 'number' && Number.isFinite(v)) ? v.toFixed(2) : '0';
      return s.replace(/\.?0+$/, '') + 'R';
    };
    const targets = [];
    const partials = [];
    targets.push(fmtR(ps.targets.tp1));
    targets.push(fmtR(ps.targets.tp2));
    partials.push(Math.round(ps.partials.tp1 || 0));
    partials.push(Math.round(ps.partials.tp2 || 0));
    if (n === 3) {
      targets.push(fmtR(ps.targets.tp3));
      partials.push(Math.round(ps.partials.tp3 || 0));
    }
    return `⚡ Custom ${targets.join('/')} · ${partials.join('/')}`;
  }

  return '⚓ Fixed';
}

function runPresetCompare() {
  const idA = parseInt(document.getElementById('pcmp-a')?.value ?? 0);
  const idB = parseInt(document.getElementById('pcmp-b')?.value ?? 0);
  const pA  = PRESETS.find(x => x.id === idA);
  const pB  = PRESETS.find(x => x.id === idB);
  const sA  = _getPresetStats(idA);
  const sB  = _getPresetStats(idB);
  const tbl = document.getElementById('preset-cmp-table');
  if (!tbl) return;

  if (!sA || !sB) {
    tbl.innerHTML = '<div style="color:var(--dim);font-size:9px;padding:8px 0">Not enough data</div>';
    return;
  }

  const fmt = (v, suffix='', dec=2) => v == null ? '—' : (v >= 0 ? '+' : '') + v.toFixed(dec) + suffix;
  const fmtN = v => v == null ? '—' : String(Math.round(v));
  const fmtPct = v => v == null ? '—' : v.toFixed(1) + '%';
  const fmtPF  = v => v == null ? '—' : (v >= 9.99 ? '∞' : v.toFixed(2));

  // Delta = A - B (convention aligned with tfRenderKpiDeltas and the temporal
  // compare table). A positive delta means P_A is larger than P_B. "Better"
  // still depends on metric polarity: pol=1 means higher is better
  // (positive→green); pol=-1 means lower is better (Max DD, Max Loss Streak).
  const delta = (a, b, pol=1, suffix='', dec=2) => {
    if (a == null || b == null) return '<span class="pcmp-neu">—</span>';
    const d = a - b;
    if (Math.abs(d) < 0.0001) return '<span class="pcmp-neu">=</span>';
    const better = pol === 1 ? d > 0 : d < 0;
    const cls = better ? 'pcmp-pos' : 'pcmp-neg';
    const arrow = d > 0 ? '▲' : '▼';
    return `<span class="${cls}">${arrow}${Math.abs(d).toFixed(dec)}${suffix}</span>`;
  };

  const tpmA = _formatPresetTpmLabel(idA);
  const tpmB = _formatPresetTpmLabel(idB);
  const rows = [
    ['TP Mode', tpmA, tpmB, '<span class="pcmp-neu">—</span>'],
    ['Trades', fmtN(sA.n),  fmtN(sB.n),   delta(sA.n,  sB.n,  1, '', 0)],
    ['Win Rate', fmtPct(sA.wr), fmtPct(sB.wr), delta(sA.wr, sB.wr, 1, 'pts', 1)],
    ['Avg R',   fmt(sA.ev,'R',4), fmt(sB.ev,'R',4), delta(sA.ev, sB.ev, 1, 'R', 4)],
    ['Total R', fmt(sA.totalR,'R',1), fmt(sB.totalR,'R',1), delta(sA.totalR, sB.totalR, 1, 'R', 1)],
    ['PF',      fmtPF(sA.pf), fmtPF(sB.pf), delta(sA.pf, sB.pf, 1, '', 2)],
    ['Max DD',  sA.maxDD.toFixed(1)+'R', sB.maxDD.toFixed(1)+'R', delta(sA.maxDD, sB.maxDD, 1, 'R', 1)],
    ['MaxW',    fmtN(sA.maxW), fmtN(sB.maxW), delta(sA.maxW, sB.maxW, 1, '', 0)],
    ['MaxL',    fmtN(sA.maxL) + (sA.maxConsecLossR !== null ? ' / '+sA.maxConsecLossR.toFixed(1)+'R' : ''), fmtN(sB.maxL) + (sB.maxConsecLossR !== null ? ' / '+sB.maxConsecLossR.toFixed(1)+'R' : ''), delta(sA.maxL, sB.maxL, -1, '', 0)],
  ];

  const nameA = pA?.label.slice(0, 10) || `P${_getPresetDisplayNum(idA)}`;
  const nameB = pB?.label.slice(0, 10) || `P${_getPresetDisplayNum(idB)}`;

  const diffHtml = _buildPresetFilterDiff(pA, pB, idA, idB);

  tbl.innerHTML = `
    <div class="preset-cmp-header preset-cmp-header-4col">
      <span>Metric</span>
      <span>P${_getPresetDisplayNum(idA)}</span>
      <span>P${_getPresetDisplayNum(idB)}</span>
      <span>Δ</span>
    </div>
    <div class="preset-cmp-subheader-4col">
      <span></span>
      <span style="color:var(--gold)">${nameA}</span>
      <span style="color:var(--b)">${nameB}</span>
      <span></span>
    </div>
    ${rows.map(([label, vA, vB, d]) => {
      const isTpm = label === 'TP Mode';
      const valCls = `preset-cmp-val${isTpm ? ' preset-cmp-tpm-cell' : ''}`;
      return `
      <div class="preset-cmp-row preset-cmp-row-4col">
        <span class="preset-cmp-label">${label}</span>
        <span class="${valCls}" style="color:var(--gold)">${vA}</span>
        <span class="${valCls}" style="color:var(--b)">${vB}</span>
        <span class="preset-cmp-delta">${d}</span>
      </div>`;
    }).join('')}
    ${diffHtml}
  `;

  _ensurePresetCmpDiffToggleWired();
}


// ══════════════════════════════════════════════════════
// POST-DRAWDOWN RECOVERY WIDGET
// ══════════════════════════════════════════════════════
let _recoveryChart = null;
let _recoveryActiveIdx = null;

function renderRecovery(trades) {
  const canvas = getByIdSafe('recoveryCanvas');
  if (!canvas) return;
  if (_recoveryChart) { _recoveryChart.destroy(); _recoveryChart = null; }
  const RECOVERY_WRAP = '.chart-card[data-gs-id="w-recovery"] .canvas-stage';
  if (!trades.length) {
    renderCanvasEmptyState(RECOVERY_WRAP, ['recoveryCanvas']);
    return;
  }
  clearCanvasEmptyState(RECOVERY_WRAP);
  if (trades.length < 5 || !hasChartJs()) return;

  // Sort by date+hour
  const sorted = _sortTradesChronological(trades);

  // Find all drawdown recovery sequences
  // A "recovery" = trades from a local peak drop to recovery back to that peak
  const tpConfig = appState.ui.tpConfig;
  let eq = 0, peak = 0;
  const recoveries = [];
  let inDD = false, ddStart = 0, ddPeak = 0, ddDepth = 0, ddTroughIdx = 0;

  sorted.forEach((t, i) => {
    eq += computeEffectiveRR(t, tpConfig);
    if (eq >= peak) {
      if (inDD && i - ddStart > 0) {
        recoveries.push({
          ddDepth:  Math.abs(ddDepth),
          trades:   i - ddStart,
          rToRecover: eq - ddPeak,
          startIdx: ddStart,
          troughIdx: ddTroughIdx,
          endIdx:   i,
        });
      }
      peak = eq;
      inDD = false;
    } else {
      if (!inDD) { inDD = true; ddStart = i; ddPeak = peak; ddDepth = eq - peak; ddTroughIdx = i; }
      else if (eq - peak < ddDepth) { ddDepth = eq - peak; ddTroughIdx = i; }
    }
  });

  // If dataset ends inside an active drawdown (not yet recovered),
  // add a dedicated point with isActive: true. This ensures the widget
  // reflects the Max DD from calcStats, which includes unrecovered DDs.
  if (inDD) {
    recoveries.push({
      ddDepth:    Math.abs(ddDepth),
      trades:     sorted.length - ddStart,
      rToRecover: null,
      startIdx:   ddStart,
      troughIdx:  ddTroughIdx,
      endIdx:     sorted.length - 1,
      isActive:   true,
    });
  }

  if (!recoveries.length) {
    canvas.getContext?.('2d')?.clearRect(0, 0, canvas.width, canvas.height);
    return;
  }

  const recoveredPoints = recoveries.filter(r => !r.isActive);
  const activePoints    = recoveries.filter(r =>  r.isActive);

  // Scatter: x = DD depth, y = trades to recover — group identical (x,y) points
  const pointMap = new Map();
  recoveredPoints.forEach(r => {
    const key = `${r.ddDepth.toFixed(2)}|${r.trades}`;
    if (!pointMap.has(key)) pointMap.set(key, { x: +r.ddDepth.toFixed(2), y: r.trades, n: 0, occurrences: [] });
    const entry = pointMap.get(key);
    entry.n++;
    entry.occurrences.push(r);
  });
  const data = [...pointMap.values()];
  const activeData = activePoints.map(r => ({
    x: +r.ddDepth.toFixed(2),
    y: r.trades,
    n: 1,
    isActive: true,
    occurrences: [r],
  }));
  const baseForAvg = recoveredPoints.length ? recoveredPoints : recoveries;
  const avgTrades = baseForAvg.reduce((s,r) => s+r.trades, 0) / baseForAvg.length;
  const avgDepth  = baseForAvg.reduce((s,r) => s+r.ddDepth, 0) / baseForAvg.length;

  // X-axis max includes active point if its ddDepth exceeds any recovered DD
  const maxRecoveredDepth = data.reduce((m, d) => Math.max(m, d.x), 0);
  const maxActiveDepth    = activeData.reduce((m, d) => Math.max(m, d.x), 0);
  const xAxisMax = Math.max(maxRecoveredDepth, maxActiveDepth) * 1.05 || undefined;

  canvas.removeAttribute('width'); canvas.removeAttribute('height');

  const _recSelCol = tc('--white') || '#ffffff';
  const _mkRecBorderColors = () => data.map((_, i) => i === _recoveryActiveIdx ? _recSelCol : 'transparent');
  const _mkRecBorderWidths = () => data.map((_, i) => i === _recoveryActiveIdx ? 3 : 0);

  _recoveryChart = new Chart(canvas, {
    type: 'scatter',
    data: { datasets: [
      {
        label: 'Recovered',
        data,
        backgroundColor: data.map(d => tc('--r') + (d.n > 1 ? 'cc' : '99')),
        pointRadius: data.map(d => Math.min(4 + d.n * 1.5, 12)),
        pointHoverRadius: data.map(d => Math.min(6 + d.n * 1.5, 14)),
        pointBorderColor: _mkRecBorderColors(),
        pointBorderWidth: _mkRecBorderWidths(),
        pointHoverBorderColor: _mkRecBorderColors(),
        pointHoverBorderWidth: _mkRecBorderWidths(),
      },
      {
        label: 'Current DD (active)',
        data: activeData,
        backgroundColor: activeData.map(() => tc('--r') + '99'),
        pointStyle: 'crossRot',
        pointRadius: 12,
        pointHoverRadius: 18,
        pointBorderWidth: 2,
        pointHoverBorderWidth: 3,
        pointBorderColor: tc('--gold'),
        pointHoverBorderColor: tc('--gold'),
      },
    ]},
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      onClick: (ev, elements, chart) => {
        if (!elements || !elements.length) return;
        const { datasetIndex, index: idx } = elements[0];
        const dsData = chart.data.datasets[datasetIndex].data;
        const bucket = dsData[idx];
        if (!bucket) return;

        openRecoveryDrawer(bucket, sorted, { isActive: !!bucket.isActive });

        // Selection highlight: recovered dataset only (index 0)
        if (datasetIndex === 0) {
          _recoveryActiveIdx = idx;
          const ds = chart.data.datasets[0];
          ds.pointBorderColor      = ds.data.map((_, i) => i === idx ? _recSelCol : 'transparent');
          ds.pointBorderWidth      = ds.data.map((_, i) => i === idx ? 3 : 0);
          ds.pointHoverBorderColor = ds.pointBorderColor.slice();
          ds.pointHoverBorderWidth = ds.pointBorderWidth.slice();
          chart.update();
        }
      },
      onHover: (ev, elements) => {
        const target = ev?.native?.target;
        if (target) target.style.cursor = elements && elements.length ? 'pointer' : 'default';
      },
      plugins: {
        legend: { display: true, labels: { color: tc('--dim'), usePointStyle: true, font: { size: _chartTipFs(), family: '"DM Mono",monospace' } } },
        tooltip: { bodyFont: { size: _chartTipFs() }, titleFont: { size: _chartTipFs() }, callbacks: {
          label: ctx => {
            const d = ctx.raw;
            if (d && d.isActive) {
              return ` Active DD: −${ctx.parsed.x}R · ${ctx.parsed.y} trades since peak · Not yet recovered`;
            }
            const occ = d.n > 1 ? ` · ${d.n} occurrences` : ` · 1 occurrence`;
            return ` DD: −${ctx.parsed.x}R → ${ctx.parsed.y} trades to recover${occ}`;
          }
        }},
        annotation: { /* handled in plugin below */ }
      },
      scales: {
        x: {
          title: { display: true, text: 'DD Depth (R)', color: tc('--dim'), font: { size: parseFloat(tc('--typo-recovery-title-size')), family: '"DM Mono",monospace' } },
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { size: parseFloat(tc('--typo-recovery-tick-size')), family: '"DM Mono",monospace' } },
          max: xAxisMax,
        },
        y: {
          title: { display: true, text: 'Trades to recover', color: tc('--dim'), font: { size: parseFloat(tc('--typo-recovery-title-size')), family: '"DM Mono",monospace' } },
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { size: parseFloat(tc('--typo-recovery-tick-size')), family: '"DM Mono",monospace' }, stepSize: 1 },
          beginAtZero: true,
        }
      }
    },
    plugins: [{
      id: 'recoveryAvg',
      afterDraw(chart) {
        const { ctx, chartArea, scales: { x, y } } = chart;
        ctx.save();
        // Average lines
        const ax = x.getPixelForValue(avgDepth);
        const ay = y.getPixelForValue(avgTrades);
        [[ax, chartArea.top, ax, chartArea.bottom, tc('--r')],
         [chartArea.left, ay, chartArea.right, ay, tc('--gold')]].forEach(([x1,y1,x2,y2,col]) => {
          ctx.strokeStyle = col + '88'; ctx.lineWidth = 1; ctx.setLineDash([4,3]);
          ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
        });
        ctx.setLineDash([]);
        ctx.fillStyle = tc('--dim'); ctx.font = `${tc('--typo-recovery-annot-size')} DM Mono, monospace`; ctx.textAlign = 'left';
        ctx.fillText('avg DD: −'+avgDepth.toFixed(1)+'R', chartArea.left+4, ay-4);
        ctx.fillText('avg recovery: '+avgTrades.toFixed(0)+' trades', ax+4, chartArea.top+12);
        ctx.restore();
      }
    }]
  });
}

// ══════════════════════════════════════════════════════
// ROLLING WIN RATE WIDGET
// ══════════════════════════════════════════════════════
let _rollingWRChart = null;

function renderRollingWR(trades) {
  const canvas = getByIdSafe('rollingWRCanvas');
  if (!canvas) return;
  if (_rollingWRChart) { _rollingWRChart.destroy(); _rollingWRChart = null; }
  const ROLLING_WR_WRAP = '.chart-card[data-gs-id="w-rollingwr"] .canvas-stage';
  if (!trades.length) {
    renderCanvasEmptyState(ROLLING_WR_WRAP, ['rollingWRCanvas']);
    return;
  }
  clearCanvasEmptyState(ROLLING_WR_WRAP);
  const N = parseInt(getByIdSafe('rolling-wr-window')?.value || 20);
  if (trades.length < N || !hasChartJs()) return;

  const sorted = _sortTradesChronological(trades);

  // Rolling WR: for each trade i, WR of last N trades
  const tpConfig = appState.ui.tpConfig;
  const rollingWR = [], equitySeries = [];
  let eq = 0;
  sorted.forEach((t, i) => {
    eq += computeEffectiveRR(t, tpConfig);
    equitySeries.push(+eq.toFixed(2));
    if (i >= N - 1) {
      const window = sorted.slice(i - N + 1, i + 1);
      const wins = window.filter(isWinner).length;
      rollingWR.push(+(wins / N * 100).toFixed(1));
    } else {
      rollingWR.push(null);
    }
  });

  const labels = sorted.map((t, i) => i % Math.max(1, Math.floor(sorted.length/10)) === 0
    ? (t.date || '').slice(5)
    : '');

  canvas.removeAttribute('width'); canvas.removeAttribute('height');

  _rollingWRChart = new Chart(canvas, {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: `WR ${N} trades`,
          data: rollingWR,
          borderColor: tc('--gold'),
          backgroundColor: tc('--gold') + '22',
          borderWidth: 1.5,
          pointRadius: 0,
          fill: false,
          yAxisID: 'yWR',
          tension: 0.3,
          spanGaps: true,
        },
        {
          label: 'Equity',
          data: equitySeries,
          borderColor: tc('--g'),
          backgroundColor: tc('--g') + '15',
          borderWidth: 1,
          pointRadius: 0,
          fill: true,
          yAxisID: 'yEq',
          tension: 0.2,
        },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: true, labels: { color: tc('--dim'), font: { size: 9, family: '"DM Mono",monospace' }, boxWidth: 12 } },
        tooltip: { bodyFont: { size: _chartTipFs() }, titleFont: { size: _chartTipFs() }, callbacks: {
          label: ctx => ctx.datasetIndex === 0
            ? ` WR: ${ctx.raw}%`
            : ` Equity: ${ctx.raw >= 0 ? '+' : ''}${ctx.raw}R`
        }}
      },
      scales: {
        x:    { display: false },
        yWR:  { position: 'right', min: 0, max: 100,
                grid: { color: tc('--line') },
                ticks: { color: tc('--gold'), font:{size:9,family:'"DM Mono",monospace'}, callback: v => v+'%' } },
        yEq:  { position: 'left',
                grid: { color: tc('--line') },
                ticks: { color: tc('--g'), font:{size:9,family:'"DM Mono",monospace'}, callback: v => (v>=0?'+':'')+v+'R' } },
      }
    },
    plugins: [{
      id: 'wrBaseline',
      afterDraw(chart) {
        const { ctx, chartArea, scales: { yWR } } = chart;
        const y50 = yWR.getPixelForValue(50);
        ctx.save();
        ctx.strokeStyle = tc('--dim') + '66'; ctx.lineWidth = 1; ctx.setLineDash([3,4]);
        ctx.beginPath(); ctx.moveTo(chartArea.left, y50); ctx.lineTo(chartArea.right, y50); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = tc('--dim'); ctx.font = '8px DM Mono,monospace'; ctx.textAlign = 'right';
        ctx.fillText('50%', chartArea.right - 2, y50 - 3);
        ctx.restore();
      }
    }]
  });
}

// ══════════════════════════════════════════════════════
// OPTIMAL RR ANALYSIS WIDGET
// ══════════════════════════════════════════════════════
let _optimalRRChart = null;

// Simulation mode for the Optimal RR widget:
//   'be-fallback' (default): winning trade that didn't reach simulated TP but
//      did reach TP1 → treated as BE exit (0R). Trades that didn't reach TP1
//      are counted as full losses.
//   'strict-loss': any winning trade that didn't reach the simulated TP is
//      a full loss, regardless of rrMax.
let _orrSimMode = 'be-fallback';
const _ORR_SIM_MODE_LS_KEY = 'flipping_orr_sim_mode';
try {
  const saved = localStorage.getItem(_ORR_SIM_MODE_LS_KEY);
  if (saved === 'be-fallback' || saved === 'strict-loss') _orrSimMode = saved;
} catch (e) {}


/**
 * Simulate different TP levels and compute EV, winrate, PF for each.
 *
 * COUNTERFACTUAL SIMULATION — rMax dominates over realized r.
 * The realized r reflects the *current* execution plan (fixed TP 2.4R + BE
 * management). When we ask "what if my TP had been `tp` instead?", only the
 * price excursion (rrMax) matters. A trade that reached rrMax ≥ tp would have
 * been a WIN under the simulated plan, even if BE management later turned the
 * realized r negative (BE-SL pattern). Putting `r < 0` first would
 * systematically misclassify these BE-SL-with-high-rrMax trades and bias the
 * curve downward.
 *
 * BE-AWARE BRANCH (BE-TP / BE-SL trades):
 * For trades whose outcome is BE-TP or BE-SL, the position was closed at BE
 * because price retraced past the BE trigger before reaching the simulated TP.
 * `rrMax` for these trades reflects price action AFTER the BE retrace (cosmetic)
 * and must NOT be used to credit a WIN. We instead read the actual protection
 * level (`beTriggerR`, parsed from trade.beManagement) and credit:
 *   - tp ≤ beTriggerR                → WIN  (+tp R) : leg captured before retrace
 *   - tp > beTriggerR                → BE-out (0R)  : closed at BE before reaching tp
 *   - beTriggerR null/unparseable    → BE-out (0R)  : matches _poSimTradeBeAware
 * This keeps the ORR curve numerically aligned with the Partial Optimizer
 * (`_poSimTradeBeAware`) and `computeEffectiveRR` personalised mode at any
 * simulated TP. Without this branch the ORR systematically over-credited
 * BE-TP/BE-SL with high rrMax (as WIN) and under-credited those with low
 * rrMax (as LOSS) — both should be 0R.
 *
 * Classification priority per trade at a given simulated TP (`tp`):
 *   0. outcome ∈ {BE-TP, BE-SL}    → BE-aware branch (see above)
 *   1. rMax ≥ tp                   → WIN    (reached simulated TP — counterfactually)
 *   2. r < 0  (and rMax < tp)      → LOSS   (real loser AND wouldn't have hit tp)
 *   3. rMax < _SYSTEM_TP_R         → LOSS   (didn't reach TP1, would have lost)
 *   4. _SYSTEM_TP_R ≤ rMax < tp    → BE-out in BE Fallback (0R)
 *                                  → LOSS   in Strict Loss (−1R)
 *   5. otherwise (no usable rMax)  → EXCLUDED
 *
 * `rMax` = raw trade.rrMax when available; for trades without rrMax, we only
 * infer from realized r if r > 0 (that gives a safe lower bound). For BE
 * trades (r = 0) with no rrMax, we genuinely don't know how far they reached,
 * so they fall through to EXCLUDED.
 *
 * The input `trades` is expected to have already been filtered upstream by
 * getFilteredForORR() — preset/chips/temporal + BE Management tag exclusion
 * have all been applied.
 */
function computeOptimalRR(trades) {
  if (!trades.length) return [];

  // 12 specific TP candidates: every 0.5R + 2.4R (main TP) + 3.3R (strategy TP)
  const steps = [0.5, 1.0, 1.5, 2.0, 2.4, 2.5, 3.0, 3.3, 3.5, 4.0, 4.5, 5.0];

  const hasRRMax = trades.some(t => t.rrMax !== null && t.rrMax !== undefined && Number.isFinite(t.rrMax));

  const results = steps.map(tp => {
    let wins = 0, losses = 0, beOut = 0, excluded = 0;

    for (let i = 0; i < trades.length; i++) {
      const t    = trades[i];
      const outcome = t?.outcome;

      // BE-aware branch — outcome- and mode-dependent classification:
      //   • Flipping BE BE-TP : "pure-tp-no-sl" — bucket per _orrSimMode,
      //     no rrMax<TP1 → LOSS rule (a BE-TP can never be a real loser).
      //   • Flipping BE BE-SL with reach<2.4 : standard SL pur classification
      //     with the bucket, BUT skipping the r<0 priority rule so trades
      //     with r=-1 (chez Max) AND rrMax in [TP1, tp) hit the bucket
      //     (beOut in be-fallback) instead of being lumped into LOSS. No
      //     excursion data → defer to journaled r (real loser).
      //   • Other (be-fallback BE-TP / BE-SL, applyBEAware) route through
      //     _resolveBeR.
      if (outcome === 'BE-TP' || outcome === 'BE-SL') {
        const decision = _resolveBEDecision(t);
        if (decision.fallbackVariant === 'pure-tp-no-sl' && t.outcome === 'BE-TP') {
          const r = typeof t.r === 'number' ? t.r : NaN;
          const rrMaxRaw = t.rrMax;
          const rMax = Number.isFinite(rrMaxRaw)
            ? rrMaxRaw
            : (Number.isFinite(r) && r > 0 ? r : null);
          if (rMax !== null && rMax >= tp) {
            wins++;
          } else if (rMax !== null) {
            if (_orrSimMode === 'strict-loss') losses++;
            else                               beOut++;
          } else {
            excluded++;
          }
          continue;
        }
        if (decision.fallbackToNoBE && t.outcome === 'BE-SL') {
          const r = typeof t.r === 'number' ? t.r : NaN;
          const rrMaxRaw = t.rrMax;
          const rMax = Number.isFinite(rrMaxRaw)
            ? rrMaxRaw
            : (Number.isFinite(r) && r > 0 ? r : null);
          if (rMax !== null && rMax >= tp) {
            wins++;
          } else if (rMax !== null && rMax < _SYSTEM_TP_R) {
            losses++;
          } else if (rMax !== null) {
            // [TP1, tp) bucket per _orrSimMode (skip r<0 priority).
            if (_orrSimMode === 'strict-loss') losses++;
            else                               beOut++;
          } else if (Number.isFinite(r) && r < 0) {
            // No excursion data — defer to journaled r (real loser).
            losses++;
          } else {
            excluded++;
          }
          continue;
        }
        // Default BE handling routes through _resolveBeR.
        const beR = _resolveBeR(t, [{ lv: tp, pct: 1 }], _getTradeReachR(t));
        if (beR > 0)      wins++;
        else if (beR < 0) losses++;
        else              beOut++;
        continue;
      }

      const r    = typeof t?.r === 'number' ? t.r : NaN;
      const rrMaxRaw = t?.rrMax;
      const rMax = Number.isFinite(rrMaxRaw)
        ? rrMaxRaw
        : (Number.isFinite(r) && r > 0 ? r : null);

      // Priority order matters — see header comment. rMax ≥ tp must be checked
      // before r < 0 so BE-SL trades with high rrMax aren't misclassified.
      if (rMax !== null && rMax >= tp) {
        wins++;
      } else if (Number.isFinite(r) && r < 0) {
        losses++;
      } else if (rMax !== null && rMax < _SYSTEM_TP_R) {
        losses++;
      } else if (rMax !== null) {
        // rMax ∈ [TP1, tp) — BE-out in BE Fallback, LOSS in Strict Loss
        if (_orrSimMode === 'strict-loss') losses++;
        else                               beOut++;
      } else {
        excluded++;
      }
    }

    const counted = wins + losses;
    const cumR    = wins * tp - losses * 1;
    // WR denominator = full input set (wins + losses + beOut + excluded), so
    // ORR widget WR matches the sticky-bar KPI (calcStats.wr = w/n) and the
    // Partial Optimizer's `wr = posCount / n`. Using `counted` would inflate
    // the WR vs the rest of the dashboard whenever beOut > 0 (BE Fallback) or
    // BE-aware trades close at BE before reaching tp.
    const total   = trades.length;
    const winrate = total > 0 ? wins / total : 0;
    const ev      = counted > 0 ? cumR / counted : 0;
    const pf      = losses > 0 ? (wins * tp) / losses : (wins > 0 ? Infinity : 0);

    return { tp, winrate, ev, pf, cumR, wins, bes: 0, losses, beOut, excluded };
  });
  results._hasRRMax = hasRRMax;
  return results;
}

function renderOptimalRRWidget(trades) {
  const canvas  = document.getElementById('optimalRRCanvas');
  const summary = document.getElementById('optimal-rr-summary');
  // Always (re)render the header control — survives widget re-mounts
  _orrRenderBeMgmtControl();
  _orrRenderSimModeControl();
  _orrRenderDatasetAWarning();
  if (!canvas || !summary) return;

  if (_optimalRRChart) { _optimalRRChart.destroy(); _optimalRRChart = null; }

  // "Filter active" badge — shown whenever the user has at least one BE
  // Management value selected for exclusion.
  const beMgmtExcluded = appState.ui.beManagementExclude || [];
  const beMgmtBadgeHtml = beMgmtExcluded.length
    ? `<div class="orr-bemgmt-active-badge">
         <span class="orr-bemgmt-active-dot"></span>
         BE Management filter · ${beMgmtExcluded.length} value${beMgmtExcluded.length > 1 ? 's' : ''} excluded
       </div>`
    : '';

  const ORR_WRAP = '.chart-card[data-gs-id="w-optimal-rr"] .canvas-stage';
  if (!trades.length) {
    summary.innerHTML = beMgmtBadgeHtml;
    renderCanvasEmptyState(ORR_WRAP, ['optimalRRCanvas']);
    return;
  }
  clearCanvasEmptyState(ORR_WRAP);

  // Sample size indicator: how many trades have a usable rrMax
  const totalTrades = trades.length;
  const tradesWithRRMax = trades.reduce(
    (n, t) => n + (t.rrMax !== null && t.rrMax !== undefined && Number.isFinite(t.rrMax) ? 1 : 0),
    0
  );
  const sampleLineStyle = "font-family:'DM Mono',monospace;font-size:9px;color:var(--dim);margin-top:6px;opacity:0.72";
  let sampleLineHtml;
  if (tradesWithRRMax === 0) {
    sampleLineHtml = `<div style="${sampleLineStyle}">No trades have rrMax — chart unavailable</div>`;
  } else if (tradesWithRRMax === totalTrades) {
    sampleLineHtml = `<div style="${sampleLineStyle}">All ${totalTrades} trades have rrMax</div>`;
  } else {
    sampleLineHtml = `<div style="${sampleLineStyle}">Based on ${tradesWithRRMax} / ${totalTrades} trades with rrMax</div>`;
  }

  // Trades without rrMax — exposed via a standalone warning button
  const tradesWithoutRRMax = trades.filter(t =>
    t.rrMax === null || t.rrMax === undefined || !Number.isFinite(t.rrMax)
  );
  window._orrTradesWithoutRRMax = tradesWithoutRRMax;
  const missingBtnHtml = tradesWithoutRRMax.length
    ? `<div class="orr-missing-row">
         <button class="orr-missing-btn" onclick="_orrOpenMissingRRMax()">⚠ ${tradesWithoutRRMax.length} sans rrMax</button>
       </div>`
    : '';

  // Skip chart entirely if no rrMax data is available
  if (tradesWithRRMax === 0) {
    summary.innerHTML = beMgmtBadgeHtml + missingBtnHtml + sampleLineHtml;
    return;
  }

  const data = computeOptimalRR(trades);
  if (!data.length) return;
  const hasRRMax = data._hasRRMax;

  // Best TP = highest EV (from current filtered data)
  let bestIdx = 0;
  for (let i = 1; i < data.length; i++) {
    if (data[i].ev > data[bestIdx].ev) bestIdx = i;
  }
  const best  = data[bestIdx];
  const maxEV = best.ev;

  // Optimal zone: extend contiguously in both directions from bestIdx
  // while EV stays within 5% of maxEV
  const zoneThresholdLow = maxEV - Math.abs(maxEV) * 0.05;
  let leftIdx  = bestIdx;
  let rightIdx = bestIdx;
  while (leftIdx  > 0               && data[leftIdx  - 1].ev >= zoneThresholdLow) leftIdx--;
  while (rightIdx < data.length - 1 && data[rightIdx + 1].ev >= zoneThresholdLow) rightIdx++;
  const plateau    = data.slice(leftIdx, rightIdx + 1);
  const plateauMin = data[leftIdx].tp;
  const plateauMax = data[rightIdx].tp;

  canvas.removeAttribute('width');
  canvas.removeAttribute('height');

  const dimColor  = tc('--dim');
  const lineColor = tc('--line');
  const accentCol = tc('--a');
  const goldCol   = tc('--gold');
  const greenCol  = tc('--g');
  const redCol    = tc('--r');
  const blueCol   = tc('--b');

  // Index of the currently-active RR filter bubble (if any) — styled distinctly
  // so the user can see which point corresponds to the active chip.
  const activeIdx = appState.ui.rrMinFilter !== null
    ? data.findIndex(d => Math.abs(d.tp - appState.ui.rrMinFilter) < 1e-9)
    : -1;

  _optimalRRChart = new Chart(canvas, {
    type: 'line',
    data: {
      labels: data.map(d => d.tp.toFixed(2) + 'R'),
      datasets: [{
        label: 'EV (R)',
        data: data.map(d => +d.ev.toFixed(4)),
        borderColor: accentCol,
        backgroundColor: accentCol + '18',
        borderWidth: 2,
        fill: true,
        tension: 0.35,
        // Active bubble (if any) takes visual priority over best-EV gold bubble.
        pointRadius: data.map((_, i) => i === activeIdx ? 9 : (i === bestIdx ? 7 : 4)),
        pointHoverRadius: data.map((_, i) => i === activeIdx ? 11 : (i === bestIdx ? 9 : 6)),
        pointBackgroundColor: data.map((d, i) =>
          i === activeIdx ? blueCol
          : i === bestIdx ? goldCol
          : (d.ev >= 0 ? greenCol : redCol)),
        pointBorderColor: data.map((d, i) =>
          i === activeIdx ? blueCol
          : i === bestIdx ? goldCol
          : (d.ev >= 0 ? greenCol : redCol)),
        pointBorderWidth: data.map((_, i) => i === activeIdx ? 3 : (i === bestIdx ? 2 : 1)),
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      onClick: (event, elements) => {
        if (!elements.length) return;
        const idx = elements[0].index;
        const d = data[idx];
        _rrFilterBubbleClick(d.tp, `≥ ${d.tp}R`);
      },
      onHover: (event, elements) => {
        event.native.target.style.cursor = elements.length ? 'pointer' : 'default';
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          bodyFont:  { size: _chartTipFs(), family: '"DM Mono",monospace' },
          titleFont: { size: _chartTipFs(), family: '"DM Mono",monospace' },
          callbacks: {
            title: ctx => 'TP = ' + ctx[0].label,
            label: ctx => {
              const d = data[ctx.dataIndex];
              const isBeFb = _orrSimMode === 'be-fallback';
              const lines = [
                ` EV: ${d.ev >= 0 ? '+' : ''}${d.ev.toFixed(3)}R`,
                ` Cumul: ${d.cumR >= 0 ? '+' : ''}${d.cumR.toFixed(1)}R`,
                ` WR: ${(d.winrate * 100).toFixed(1)}%`,
                ` PF: ${isFinite(d.pf) ? d.pf.toFixed(2) : '∞'}`,
              ];
              if (isBeFb) {
                lines.push(` W / L / BE: ${d.wins} / ${d.losses} / ${d.beOut || 0}`);
              } else {
                lines.push(` W / L: ${d.wins} / ${d.losses}`);
              }
              if (d.excluded > 0) {
                lines.push(` Excluded (no rrMax): ${d.excluded}`);
              }
              return lines;
            }
          }
        }
      },
      scales: {
        x: {
          grid:  { color: lineColor },
          ticks: { color: dimColor, font: { size: parseFloat(tc('--typo-orr-tick-size')), family: '"DM Mono",monospace' }, maxTicksLimit: 12, autoSkip: false }
        },
        y: {
          grid:  { color: lineColor },
          ticks: {
            color: dimColor,
            font:  { size: parseFloat(tc('--typo-orr-tick-size')), family: '"DM Mono",monospace' },
            callback: v => (v >= 0 ? '+' : '') + v.toFixed(2) + 'R'
          }
        }
      }
    },
    plugins: [{
      id: 'orrAnnotations',
      afterDraw(chart) {
        const { ctx, chartArea, scales } = chart;
        if (!chartArea) return;

        // Zero baseline
        const y0 = scales.y.getPixelForValue(0);
        ctx.save();
        ctx.strokeStyle = dimColor + '55';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 3]);
        ctx.beginPath();
        ctx.moveTo(chartArea.left, y0);
        ctx.lineTo(chartArea.right, y0);
        ctx.stroke();
        ctx.setLineDash([]);

        // Best TP vertical marker
        const xBest = scales.x.getPixelForValue(bestIdx);
        ctx.strokeStyle = goldCol + 'aa';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(xBest, chartArea.top);
        ctx.lineTo(xBest, chartArea.bottom);
        ctx.stroke();
        ctx.setLineDash([]);

        // Plateau shading — boundaries interpolated from EV threshold crossings
        if (plateau.length >= 1) {
          // Interpolate x where EV curve crosses zoneThresholdLow
          const interp = (iA, iB) => {
            const evA = data[iA].ev, evB = data[iB].ev;
            const t = evA === evB ? 0 : (zoneThresholdLow - evA) / (evB - evA);
            return scales.x.getPixelForValue(iA + t * (iB - iA));
          };
          const xPlatMin = leftIdx > 0
            ? interp(leftIdx, leftIdx - 1)
            : scales.x.getPixelForValue(leftIdx);
          const xPlatMax = rightIdx < data.length - 1
            ? interp(rightIdx, rightIdx + 1)
            : scales.x.getPixelForValue(rightIdx);
          ctx.fillStyle = goldCol + '18';
          ctx.fillRect(xPlatMin, chartArea.top, xPlatMax - xPlatMin, chartArea.bottom - chartArea.top);
        }

        // Reference TP markers (2.4R and 3.3R)
        const refTPs = [{ tp: 2.4, col: tc('--r') }, { tp: 3.3, col: tc('--a') }];
        refTPs.forEach(({ tp, col }) => {
          const idx = data.findIndex(d => Math.abs(d.tp - tp) < 1e-9);
          if (idx === -1) return;
          const xRef = scales.x.getPixelForValue(idx);
          // Vertical line
          ctx.strokeStyle = col + 'bb';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([2, 4]);
          ctx.beginPath();
          ctx.moveTo(xRef, chartArea.top);
          ctx.lineTo(xRef, chartArea.bottom);
          ctx.stroke();
          ctx.setLineDash([]);
          // Label at top
          ctx.fillStyle = col;
          ctx.font = `bold ${tc('--typo-orr-annot-size')} DM Mono, monospace`;
          ctx.textAlign = 'center';
          ctx.fillText(tp.toFixed(1) + 'R', xRef, chartArea.top + 10);
        });

        ctx.restore();
      }
    }]
  });

  // ── Summary block ──
  const wr = (best.winrate * 100).toFixed(1);
  const pfStr = isFinite(best.pf) ? best.pf.toFixed(2) : '∞';

  const isBeFb = _orrSimMode === 'be-fallback';

  // Reference TP stats rows
  const refRows = [2.4, 3.3].map(tp => {
    const d = data.find(r => Math.abs(r.tp - tp) < 1e-9);
    if (!d) return '';
    const col = tp === 2.4 ? 'var(--r)' : 'var(--a)';
    const evStr = (d.ev >= 0 ? '+' : '') + d.ev.toFixed(3) + 'R';
    const wrStr = (d.winrate * 100).toFixed(1) + '%';
    const cumStr = (d.cumR >= 0 ? '+' : '') + d.cumR.toFixed(2) + 'R';
    const refBeCount = isBeFb ? _getBeColumnCountAtTp(d.tp) : null;
    return `<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-top:4px;font-family:'DM Mono',monospace;opacity:0.72">
      <div style="background:var(--bg2);border-radius:4px;padding:5px 4px;text-align:center">
        <div style="font-size:7px;color:var(--dim);margin-bottom:2px">TP Ref</div>
        <div style="font-size:12px;font-weight:700;color:${col}">${tp.toFixed(1)}R</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:5px 4px;text-align:center">
        <div style="font-size:7px;color:var(--dim);margin-bottom:2px">💰 Cumul</div>
        <div style="font-size:12px;font-weight:700;color:${d.cumR >= 0 ? 'var(--g)' : 'var(--r)'}">${cumStr}</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:5px 4px;text-align:center">
        <div style="font-size:7px;color:var(--dim);margin-bottom:2px">📊 EV</div>
        <div style="font-size:12px;font-weight:700;color:${d.ev >= 0 ? 'var(--g)' : 'var(--r)'}">${evStr}</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:5px 4px;text-align:center">
        <div style="font-size:7px;color:var(--dim);margin-bottom:2px">📈 WR</div>
        <div style="font-size:12px;font-weight:700;color:var(--body)">${wrStr}</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:5px 4px;text-align:center">
        <div style="font-size:7px;color:var(--dim);margin-bottom:2px">${isBeFb ? 'W / L / BE' : 'W / L'}</div>
        <div style="font-size:11px;font-weight:700">
          <span style="color:var(--g)">${d.wins}</span>
          <span style="color:var(--dim);font-weight:400"> / </span>
          <span style="color:var(--r)">${d.losses}</span>
          ${isBeFb ? `
            <span style="color:var(--dim);font-weight:400"> / </span>
            <span style="color:var(--gold)">${refBeCount}</span>
          ` : ''}
        </div>
      </div>
    </div>`;
  }).join('');

  const plateauHtml = plateauMin !== null
    ? (() => {
        const isSingle = plateauMin === plateauMax;
        const label = 'Optimal zone';
        const hint  = 'EV within 5% of max';
        const range = isSingle ? `${plateauMin.toFixed(2)}R` : `${plateauMin.toFixed(2)}R → ${plateauMax.toFixed(2)}R`;
        return `<div style="margin-top:6px;padding:5px 10px;background:var(--bg2);border-radius:4px;font-family:'DM Mono',monospace;font-size:9px;color:var(--dim);display:flex;align-items:center;gap:6px">
          <span style="color:var(--gold);font-size:11px">${isSingle ? '◆' : '▬'}</span>
          <span>${label}: <strong style="color:var(--body)">${range}</strong></span>
          <span style="margin-left:4px;opacity:.65">(${hint})</span>
        </div>`;
      })()
    : '';

  const dataQualityBadge = !hasRRMax
    ? `<div style="margin-top:5px;padding:4px 8px;background:var(--gold)18;border:1px solid var(--gold)44;border-radius:4px;font-family:'DM Mono',monospace;font-size:8px;color:var(--gold)">
        ⚠ Simulation based on outcome (RR max not provided) — approximate results
      </div>`
    : '';

  // BE-out row — visible in BE Fallback mode when the best (or active) bubble
  // has trades in the [TP1, tp) band. Reports the active bubble when one is
  // selected, otherwise the best-EV bubble.
  const beOutSource = activeIdx >= 0 ? data[activeIdx] : best;
  const beOutLine = (_orrSimMode === 'be-fallback' && beOutSource?.beOut > 0)
    ? `<div style="margin-top:6px;padding:5px 10px;background:var(--bg2);border-radius:4px;font-family:'DM Mono',monospace;font-size:9px;color:var(--dim);display:flex;align-items:center;gap:6px">
         <span class="orr-sim-mode-dot is-be" style="width:8px;height:8px;border-radius:50%"></span>
         <span><strong style="color:var(--body)">${beOutSource.beOut}</strong> trade${beOutSource.beOut > 1 ? 's' : ''} treated as BE (0R) at TP=${beOutSource.tp.toFixed(2)}R</span>
       </div>`
    : '';

  summary.innerHTML = `
    ${beMgmtBadgeHtml}
    ${missingBtnHtml}
    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;font-family:'DM Mono',monospace">
      <div style="background:var(--bg2);border-radius:4px;padding:7px 6px;text-align:center">
        <div style="font-size:8px;color:var(--dim);margin-bottom:3px">🔥 Optimal TP</div>
        <div style="font-size:15px;font-weight:700;color:var(--gold)">${best.tp.toFixed(2)}R</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:7px 6px;text-align:center">
        <div style="font-size:8px;color:var(--dim);margin-bottom:3px">💰 Cumul</div>
        <div style="font-size:15px;font-weight:700;color:${best.cumR >= 0 ? 'var(--g)' : 'var(--r)'}">${best.cumR >= 0 ? '+' : ''}${best.cumR.toFixed(2)}R</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:7px 6px;text-align:center">
        <div style="font-size:8px;color:var(--dim);margin-bottom:3px">📊 Max EV</div>
        <div style="font-size:15px;font-weight:700;color:${maxEV >= 0 ? 'var(--g)' : 'var(--r)'}">${maxEV >= 0 ? '+' : ''}${maxEV.toFixed(3)}R</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:7px 6px;text-align:center">
        <div style="font-size:8px;color:var(--dim);margin-bottom:3px">📈 WR @ Optimal</div>
        <div style="font-size:15px;font-weight:700;color:var(--body)">${wr}%</div>
      </div>
      <div style="background:var(--bg2);border-radius:4px;padding:7px 6px;text-align:center">
        <div style="font-size:8px;color:var(--dim);margin-bottom:3px">${isBeFb ? 'W / L / BE' : 'W / L'}</div>
        <div style="font-size:13px;font-weight:700;letter-spacing:1px">
          <span style="color:var(--g)">${best.wins}</span>
          <span style="color:var(--dim);font-weight:400"> / </span>
          <span style="color:var(--r)">${best.losses}</span>
          ${isBeFb ? `
            <span style="color:var(--dim);font-weight:400"> / </span>
            <span style="color:var(--gold)">${_getBeColumnCountAtTp((activeIdx >= 0 ? data[activeIdx].tp : best.tp))}</span>
          ` : ''}
        </div>
      </div>
    </div>
    ${refRows}
    ${plateauHtml}
    ${beOutLine}
    ${dataQualityBadge}
    ${sampleLineHtml}
  `;
}

// ── Missing rrMax drawer (Optimal RR widget) ──
function _orrOpenMissingRRMax() {
  const trades = window._orrTradesWithoutRRMax || [];
  if (!trades.length) return;
  openWidgetDrawer('Trades without RR Max', `${trades.length} trade${trades.length > 1 ? 's' : ''} to complete`, trades);
}

// ══════════════════════════════════════════════════════
// PAIR × SESSION HEATMAP WIDGET
// ══════════════════════════════════════════════════════
let _sdMetric          = 'ev';
let _pairSessionMetric = 'ev';
let _hmHardMode        = false;

// ── Heatmap sync: link both heatmaps together ──
let _heatmapSyncEnabled = false;
let _heatmapSyncGuard   = false;

function toggleHeatmapSync() {
  _heatmapSyncEnabled = !_heatmapSyncEnabled;
  document.querySelectorAll('.hm-sync-btn').forEach(b => b.classList.toggle('active', _heatmapSyncEnabled));
}

// ── Heatmap confidence threshold (hachures on low-n cells) ──
const _HM_THRESHOLD_KEY    = 'flipping_heatmap_threshold';
const _PS_THRESHOLD_KEY    = 'flipping_pair_session_threshold';
const _HM_VALID_THRESHOLDS = [0, 5, 10, 20];
function _parseHmThreshold(raw) {
  const n = parseInt(raw, 10);
  return _HM_VALID_THRESHOLDS.includes(n) ? n : 5;
}
let _heatmapThreshold     = _parseHmThreshold(localStorage.getItem(_HM_THRESHOLD_KEY));
let _hourHeatmapThreshold = _parseHmThreshold(localStorage.getItem(_PS_THRESHOLD_KEY));

function setHeatmapThreshold(n) {
  _heatmapThreshold = _parseHmThreshold(n);
  localStorage.setItem(_HM_THRESHOLD_KEY, String(_heatmapThreshold));
  document.querySelectorAll('#sd-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _heatmapThreshold);
  });
  renderHeatmap(getFiltered());
  if (_heatmapSyncEnabled && !_heatmapSyncGuard) {
    _heatmapSyncGuard = true;
    setPairSessionThreshold(n);
    _heatmapSyncGuard = false;
  }
}

function setPairSessionThreshold(n) {
  _hourHeatmapThreshold = _parseHmThreshold(n);
  localStorage.setItem(_PS_THRESHOLD_KEY, String(_hourHeatmapThreshold));
  document.querySelectorAll('#ps-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _hourHeatmapThreshold);
  });
  renderPairSession(getFiltered());
  if (_heatmapSyncEnabled && !_heatmapSyncGuard) {
    _heatmapSyncGuard = true;
    setHeatmapThreshold(n);
    _heatmapSyncGuard = false;
  }
}

function toggleHardMode() {
  _hmHardMode = !_hmHardMode;
  document.querySelectorAll('.hm-hardmode-btn').forEach(b => b.classList.toggle('active', _hmHardMode));
  renderHeatmap(getFiltered());
  renderPairSession(getFiltered());
}

function _syncHardModeBtn() {
  const show = barMode === 'wr';
  document.querySelectorAll('.hm-hardmode-btn').forEach(b => {
    setVisible(b, show);
  });
}

function setPairSessionMetric(metric) {
  _pairSessionMetric = metric;
  document.querySelectorAll('#ps-metric-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.metric === metric);
  });
  renderPairSession(getFiltered());
  if (_heatmapSyncEnabled && !_heatmapSyncGuard) {
    _heatmapSyncGuard = true;
    setHeatmapMetric(metric);
    _heatmapSyncGuard = false;
  }
}

function setHeatmapMetric(metric) {
  _sdMetric = metric;
  document.querySelectorAll('#sd-metric-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.metric === metric);
  });
  renderHeatmap(getFiltered());
  if (_heatmapSyncEnabled && !_heatmapSyncGuard) {
    _heatmapSyncGuard = true;
    setPairSessionMetric(metric);
    _heatmapSyncGuard = false;
  }
}


// ══════════════════════════════════════════════════════
// UNIFIED TOOLTIP SYSTEM
// ══════════════════════════════════════════════════════
let _utip = null;
function _getUtip() {
  if (!_utip) {
    _utip = document.createElement('div');
    _utip.className = 'utip';
    _utip.id = 'utip';
    document.body.appendChild(_utip);
  }
  return _utip;
}
function showUtip(e, html) {
  const tt = _getUtip();
  tt.innerHTML = html;
  tt.classList.add('visible');
  _posUtip(e.clientX, e.clientY);
}
function showUtipText(e, text) {
  // Plain-text tooltip: split on ' · ' into multiple lines
  const tt = _getUtip();
  tt.innerHTML = `<div class="utip-plain">${text.replace(/ · /g, '\n')}</div>`;
  tt.classList.add('visible');
  _posUtip(e.clientX, e.clientY);
}
function hideUtip() {
  if (_utip) _utip.classList.remove('visible');
}
function _posUtip(cx, cy) {
  const tt = _utip; if (!tt) return;
  const tw = tt.offsetWidth || 220, th = tt.offsetHeight || 160;
  const W = window.innerWidth, H = window.innerHeight;
  let x = cx + 14, y = cy - 10;
  if (x + tw > W - 8) x = cx - tw - 14;
  if (y + th > H - 8) y = H - th - 8;
  tt.style.left = x + 'px'; tt.style.top = y + 'px';
}

// ── Pair × Session tooltip (now uses unified system) ──
function _showPSTip(e, text) { showUtipText(e, text); }
function _hidePSTip() { hideUtip(); }
function _utipValueClass(isPositive) {
  return isPositive ? 'utip-value utip-value-pos utip-align-right' : 'utip-value utip-value-neg utip-align-right';
}
function _utipNeutralClass(extra = '') {
  return `utip-value utip-align-right${extra ? ' ' + extra : ''}`;
}

function renderPairSession(trades) {
  const container = document.getElementById('pair-session-container');
  if (!container) return;
  if (!trades.length) { renderWidgetEmptyState('pair-session-container'); return; }

  // Build data grid: pair × session (UTC)
  const pairSet    = new Set(trades.map(t => t.pair).filter(Boolean));
  const sessionSet = new Set(trades.map(t => t.sessionUtc || t.session).filter(Boolean));
  const pairs    = [...pairSet].sort();
  const sessions = SESSION_ORDER.filter(s => sessionSet.has(s))
                   .concat([...sessionSet].filter(s => !SESSION_ORDER.includes(s)).sort());

  const tpConfig = appState.ui.tpConfig;
  const data = {};
  trades.forEach(t => {
    const k = (t.pair||'') + '|' + (t.sessionUtc || t.session || '');
    if (!data[k]) data[k] = { r: 0, n: 0, wins: 0, tpR: 0, slR: 0, betpR: 0, beslR: 0 };
    const r = computeEffectiveRR(t, tpConfig);
    data[k].r += r;
    data[k].n++;
    if (isWinner(t)) data[k].wins++;
    if (t.outcome==='TP')    data[k].tpR+=r;
    else if (t.outcome==='SL')    data[k].slR+=r;
    else if (t.outcome==='BE-TP') data[k].betpR+=r;
    else if (t.outcome==='BE-SL') data[k].beslR+=r;
  });

  const metric = barMode === 'wr' ? 'wr' : barMode === 'n' ? 'n' : _pairSessionMetric;
  const useTotal = barMode === 'total';
  const valFn = v => metric === 'ev'  ? (useTotal ? v.r : v.r / v.n)
                   : metric === 'wr'  ? v.wins / v.n * 100
                   : v.n;
  const fmtFn = v => metric === 'ev'  ? (v >= 0 ? '+' : '') + v.toFixed(useTotal ? 1 : 2) + 'R'
                   : metric === 'wr'  ? v.toFixed(0) + '%'
                   : String(v);

  // Compute range for color intensity
  let mn = Infinity, mx = -Infinity;
  pairs.forEach(p => sessions.forEach(s => {
    const v = data[p+'|'+s];
    if (v && v.n >= 2) {
      const val = valFn(v);
      mn = Math.min(mn, val); mx = Math.max(mx, val);
    }
  }));
  if (mn === Infinity) { mn = 0; mx = 1; }
  const range = Math.max(Math.abs(mx), Math.abs(mn)) || 1;

  const toRgb = h => { const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r ? `${parseInt(r[1],16)},${parseInt(r[2],16)},${parseInt(r[3],16)}` : '180,180,180'; };
  const cG = tc('--g'), cR = tc('--r');

  // ── Dynamic sizing ──────────────────────────────────────
  // Measure available space AFTER layout has settled
  const ROW_LABEL_W = 64; // px reserved for session labels column
  const GAP         = 2;  // px gap between cells
  const PADDING     = 4;  // px padding around the grid

  const availH = container.clientHeight || 200;

  // Total rows = 1 header row + N session rows
  const nRows = sessions.length + 1;

  // Cell height: distribute available height across all rows
  const totalVGap   = GAP * (nRows - 1) + PADDING * 2;
  const rawCellH    = Math.floor((availH - totalVGap) / nRows);
  const cellH       = Math.max(rawCellH, 22); // never below 22px

  // Header row height (pair labels): slightly smaller
  const headerH     = Math.max(Math.floor(cellH * 0.7), 18);

  // Font size: scale with cell height, clamped
  const fontSize    = Math.max(7, Math.min(12, Math.floor(cellH * 0.32)));
  const labelFontSz = Math.max(8, Math.min(12, Math.floor(cellH * 0.32)));

  // Determine if cells are tall enough to show a second sub-line (n count)
  const showSubLine = cellH >= 38;

  // Grid uses 1fr for data columns so they fill width evenly
  container.style.cssText = `
    display: grid;
    grid-template-columns: ${ROW_LABEL_W}px repeat(${pairs.length}, 1fr);
    grid-template-rows: ${headerH}px repeat(${sessions.length}, 1fr);
    gap: ${GAP}px;
    padding: ${PADDING}px;
    height: 100%;
    overflow: hidden;
    min-width: 0;
    box-sizing: border-box;
  `;
  container.innerHTML = '';

  // ── Header row: blank corner + pair labels ──
  const blank = document.createElement('div');
  container.appendChild(blank);

  pairs.forEach(p => {
    const el = document.createElement('div');
    el.style.cssText = `
      display: flex; align-items: flex-end; justify-content: center;
      font-family: "DM Mono", monospace;
      font-size: ${labelFontSz}px;
      color: var(--dim);
      padding: 0 2px 3px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
      text-align: center;
    `;
    el.textContent = p;
    container.appendChild(el);
  });

  // ── Data rows: one per session ──
  sessions.forEach(s => {
    // Row label
    const lbl = document.createElement('div');
    lbl.style.cssText = `
      display: flex; align-items: center;
      font-family: "DM Mono", monospace;
      font-size: ${labelFontSz}px;
      font-weight: 600;
      color: var(--body);
      padding-right: 6px;
      white-space: nowrap;
    `;
    lbl.textContent = SESSION_SHORT[s] || s;
    container.appendChild(lbl);

    pairs.forEach(p => {
      const v = data[p+'|'+s];
      const cell = document.createElement('div');
      cell.style.cssText = `
        border-radius: 3px;
        display: flex; flex-direction: column;
        align-items: center; justify-content: center;
        font-family: "DM Mono", monospace;
        font-size: ${fontSize}px;
        font-weight: 600;
        cursor: default;
        overflow: hidden;
        line-height: 1.2;
        gap: 2px;
      `;

      if (_hourHeatmapThreshold > 0 && v && v.n < _hourHeatmapThreshold) {
        cell.classList.add('cell-low-n');
      }

      if (v && v.n >= 2) {
        const val  = valFn(v);
        let alpha, pos;
        if (metric === 'wr') {
          if (!_hmHardMode) {
            pos = true;
            const span = (mx - mn) || 1;
            alpha = Math.min(((val - mn) / span) * 0.75 + 0.18, 0.95);
          } else {
            const WR_MID = 40;
            pos = val >= WR_MID;
            const dev = val - WR_MID;
            const maxDev = pos ? (100 - WR_MID) : WR_MID;
            alpha = pos ? Math.min(Math.abs(dev / (maxDev || 1)) * 0.8 + 0.25, 0.95) : 0.28;
          }
        } else {
          pos = metric === 'n' ? true : val >= 0;
          alpha = Math.min(Math.abs(val / range) * (pos ? 0.8 : 0.65) + 0.22, 0.95);
        }
        cell.style.background = `rgba(${toRgb(pos ? cG : cR)},${alpha})`;
        cell.style.color = alpha > 0.55 ? tc('--bg1') : (pos ? cG : cR);

        const valueSpan = document.createElement('span');
        valueSpan.textContent = fmtFn(val);
        cell.appendChild(valueSpan);

        const avgR = v.r / v.n;
        const wrPct = (v.wins / v.n * 100).toFixed(0);
        const netTP = v.tpR + v.betpR;
        const netSL = v.slR + v.beslR;
        const netRows = `<span class="utip-label">Net TP</span><span></span><span class="utip-value utip-value-pos utip-align-right">${netTP>=0?'+':''}${netTP.toFixed(1)}R</span>
             <span class="utip-label">Net SL</span><span></span><span class="utip-value utip-value-neg utip-align-right">${netSL.toFixed(1)}R</span>`;
        const tipHtml = `<div class="utip-header">${p} × ${SESSION_SHORT[s]||s}</div>
          <div class="utip-grid">
            <span class="utip-label">Value</span><span></span><span class="${_utipValueClass(pos)}">${fmtFn(val)}</span>
            <span class="utip-label">Trades</span><span></span><span class="${_utipNeutralClass()}">×${v.n}</span>
            <span class="utip-label">Win Rate</span><span></span><span class="${_utipValueClass(+wrPct>=50)}">${wrPct}%</span>
            <span class="utip-label">Avg R</span><span></span><span class="${_utipNeutralClass()}">${(avgR>=0?'+':'')+avgR.toFixed(3)}R</span>
            <span class="utip-label">Total R</span><span></span><span class="${_utipNeutralClass()}">${(v.r>=0?'+':'')+v.r.toFixed(1)}R</span>
            ${netRows}
          </div>`;
        bindManagedEvent(cell, '_managedMouseEnter', 'mouseenter', e => showUtip(e, tipHtml));
        bindManagedEvent(cell, '_managedMouseMove', 'mousemove', e => _posUtip(e.clientX, e.clientY));
        bindManagedEvent(cell, '_managedMouseLeave', 'mouseleave', hideUtip);
        // Click: open shared drawer
        cell.style.cursor = 'pointer';
        bindManagedEvent(cell, '_managedClick', 'click', () => {
          const cellTrades = trades.filter(t => t.pair === p && (t.sessionUtc||t.session) === s);
          if (!cellTrades.length) return;
          document.querySelectorAll('#pair-session-container .wd-cell-active').forEach(el => el.classList.remove('wd-cell-active'));
          cell.classList.add('wd-cell-active');
          openWidgetDrawer(`${p} × ${SESSION_SHORT[s]||s}`, `${v.n} trades`, cellTrades);
        });
        bindManagedEvent(cell, '_managedCtxMenu', 'contextmenu', e => {
          e.preventDefault();
          _showCellComboContextMenu('pairSession', `${p}|${s}`, `${p} × ${SESSION_SHORT[s]||s}`, e);
        });
      } else if (v && v.n === 1) {
        cell.style.background = 'var(--bg3)';
        cell.style.color = 'var(--mute)';
        cell.textContent = '·';
        const tip1 = `<div class="utip-header">${p} × ${SESSION_SHORT[s]||s}</div><div class="utip-grid"><span class="utip-label">Trades</span><span></span><span class="${_utipNeutralClass()}">×1 (low confidence)</span></div>`;
        bindManagedEvent(cell, '_managedMouseEnter', 'mouseenter', e => showUtip(e, tip1));
        bindManagedEvent(cell, '_managedMouseMove', 'mousemove', e => _posUtip(e.clientX, e.clientY));
        bindManagedEvent(cell, '_managedMouseLeave', 'mouseleave', hideUtip);
      } else {
        cell.style.background = 'var(--bg3)';
        cell.style.color = 'var(--mute)';
        cell.textContent = '—';
      }
      container.appendChild(cell);
    });
  });
}


// ══════════════════════════════════════════════════════
// SHARED WIDGET DRAWER
// Detail panel reused by all performance widgets.
// Opens on click from bar rows and heatmap cells.
// ══════════════════════════════════════════════════════
const _WD_OC_CLASS = { TP:'oc-tp', SL:'oc-sl', 'BE-TP':'oc-betp', 'BE-SL':'oc-besl' };
const _WD_ROW_BG   = {
  TP:    'rgba(110,224,180,.12)',
  SL:    'rgba(224,90,114,.12)',
  'BE-TP':'rgba(41,98,255,.10)',
  'BE-SL':'rgba(180,120,240,.10)'
};
const _WD_BG_CLASS = {
  TP: 'wd-trade-card-tp',
  SL: 'wd-trade-card-sl',
  'BE-TP': 'wd-trade-card-betp',
  'BE-SL': 'wd-trade-card-besl',
};

/* Build one trade card HTML for the shared drawer */
function _wdTradeCard(t) {
  // Screenshot buttons: H4 Before · M15 Before · M15 After
  const safePair  = (t.pair||'').replace(/"/g,'&quot;');
  const safeDate  = (t.date||'').replace(/"/g,'&quot;');
  const safeH4b   = (t.imgH4Before||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');
  const safeM15b  = (t.imgM15||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');
  const safeM15a  = (t.imgM15After||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');
  const safeH4bOrig  = (t.imgH4BeforeOrig||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');
  const safeM15bOrig = (t.imgM15Orig     ||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');
  const safeM15aOrig = (t.imgM15AfterOrig||'').trim().replace(/'/g,"\\'").replace(/"/g,'&quot;');

  const _wdBtn = (url, step, emoji, label) => url
    ? `<div class="wd-media-item">
         <button class="trade-media-btn wd-media-btn" data-action="open-img-lightbox"
           data-img-url="${url}"
           data-img-step="${step}"
           data-trade-pair="${safePair}"
           data-trade-date="${safeDate}"
           data-trade-h4before="${safeH4b}"
           data-trade-m15before="${safeM15b}"
           data-trade-m15after="${safeM15a}"
           data-trade-h4before-orig="${safeH4bOrig}"
           data-trade-m15before-orig="${safeM15bOrig}"
           data-trade-m15after-orig="${safeM15aOrig}"
           title="${label}">${emoji}</button>
         <span class="wd-media-label">${label.replace(' Before','').replace(' After','A')}</span>
       </div>`
    : '';

  const imgBtn = [
    _wdBtn(safeH4b,  'h4Before',  '📷', 'H4 Before'),
    _wdBtn(safeM15b, 'm15Before', '📷', 'M15 Before'),
    _wdBtn(safeM15a, 'm15After',  '📸', 'M15 After'),
  ].filter(Boolean).join('');

  // Notion page button
  const notionUrl = (t.notionUrl || '').trim();
  const notionBtn = notionUrl
    ? `<button class="trade-media-btn wd-media-btn trade-link-btn" data-action="open-notion-overlay"
         data-notion-url="${notionUrl.replace(/"/g, '&quot;')}"
         title="Open in Notion">🔗</button>`
    : '';

  // H4 obstacles
  const h4Arr = Array.isArray(t.h4) ? t.h4 : (t.h4 ? [t.h4] : []);
  const h4Html = h4Arr.length
    ? `<div class="wd-trade-meta-line wd-trade-meta-line-full">
         <span class="wd-trade-meta-title">Obstacles H4 :</span><span class="wd-trade-meta-value">${[...h4Arr].sort().join(' · ')}</span></div>`
    : '';

  // M15 obstacles
  const obsArr = Array.isArray(t.obstacles) ? t.obstacles : (t.obstacles ? [t.obstacles] : []);
  const obsHtml = obsArr.length
    ? `<div class="wd-trade-meta-line wd-trade-meta-line-full">
         <span class="wd-trade-meta-title">Obstacles M15 :</span><span class="wd-trade-meta-value">${[...obsArr].sort().join(' · ')}</span></div>`
    : '';

  // Session + hour line
  const sessionHourHtml = (t.session||t.hour!=null)
    ? `<div class="wd-trade-session-hour wd-trade-meta-line-full">${t.session?`<span>${t.session}</span>`:''}${t.hour!=null?`<span>${String(t.hour).padStart(2,'0')}:00</span>`:''}</div>`
    : '';

  // RR Max line — always shown when the trade has a finite rrMax, regardless of TP mode
  const rrMaxHtml = (typeof t.rrMax === 'number' && Number.isFinite(t.rrMax))
    ? `<div class="wd-trade-meta-line wd-trade-meta-line-full">
         <span class="wd-trade-meta-title">RR Max :</span><span class="wd-trade-meta-value">${t.rrMax.toFixed(1)}R</span></div>`
    : '';

  // TP hits line — shown in Multi / Personalised modes only.
  // A given TP slot is displayed only if its per-trade value (t.tpN_rr) is a finite
  // number. If no slot qualifies, the entire line is hidden.
  const _tpConfigForCard = appState.ui.tpConfig;
  const _tpModeForCard   = _tpConfigForCard && _tpConfigForCard.mode;
  const _showTpHits      = _tpModeForCard === 'multi' || _tpModeForCard === 'personalised';
  const tpHitsHtml = (() => {
    if (!_showTpHits) return '';
    // Hide the whole TP hits line for losing or BE-neutre trades — the big R
    // figure already conveys the outcome, and per-TP detail is meaningful only
    // when at least one tier was actually captured (effectiveClass === 'win').
    // Under fixed mode: BE-SL with trade.r=-1 → effectiveClass='loss' → hidden,
    // matching the legacy `t.r < 0 || outcome === 'BE-SL'` behavior.
    if (t.effectiveClass === 'loss' || t.effectiveClass === 'be') return '';
    const tpCount = (_tpModeForCard === 'multi'
      ? _tpConfigForCard.multi?.tpCount
      : _tpConfigForCard.personalised?.tpCount) || 2;
    const isFiniteNum = v => typeof v === 'number' && Number.isFinite(v);
    const slots = [
      { label: 'TP1', val: t.tp1_rr },
      { label: 'TP2', val: t.tp2_rr },
    ];
    if (tpCount === 3) slots.push({ label: 'TP3', val: t.tp3_rr });
    const parts = slots
      .filter(s => isFiniteNum(s.val))
      .map(s => `${s.label}: ${s.val.toFixed(1)}R`);
    if (!parts.length) return '';
    return `<div class="wd-trade-meta-line wd-trade-meta-line-full">
              <span class="wd-trade-meta-title">TP hits :</span><span class="wd-trade-meta-value">${parts.join(' · ')}</span></div>`;
  })();

  // Direction line — Achat = blue, Vente = rose
  const _dirCol = t.direction === 'Achat' ? '#5b9cf6' : t.direction === 'Vente' ? '#f472b6' : 'var(--dim)';
  const directionHtml = t.direction
    ? `<div class="wd-trade-direction" style="color:${_dirCol}">${t.direction}</div>`
    : '';

  // Setup line: prefer setupDetail over setup
  const setupLine = t.setupDetail || t.setup || '—';

  return `
    <div class="wd-trade-card ${_WD_BG_CLASS[t.outcome]||''}">
      <div class="wd-trade-main">
        <div class="wd-trade-pair-row">
          ${t.pair||'—'}${notionBtn}
        </div>
        ${t.date?`<div class="wd-trade-date">${t.date}</div>`:''}
      </div>
      <div class="wd-trade-side">
        <div class="wd-trade-r ${t.outcome==='BE-TP'?'wd-trade-r-betp':t.outcome==='BE-SL'?'wd-trade-r-besl':t.r>0?'wd-trade-r-pos':t.r<0?'wd-trade-r-neg':'wd-trade-r-neu'}">
          ${(() => {
            // Display value logic:
            //   - SL: show the realized SL magnitude. If tp1_rr is a finite negative
            //     number (partial SL, e.g. -0.5R), use it; otherwise fall back to t.r
            //     (typically -1.0R for a full SL). PRESERVED — independent of
            //     classification, this is journaling-side metadata.
            //   - Other outcomes (TP / BE-TP / BE-SL): show t.effectiveR (cached
            //     by filterDataset enrichment under active TP config; falls back to
            //     a one-shot computeEffectiveRR when unenriched). Under fixed mode
            //     effectiveR === t.r, so behavior is identical.
            // Class above is driven by raw t.r and t.outcome so BE-TP / BE-SL keep their
            // distinctive color even if the effective R shifts sign — intentional.
            let _rDisplay;
            if (t.outcome === 'SL') {
              _rDisplay = (typeof t.tp1_rr === 'number' && Number.isFinite(t.tp1_rr) && t.tp1_rr < 0)
                ? t.tp1_rr
                : t.r;
            } else {
              _rDisplay = t.effectiveR ?? computeEffectiveRR(t, appState.ui.tpConfig);
            }
            const _rNum = (typeof _rDisplay === 'number' && Number.isFinite(_rDisplay)) ? _rDisplay : t.r;
            return `${_rNum > 0 ? '+' : ''}${_rNum.toFixed(1)}R`;
          })()}</div>
        ${imgBtn}
      </div>
      ${directionHtml}
      <div class="wd-trade-outcome-wrap">
        <span class="${_WD_OC_CLASS[t.outcome]||''} wd-trade-outcome">
          ${t.outcome||'—'}</span>
      </div>
      <div class="wd-trade-setup wd-trade-meta-line-full">${setupLine}</div>
      ${sessionHourHtml}
      ${rrMaxHtml}
      ${tpHitsHtml}
      ${h4Html}
      ${obsHtml}
    </div>`;
}

/* Open the shared widget drawer with a filtered set of trades.
   Trades are always sorted by date asc → hour asc regardless of widget source. */
function openWidgetDrawer(title, subtitle, trades, highlightTrade = null) {
  if (!trades || !trades.length) return;

  // Sort: date asc, then hour asc
  const sorted = _sortTradesChronological(trades);

  // Aggregate stats from the trade list
  const tpConfig = appState.ui.tpConfig;
  const totalR = sorted.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig)) || 0), 0);
  const wins   = sorted.filter(isWinner).length;
  const n      = sorted.length;
  const sign   = totalR >= 0 ? '+' : '';
  const col    = totalR >= 0 ? 'var(--g)' : 'var(--r)';

  // Create drawer & backdrop once; reuse afterwards
  let drawer = document.getElementById('wd-drawer');
  if (!drawer) {
    drawer = document.createElement('div');
    drawer.id = 'wd-drawer';
    drawer.className = 'wd-drawer';
    document.body.appendChild(drawer);

    const bd = document.createElement('div');
    bd.id = 'wd-backdrop';
    bd.className = 'wd-backdrop';
    bd.dataset.action = 'close-widget-drawer';
    document.body.appendChild(bd);
  }

  const sub = subtitle || `${n} trade${n>1?'s':''} · ${wins}W ${n-wins}L`;

  drawer.innerHTML = `
    <div class="wd-drawer-head">
      <div class="wd-drawer-head-main">
        <div class="wd-drawer-title">${title}</div>
        <div class="wd-drawer-sub">${sub}</div>
      </div>
      <div class="wd-drawer-head-side">
        <div class="wd-drawer-total ${totalR >= 0 ? 'wd-drawer-total-pos' : 'wd-drawer-total-neg'}">${sign}${totalR.toFixed(1)}R</div>
        <button class="wd-drawer-close" data-action="close-widget-drawer">×</button>
      </div>
    </div>
    <div class="wd-drawer-body">${sorted.map(_wdTradeCard).join('')}</div>`;

  if (highlightTrade) {
    const idx = sorted.findIndex(t => t === highlightTrade) !== -1
      ? sorted.findIndex(t => t === highlightTrade)
      : sorted.findIndex(t =>
          t.date === highlightTrade.date &&
          t.pair === highlightTrade.pair &&
          (t.hour ?? null) === (highlightTrade.hour ?? null) &&
          // KEEP raw trade.r — identity matching for click-to-locate. Must NOT use computeEffectiveRR (weighted value would break the lookup).
          Math.abs((Number(t.r)||0) - (Number(highlightTrade.r)||0)) < 1e-6 &&
          t.outcome === highlightTrade.outcome
        );
    if (idx >= 0) {
      const cards = drawer.querySelectorAll('.wd-drawer-body .wd-trade-card');
      const card = cards[idx];
      if (card) {
        card.classList.add('is-active');
        requestAnimationFrame(() => card.scrollIntoView({ block: 'center', behavior: 'smooth' }));
      }
    }
  }

  requestAnimationFrame(() => {
    drawer.classList.add('is-open');
    const bd = document.getElementById('wd-backdrop');
    if (bd) bd.classList.add('is-open');
  });
}

/* Open the shared drawer with DD recovery occurrences — one collapsible section per occurrence,
   each containing a Drawdown sequence + Recovery sequence of trade cards. */
function openRecoveryDrawer(bucket, sorted, opts = {}) {
  if (!bucket || !Array.isArray(bucket.occurrences) || !bucket.occurrences.length) return;

  let drawer = document.getElementById('wd-drawer');
  if (!drawer) {
    drawer = document.createElement('div');
    drawer.id = 'wd-drawer';
    drawer.className = 'wd-drawer';
    document.body.appendChild(drawer);

    const bd = document.createElement('div');
    bd.id = 'wd-backdrop';
    bd.className = 'wd-backdrop';
    bd.dataset.action = 'close-widget-drawer';
    document.body.appendChild(bd);
  }

  const isActive = !!opts.isActive;
  const n = bucket.occurrences.length;
  const title = isActive
    ? `Active Drawdown  −${bucket.x}R × ${bucket.y} trades (ongoing)`
    : `DD Recovery  −${bucket.x}R × ${bucket.y} trades`;
  const sub = isActive
    ? 'Not yet recovered'
    : `${n} occurrence${n > 1 ? 's' : ''}`;

  const _tradeMs = t => {
    const [y, m, d] = (t?.date || '').split('-').map(Number);
    if (!y) return NaN;
    return new Date(y, (m || 1) - 1, d || 1, Number(t.hour) || 0).getTime();
  };
  const _fmtSeqDuration = (tradesSeq) => {
    if (!tradesSeq || tradesSeq.length < 2) return '—';
    const a = _tradeMs(tradesSeq[0]);
    const b = _tradeMs(tradesSeq[tradesSeq.length - 1]);
    if (!isFinite(a) || !isFinite(b) || b < a) return '—';
    const h = (b - a) / 3_600_000;
    if (h < 1) return '<1h';
    if (h < 24) return `${Math.round(h)}h`;
    const days = h / 24;
    if (days < 10) return `${days.toFixed(1)}d`;
    return `${Math.round(days)}d`;
  };

  const occHtml = bucket.occurrences.map((occ, i) => {
    const ddTrades  = sorted.slice(occ.startIdx, occ.troughIdx + 1);
    const recTrades = sorted.slice(occ.troughIdx + 1, occ.endIdx + 1);
    const ddDur  = _fmtSeqDuration(ddTrades);
    const recDur = _fmtSeqDuration(recTrades);

    if (isActive) {
      const rangeLabel = `${sorted[occ.startIdx]?.date || '—'} → ${sorted[occ.endIdx]?.date || '—'} (ongoing)`;

      const recBodyHtml = recTrades.length > 0
        ? recTrades.map(_wdTradeCard).join('')
        : `<div class="wd-occ-empty">Recovery has not started yet — drawdown is still deepening.</div>`;

      const recCountLabel = recTrades.length > 0
        ? `${recTrades.length} trade${recTrades.length > 1 ? 's' : ''} · ${recDur} · in progress`
        : `— not yet started`;

      return `
        <div class="wd-occ is-expanded" data-occ-idx="${i}">
          <button class="wd-occ-head" data-action="toggle-recovery-occ" type="button">
            <span class="wd-occ-chevron">▸</span>
            <span class="wd-occ-title">Active Drawdown</span>
            <span class="wd-occ-meta">${rangeLabel}</span>
          </button>
          <div class="wd-occ-body">
            <div class="wd-occ-section wd-occ-section-dd">
              <button class="wd-occ-section-head" data-action="toggle-recovery-section" type="button">
                <span class="wd-occ-chevron">▸</span>
                <span class="wd-occ-section-label">Drawdown sequence</span>
                <span class="wd-occ-section-count">${ddTrades.length} trade${ddTrades.length > 1 ? 's' : ''} · ${ddDur}</span>
              </button>
              <div class="wd-occ-section-body">${ddTrades.map(_wdTradeCard).join('')}</div>
            </div>
            <div class="wd-occ-section wd-occ-section-rec">
              <button class="wd-occ-section-head" data-action="toggle-recovery-section" type="button">
                <span class="wd-occ-chevron">▸</span>
                <span class="wd-occ-section-label">Recovery sequence (in progress)</span>
                <span class="wd-occ-section-count">${recCountLabel}</span>
              </button>
              <div class="wd-occ-section-body">${recBodyHtml}</div>
            </div>
          </div>
        </div>`;
    }

    const rangeLabel = `${sorted[occ.startIdx]?.date || '—'} → ${sorted[occ.endIdx]?.date || '—'}`;
    return `
      <div class="wd-occ" data-occ-idx="${i}">
        <button class="wd-occ-head" data-action="toggle-recovery-occ" type="button">
          <span class="wd-occ-chevron">▸</span>
          <span class="wd-occ-title">Occurrence ${i + 1}</span>
          <span class="wd-occ-meta">${rangeLabel}</span>
        </button>
        <div class="wd-occ-body">
          <div class="wd-occ-section wd-occ-section-dd">
            <button class="wd-occ-section-head" data-action="toggle-recovery-section" type="button">
              <span class="wd-occ-chevron">▸</span>
              <span class="wd-occ-section-label">Drawdown sequence</span>
              <span class="wd-occ-section-count">${ddTrades.length} trade${ddTrades.length > 1 ? 's' : ''} · ${ddDur}</span>
            </button>
            <div class="wd-occ-section-body">${ddTrades.map(_wdTradeCard).join('')}</div>
          </div>
          <div class="wd-occ-section wd-occ-section-rec">
            <button class="wd-occ-section-head" data-action="toggle-recovery-section" type="button">
              <span class="wd-occ-chevron">▸</span>
              <span class="wd-occ-section-label">Recovery sequence</span>
              <span class="wd-occ-section-count">${recTrades.length} trade${recTrades.length > 1 ? 's' : ''} · ${recDur}</span>
            </button>
            <div class="wd-occ-section-body">${recTrades.map(_wdTradeCard).join('')}</div>
          </div>
        </div>
      </div>`;
  }).join('');

  drawer.innerHTML = `
    <div class="wd-drawer-head">
      <div class="wd-drawer-head-main">
        <div class="wd-drawer-title">${title}</div>
        <div class="wd-drawer-sub">${sub}</div>
      </div>
      <div class="wd-drawer-head-side">
        <button class="wd-drawer-close" data-action="close-widget-drawer">×</button>
      </div>
    </div>
    <div class="wd-drawer-body wd-drawer-body-recovery">${occHtml}</div>`;

  requestAnimationFrame(() => {
    drawer.classList.add('is-open');
    const bd = document.getElementById('wd-backdrop');
    if (bd) bd.classList.add('is-open');
  });
}

/* Helper: ensure shared drawer + backdrop exist */
function _ensureWidgetDrawerEls() {
  let drawer = document.getElementById('wd-drawer');
  if (!drawer) {
    drawer = document.createElement('div');
    drawer.id = 'wd-drawer';
    drawer.className = 'wd-drawer';
    document.body.appendChild(drawer);

    const bd = document.createElement('div');
    bd.id = 'wd-backdrop';
    bd.className = 'wd-backdrop';
    bd.dataset.action = 'close-widget-drawer';
    document.body.appendChild(bd);
  }
  return drawer;
}

/* Helper: run metadata (range label, sign, color) for streak drawer sections */
const _STREAK_TYPE_COL = {
  w:    'var(--g)',
  win:  'var(--g)',
  l:    'var(--r)',
  loss: 'var(--r)',
  be:   'var(--oc-betp)',
  besl: 'var(--oc-besl)',
};
const _STREAK_TYPE_LABEL = {
  w: 'Win', win: 'Win',
  l: 'Loss', loss: 'Loss',
  be: 'BE-TP',
  besl: 'BE-SL',
};
function _streakRunMeta(run) {
  const trades = run.trades || [];
  const totalR = run.totalR != null ? run.totalR : trades.reduce((s, t) => s + (Number(computeEffectiveRR(t, appState.ui.tpConfig))||0), 0);
  const first = trades[0], last = trades[trades.length - 1];
  const start = first?.date || '—';
  const end   = last?.date || '—';
  const range = (start === end) ? start : `${start} → ${end}`;
  const sign  = (totalR >= 0 ? '+' : '') + totalR.toFixed(1) + 'R';
  return { totalR, range, signedR: sign };
}

/* Open the shared drawer with one section per streak run.
   type: 'win' | 'loss' — for histogram click (all runs share the same length). */
function openStreakDrawer(type, length, runs) {
  if (!Array.isArray(runs) || !runs.length) return;
  const drawer = _ensureWidgetDrawerEls();

  const n = runs.length;
  const label = type === 'win' ? 'Win Streak' : 'Loss Streak';
  const title = `${label} × ${length} trade${length > 1 ? 's' : ''}`;
  const sub   = `${n} run${n > 1 ? 's' : ''}`;
  const dotCol = _STREAK_TYPE_COL[type] || 'var(--dim)';

  const occHtml = runs.map((run, i) => {
    const { range, signedR } = _streakRunMeta(run);
    const isExpanded = i === 0 ? ' is-expanded' : '';
    return `
      <div class="wd-occ${isExpanded}" data-occ-idx="${i}">
        <button class="wd-occ-head" data-action="toggle-recovery-occ" type="button">
          <span class="wd-occ-chevron">▸</span>
          <span class="wd-occ-title"><span class="wd-occ-dot" style="background:${dotCol}"></span>Run ${i + 1}</span>
          <span class="wd-occ-meta">${range} · ${signedR}</span>
        </button>
        <div class="wd-occ-body">${(run.trades||[]).map(_wdTradeCard).join('')}</div>
      </div>`;
  }).join('');

  drawer.innerHTML = `
    <div class="wd-drawer-head">
      <div class="wd-drawer-head-main">
        <div class="wd-drawer-title">${title}</div>
        <div class="wd-drawer-sub">${sub}</div>
      </div>
      <div class="wd-drawer-head-side">
        <button class="wd-drawer-close" data-action="close-widget-drawer">×</button>
      </div>
    </div>
    <div class="wd-drawer-body wd-drawer-body-recovery">${occHtml}</div>`;

  requestAnimationFrame(() => {
    drawer.classList.add('is-open');
    const bd = document.getElementById('wd-backdrop');
    if (bd) bd.classList.add('is-open');
  });
}

/* Open the shared drawer listing ALL timeline runs — clicked run is expanded,
   others collapsed. Section header shows type + range + totalR. */
function openStreakTimelineDrawer(allRuns, clickedRunIdx) {
  if (!Array.isArray(allRuns) || !allRuns.length) return;
  const drawer = _ensureWidgetDrawerEls();

  const title = 'Streak Timeline';
  const sub   = `${allRuns.length} run${allRuns.length > 1 ? 's' : ''}`;

  const occHtml = allRuns.map((run, i) => {
    const { range, signedR } = _streakRunMeta(run);
    const sign = run.sign || 'w';
    const typeLabel = _STREAK_TYPE_LABEL[sign] || sign;
    const dotCol    = _STREAK_TYPE_COL[sign]   || 'var(--dim)';
    const trades = run.trades || [];
    const n = trades.length;
    const isExpanded = i === clickedRunIdx ? ' is-expanded' : '';
    const cardsHtml = trades.map((t, ti) =>
      `<div class="wd-trade-card-wrap" data-action="focus-streak-trade" data-run-idx="${i}" data-trade-idx="${ti}">${_wdTradeCard(t)}</div>`
    ).join('');
    return `
      <div class="wd-occ${isExpanded}" data-occ-idx="${i}">
        <button class="wd-occ-head" data-action="toggle-recovery-occ" type="button">
          <span class="wd-occ-chevron">▸</span>
          <span class="wd-occ-title"><span class="wd-occ-dot" style="background:${dotCol}"></span>${typeLabel} × ${n}</span>
          <span class="wd-occ-meta">${range} · ${signedR}</span>
        </button>
        <div class="wd-occ-body">${cardsHtml}</div>
      </div>`;
  }).join('');

  drawer.innerHTML = `
    <div class="wd-drawer-head">
      <div class="wd-drawer-head-main">
        <div class="wd-drawer-title">${title}</div>
        <div class="wd-drawer-sub">${sub}</div>
      </div>
      <div class="wd-drawer-head-side">
        <button class="wd-drawer-close" data-action="close-widget-drawer">×</button>
      </div>
    </div>
    <div class="wd-drawer-body wd-drawer-body-recovery">${occHtml}</div>`;

  requestAnimationFrame(() => {
    drawer.classList.add('is-open');
    const bd = document.getElementById('wd-backdrop');
    if (bd) bd.classList.add('is-open');
    const activeEl = drawer.querySelector(`.wd-occ[data-occ-idx="${clickedRunIdx}"]`);
    if (activeEl) activeEl.scrollIntoView({ block: 'center', behavior: 'smooth' });
  });
}

function closeWidgetDrawer() {
  const drawer = document.getElementById('wd-drawer');
  const bd     = document.getElementById('wd-backdrop');
  if (drawer) drawer.classList.remove('is-open');
  if (bd) bd.classList.remove('is-open');
  // Remove bar highlight
  document.querySelectorAll('.bar-row.lb-active').forEach(r => r.classList.remove('lb-active'));
  // Remove cell highlight (calendar, pair×session)
  document.querySelectorAll('.wd-cell-active').forEach(el => el.classList.remove('wd-cell-active'));
  // Remove streak timeline run + square highlights
  document.querySelectorAll('.stl-run.stl-run-active').forEach(el => el.classList.remove('stl-run-active'));
  document.querySelectorAll('.stl-sq.stl-sq-active').forEach(el => el.classList.remove('stl-sq-active'));
  // Clear streak histogram selection
  if (_streakHistActiveDataset !== null || _streakHistActiveIdx !== null) {
    _streakHistActiveDataset = null;
    _streakHistActiveIdx     = null;
    if (_streakTab === 'histogram') renderStreakHistogram(getFiltered());
  }
  // Clear recovery scatter selection
  if (_recoveryActiveIdx !== null) {
    _recoveryActiveIdx = null;
    renderRecovery(getFiltered());
  }
  // Remove monthly canvas bar highlight
  if (appState.ui.monthlySelectedMonth !== null) {
    appState.ui.monthlySelectedMonth = null;
    drawMonthly(getFiltered());
  }
  // Close lightbox if open
  const ov = document.getElementById('img-lightbox-overlay');
  if (ov) { ov.remove(); _lbRemoveKeyHandler(); }
}

// ══════════════════════════════════════════════════════
// STREAK CALENDAR WIDGET — SAFE IMPROVED REPLACEMENT
// Compatible with existing dashboard wiring
// ══════════════════════════════════════════════════════
let _calTrades    = [];
let _calMode      = 'annual';   // 'annual' | 'monthly'
let _calMonthSort = 'hour';     // 'hour' | 'session'
let _calDayMap    = {};
let _calYearMap   = {};

const _CAL_MONTHS = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
const _CAL_DAY_LABELS = ['Mo','Tu','We','Th','Fr','Sa','Su'];
const _CAL_OC_CLASS = { TP:'oc-tp', SL:'oc-sl', 'BE-TP':'oc-betp', 'BE-SL':'oc-besl' };
const _CAL_ROW_BG = {
  TP:'rgba(110,224,180,.12)',
  SL:'rgba(224,90,114,.12)',
  'BE-TP':'rgba(41,98,255,.10)',
  'BE-SL':'rgba(180,120,240,.10)'
};

function setCalMode(mode) {
  _calMode = mode;
  document.getElementById('cal-btn-annual') ?.classList.toggle('active', mode === 'annual');
  document.getElementById('cal-btn-monthly')?.classList.toggle('active', mode === 'monthly');

  const monthSel = document.getElementById('cal-month-sel');
  const sortBtns = document.getElementById('cal-month-sort-btns');

  if (monthSel) setVisible(monthSel, mode === 'monthly');

  // hidden permanently: monthly view is always by hour
  if (sortBtns) setVisible(sortBtns, false);

  if (mode === 'monthly' && monthSel && !monthSel.dataset.initialized) {
    monthSel.value = String(new Date().getMonth() + 1).padStart(2, '0');
    monthSel.dataset.initialized = '1';
  }

  _calMonthSort = 'hour';
  renderCalendar(_calTrades);
}

function setCalMonthSort(sort) {
  _calMonthSort = 'hour';

  document.getElementById('cal-sort-hour')?.classList.add('active');
  document.getElementById('cal-sort-session')?.classList.remove('active');

  renderCalendar(_calTrades);
}

function renderCalendar(trades) {
  const grid = document.getElementById('calendar-grid');
  const yearSel = document.getElementById('cal-year-sel');
  if (!grid || !yearSel) return;

  if (!trades || !trades.length) {
    renderWidgetEmptyState('calendar-grid');
    return;
  }

  _calTrades = Array.isArray(trades) ? trades : [];
  _calRebuildCaches(_calTrades);

  const years = Object.keys(_calYearMap).sort().reverse();
  if (!years.length) {
    renderWidgetEmptyState('calendar-grid');
    return;
  }

  const prevYear = yearSel.value;
  yearSel.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
  yearSel.value = (prevYear && years.includes(prevYear)) ? prevYear : years[0];

  if (_calMode === 'monthly') {
    _renderCalendarMonthly(_calTrades, yearSel);
    return;
  }

  const year = yearSel.value;
  const cG = tc('--g');
  const cR = tc('--r');
  const maxAbs = _calGetYearMaxAbs(year);

  let html = `<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px 12px;padding:4px 2px">`;

  for (let mo = 0; mo < 12; mo++) {
    const daysInMonth = new Date(parseInt(year, 10), mo + 1, 0).getDate();
    const firstDow = (new Date(parseInt(year, 10), mo, 1).getDay() + 6) % 7;
    const moPrefix = `${year}-${String(mo + 1).padStart(2, '0')}`;
    const moTrades = (_calYearMap[year]?.months?.[moPrefix]?.trades) || [];
    const moR = moTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, appState.ui.tpConfig)) || 0), 0);
    const moW = moTrades.filter(isWinner).length;
    const moL = moTrades.filter(isLoser).length;
    const moN = moTrades.length;
    const moCol = moR >= 0 ? cG : cR;
    const moRgb = _calHexToRgb(moR >= 0 ? cG : cR);

    html += `<div>`;
    html += `
  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
    <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-header,9px);font-weight:600;letter-spacing:1.2px;color:var(--dim);text-transform:uppercase">
      ${_CAL_MONTHS[mo]}
    </div>
    ${moN > 0 ? `
      <div style="display:flex;align-items:center;gap:10px">
        <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-stats,7px);color:var(--dim)">
          ${moN}T
          <span style="color:var(--g)">${moW}W</span>
          <span style="color:var(--r)">${moL}L</span>
        </div>
        <div style="font-family:'Anybody',sans-serif;font-size:var(--fs-cal-value,11px);font-weight:800;color:${moCol}">
          ${moR >= 0 ? '+' : ''}${moR.toFixed(1)}R
        </div>
      </div>
    ` : ''}
  </div>
`;
    html += `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px">`;

    _CAL_DAY_LABELS.forEach(dl => {
      html += `<div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7.5px);color:var(--dim);text-align:center;padding-bottom:2px">${dl}</div>`;
    });

    for (let i = 0; i < firstDow; i++) {
      html += `<div style="aspect-ratio:1"></div>`;
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = `${year}-${String(mo + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      html += _calRenderAnnualDayCell(dateStr, _calDayMap[dateStr], maxAbs, cG, cR);
    }

    html += `</div>`;

    html += `</div>`;
  }

  html += `</div>`;
  grid.innerHTML = html;
}

function _calRebuildCaches(trades) {
  _calDayMap = {};
  _calYearMap = {};
  const tpConfig = appState.ui.tpConfig;

  for (const raw of trades) {
    if (!raw || !raw.date) continue;

    const t = { ...raw, r: Number(raw.r) || 0 };
    const r = computeEffectiveRR(t, tpConfig);
    const date = t.date;
    const year = date.slice(0, 4);
    const month = date.slice(0, 7);

    if (!_calDayMap[date]) {
      _calDayMap[date] = {
        r: 0,
        n: 0,
        wins: 0,
        losses: 0,
        trades: [],
        hours: {},
        sessions: {}
      };
    }

    const d = _calDayMap[date];
    d.r += r;
    d.n += 1;
    if (isWinner(t)) d.wins += 1;
    if (isLoser(t)) d.losses += 1;
    d.trades.push(t);

    const hKey = (t.hour != null && !isNaN(t.hour)) ? Number(t.hour) : -1;
    if (!d.hours[hKey]) d.hours[hKey] = { r: 0, n: 0, ocs: {}, trades: [] };
    d.hours[hKey].r += r;
    d.hours[hKey].n += 1;
    d.hours[hKey].trades.push(t);
    d.hours[hKey].ocs[t.outcome || 'SL'] = (d.hours[hKey].ocs[t.outcome || 'SL'] || 0) + 1;

    const sKey = t.session || '—';
    if (!d.sessions[sKey]) d.sessions[sKey] = { r: 0, n: 0, ocs: {}, trades: [] };
    d.sessions[sKey].r += r;
    d.sessions[sKey].n += 1;
    d.sessions[sKey].trades.push(t);
    d.sessions[sKey].ocs[t.outcome || 'SL'] = (d.sessions[sKey].ocs[t.outcome || 'SL'] || 0) + 1;

    if (!_calYearMap[year]) _calYearMap[year] = { maxAbs: 0, months: {} };
    if (!_calYearMap[year].months[month]) _calYearMap[year].months[month] = { trades: [] };
    _calYearMap[year].months[month].trades.push(t);
    _calYearMap[year].maxAbs = Math.max(_calYearMap[year].maxAbs, Math.abs(d.r));
  }
}

function _calGetYearMaxAbs(year) {
  return Math.max(_calYearMap[year]?.maxAbs || 0, 0.01);
}

function _calRenderAnnualDayCell(dateStr, data, maxAbs, cG, cR) {
  if (!data) {
    return `<div style="aspect-ratio:1;background:var(--bg3);border-radius:2px"></div>`;
  }

  const isWin = data.r > 0;
  const intensity = Math.min(Math.abs(data.r) / maxAbs, 1);
  const alpha = (0.18 + intensity * 0.72).toFixed(2);
  const hexCol = isWin ? cG : cR;
  const bg = `rgba(${_calHexToRgb(hexCol)},${alpha})`;
  const txtCol = intensity > 0.45 ? 'rgba(0,0,0,0.9)' : (isWin ? cG : cR);
  const sign = isWin ? '+' : '';
  const valStr = `${sign}${data.r.toFixed(1)}`;

  return `<div
    class="cal-day-cell"
    data-date="${dateStr}"
    data-action="cal-open-day"
    style="aspect-ratio:1;background:${bg};border-radius:2px;display:flex;align-items:center;justify-content:center;font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7px);font-weight:700;color:${txtCol};cursor:pointer;transition:filter .12s;line-height:1;overflow:hidden"
  >${valStr}</div>`;
}

function _renderCalendarMonthly(trades, yearSel) {
  const grid = document.getElementById('calendar-grid');
  const monthSel = document.getElementById('cal-month-sel');
  if (!grid) return;

  const years = Object.keys(_calYearMap).sort().reverse();
  if (!years.length) {
    grid.innerHTML = '<div class="no-data">No data</div>';
    return;
  }

  const prevYear = yearSel.value;
  yearSel.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
  yearSel.value = (prevYear && years.includes(prevYear)) ? prevYear : years[0];

  const year = yearSel.value;
  const selectedMonth = (monthSel ? monthSel.value : null) || String(new Date().getMonth() + 1).padStart(2, '0');
  const prefix = `${year}-${selectedMonth}`;
  const mo = parseInt(selectedMonth, 10) - 1;
  const daysInMonth = new Date(parseInt(year, 10), mo + 1, 0).getDate();
  const firstDow = (new Date(parseInt(year, 10), mo, 1).getDay() + 6) % 7;

  const mTrades = trades.filter(t => t.date && t.date.startsWith(prefix));
  const tpConfig = appState.ui.tpConfig;
  const totAll = mTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig)) || 0), 0);
  const winsAll = mTrades.filter(isWinner).length;
  const lossAll = mTrades.filter(isLoser).length;
  const maxAbs = Math.max(...Object.entries(_calDayMap).filter(([d]) => d.startsWith(prefix)).map(([,v]) => Math.abs(v.r)), 0.01);

  const cG = tc('--g');
  const cR = tc('--r');

  const summaryHtml = `<div style="background:var(--bg2);border-radius:5px;padding:8px 12px;margin-bottom:6px;flex-shrink:0;display:flex;justify-content:space-between;align-items:center">
    <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-header,9px);color:var(--dim)">${_CAL_MONTHS[mo]} ${year}</div>
    <div style="display:flex;flex-direction:column;align-items:flex-end;gap:1px">
      <div style="font-family:'Anybody',sans-serif;font-size:var(--fs-cal-summary,18px);font-weight:800;color:${totAll >= 0 ? 'var(--g)' : 'var(--r)'};line-height:1">${totAll >= 0 ? '+' : ''}${totAll.toFixed(1)}R</div>
      <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-stats,7px);color:var(--dim)">${mTrades.length}T &nbsp;<span style="color:var(--g)">${winsAll}W</span> <span style="color:var(--r)">${lossAll}L</span></div>
    </div>
  </div>`;

  const numWeeks = Math.ceil((firstDow + daysInMonth) / 7);
  let html = `<div style="flex:1;min-height:0;display:grid;grid-template-columns:repeat(7,1fr) minmax(52px,auto);grid-template-rows:auto repeat(${numWeeks},1fr);gap:3px">`;

  _CAL_DAY_LABELS.forEach(dl => {
    html += `<div style="text-align:center;font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7.5px);color:var(--dim);padding-bottom:3px">${dl}</div>`;
  });
  html += `<div style="text-align:center;font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7.5px);color:var(--dim);padding-bottom:3px">Week</div>`;

  for (let i = 0; i < firstDow; i++) html += `<div></div>`;

  let col = firstDow;
  let weekTrades = [];

  for (let day = 1; day <= daysInMonth; day++) {
    const dateStr = `${year}-${selectedMonth}-${String(day).padStart(2, '0')}`;
    const data = _calDayMap[dateStr];

    if (data) weekTrades.push(...data.trades);

    html += _calRenderMonthlyDayCell(dateStr, day, data, maxAbs, cG, cR);

    col++;
    const isLastDay = day === daysInMonth;
    const isEndOfWeek = col === 7;

    if (isEndOfWeek || isLastDay) {
      if (isLastDay && col < 7) {
        for (let i = col; i < 7; i++) html += `<div></div>`;
      }

      const wR = weekTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig)) || 0), 0);
      const wW = weekTrades.filter(isWinner).length;
      const wL = weekTrades.filter(isLoser).length;
      const wN = weekTrades.length;
      const wC = wR >= 0 ? 'var(--g)' : 'var(--r)';

      html += wN > 0
        ? `<div style="background:var(--bg2);border-radius:3px;padding:4px 3px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px">
            <div style="font-family:'Anybody',sans-serif;font-size:var(--fs-cal-value,11px);font-weight:800;color:${wC};line-height:1">${wR >= 0 ? '+' : ''}${wR.toFixed(1)}R</div>
            <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-stats,7px);color:var(--dim)">${wN}T</div>
            <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-stats,7px);display:flex;gap:3px">
              <span style="color:var(--g)">${wW}W</span><span style="color:var(--r)">${wL}L</span>
            </div>
          </div>`
        : `<div style="background:var(--bg2);border-radius:3px;opacity:0.3"></div>`;

      weekTrades = [];
      col = 0;
    }
  }

  html += `</div>`;
  if (!mTrades.length) html = `<div class="no-data">No trades for ${prefix}</div>`;

  grid.innerHTML = `<div style="padding:4px 2px;display:flex;flex-direction:column;height:100%;overflow:hidden">${summaryHtml}${html}</div>`;
}

function _calRenderMonthlyDayCell(dateStr, day, data, maxAbs, cG, cR) {
  if (!data) {
    return `<div style="background:var(--bg3);border-radius:3px;padding:3px;display:flex;flex-direction:column">
      <div style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7px);color:rgba(255,255,255,0.15)">${day}</div>
    </div>`;
  }

  const isWin = data.r >= 0;
  const rCol = isWin ? 'var(--g)' : 'var(--r)';
  const hdrBg = `rgba(${_calHexToRgb(isWin ? cG : cR)},0.20)`;

  let innerHtml = '';

  innerHtml = `<div style="flex:1;min-height:0;display:grid;grid-template-columns:repeat(6,1fr);grid-auto-rows:1fr;gap:1px">`;
  for (let h = 0; h < 24; h++) {
    const v = data.hours[h];
    if (v) {
      const rgb = _calOcRgb(v.ocs, cG, cR);
      const a = (0.45 + Math.min(Math.abs(v.r) / (maxAbs || 1), 1) * 0.50).toFixed(2);
      innerHtml += `<div title="${String(h).padStart(2, '0')}h: ${v.r >= 0 ? '+' : ''}${v.r.toFixed(1)}R" style="background:rgba(${rgb},${a});border-radius:1px"></div>`;
    } else {
      innerHtml += `<div title="${String(h).padStart(2, '0')}h" style="background:rgba(255,255,255,0.05);border-radius:1px"></div>`;
    }
  }
  innerHtml += `</div>`;

  return `<div
    class="cal-day-cell"
    data-date="${dateStr}"
    data-action="cal-open-day"
    style="background:var(--bg3);border-radius:3px;padding:3px;cursor:pointer;transition:filter .12s;display:flex;flex-direction:column"
  >
    <div style="flex-shrink:0;display:flex;justify-content:space-between;align-items:center;background:${hdrBg};border-radius:2px;padding:1px 3px;margin-bottom:2px">
      <span style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7px);color:var(--dim)">${day} <span style="opacity:0.6">${data.n}t</span></span>
      <span style="font-family:'DM Mono',monospace;font-size:var(--fs-cal-day,7px);font-weight:700;color:${rCol}">${isWin ? '+' : ''}${data.r.toFixed(1)}</span>
    </div>
    ${innerHtml}
  </div>`;
}

function _calShowTip(e, dateStr) {
  const day = _calDayMap[dateStr];
  if (!day || !day.trades.length) return;

  let tt = document.getElementById('cal-tooltip');
  if (!tt) {
    tt = document.createElement('div');
    tt.id = 'cal-tooltip';
    tt.className = 'floating-tooltip cal-tooltip';
    document.body.appendChild(tt);
  }

  const totalR = day.r;
  const wins = day.wins;
  const sign = totalR >= 0 ? '+' : '';
  const col = totalR >= 0 ? 'var(--g)' : 'var(--r)';

  const rows = day.trades.map(t => {
    const _rEff = t.effectiveR ?? computeEffectiveRR(t, appState.ui.tpConfig);
    return `<div style="display:grid;grid-template-columns:58px 1fr auto auto;gap:6px;align-items:center;padding:5px 10px;border-top:1px solid var(--line)">
      <span style="color:var(--dim);font-size:var(--typo-micro-size,8px)">${t.pair || '—'}</span>
      <span style="color:var(--body);font-size:var(--typo-micro-size,8px);overflow:hidden;text-overflow:ellipsis">${t.setup ? t.setup.split(' ').slice(-2).join(' ') : ''}</span>
      <span class="${_CAL_OC_CLASS[t.outcome] || ''}" style="font-size:var(--typo-micro-size,8px);font-weight:600">${t.outcome || '—'}</span>
      <span style="font-weight:700;color:${_rEff > 0 ? 'var(--g)' : _rEff < 0 ? 'var(--r)' : 'var(--gold)'}">${_rEff > 0 ? '+' : ''}${_rEff.toFixed(1)}R</span>
    </div>`;
  }).join('');

  tt.innerHTML = `
    <div style="padding:7px 10px;background:var(--bg2);display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)">
      <span style="color:var(--white);font-weight:700;font-size:var(--typo-table-body-size,10px)">${dateStr}</span>
      <span style="color:${col};font-weight:700;font-size:12px">${sign}${totalR.toFixed(1)}R</span>
    </div>
    <div style="padding:4px 10px 5px;display:flex;gap:12px;border-bottom:1px solid var(--line);font-size:var(--typo-micro-size,8px);color:var(--dim)">
      <span>${day.n} trade${day.n > 1 ? 's' : ''}</span>
      <span style="color:var(--g)">${wins}W</span><span style="color:var(--r)">${day.n - wins}L</span>
      <span style="margin-left:auto">Click to expand ↓</span>
    </div>${rows}`;

  const W = 200, H = 120 + day.trades.length * 28;
  const vw = window.innerWidth, vh = window.innerHeight;
  let x = e.clientX + 14, y = e.clientY - 20;
  if (x + W > vw - 8) x = e.clientX - W - 10;
  if (y + H > vh - 8) y = vh - H - 8;
  if (y < 8) y = 8;
  tt.style.left = x + 'px';
  tt.style.top = y + 'px';
  setVisible(tt, true);
}

function _calHideTip() {
  const tt = document.getElementById('cal-tooltip');
  if (tt) setVisible(tt, false);
}

function _calOpenDay(dateStr) {
  const day = _calDayMap[dateStr];
  const data = day ? day.trades : [];
  if (!data.length) return;
  _calHideTip();
  // Highlight the clicked day cell
  document.querySelectorAll('#calendar-grid [data-date]').forEach(el => el.classList.remove('wd-cell-active'));
  const el = document.querySelector(`#calendar-grid [data-date="${dateStr}"]`);
  if (el) el.classList.add('wd-cell-active');
  // Delegate to shared drawer
  const subtitle = `${day.n} trade${day.n>1?'s':''} · ${day.wins}W ${day.n-day.wins}L`;
  openWidgetDrawer(dateStr, subtitle, data);
}

function _calCloseDrawer() {
  // Kept for backward compat (onclick in calendar cells still calls this)
  closeWidgetDrawer();
}

function _calHexToRgb(h) {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h || '');
  return m ? `${parseInt(m[1],16)},${parseInt(m[2],16)},${parseInt(m[3],16)}` : '110,224,180';
}

function _calOcRgb(ocs, cG, cR) {
  const OC_RGB = {
    TP: _calHexToRgb(cG),
    'BE-TP': '41,98,255',
    'BE-SL': '180,120,240',
    SL: _calHexToRgb(cR)
  };
  const dom = Object.entries(ocs || {}).sort((a, b) => b[1] - a[1])[0]?.[0] || 'SL';
  return OC_RGB[dom] || _calHexToRgb(cR);
}


// ══════════════════════════════════════════════════════
// MONTE CARLO SIMULATION WIDGET — ADVANCED
//   Inputs: initialBalance, risk%, winRate%, tradesPerMonth, months, rr
//   Engine: 2,000 iterations, percentile scenarios (p5 / p50 / p95)
//   Output: 3 clickable scenario cards + multi-line equity chart
// ══════════════════════════════════════════════════════
let _mcChart = null;
let _mc2LastRun = null;          // { worst, median, best, totalTrades, initial }
let _mc2ActiveTab = 'median';    // 'worst' | 'median' | 'best'
let _mc2SimToken = 0;            // cancels in-flight async sims on re-run
let _mc2InputsBound = false;
let _mc2ShowSpectrum = false;    // toggled via the header checkbox

const _MC2_DEFAULTS = {
  balance: 100000,
  risk:    1,
  wr:      50,
  tpm:     20,
  months:  12,
  rr:      2.4,
  mode:    'full',  // 'full' | 'multi'
  tps: [
    { R: 1.0, reach: 60, size: 50 },
    { R: 2.0, reach: 35, size: 30 },
    { R: 3.0, reach: 20, size: 20 }
  ]
};
const _MC2_MULTI_PREFS_KEY = 'mc2-multi-tp-v1';

// Spectrum paths shown behind the 3 scenario curves
const _MC2_SPECTRUM_COUNT = 100;

// ── Internal GridStack layout (like Partials Planner) ──
const _MC2_SECTION_LAYOUT_KEY = 'mc2-section-layout-v2';
const _MC2_SECTION_GRID_COLS  = 12;
const _MC2_SECTION_MIN = {
  inputs: { w: 3, h: 8 },
  chart:  { w: 4, h: 8 },
  bilan:  { w: 3, h: 8 }
};
const _MC2_DEFAULT_SECTION_LAYOUT = {
  inputs: { x: 1,  y: 1, w: 3, h: 18 },
  chart:  { x: 4,  y: 1, w: 6, h: 18 },
  bilan:  { x: 10, y: 1, w: 3, h: 18 }
};
let _mc2SectionEditBound = false;

// ── Called from renderPanels() — refreshes the input fields from the
// current filtered dataset without launching a simulation. The user must
// click Simulate manually.
function runMonteCarlo(trades) {
  _mc2BindOnce();
  _mc2PopulateInputsFromDataset(trades || []);
  _mc2UpdateChartEmpty();
}

function _mc2BindOnce() {
  if (_mc2InputsBound) return;
  _mc2InputsBound = true;

  // Scenario tab switching
  const scope = document.getElementById('mc2-scenarios');
  if (scope) {
    scope.addEventListener('click', (e) => {
      const btn = e.target.closest('.mc2-card');
      if (!btn) return;
      const tab = btn.dataset.mc2Tab;
      if (!tab || tab === _mc2ActiveTab) return;
      _mc2ActiveTab = tab;
      _mc2RefreshActiveTabUI();
      if (_mc2LastRun) _mc2RenderChart(_mc2LastRun);
    });
  }

  // Spectrum toggle
  const tog = document.getElementById('mc2-show-spectrum');
  if (tog) {
    _mc2ShowSpectrum = tog.checked;
    tog.addEventListener('change', () => {
      _mc2ShowSpectrum = tog.checked;
      if (_mc2LastRun) _mc2RenderChart(_mc2LastRun);
    });
  }

  // Track user interaction with the compounding checkbox so we don't
  // overwrite their choice on dataset switch.
  const cmp = document.getElementById('mc2-in-compound');
  if (cmp) cmp.addEventListener('change', () => { cmp.dataset.mc2Touched = '1'; });

  _mc2BindMultiTpUI();

  _mc2ApplySectionLayout();
  _mc2InitSectionLayoutEdit();
}

// ── Multi TP: persistence + mode toggle + live validation/EV ──
let _mc2TpMode = 'full';
function _mc2GetMode() { return _mc2TpMode; }

function _mc2LoadMultiPrefs() {
  try {
    const raw = JSON.parse(localStorage.getItem(_MC2_MULTI_PREFS_KEY));
    if (!raw || typeof raw !== 'object') return null;
    return raw;
  } catch { return null; }
}
function _mc2SaveMultiPrefs() {
  try {
    const read = (id) => {
      const v = parseFloat(document.getElementById(id)?.value);
      return Number.isFinite(v) ? v : null;
    };
    const payload = {
      mode: _mc2TpMode,
      tps: [1, 2, 3].map((n) => ({
        R:     read(`mc2-in-tp${n}-r`),
        reach: read(`mc2-in-tp${n}-reach`),
        size:  read(`mc2-in-tp${n}-size`)
      }))
    };
    localStorage.setItem(_MC2_MULTI_PREFS_KEY, JSON.stringify(payload));
  } catch {}
}

function _mc2ApplyModeUI(mode) {
  _mc2TpMode = (mode === 'multi') ? 'multi' : 'full';
  // Toggle buttons
  document.querySelectorAll('.mc2-tp-mode-btn').forEach((b) => {
    const isActive = b.dataset.mc2TpMode === _mc2TpMode;
    b.classList.toggle('is-active', isActive);
    b.setAttribute('aria-selected', isActive ? 'true' : 'false');
  });
  // Show/hide full-vs-multi sections
  document.querySelectorAll('[data-mc2-mode-only]').forEach((el) => {
    const show = el.dataset.mc2ModeOnly === _mc2TpMode;
    if (show) { el.hidden = false; el.style.display = ''; }
    else      { el.hidden = true;  el.style.display = 'none'; }
  });
  // Disable WR input in multi mode — the effective WR comes from TP1 reach
  const wrField = document.querySelector('[data-mc2-field="wr"]');
  const wrInput = document.getElementById('mc2-in-wr');
  if (wrField && wrInput) {
    const isMulti = _mc2TpMode === 'multi';
    wrField.classList.toggle('is-disabled', isMulti);
    wrInput.disabled = isMulti;
  }
  _mc2RefreshMultiValidation();
}

function _mc2ReadTpsFromUi() {
  const read = (id, fb) => {
    const v = parseFloat(document.getElementById(id)?.value);
    return Number.isFinite(v) ? v : fb;
  };
  return [1, 2, 3].map((n, i) => ({
    R:     read(`mc2-in-tp${n}-r`,     _MC2_DEFAULTS.tps[i].R),
    reach: read(`mc2-in-tp${n}-reach`, _MC2_DEFAULTS.tps[i].reach),
    size:  read(`mc2-in-tp${n}-size`,  _MC2_DEFAULTS.tps[i].size)
  }));
}

function _mc2RefreshMultiValidation() {
  const tps = _mc2ReadTpsFromUi();
  const sumSize = tps.reduce((a, t) => a + (+t.size || 0), 0);
  const sizeOk = Math.abs(sumSize - 100) <= 0.1;
  const reachOk = tps[0].reach >= tps[1].reach && tps[1].reach >= tps[2].reach;

  const sizeHelper = document.getElementById('mc2-multi-size-helper');
  if (sizeHelper) {
    sizeHelper.textContent = sizeOk
      ? `TP sizes: 100%`
      : `TP sizes must sum to 100% (current: ${sumSize.toFixed(1)}%)`;
    sizeHelper.dataset.tone = sizeOk ? 'ok' : 'err';
  }
  const reachHelper = document.getElementById('mc2-multi-reach-helper');
  if (reachHelper) reachHelper.hidden = reachOk;

  // EV = Σ sizek × Rk × reachk  − (1 − reach1)   (units = R per trade)
  const frac = (x) => Math.max(0, Math.min(100, +x || 0)) / 100;
  const r1 = frac(tps[0].reach), r2 = frac(tps[1].reach), r3 = frac(tps[2].reach);
  const ev = frac(tps[0].size) * (+tps[0].R || 0) * r1
           + frac(tps[1].size) * (+tps[1].R || 0) * r2
           + frac(tps[2].size) * (+tps[2].R || 0) * r3
           - (1 - r1);
  const evEl = document.getElementById('mc2-multi-ev');
  if (evEl) {
    evEl.textContent = `EV = ${(ev >= 0 ? '+' : '')}${ev.toFixed(2)} R/trade`;
    evEl.dataset.tone = ev > 0.005 ? 'pos' : (ev < -0.005 ? 'neg' : 'dim');
  }

  // Only gate Simulate in Multi mode. In Full mode it's always enabled.
  const btn = document.getElementById('mc2-simulate-btn');
  if (btn) {
    const blocked = (_mc2TpMode === 'multi') && !sizeOk;
    btn.disabled = blocked;
    btn.classList.toggle('is-disabled', blocked);
  }
}

function _mc2BindMultiTpUI() {
  // Load saved prefs → populate inputs
  const prefs = _mc2LoadMultiPrefs();
  const tps = (prefs && Array.isArray(prefs.tps) && prefs.tps.length === 3)
    ? prefs.tps
    : _MC2_DEFAULTS.tps;
  [1, 2, 3].forEach((n, i) => {
    const set = (id, v, fb) => {
      const el = document.getElementById(id);
      if (el && el.value === '') el.value = Number.isFinite(+v) ? +v : fb;
      else if (el && Number.isFinite(+v)) el.value = +v;
      else if (el) el.value = fb;
    };
    set(`mc2-in-tp${n}-r`,     tps[i]?.R,     _MC2_DEFAULTS.tps[i].R);
    set(`mc2-in-tp${n}-reach`, tps[i]?.reach, _MC2_DEFAULTS.tps[i].reach);
    set(`mc2-in-tp${n}-size`,  tps[i]?.size,  _MC2_DEFAULTS.tps[i].size);
  });

  // Toggle listener
  document.querySelectorAll('.mc2-tp-mode-btn').forEach((b) => {
    b.addEventListener('click', () => {
      const m = b.dataset.mc2TpMode;
      if (m === _mc2TpMode) return;
      _mc2ApplyModeUI(m);
      _mc2SaveMultiPrefs();
    });
  });

  // Live input listeners (validation + EV + persistence)
  const liveIds = [];
  [1, 2, 3].forEach((n) => {
    liveIds.push(`mc2-in-tp${n}-r`, `mc2-in-tp${n}-reach`, `mc2-in-tp${n}-size`);
  });
  liveIds.forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('input', () => {
      _mc2RefreshMultiValidation();
      _mc2SaveMultiPrefs();
    });
  });

  // Apply saved mode (defaults to 'full')
  const savedMode = (prefs && (prefs.mode === 'full' || prefs.mode === 'multi'))
    ? prefs.mode
    : _MC2_DEFAULTS.mode;
  _mc2ApplyModeUI(savedMode);
}

// ── Populate input fields ──
// Only Win Rate is derived from the dataset. Balance, risk, tpm, months,
// and rr use the fixed defaults (20 trades/month, 12 months, 2.4 RR) so
// the simulation reflects a standard planning horizon rather than the
// specific sample size of the current filter.
function _mc2PopulateInputsFromDataset(trades) {
  const stats = calcStats(trades);
  const wr = stats && Number.isFinite(stats.wr) ? stats.wr : _MC2_DEFAULTS.wr;

  const setVal = (id, value) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.value = value;
    el.dataset.mc2Auto = '1';
  };

  setVal('mc2-in-balance', _MC2_DEFAULTS.balance);
  setVal('mc2-in-risk',    _MC2_DEFAULTS.risk);
  setVal('mc2-in-wr',      +wr.toFixed(1));
  setVal('mc2-in-tpm',     _MC2_DEFAULTS.tpm);
  setVal('mc2-in-months',  _MC2_DEFAULTS.months);
  setVal('mc2-in-rr',      _MC2_DEFAULTS.rr);
  // Compounding defaults OFF — fixed-dollar risk is safer and more common.
  // Only set the first time (don't stomp a user choice on dataset switch).
  const cmp = document.getElementById('mc2-in-compound');
  if (cmp && cmp.dataset.mc2Touched !== '1') cmp.checked = false;

  _mc2SetStatus('Ready');
}

function _mc2SetStatus(text, tone) {
  const el = document.getElementById('mc2-status');
  if (!el) return;
  el.textContent = text;
  el.dataset.tone = tone || '';
}

function _mc2ReadInputs() {
  const num = (id, fb) => {
    const v = parseFloat(document.getElementById(id)?.value);
    return Number.isFinite(v) ? v : fb;
  };
  const mode = _mc2GetMode();
  const tps = [1, 2, 3].map((n, i) => ({
    R:     Math.max(0,   num(`mc2-in-tp${n}-r`,     _MC2_DEFAULTS.tps[i].R)),
    reach: Math.max(0,   Math.min(100, num(`mc2-in-tp${n}-reach`, _MC2_DEFAULTS.tps[i].reach))),
    size:  Math.max(0,   Math.min(100, num(`mc2-in-tp${n}-size`,  _MC2_DEFAULTS.tps[i].size)))
  }));
  // In Multi TP mode, TP1.reach drives the effective win rate regardless
  // of the wr input (which is disabled in the UI).
  const wrInput = Math.max(0, Math.min(100, num('mc2-in-wr', _MC2_DEFAULTS.wr)));
  return {
    balance:  Math.max(1,     num('mc2-in-balance', _MC2_DEFAULTS.balance)),
    risk:     Math.max(0.01,  Math.min(100, num('mc2-in-risk', _MC2_DEFAULTS.risk))),
    wr:       mode === 'multi' ? tps[0].reach : wrInput,
    tpm:      Math.max(1,     Math.round(num('mc2-in-tpm',    _MC2_DEFAULTS.tpm))),
    months:   Math.max(1,     Math.round(num('mc2-in-months', _MC2_DEFAULTS.months))),
    rr:       Math.max(0.1,   num('mc2-in-rr',  _MC2_DEFAULTS.rr)),
    compound: !!document.getElementById('mc2-in-compound')?.checked,
    mode,
    tps
  };
}

function _mc2UpdateChartEmpty() {
  const empty = document.getElementById('mc2-chart-empty');
  if (!empty) return;
  empty.style.display = _mc2LastRun ? 'none' : 'flex';
}

// ── Public entry: runs when the Simulate button is clicked ──
function _mc2RunSimulate() {
  const inputs = _mc2ReadInputs();
  const N      = inputs.tpm * inputs.months;      // trades per iteration
  const ITER   = 2000;
  if (N < 1) { _mc2SetStatus('Check inputs', 'warn'); return; }

  const token = ++_mc2SimToken;
  _mc2SetStatus(`Simulating ${ITER.toLocaleString()}×${N.toLocaleString()}…`);
  const btn = document.getElementById('mc2-simulate-btn');
  if (btn) { btn.disabled = true; btn.classList.add('is-busy'); }

  // Async chunked engine to keep the UI responsive.
  _mc2SimulateAsync(inputs, N, ITER, token, (result) => {
    if (btn) { btn.disabled = false; btn.classList.remove('is-busy'); }
    if (token !== _mc2SimToken) return;   // superseded by a later click
    if (!result) { _mc2SetStatus('Cancelled', 'warn'); return; }
    _mc2LastRun = result;
    _mc2UpdateChartEmpty();
    _mc2RenderCards(result, inputs);
    _mc2RenderChart(result);
    _mc2SetStatus(`Done · ${ITER.toLocaleString()} iterations`, 'ok');
  });
}

// ── Async Monte Carlo engine (chunked with setTimeout) ──
// Each iteration: simulate N trades compounding the balance. Each trade
// either wins (+balance * risk% * RR) or loses (-balance * risk%). The
// iteration's full equity curve is recorded for percentile extraction.
function _mc2SimulateAsync(inp, N, ITER, token, done) {
  const { balance: B0, risk, wr, rr, compound, mode, tps } = inp;
  const riskFrac = risk / 100;
  const winProb  = wr / 100;
  // Fixed-dollar risk (non-compounding): every trade risks the same cash
  // amount, based on the initial balance. Compounding re-bases off the
  // current balance so wins and losses scale dynamically.
  const fixedRiskAmt = B0 * riskFrac;
  // Multi TP lookup: single uniform draw u ∈ [0,1] per trade. TP_k hits iff
  // u < reach_k/100. This 1-draw formulation treats reach as absolute and
  // guarantees coherence (TP3⇒TP2⇒TP1) when reach is monotonically decreasing.
  const isMulti = mode === 'multi';
  const t0 = isMulti ? (tps[0].reach / 100) : 0;
  const t1 = isMulti ? (tps[1].reach / 100) : 0;
  const t2 = isMulti ? (tps[2].reach / 100) : 0;
  const s0 = isMulti ? (tps[0].size / 100) : 0;
  const s1 = isMulti ? (tps[1].size / 100) : 0;
  const s2 = isMulti ? (tps[2].size / 100) : 0;
  const r0 = isMulti ? tps[0].R : 0;
  const r1 = isMulti ? tps[1].R : 0;
  const r2 = isMulti ? tps[2].R : 0;

  // Iteration records
  const finals      = new Float64Array(ITER);
  const maxDDs      = new Float64Array(ITER);
  const maxLoseR    = new Int32Array(ITER);
  const maxWinR     = new Int32Array(ITER);
  const winPcts     = new Float32Array(ITER);
  // Equity curves (N+1 points each). Float32 keeps memory bounded.
  // ITER * (N+1) — at ITER=2000 N=240 → 482k floats ≈ 1.9 MB. Fine.
  const curves      = new Array(ITER);

  // Larger chunks + MessageChannel yield: setTimeout(0) is clamped to 1s
  // when the tab is backgrounded, which would stall long sims. A MessageChannel
  // port.postMessage → onmessage runs on the next macrotask *without* clamping.
  const CHUNK = Math.max(200, Math.floor(ITER / 10));  // ~10 chunks for ITER=2000
  let i = 0;

  const _chan = new MessageChannel();
  const _scheduleNext = () => _chan.port2.postMessage(0);

  function step() {
    if (token !== _mc2SimToken) { done(null); return; }
    const end = Math.min(ITER, i + CHUNK);
    for (; i < end; i++) {
      let bal = B0, peak = B0, maxDD = 0;
      let curW = 0, curL = 0, mxW = 0, mxL = 0, wins = 0;
      const curve = new Float32Array(N + 1);
      curve[0] = B0;
      for (let k = 0; k < N; k++) {
        const riskAmt = compound ? bal * riskFrac : fixedRiskAmt;
        if (isMulti) {
          const u = Math.random();
          if (u < t0) {
            // TP1 reached → trade is a win. Portions for TP2/TP3 realise R only
            // if their reach threshold is also crossed; otherwise the portion
            // exits at BE (0R contribution).
            let gainR = s0 * r0;
            if (u < t1) gainR += s1 * r1;
            if (u < t2) gainR += s2 * r2;
            bal += riskAmt * gainR;
            wins++;
            curW++; curL = 0;
            if (curW > mxW) mxW = curW;
          } else {
            bal -= riskAmt;
            curL++; curW = 0;
            if (curL > mxL) mxL = curL;
          }
        } else if (Math.random() < winProb) {
          bal += riskAmt * rr;
          wins++;
          curW++; curL = 0;
          if (curW > mxW) mxW = curW;
        } else {
          bal -= riskAmt;
          curL++; curW = 0;
          if (curL > mxL) mxL = curL;
        }
        if (bal > peak) peak = bal;
        const dd = peak > 0 ? (peak - bal) / peak : 0;
        if (dd > maxDD) maxDD = dd;
        curve[k + 1] = bal;
      }
      finals[i]   = bal;
      maxDDs[i]   = maxDD;
      maxLoseR[i] = mxL;
      maxWinR[i]  = mxW;
      winPcts[i]  = N > 0 ? (wins / N) * 100 : 0;
      curves[i]   = curve;
    }
    if (i < ITER) {
      _scheduleNext();   // yield without throttling
    } else {
      _chan.port1.onmessage = null;
      done(_mc2Reduce({ finals, maxDDs, maxLoseR, maxWinR, winPcts, curves, B0, N }));
    }
  }
  _chan.port1.onmessage = step;
  step();
}

// ── Reduce raw iteration data into the 3 scenario buckets ──
// Also samples ~100 equity curves across the full rank distribution so the
// chart can render a faint "spectrum" of possible outcomes behind the 3
// named scenarios.
function _mc2Reduce({ finals, maxDDs, maxLoseR, maxWinR, winPcts, curves, B0, N }) {
  const ITER = finals.length;
  const idxSorted = Array.from({ length: ITER }, (_, i) => i)
    .sort((a, b) => finals[a] - finals[b]);

  const pick = (p) => idxSorted[Math.min(ITER - 1, Math.max(0, Math.floor(p * ITER)))];
  const iWorst = pick(0.05);
  const iMed   = pick(0.50);
  const iBest  = pick(0.95);

  const pack = (idx) => ({
    finalBalance:  finals[idx],
    maxDD:         maxDDs[idx],
    maxLoseStreak: maxLoseR[idx],
    maxWinStreak:  maxWinR[idx],
    winPct:        winPcts[idx],
    curve:         curves[idx]
  });

  // Evenly-spaced spectrum sample across the rank distribution
  const spectrumCount = Math.min(_MC2_SPECTRUM_COUNT, ITER);
  const spectrum = new Array(spectrumCount);
  for (let k = 0; k < spectrumCount; k++) {
    const rank = Math.floor((k + 0.5) / spectrumCount * ITER);
    const idx  = idxSorted[Math.min(ITER - 1, rank)];
    spectrum[k] = { curve: curves[idx], finalBalance: finals[idx] };
  }

  return {
    worst:       pack(iWorst),
    median:      pack(iMed),
    best:        pack(iBest),
    spectrum,
    initial:     B0,
    totalTrades: N
  };
}

// ── Render the 3 scenario cards ──
function _mc2RenderCards(run, inputs) {
  const fmtMoney = v => '$' + Math.round(v).toLocaleString('en-US');
  const fmtPct   = v => (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
  const fmtDD    = v => '−' + (v * 100).toFixed(1) + '%';

  const setSlot = (cardEl, slot, text, tone) => {
    const el = cardEl.querySelector(`[data-mc2-slot="${slot}"]`);
    if (!el) return;
    el.textContent = text;
    if (tone) el.dataset.tone = tone;
  };

  const fmtDeltaCash = v => (v >= 0 ? '+$' : '−$') + Math.round(Math.abs(v)).toLocaleString('en-US');
  const fmtPctInline = v => (v >= 0 ? '+' : '') + v.toFixed(2) + '%';

  const fill = (tabKey, s) => {
    const card = document.querySelector(`.mc2-card[data-mc2-tab="${tabKey}"]`);
    if (!card) return;
    const ret = ((s.finalBalance - run.initial) / run.initial) * 100;
    const retTone = ret >= 0 ? 'pos' : 'neg';
    const delta = s.finalBalance - run.initial;
    const months = Math.max(1, inputs.months);
    const ratio = run.initial > 0 ? s.finalBalance / run.initial : 0;
    const avgMoPct = ratio > 0 ? (Math.pow(ratio, 1 / months) - 1) * 100 : -100;
    const avgMoCash = delta / months;
    const avgMoTone = avgMoCash >= 0 ? 'pos' : 'neg';

    setSlot(card, 'result',  fmtMoney(s.finalBalance), retTone);
    setSlot(card, 'return',  `${fmtPct(ret)} (${fmtDeltaCash(delta)})`, retTone);
    setSlot(card, 'initial', fmtMoney(run.initial));
    setSlot(card, 'months',  String(inputs.months));
    setSlot(card, 'avgmo',   `${fmtDeltaCash(avgMoCash)} (${fmtPctInline(avgMoPct)})`, avgMoTone);
    setSlot(card, 'maxdd',   fmtDD(s.maxDD),           'neg');
    setSlot(card, 'maxll',   String(s.maxLoseStreak),  'neg');
    setSlot(card, 'maxww',   String(s.maxWinStreak),   'pos');
    setSlot(card, 'wr',      s.winPct.toFixed(1) + '%');
  };

  fill('worst',  run.worst);
  fill('median', run.median);
  fill('best',   run.best);

  _mc2RefreshActiveTabUI();
}

function _mc2RefreshActiveTabUI() {
  document.querySelectorAll('.mc2-card').forEach(el => {
    el.classList.toggle('is-active', el.dataset.mc2Tab === _mc2ActiveTab);
  });
}

// ── Render the multi-line equity chart ──
function _mc2RenderChart(run) {
  const canvas = document.getElementById('mcCanvas');
  if (!canvas) return;
  if (_mcChart) { _mcChart.destroy(); _mcChart = null; }

  const cG     = tc('--g');
  const cR     = tc('--r');
  const cGold  = tc('--gold');
  const cDim   = tc('--dim');
  const cLine  = tc('--line');

  const colorFor = (tab) => tab === 'worst' ? cR : tab === 'best' ? cG : cGold;

  const N = run.totalTrades;
  // Sparse labels — one label per ~5% of the x-axis
  const labels = new Array(N + 1);
  for (let i = 0; i <= N; i++) labels[i] = i;

  const rgbG = _mc2Hex2Rgb(cG);
  const rgbR = _mc2Hex2Rgb(cR);

  const makeDs = (tab, curve) => {
    const active = tab === _mc2ActiveTab;
    const baseColor = colorFor(tab);
    const base = {
      label: tab,
      data: Array.from(curve),
      borderColor: active
        ? baseColor
        : `rgba(${_mc2Hex2Rgb(baseColor)},0.55)`,
      borderWidth: active ? 2.6 : 1.4,
      pointRadius: 0,
      tension: 0.25,
      order: active ? 1 : 2
    };
    if (active) {
      // Fill from the line down to the initial-balance reference, green when
      // the equity is above, red when it drops below.
      base.fill = {
        target: { value: run.initial },
        above: `rgba(${rgbG},0.18)`,
        below: `rgba(${rgbR},0.22)`
      };
      base.backgroundColor = `rgba(${_mc2Hex2Rgb(baseColor)},0.12)`;
    } else {
      base.fill = false;
      base.backgroundColor = 'transparent';
    }
    return base;
  };

  const datasets = [];

  // ── Spectrum: ~100 faint equity paths showing the full distribution ──
  if (_mc2ShowSpectrum && Array.isArray(run.spectrum)) {
    run.spectrum.forEach(s => {
      const positive = s.finalBalance >= run.initial;
      datasets.push({
        label: '_spectrum',
        data: Array.from(s.curve),
        borderColor: positive
          ? `rgba(${rgbG},0.10)`
          : `rgba(${rgbR},0.10)`,
        borderWidth: 0.8,
        pointRadius: 0,
        tension: 0.2,
        fill: false,
        order: 20
      });
    });
  }

  // ── Named scenarios on top ──
  datasets.push(makeDs('worst',  run.worst.curve));
  datasets.push(makeDs('best',   run.best.curve));
  datasets.push(makeDs('median', run.median.curve));

  // ── Initial-balance reference ──
  datasets.push({
    label: '_baseline',
    data: new Array(N + 1).fill(run.initial),
    borderColor: `rgba(${_mc2Hex2Rgb(cDim)},0.35)`,
    borderDash: [4, 4],
    borderWidth: 1,
    pointRadius: 0,
    fill: false,
    order: 10
  });

  datasets.sort((a, b) => b.order - a.order);

  const tickSize = parseFloat(tc('--typo-mc-tick-size')) || 8;

  _mcChart = new Chart(canvas, {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 300, easing: 'easeOutCubic' },
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          enabled: true,
          backgroundColor: tc('--bg2'),
          titleColor:  tc('--white'),
          bodyColor:   tc('--body'),
          borderColor: tc('--line2'),
          borderWidth: 1,
          padding: 8,
          titleFont: { family: '"DM Mono", monospace', size: 10, weight: '600' },
          bodyFont:  { family: '"DM Mono", monospace', size: 10 },
          callbacks: {
            title: (items) => `Trade #${items[0].label}`,
            label: (ctx) => {
              const lbl = ctx.dataset.label;
              if (lbl === '_baseline' || lbl === '_spectrum') return null;
              const name = lbl === 'worst' ? 'Worst'
                         : lbl === 'best'  ? 'Best'
                         : 'Most Possible';
              const v = ctx.parsed.y;
              return `${name}: $${Math.round(v).toLocaleString('en-US')}`;
            }
          },
          filter: (item) => item.dataset.label !== '_baseline' && item.dataset.label !== '_spectrum'
        }
      },
      scales: {
        x: {
          ticks: {
            color: cDim,
            font: { size: tickSize, family: '"DM Mono", monospace' },
            maxTicksLimit: 8,
            autoSkip: true
          },
          grid: { color: cLine, drawBorder: false }
        },
        y: {
          ticks: {
            color: cDim,
            font: { size: tickSize, family: '"DM Mono", monospace' },
            maxTicksLimit: 6,
            callback: v => '$' + (Math.abs(v) >= 1000 ? (v / 1000).toFixed(v % 1000 === 0 ? 0 : 1) + 'k' : v)
          },
          grid: { color: cLine, drawBorder: false }
        }
      }
    }
  });
}

function _mc2Hex2Rgb(hex) {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex || '');
  if (!m) return '180,180,180';
  return `${parseInt(m[1],16)},${parseInt(m[2],16)},${parseInt(m[3],16)}`;
}

// Back-compat: some other places in the file reference _hexToRgb.
function _hexToRgb(hex) { return _mc2Hex2Rgb(hex); }

// ── Internal GridStack layout (section drag/resize in Layout Edit mode) ──
function _mc2CloneLayout(layout) {
  return Object.fromEntries(
    Object.entries(layout).map(([k, v]) => [k, { ...v }])
  );
}
function _mc2RectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
function _mc2ClampSectionRect(key, rect) {
  const min = _MC2_SECTION_MIN[key] || { w: 3, h: 3 };
  const w = Math.max(min.w, Math.min(_MC2_SECTION_GRID_COLS, Math.round(rect.w || min.w)));
  const h = Math.max(min.h, Math.round(rect.h || min.h));
  const x = Math.max(1, Math.min(_MC2_SECTION_GRID_COLS - w + 1, Math.round(rect.x || 1)));
  const y = Math.max(1, Math.round(rect.y || 1));
  return { x, y, w, h };
}
function _mc2CompactLayout(layout) {
  const keys = Object.keys(layout).sort((a, b) => layout[a].y - layout[b].y || layout[a].x - layout[b].x);
  keys.forEach(key => {
    const rect = layout[key];
    let nextY = rect.y;
    while (nextY > 1) {
      const probe = { ...rect, y: nextY - 1 };
      const blocked = keys.some(other => other !== key && _mc2RectsOverlap(probe, layout[other]));
      if (blocked) break;
      nextY -= 1;
    }
    rect.y = nextY;
  });
  return layout;
}
function _mc2NormalizeLayout(raw) {
  const layout = _mc2CloneLayout(_MC2_DEFAULT_SECTION_LAYOUT);
  if (raw && typeof raw === 'object') {
    Object.keys(_MC2_DEFAULT_SECTION_LAYOUT).forEach(key => {
      if (raw[key]) layout[key] = _mc2ClampSectionRect(key, raw[key]);
    });
  }
  const keys = Object.keys(layout).sort((a, b) => layout[a].y - layout[b].y || layout[a].x - layout[b].x);
  for (let i = 0; i < keys.length; i++) {
    for (let j = i + 1; j < keys.length; j++) {
      if (_mc2RectsOverlap(layout[keys[i]], layout[keys[j]])) {
        layout[keys[j]].y = layout[keys[i]].y + layout[keys[i]].h;
      }
    }
  }
  return _mc2CompactLayout(layout);
}
function _mc2GetSectionLayout() {
  try { return _mc2NormalizeLayout(JSON.parse(localStorage.getItem(_MC2_SECTION_LAYOUT_KEY))); }
  catch { return _mc2CloneLayout(_MC2_DEFAULT_SECTION_LAYOUT); }
}
function _mc2SaveSectionLayout(layout) {
  try { localStorage.setItem(_MC2_SECTION_LAYOUT_KEY, JSON.stringify(_mc2NormalizeLayout(layout))); } catch {}
}
function _mc2SetSectionRect(layout, key, nextRect) {
  const next = _mc2CloneLayout(layout);
  next[key] = _mc2ClampSectionRect(key, nextRect);
  const keys = Object.keys(next).filter(k => k !== key);
  let changed = true;
  while (changed) {
    changed = false;
    keys.forEach(other => {
      if (_mc2RectsOverlap(next[key], next[other])) {
        next[other] = { ...next[other], y: next[key].y + next[key].h };
        changed = true;
      }
    });
  }
  return _mc2CompactLayout(next);
}
function _mc2ApplySectionLayout() {
  const grid = document.getElementById('mc2-main-grid');
  if (!grid) return;
  const layout = _mc2GetSectionLayout();
  let maxRow = 0;
  grid.querySelectorAll('.mc2-section-block').forEach(block => {
    const key = block.dataset.mc2Section;
    const rect = layout[key] || _MC2_DEFAULT_SECTION_LAYOUT[key];
    block.style.gridColumn = `${rect.x} / span ${rect.w}`;
    block.style.gridRow    = `${rect.y} / span ${rect.h}`;
    maxRow = Math.max(maxRow, rect.y + rect.h - 1);
  });
  grid.style.setProperty('--mc2-grid-rows', String(maxRow));
  // Chart.js doesn't auto-resize when grid cell changes — ping it
  if (_mcChart) requestAnimationFrame(() => { try { _mcChart.resize(); } catch {} });
}
function _mc2InitSectionLayoutEdit() {
  if (_mc2SectionEditBound) return;
  const grid = document.getElementById('mc2-main-grid');
  const widget = document.querySelector('[data-gs-id="w-montecarlo"]');
  if (!grid || !widget) return;
  _mc2SectionEditBound = true;

  const getGridMetrics = () => {
    const rect = grid.getBoundingClientRect();
    const styles = getComputedStyle(grid);
    const colGap = parseFloat(styles.columnGap || styles.gap || '0') || 0;
    const rowGap = parseFloat(styles.rowGap    || styles.gap || '0') || 0;
    const usableW = Math.max(1, rect.width - colGap * (_MC2_SECTION_GRID_COLS - 1));
    const colW = usableW / _MC2_SECTION_GRID_COLS;
    const rowH = parseFloat(styles.getPropertyValue('--mc2-row-h')) || 28;
    return { rect, colW, rowH, colGap, rowGap };
  };
  const toGridPoint = (clientX, clientY) => {
    const { rect, colW, rowH, colGap, rowGap } = getGridMetrics();
    const colStep = colW + colGap;
    const rowStep = rowH + rowGap;
    return {
      x: Math.max(1, Math.min(_MC2_SECTION_GRID_COLS, Math.round((clientX - rect.left) / Math.max(1, colStep)) + 1)),
      y: Math.max(1, Math.round((clientY - rect.top) / Math.max(1, rowStep)) + 1),
    };
  };

  const begin = (key, mode, startEvent, dir = 'se') => {
    if (!_editMode) return;
    startEvent.preventDefault();
    const layout = _mc2GetSectionLayout();
    const start = layout[key];
    if (!start) return;
    const block = grid.querySelector(`.mc2-section-block[data-mc2-section="${key}"]`);
    block?.classList.add('is-dragging');

    const origin = toGridPoint(startEvent.clientX, startEvent.clientY);
    const s = { x: start.x, y: start.y, w: start.w, h: start.h };

    const onMove = e => {
      const p  = toGridPoint(e.clientX, e.clientY);
      const dx = p.x - origin.x;
      const dy = p.y - origin.y;
      let next;
      if (mode === 'move') {
        next = { x: s.x + dx, y: s.y + dy, w: s.w, h: s.h };
      } else {
        const min = _MC2_SECTION_MIN[key] || { w: 3, h: 3 };
        let x = s.x, y = s.y, w = s.w, h = s.h;
        if (dir.includes('e')) w = Math.max(min.w, s.w + dx);
        if (dir.includes('s')) h = Math.max(min.h, s.h + dy);
        if (dir.includes('w')) { const cw = Math.max(min.w, s.w - dx); x = s.x + (s.w - cw); w = cw; }
        if (dir.includes('n')) { const ch = Math.max(min.h, s.h - dy); y = s.y + (s.h - ch); h = ch; }
        next = { x, y, w, h };
      }
      if (mode === 'resize') {
        const { rect, colW, colGap } = getGridMetrics();
        const colStep = colW + colGap;
        const nearRight = (rect.right - e.clientX) < Math.max(14, colStep * 0.6);
        if (dir.includes('e') && nearRight) next.w = _MC2_SECTION_GRID_COLS - next.x + 1;
      }
      const nextLayout = _mc2SetSectionRect(layout, key, next);
      _mc2SaveSectionLayout(nextLayout);
      _mc2ApplySectionLayout();
    };
    const onUp = () => {
      block?.classList.remove('is-dragging');
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup',   onUp);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup',   onUp);
  };

  grid.querySelectorAll('.mc2-inner-drag-handle').forEach(btn => {
    btn.onpointerdown = e => begin(btn.dataset.dragKey, 'move', e);
  });
  grid.querySelectorAll('.mc2-section-block > .ui-resizable-handle').forEach(btn => {
    btn.onpointerdown = e => begin(btn.dataset.resizeKey, 'resize', e, btn.dataset.resizeDir || 'se');
  });
}

// ══════════════════════════════════════════════════════
// PARTIALS PLANNER — CUSTOM EXIT STRATEGY SIMULATOR
// ══════════════════════════════════════════════════════

// Default plan shown on first load
function _getTradeReachR(trade) {
  const rrMax = trade?.rrMax;
  const realizedR = typeof trade?.r === 'number' && trade.r > 0 ? trade.r : 0;
  if (rrMax !== null && rrMax !== undefined && Number.isFinite(rrMax)) {
    return Math.max(rrMax, realizedR);
  }
  return realizedR;
}

// ── Simulated r for a trade at the active TP target ──
// Mirrors EXACTLY the rules used in computeOptimalRR so that the curve and the
// dashboard agree when a bubble is clicked.
//
// COUNTERFACTUAL SIMULATION — rMax dominates over realized r. The realized r
// reflects the *current* plan (TP 2.4R + BE management); under a different
// simulated TP, only price excursion (rrMax) matters. Checking r < 0 first
// would misclassify BE-SL trades with rrMax ≥ tp as losses when they should
// counterfactually be wins.
//
// BE-AWARE BRANCH (BE-TP / BE-SL): position was closed at BE before retrace.
// rrMax post-BE is cosmetic; the actual cap is beTriggerR (parsed from
// trade.beManagement). Aligns with _poSimTradeBeAware:
//   - tp ≤ beTriggerR              → tp (WIN — leg captured before BE retrace)
//   - tp > beTriggerR              → 0  (BE — closed at BE before reaching tp)
//   - beTriggerR null/unparseable  → 0  (BE fallback, consistent with PO)
// Returning 0 (not null) keeps these trades in the simulated dataset and
// pulls the dashboard ↔ ORR curve into numerical alignment with the PO.
//
// Classification mirrors the computeOptimalRR priority table:
//
//   0. outcome ∈ {BE-TP, BE-SL}   → BE-aware branch (see above)
//   1. rrMax ≥ tp                 → tp    (WIN — reached simulated TP)
//   2. r < 0  (and rrMax < tp)    → -1    (LOSS — real loser AND wouldn't hit tp)
//   3. rrMax < _SYSTEM_TP_R       → -1    (LOSS — didn't reach TP1)
//   4. _SYSTEM_TP_R ≤ rrMax < tp  → 0     (BE) in BE Fallback
//                                 → -1    (LOSS) in Strict Loss
//   5. otherwise (rrMax missing)  → null  (EXCLUDED)
function _getSimulatedR(trade) {
  const tp   = appState.ui.rrMinFilter !== null ? appState.ui.rrMinFilter : _SYSTEM_TP_R;

  // BE-aware branch — mirrors `computeOptimalRR` so the bubble-click drilldown
  // agrees with the chart classification. Three classification paths:
  //   • Flipping BE BE-TP (pure-tp-no-sl) : bucket WITHOUT rrMax<TP1 cutoff.
  //   • Flipping BE BE-SL with reach<2.4 : standard SL bucket WITH TP1 cutoff,
  //     skipping the r<0 priority so [TP1, tp) hits the bucket. No excursion
  //     data → defer to journaled r (real loser).
  //   • Other → _resolveBeR.
  if (trade?.outcome === 'BE-TP' || trade?.outcome === 'BE-SL') {
    const decision = _resolveBEDecision(trade);
    if (decision.fallbackVariant === 'pure-tp-no-sl' && trade.outcome === 'BE-TP') {
      const r = typeof trade.r === 'number' ? trade.r : NaN;
      const rrMaxRaw = trade.rrMax;
      const rMax = Number.isFinite(rrMaxRaw)
        ? rrMaxRaw
        : (Number.isFinite(r) && r > 0 ? r : null);
      if (rMax !== null && rMax >= tp) return tp;
      if (rMax !== null) return _orrSimMode === 'strict-loss' ? -1 : 0;
      return null;
    }
    if (decision.fallbackToNoBE && trade.outcome === 'BE-SL') {
      const r = typeof trade.r === 'number' ? trade.r : NaN;
      const rrMaxRaw = trade.rrMax;
      const rMax = Number.isFinite(rrMaxRaw)
        ? rrMaxRaw
        : (Number.isFinite(r) && r > 0 ? r : null);
      if (rMax !== null && rMax >= tp) return tp;
      if (rMax !== null && rMax < _SYSTEM_TP_R) return -1;
      if (rMax !== null) return _orrSimMode === 'strict-loss' ? -1 : 0;
      if (Number.isFinite(r) && r < 0) return -1;
      return null;
    }
    return _resolveBeR(trade, [{ lv: tp, pct: 1 }], _getTradeReachR(trade));
  }

  const r    = typeof trade?.r === 'number' ? trade.r : NaN;
  const rrMaxRaw = trade?.rrMax;
  const rMax = Number.isFinite(rrMaxRaw)
    ? rrMaxRaw
    : (Number.isFinite(r) && r > 0 ? r : null);

  // Priority order matters — rMax ≥ tp must be checked before r < 0 so BE-SL
  // trades with high rrMax aren't misclassified. See header comment.
  if (rMax !== null && rMax >= tp) return tp;
  if (Number.isFinite(r) && r < 0) return -1;
  if (rMax !== null && rMax < _SYSTEM_TP_R) return -1;
  if (rMax !== null) {
    // TP1 ≤ rMax < tp (BE-out range):
    //   BE Fallback → return null (removed from the dataset by the upstream
    //     filter at _getContextFiltered; still counted by the BE Trades KPI
    //     which reads from the pre-simulation dataset).
    //   Strict Loss → treated as a full loss (−1R) and stays in the dataset.
    return _orrSimMode === 'strict-loss' ? -1 : null;
  }
  return null;
}

// Returns a new array of trades with r recomputed through the simulator.
// Only kicks in when rrMinFilter is active — otherwise the raw r from the
// data source is preserved as-is. Trades that simulate to null have already
// been removed by _getContextFiltered when this runs.
//
// Stamps `_simulated: true` on every trade copy so computeEffectiveRR can
// short-circuit and return the simulated r directly instead of re-deriving
// under multi/personalised mode (which would read the trade's outcome and
// rrMax to apply its own plan, conflicting with the ORR pill semantic).
//
// Outcome is PRESERVED (Notion-pure invariant per CLAUDE.md). The previous
// rewrite (simR > 0 ? 'TP' : 'SL') broke convergence with the Partial
// Optimizer for two reasons: (a) when simR === 0 it labelled trades as 'SL'
// even though r === 0, producing incoherent state; (b) when simR > 0 it
// rewrote BE-SL → 'TP', destroying the BE-aware identity that PO and
// computeEffectiveRR rely on to dispatch the BE-aware capping branch.
function _applySimulation(trades) {
  if (appState.ui.rrMinFilter === null) return trades;
  return trades.map(t => {
    const simR = _getSimulatedR(t);
    if (simR === null) return t; // safety — should already be filtered out upstream
    // The shallow spread inherits _effectiveClassMode / effectiveR / effectiveClass
    // stamped by filterDataset on the pre-sim trade. Those reflect the JOURNALED r
    // and would cause _enrichTradeClassification to skip re-enrichment (hash match)
    // for the simulated copy, locking in the pre-sim sign — e.g. a BE-SL trade
    // (raw r=-1, cached class='loss') simulated to 0R would still show as a loss.
    // Clear those fields so downstream calcStats picks up the simulated r.
    const out = simR === t.r
      ? { ...t, _simulated: true }
      : { ...t, r: simR, _simulated: true };
    out._effectiveClassMode = undefined;
    out.effectiveR = undefined;
    out.effectiveClass = undefined;
    return out;
  });
}
function _ppSimTrade(rrMax, partials) {
  if (!partials.length) return 0;
  const tp1 = partials[0].lv;
  if (rrMax < tp1) return -1;

  let r = 0;
  for (const { pct, lv } of partials) {
    if (rrMax >= lv) r += pct * lv;
  }
  return r;
}
function _ppBuildReachDataset(trades) {
  const beChip = appState.filters.chips.beManagement;
  const reintegrated = new Set();
  if (!beChip || beChip.excluded.size === 0) {
    return { trades, reintegrated };
  }

  const bypassValues = new Set();
  for (const v of beChip.excluded) {
    if (_hasNumericRValue(v)) bypassValues.add(v);
  }
  if (bypassValues.size === 0) return { trades, reintegrated };

  const originalSet = new Set(trades);

  const savedExcluded = beChip.excluded;
  const savedMode     = beChip.mode;
  const reducedExcluded = new Set([...savedExcluded].filter(v => !bypassValues.has(v)));

  beChip.excluded = reducedExcluded;
  if (reducedExcluded.size === 0 && beChip.included.size === 0) {
    beChip.mode = 'neutral';
  }

  invalidateFilterCache();
  const result = _getContextFiltered(true);

  beChip.excluded = savedExcluded;
  beChip.mode     = savedMode;
  invalidateFilterCache();

  // Tag trades that the bypass brought back (i.e. weren't in the original
  // filtered set). The bounded-reach rule applies only to these.
  for (const t of result) {
    if (!originalSet.has(t)) reintegrated.add(t);
  }

  return { trades: result, reintegrated };
}
// SVG icons used in the button / option rows
const _ORR_BEMGMT_FILTER_ICON = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h12l-4.5 6v5l-3-1.5V9L2 3z"/></svg>';
const _ORR_BEMGMT_CHECK_ICON  = '<svg viewBox="0 0 16 16" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8.5l3.5 3.5L13 5"/></svg>';


// True when a BE Management chip value contains at least one number — used
// by the Partial Planner reach distribution to detect "this trade factually
// reached Nr before being moved to BE" labels (e.g. "BE si Set à 1R", "BE 2R",
// "BE 1.5R"). Trades excluded by such chips are reintegrated into the reach
// dataset so the percentages reflect actual rrMax behaviour.
function _hasNumericRValue(value) {
  if (typeof value !== 'string') return false;
  return /\d+(?:\.\d+)?/.test(value);
}


// Apply filterChips with the whole beManagement dimension neutralized. Used
// by the ORR / PP popups so a sidebar EXCLUDE on a BE Management value doesn't
// remove that value from the popup list (which would leave the user unable to
// untick it from the widget). Same spirit as the cross-dimensional chip count
// rule from Bloc 3 — a dim never filters its own displayed values.
function _filterChipsSkippingBeManagement(trades) {
  const entry = appState.filters.chips.beManagement;
  if (!entry) return filterChips(trades);
  const savedIncluded = entry.included;
  const savedExcluded = entry.excluded;
  const savedMode     = entry.mode;
  entry.included = new Set();
  entry.excluded = new Set();
  entry.mode     = 'neutral';
  const result = filterChips(trades);
  entry.included = savedIncluded;
  entry.excluded = savedExcluded;
  entry.mode     = savedMode;
  return result;
}



function _orrGetAllBeManagementValues() {
  // Reflects the currently filtered subset (presets + chips + temporal) EXCEPT
  // the beManagement dimension, which is skipped so a sidebar EXCLUDE on a
  // value doesn't hide it from the widget popup. The safeguard that adds
  // appState.ui.beManagementExclude still applies so widget-ticked values
  // also survive preset / dataset changes.
  let base = filterDataset(appState.trades.items);
  if (!appState.ui.showRawAll) {
    base = filterPreset(base);
    base = _filterChipsSkippingBeManagement(base);
  }
  base = filterTemporal(base);
  const set = new Set();
  for (const t of base) {
    const arr = t && t.beManagement;
    if (Array.isArray(arr)) {
      for (const v of arr) {
        if (typeof v === 'string' && v.length) set.add(v);
      }
    }
  }
  for (const v of (appState.ui.beManagementExclude || [])) {
    if (typeof v === 'string' && v.length) set.add(v);
  }
  return [...set].sort((a, b) => a.localeCompare(b));
}

// Per-beManagement-value trade counts, computed against the CURRENT filtered
// dataset BUT ignoring the beManagement chip dim (so the popup shows "how
// many trades would match this value if you unticked it"), beManagementExclude
// and rrMinFilter.
function _orrGetBeMgmtCounts() {
  let base = filterDataset(appState.trades.items);
  if (!appState.ui.showRawAll) {
    base = filterPreset(base);
    base = _filterChipsSkippingBeManagement(base);
  }
  base = filterTemporal(base);
  const counts = Object.create(null);
  for (const t of base) {
    const arr = t && t.beManagement;
    if (!Array.isArray(arr) || !arr.length) continue;
    const seen = new Set();
    for (const v of arr) {
      if (typeof v !== 'string' || !v.length || seen.has(v)) continue;
      seen.add(v);
      counts[v] = (counts[v] || 0) + 1;
    }
  }
  return counts;
}

let _orrBeMgmtPopOpen = false;
let _orrBeMgmtClickAwayBound = false;

function _orrRenderDatasetAWarning() {
  const slot = document.getElementById('orr-dataset-a-warning-slot');
  if (!slot) return;
  slot.innerHTML = '';
}

function _orrRenderSimModeControl() {
  const host = document.getElementById('orr-sim-mode-host');
  if (!host) return;
  const isBE = _orrSimMode === 'be-fallback';
  // The "?" info popup lives next to the widget title (static HTML in
  // index.html). Here we only render the BE Fallback / Strict Loss toggle.
  host.innerHTML = `
    <div class="orr-sim-mode-wrap">
      <button type="button" class="orr-sim-mode-btn" data-action="toggle-orr-sim-mode"
              title="Toggle simulation mode (BE Fallback / Strict Loss)">
        <span class="orr-sim-mode-dot ${isBE ? 'is-be' : 'is-strict'}"></span>
        <span class="orr-sim-mode-label">${isBE ? 'BE Fallback' : 'Strict Loss'}</span>
      </button>
    </div>
  `;
}

function _orrRenderBeMgmtControl() {
  const wrap = document.getElementById('orr-bemgmt-wrap');
  if (!wrap) return;
  // Union of both exclusion sources: the widget's own state AND the sidebar
  // BE Management chip exclusion. Keeps the pill count consistent with the
  // popup's checked-boxes count.
  const excludeUnion = new Set([
    ...(appState.ui.beManagementExclude || []),
    ...(appState.filters.chips.beManagement?.excluded || []),
  ]);
  const n = excludeUnion.size;
  const label = n > 0 ? 'BE Management' : 'BE Management';
  const title = n > 0
    ? `BE Management · ${n} value${n > 1 ? 's' : ''} excluded — click to edit`
    : 'Exclude BE Management values from the dashboard';
  wrap.innerHTML = `
    <button type="button"
            class="orr-bemgmt-btn ${n > 0 ? 'active' : ''}"
            id="orr-bemgmt-btn"
            title="${title}"
            onclick="_orrToggleBeMgmtPop(event)">
      <span class="orr-bemgmt-btn-icon">${_ORR_BEMGMT_FILTER_ICON}</span>
      <span>${label}</span>
      ${n > 0 ? `<span class="orr-bemgmt-btn-count">${n}</span>` : ''}
      <span class="orr-bemgmt-btn-caret">▾</span>
    </button>`;
}

function _orrToggleBeMgmtPop(ev) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  // Determine the anchor button (ORR or PP widget). Both buttons share the
  // .orr-bemgmt-btn class and open the same singleton popup; the popup re-
  // anchors when the user clicks the other widget's button while open.
  const anchor = (ev && ev.currentTarget && ev.currentTarget.closest('.orr-bemgmt-btn'))
              || document.getElementById('orr-bemgmt-btn');
  if (!anchor) return;
  const pop = document.getElementById('orr-bemgmt-pop');
  if (_orrBeMgmtPopOpen && pop && pop.dataset.anchorBtnId === anchor.id) {
    _orrCloseBeMgmtPop();
    return;
  }
  _orrOpenBeMgmtPop(anchor);
}

function _orrRenderBeMgmtPopBody(pop) {
  const values = _orrGetAllBeManagementValues();
  // Union of both exclusion sources — widget state + sidebar chip exclusion —
  // so a value excluded in either place renders as checked. Untick routes
  // through _orrToggleBeMgmtValue which clears both sources.
  const exclude = new Set([
    ...(appState.ui.beManagementExclude || []),
    ...(appState.filters.chips.beManagement?.excluded || []),
  ]);
  const counts = _orrGetBeMgmtCounts();
  const hasSelection = exclude.size > 0;

  const optsHtml = values.length
    ? `<div class="orr-bemgmt-pop-list">` + values.map(v => {
        const checked = exclude.has(v);
        const n = counts[v] || 0;
        const safeVal = v.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        return `
          <div class="orr-bemgmt-opt ${checked ? 'checked' : ''}"
               data-value="${safeVal}"
               role="checkbox"
               tabindex="0"
               aria-checked="${checked}"
               onclick="_orrToggleBeMgmtValueFromEl(this)">
            <span class="orr-bemgmt-opt-check">${_ORR_BEMGMT_CHECK_ICON}</span>
            <span class="orr-bemgmt-opt-label">${v}</span>
            <span class="orr-bemgmt-opt-n">${n}</span>
          </div>`;
      }).join('') + `</div>`
    : `<div class="orr-bemgmt-empty">No BE Management values in dataset</div>`;

  pop.innerHTML = `
    <div class="orr-bemgmt-pop-head">
      <span class="orr-bemgmt-pop-title">Exclude <strong>${exclude.size}</strong>/${values.length}</span>
      <button class="orr-bemgmt-pop-clear"
              ${hasSelection ? '' : 'disabled'}
              onclick="_orrClearBeMgmt()">Clear all</button>
    </div>
    ${optsHtml}`;
}

function _orrOpenBeMgmtPop(anchorBtn) {
  _orrCloseBeMgmtPop();
  const btn = anchorBtn || document.getElementById('orr-bemgmt-btn');
  if (!btn) return;

  const pop = document.createElement('div');
  pop.className = 'orr-bemgmt-pop';
  pop.id = 'orr-bemgmt-pop';
  pop.dataset.anchorBtnId = btn.id;
  pop.onclick = (e) => e.stopPropagation();
  _orrRenderBeMgmtPopBody(pop);

  document.body.appendChild(pop);
  _orrPositionBeMgmtPop(btn, pop);
  _orrBeMgmtPopOpen = true;

  if (!_orrBeMgmtClickAwayBound) {
    _orrBeMgmtClickAwayBound = true;
    setTimeout(() => {
      document.addEventListener('click', _orrBeMgmtClickAway);
      window.addEventListener('scroll', _orrBeMgmtViewportChange, true);
      window.addEventListener('resize', _orrBeMgmtViewportChange);
    }, 0);
  }
}

function _orrPositionBeMgmtPop(btn, pop) {
  const r = btn.getBoundingClientRect();
  pop.style.position = 'fixed';
  pop.style.visibility = 'hidden';
  pop.style.left = '0px';
  pop.style.top  = '0px';
  const pw = pop.offsetWidth;
  const ph = pop.offsetHeight;
  const gap = 6;
  let top  = r.bottom + gap;
  if (top + ph > window.innerHeight - 8) {
    const above = r.top - ph - gap;
    if (above >= 8) top = above;
    else top = Math.max(8, window.innerHeight - ph - 8);
  }
  let left = r.right - pw;
  if (left < 8) left = 8;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  pop.style.top  = top  + 'px';
  pop.style.left = left + 'px';
  pop.style.visibility = '';
}

function _orrBeMgmtViewportChange() {
  if (!_orrBeMgmtPopOpen) return;
  const pop = document.getElementById('orr-bemgmt-pop');
  if (!pop) return;
  const btn = document.getElementById(pop.dataset.anchorBtnId || 'orr-bemgmt-btn');
  if (!btn) return;
  _orrPositionBeMgmtPop(btn, pop);
}

function _orrBeMgmtClickAway(e) {
  if (!_orrBeMgmtPopOpen) return;
  if (e.target.closest('#orr-bemgmt-pop')) return;
  // Ignore ANY bemgmt button (both ORR and PP share the .orr-bemgmt-btn class)
  if (e.target.closest('.orr-bemgmt-btn')) return;
  _orrCloseBeMgmtPop();
}

function _orrCloseBeMgmtPop() {
  const pop = document.getElementById('orr-bemgmt-pop');
  if (pop) pop.remove();
  _orrBeMgmtPopOpen = false;
  if (_orrBeMgmtClickAwayBound) {
    document.removeEventListener('click', _orrBeMgmtClickAway);
    window.removeEventListener('scroll', _orrBeMgmtViewportChange, true);
    window.removeEventListener('resize', _orrBeMgmtViewportChange);
    _orrBeMgmtClickAwayBound = false;
  }
}

function _orrToggleBeMgmtValue(value, checked) {
  const list = appState.ui.beManagementExclude || [];
  const set = new Set(list);
  if (checked) set.add(value);
  else         set.delete(value);
  appState.ui.beManagementExclude = [...set];
  // Sync with left-panel beManagement chip filter
  const chipEntry = appState.filters.chips.beManagement;
  if (chipEntry) {
    if (checked) {
      chipEntry.excluded.add(value);
      if (chipEntry.mode !== 'exclude') chipEntry.mode = 'exclude';
      _syncChipModeButtons('beManagement');
    } else {
      chipEntry.excluded.delete(value);
      if (!chipEntry.excluded.size && !chipEntry.included.size) {
        chipEntry.mode = 'neutral';
        _syncChipModeButtons('beManagement');
      }
    }
  }
  invalidateFilterCache();
  // Phase 3 : ORR BE Mgmt popup mute beManagement chip live → sync slot actif.
  _syncLiveSlotFromActiveChips();
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
  _orrRenderBeMgmtControl();
  render();
  // Re-render popup body IN PLACE so counts and header update without flashing
  const pop = document.getElementById('orr-bemgmt-pop');
  if (pop) {
    _orrRenderBeMgmtPopBody(pop);
    const btn = document.getElementById(pop.dataset.anchorBtnId || 'orr-bemgmt-btn');
    if (btn) _orrPositionBeMgmtPop(btn, pop);
  }
}

function _orrToggleBeMgmtValueFromEl(el) {
  if (!el) return;
  const value = el.getAttribute('data-value') || '';
  // Decode the HTML-escaped entities we wrote in the attribute
  const decoded = value.replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  const nowChecked = !el.classList.contains('checked');
  _orrToggleBeMgmtValue(decoded, nowChecked);
}

function _orrClearBeMgmt() {
  if (!(appState.ui.beManagementExclude || []).length) return;
  appState.ui.beManagementExclude = [];
  // Sync with left-panel beManagement chip filter
  const chipEntry = appState.filters.chips.beManagement;
  if (chipEntry) {
    chipEntry.excluded.clear();
    chipEntry.mode = 'neutral';
    _syncChipModeButtons('beManagement');
  }
  invalidateFilterCache();
  _orrRenderBeMgmtControl();
  render();
  const pop = document.getElementById('orr-bemgmt-pop');
  if (pop) {
    _orrRenderBeMgmtPopBody(pop);
    const btn = document.getElementById(pop.dataset.anchorBtnId || 'orr-bemgmt-btn');
    if (btn) _orrPositionBeMgmtPop(btn, pop);
  }
}

// Expose for inline handlers in the popup HTML
window._orrToggleBeMgmtPop         = _orrToggleBeMgmtPop;
window._orrToggleBeMgmtValue       = _orrToggleBeMgmtValue;
window._orrToggleBeMgmtValueFromEl = _orrToggleBeMgmtValueFromEl;
window._orrClearBeMgmt             = _orrClearBeMgmt;
// ── RR Min Filter (bubble click → apply directly, no modal) ──

function _rrFilterBubbleClick(lv, _label) {
  const wasActive = appState.ui.rrMinFilter === lv;
  const activating = !wasActive;
  appState.ui.rrMinFilter = wasActive ? null : lv;
  invalidateFilterCache();
  // Persist into the active preset's live slot so the bubble restores on
  // reload AND travels with the preset (switching presets picks up the
  // preset's saved bubble; switching back restores this one).
  const liveSlot = getPresetLiveSlot(appState.presets.activeId);
  liveSlot.rrMinFilter = appState.ui.rrMinFilter;
  savePresetLiveFilters();

  // PP preset deactivation removed (Partial Planner widget retired).
  render();
  _rrSyncActiveFilterBadge();
  // Refresh Compare Presets if open — it shows "⚓ Fixed @ XR" using rrMinFilter.
  try {
    if (_presetCmpOpen && typeof runPresetCompare === 'function') runPresetCompare();
  } catch (e) {
    console.warn('[rrBubble] preset compare refresh failed:', e.message);
  }
}

function _rrClearFilter() {
  appState.ui.rrMinFilter = null;
  invalidateFilterCache();
  const liveSlot = getPresetLiveSlot(appState.presets.activeId);
  liveSlot.rrMinFilter = null;
  savePresetLiveFilters();
  render();
  _rrSyncActiveFilterBadge();
  // Refresh Compare Presets if open — it shows "⚓ Fixed @ XR" using rrMinFilter.
  try {
    if (_presetCmpOpen && typeof runPresetCompare === 'function') runPresetCompare();
  } catch (e) {
    console.warn('[rrClear] preset compare refresh failed:', e.message);
  }
}

function _rrSyncActiveFilterBadge() {
  // --- Topbar Clear-RR button (static in index.html, toggled via display) ---
  const topBtn = document.getElementById('rr-clear-topbar-btn');
  if (topBtn) {
    if (appState.ui.rrMinFilter !== null) {
      topBtn.style.display = '';
      // In Fixed mode, the anchor replaces the ✕ entirely (the click still
      // clears — the icon just signals the active TPM identity since there's
      // no topbar TPM badge in Fixed). Other modes keep ✕ as the clear cue.
      const isFixed = appState.ui.tpConfig?.mode === 'fixed';
      const lead = isFixed ? '⚓' : '✕';
      topBtn.textContent = `${lead} RR ≥ ${appState.ui.rrMinFilter}R`;
    } else {
      topBtn.style.display = 'none';
      topBtn.textContent = '';
    }
  }

  // --- RR filter badge (lives inside #fcs-consolidated, re-injected after each render) ---
  let topBadge = document.getElementById('rr-filter-topbadge');
  if (appState.ui.rrMinFilter !== null) {
    if (!topBadge) {
      topBadge = document.createElement('div');
      topBadge.id = 'rr-filter-topbadge';
      topBadge.className = 'af-pill af-pill-accent rr-filter-topbadge';
      topBadge.tabIndex = 0;
      topBadge.onclick = _rrClearFilter;
    }
    topBadge.innerHTML = `<span class="af-pill-label">RR ≥</span> ${appState.ui.rrMinFilter}R`;
    const container = document.getElementById('fcs-consolidated');
    if (container && topBadge.parentNode !== container) container.appendChild(topBadge);
  } else {
    topBadge?.remove();
  }

  // --- Badge inside Optimal RR widget ---
  let widgetBadge = document.getElementById('rr-filter-widget-badge');
  const widgetHeader = null; // partials-planner-widget retired — no in-widget badge slot.
  if (appState.ui.rrMinFilter !== null) {
    if (!widgetBadge && widgetHeader) {
      widgetBadge = document.createElement('span');
      widgetBadge.id = 'rr-filter-widget-badge';
      widgetBadge.className = 'rr-widget-badge';
      widgetBadge.onclick = _rrClearFilter;
      widgetHeader.appendChild(widgetBadge);
    }
    if (widgetBadge) widgetBadge.innerHTML = `RR ≥ ${appState.ui.rrMinFilter}R ×`;
  } else {
    widgetBadge?.remove();
  }
}


// Syncs the header TPM preset badge visibility + content based on the current
// tpConfig. Called after every tpConfig mutation (via _saveTpConfig hook) and
// on initial load. No-ops cleanly when no preset matches.
function _ppSyncActivePresetBadge() {
  const btn = document.getElementById('tpm-active-preset-topbar-btn');
  if (!btn) return;

  const cfg = appState.ui.tpConfig;
  if (!cfg || !cfg.mode) {
    btn.style.display = 'none';
    btn.textContent = '';
    return;
  }

  // Reset variant classes; one of them is reapplied below per active mode.
  btn.classList.remove(
    'tpm-badge-fixed',
    'tpm-badge-multi',
    'tpm-badge-custom',
    'tpm-badge-pp'
  );

  let icon = '';
  let label = '';
  let tooltip = '';
  let variantClass = '';
  let inert = false;

  if (cfg.mode === 'fixed') {
    // Fixed mode does not show a topbar badge — its anchor icon migrates to
    // the ORR active-filter badge when a bubble is active (see
    // _rrSyncActiveFilterBadge). The topbar TPM badge stays hidden here.
    btn.style.display = 'none';
    btn.textContent = '';
    btn.classList.remove('tpm-badge-inert');
    return;
  } else if (cfg.mode === 'multi' && cfg.multi) {
    const m = cfg.multi;
    const n = m.tpCount === 3 ? 3 : 2;
    const parts = [];
    parts.push(Math.round(m.partials.tp1 || 0));
    parts.push(Math.round(m.partials.tp2 || 0));
    if (n === 3) parts.push(Math.round(m.partials.tp3 || 0));
    icon = '🪜';
    label = `Multi ${parts.join('/')}`;
    tooltip = 'Click to deactivate Multi TP and reset to Fixed';
    variantClass = 'tpm-badge-multi';
  } else if (cfg.mode === 'personalised' && cfg.personalised) {
    // Personalised — show targets + partials.
    const ps = cfg.personalised;
    const n = ps.tpCount === 3 ? 3 : 2;
    const targets = [];
    const partials = [];
    // Trim trailing zeros for cleaner display: 2 not 2.00, 2.4 not 2.40
    const fmtR = v => {
      const s = (typeof v === 'number' && Number.isFinite(v)) ? v.toFixed(2) : '0';
      return s.replace(/\.?0+$/, '') + 'R';
    };
    targets.push(fmtR(ps.targets.tp1));
    targets.push(fmtR(ps.targets.tp2));
    partials.push(Math.round(ps.partials.tp1 || 0));
    partials.push(Math.round(ps.partials.tp2 || 0));
    if (n === 3) {
      targets.push(fmtR(ps.targets.tp3));
      partials.push(Math.round(ps.partials.tp3 || 0));
    }
    icon = '⚡';
    label = `Custom ${targets.join('/')} · ${partials.join('/')}`;
    tooltip = 'Click to deactivate Custom TP and reset to Fixed';
    variantClass = 'tpm-badge-custom';
  } else {
    // Unknown mode — defensive hide
    btn.style.display = 'none';
    btn.textContent = '';
    return;
  }

  btn.textContent = `${icon} ${label}`;
  btn.title = tooltip;
  btn.style.display = '';
  if (variantClass) btn.classList.add(variantClass);

  // Inert in Fixed: visual hint via class (cursor + no hover effect). The
  // static onclick="_tpmDeactivateActivePreset()" stays in HTML;
  // _tpmDeactivateActivePreset already short-circuits when mode is 'fixed'.
  btn.classList.toggle('tpm-badge-inert', inert);
}

// Header badge click handler — wipes the preset match by switching to Fixed.
// Exposed on window so the static onclick in index.html can reach it.
function _tpmDeactivateActivePreset() {
  if (!appState.ui.tpConfig) return;
  // No-op if already in Fixed mode — protects the Fixed badge from re-firing
  // a redundant render when clicked (its CSS makes it look inert anyway).
  if (appState.ui.tpConfig.mode === 'fixed') return;
  // Reset to Fixed mode (the safe default). Sub-configs are preserved so the
  // user can switch back to Personalised / Multi without losing their work.
  _setTpMode('fixed');
  // _saveTpConfig fires inside _setTpMode which triggers _ppSyncActivePresetBadge
  // via the hook added in _saveTpConfig.
}
window._tpmDeactivateActivePreset = _tpmDeactivateActivePreset;

