// ══════════════════════════════════════════════════════════════════
// PARTIAL OPTIMIZER — BE-aware simulation helpers (dependencies of
// _poSimulateModel; placed here so they're declared before the main PO block)
// ══════════════════════════════════════════════════════════════════

// Parse the max R-trigger out of a trade.beManagement chip array.
// Returns the highest R value found across all chips (e.g. for
// ["BE si set à 1RR", "BE si set à 2RR"], returns 2). Used by
// _poSimTradeBeAware to cap BE-TP payouts. If no chip parses, returns null.
//
// IMPORTANT: takes the MAX, not the first match. Multi-chip trades happen
// when the user evolved their BE management mid-position; the highest
// trigger represents the actual cap that was set on the position. Taking
// the first or min would understate realized payouts on every BE-aware
// simulation (e.g. ["1RR","2RR"] would yield 1 instead of 2).
function _parseBeTriggerR(beManagementArr) {
  if (!Array.isArray(beManagementArr)) return null;
  let max = null;
  for (const s of beManagementArr) {
    if (typeof s !== 'string') continue;
    const m = s.match(/(\d+(?:\.\d+)?)\s*R/i);
    if (m) {
      const n = parseFloat(m[1]);
      if (Number.isFinite(n) && (max === null || n > max)) max = n;
    }
  }
  return max;
}

// Hardcoded "Flipping" BE trigger applied when appState.ui.beMode is
// 'flipping-be'. Per the project's reference convention, BE is always armed
// at 2.4R irrespective of the journaled chip — but ONLY for trades whose
// price excursion actually reached 2.4R (rrMax ≥ 2.4). Trades with
// rrMax < 2.4 are treated as if they never had BE management (BE-unaware
// fallback for that trade).
const _FLIPPING_BE_R = 2.4;

// ── BE Management decision resolver ────────────────────────────────────────
// Single source of truth for every consumer (PO `_poSimTradeBeAware`,
// `computeEffectiveRR` fixed/multi/personalised, `_getSimulatedR`,
// `computeOptimalRR` BE branch). Returns a decision object describing what
// the BE-TP / BE-SL trade should produce under the active mode:
//
//   { applyBEAware: true,  triggerR: <number>, fallbackToNoBE: false }
//     → BE armed and held: legs at lv ≤ triggerR captured, legs above → 0R.
//       In Fixed mode (no plan): always 0R (BE-TP and BE-SL symmetric).
//       Doctrine: BE mechanism ran its course, no no-cut counterfactual.
//
//   { applyBEAware: false, triggerR: null,    fallbackToNoBE: true }
//     → BE-unaware fallback (per fallbackVariant): BE-TP runs plan as TP,
//       BE-SL runs plan as SL pur. Only set by flipping-be branches.
//
//   { applyBEAware: false, triggerR: null,    fallbackToNoBE: false }
//     → 0R (be-fallback null chip — BE neutre, current behavior).
//
// Modes (the no-be mode was removed in PR feat/kill-no-be-mode, 2026-04 —
// users on stale 'no-be' localStorage values are migrated to 'be-fallback'
// silently at boot):
//   'be-fallback' : trigger = _parseBeTriggerR(chip). Null chip → 0R bucket.
//   'flipping-be' : if rrMax (or _getTradeReachR fallback) ≥ 2.4 → BE-aware
//                   with trigger=2.4. Else → BE-unaware fallback for this
//                   trade (the counterfactual BE never armed). Trades with
//                   no usable reach proxy fall through to the fallback too.
//
// Caller MUST have established outcome ∈ {BE-TP, BE-SL} before invoking.
function _activeBeMode() {
  return (typeof appState !== 'undefined' && appState.ui && appState.ui.beMode) || 'be-fallback';
}

function _resolveBEDecision(trade) {
  const mode = _activeBeMode();
  if (mode === 'flipping-be') {
    // BE-TP under Flipping BE: treated EXACTLY as a TP normal except for one
    // detail — when no leg gets credited (rrMax < lowest leg), the trade is
    // floored at 0R (BE-out / KPI BE Trades), NOT -1R. Rationale: a BE-TP
    // reached its journaled TP target by definition, so it can never be a
    // real loser in the counterfactual; the worst case is "didn't reach the
    // simulated TP" which is the BE-out semantic. ORR widget mirrors the
    // standard TP-pure bucket logic but skips the TP1 cutoff for the same
    // reason.
    if (trade.outcome === 'BE-TP') {
      return { applyBEAware: false, triggerR: null, fallbackToNoBE: true, fallbackVariant: 'pure-tp-no-sl' };
    }
    // BE-SL: BE-aware only if the price actually reached the 2.4R trigger
    // counterfactually. Below the trigger → BE never armed → BE-unaware
    // fallback (BE-SL re-simulated as SL pur via _ppSimTrade).
    const reach = _getTradeReachR(trade);
    if (Number.isFinite(reach) && reach >= _FLIPPING_BE_R) {
      return { applyBEAware: true, triggerR: _FLIPPING_BE_R, fallbackToNoBE: false };
    }
    return { applyBEAware: false, triggerR: null, fallbackToNoBE: true, fallbackVariant: 'pure-tp-with-sl' };
  }
  // be-fallback
  const trigger = _parseBeTriggerR(trade.beManagement);
  if (trigger === null) {
    return { applyBEAware: false, triggerR: null, fallbackToNoBE: false };
  }
  return { applyBEAware: true, triggerR: trigger, fallbackToNoBE: false };
}

// Multi-leg plan path. Used by PO + Personalised + ORR (single-leg).
function _resolveBeR(trade, partials, reachR) {
  const mode = _activeBeMode();

  // flipping-be with a plan: trigger BE counterfactuel = first plan leg,
  // NOT the hardcoded _FLIPPING_BE_R = 2.4R. Rationale: the BE under the
  // simulated plan is moved when the first partial is taken, so the cap
  // for the BE-TP/BE-SL counterfactual must align with that leg.
  // _resolveBEDecision is bypassed here because it doesn't know about the
  // plan (signature: trade only). For Fixed mode (no plan), the original
  // _FLIPPING_BE_R logic remains in _resolveBeRFixed, which doesn't call
  // this function.
  if (mode === 'flipping-be' && partials && partials.length > 0) {
    const triggerR = partials[0].lv;
    const reach = Number.isFinite(reachR) ? reachR : null;
    const beArmed = reach !== null && reach >= triggerR;

    if (trade.outcome === 'BE-TP') {
      // BE-TP can never be a real loser in the counterfactual (reached its
      // journaled TP target by definition). Above the trigger: nothing
      // captured because the BE held; below: 0R floor (BE-out / KPI BE
      // Trades). When beArmed, only legs at lv ≤ trigger are captured
      // (i.e. the first leg only, since trigger == partials[0].lv).
      if (!beArmed) return 0;
      let r = 0;
      for (const { pct, lv } of partials) {
        if (lv <= triggerR) r += pct * lv;
      }
      return r;
    }
    // BE-SL
    if (beArmed) {
      // BE armed counterfactually: legs at lv ≤ trigger captured, legs
      // above are 0R (closed at BE before reaching them).
      let r = 0;
      for (const { pct, lv } of partials) {
        if (lv <= triggerR) r += pct * lv;
      }
      return r;
    }
    // BE never armed: SL pur via _ppSimTrade. reach < first leg → -1R
    // by _ppSimTrade contract.
    return _ppSimTrade(reachR, partials);
  }

  // be-fallback (or flipping-be with no plan — defensive) routes through
  // the original decision logic via _resolveBEDecision.
  const d = _resolveBEDecision(trade);
  if (d.applyBEAware) {
    // be-fallback: legs at lv ≤ triggerR (from chip) are captured before
    // BE retrace; legs above triggerR are credited 0R. Symmetric for BE-TP
    // and BE-SL.
    let r = 0;
    for (const { pct, lv } of partials) {
      if (lv <= d.triggerR) r += pct * lv;
    }
    return r;
  }
  if (d.fallbackToNoBE) {
    // Defensive — only reachable if a flipping-be path hits this without
    // a plan (no current call-site does), kept for symmetry with the
    // pre-fix code paths.
    if (d.fallbackVariant === 'pure-tp-no-sl' && trade.outcome === 'BE-TP') {
      let r = 0;
      for (const { pct, lv } of partials) {
        if (reachR >= lv) r += pct * lv;
      }
      return r;
    }
    return _ppSimTrade(reachR, partials);
  }
  return 0; // be-fallback null chip → 0R BE neutre
}

// Multi mode path. Reads realized tpN_rr × partials.
function _resolveBeRMulti(trade, mCfg) {
  const d = _resolveBEDecision(trade);
  if (d.applyBEAware) {
    // be-fallback / flipping-be (reach≥2.4): tp_N_rr tiers below triggerR
    // are captured before BE retrace; tiers above are 0R (closed at BE).
    // Symmetric for BE-TP and BE-SL.
    const p = mCfg.partials, n = mCfg.tpCount;
    let rr = 0;
    if (trade.tp1_rr != null && trade.tp1_rr <= d.triggerR)            rr += (p.tp1 / 100) * trade.tp1_rr;
    if (trade.tp2_rr != null && trade.tp2_rr <= d.triggerR)            rr += (p.tp2 / 100) * trade.tp2_rr;
    if (n === 3 && trade.tp3_rr != null && trade.tp3_rr <= d.triggerR) rr += (p.tp3 / 100) * trade.tp3_rr;
    return rr;
  }
  if (d.fallbackToNoBE) {
    // BE-SL under flipping-be (reach<2.4): match the SL pur convention in
    // Multi mode, which is `return trade.r` (passthrough). For chez Max
    // BE-SL = -1R; for community users with different conventions the
    // passthrough preserves the journaled value.
    if (trade.outcome === 'BE-SL') return trade.r;
    // BE-TP fallback: weighted sum of every realized tpN_rr, no cap.
    const p = mCfg.partials, n = mCfg.tpCount;
    let rr = 0, anyHit = false;
    if (trade.tp1_rr != null)              { rr += (p.tp1 / 100) * trade.tp1_rr; anyHit = true; }
    if (trade.tp2_rr != null)              { rr += (p.tp2 / 100) * trade.tp2_rr; anyHit = true; }
    if (n === 3 && trade.tp3_rr != null)   { rr += (p.tp3 / 100) * trade.tp3_rr; anyHit = true; }
    return anyHit ? rr : 0;
  }
  return 0;
}

// Fixed mode path. No plan — uses the BE decision to pick the policy:
//   - be-fallback applyBEAware (chip parsable):
//       BE-TP and BE-SL both → 0R (BE armed and held, position closed at BE).
//   - flipping-be applyBEAware (reach ≥ 2.4):
//       BE-TP and BE-SL both → 0R (same mechanics, BE armed at 2.4R).
//   - flipping-be fallbackToNoBE (BE never armed counterfactually):
//       BE-TP → trade.r (journaled TP); BE-SL → rrMax≥2.4 ? +2.4R : -1.
//   - be-fallback null chip:
//       passthrough trade.r (matches pre-feature behavior).
function _resolveBeRFixed(trade) {
  const d = _resolveBEDecision(trade);
  if (d.applyBEAware) {
    // be-fallback doctrine: BE armed and held — position closed at 0R by the
    // moved SL. Symmetric for BE-TP and BE-SL: the BE mechanism ran its
    // course, payout = 0R. (No no-cut counterfactual in be-fallback; for
    // counterfactual semantics, switch to flipping-be mode.)
    return 0;
  }
  if (d.fallbackToNoBE) {
    // flipping-be branch only. Reached only when BE never armed
    // counterfactually (reach < 2.4R) for BE-SL, or always for BE-TP
    // (variant 'pure-tp-no-sl').
    if (trade.outcome === 'BE-SL') {
      // Fixed mode has no plan — binary counterfactual: rrMax ≥ 2.4 → +2.4R,
      // else -1R. NOTE: this branch is only entered when reach < 2.4R, so
      // the rrMax ≥ _SYSTEM_TP_R sub-condition is effectively unreachable
      // (dead branch preserved for defensive symmetry; safe to retire if
      // _resolveBEDecision invariant is hardened).
      const rrMax = trade.rrMax;
      return (Number.isFinite(rrMax) && rrMax >= _SYSTEM_TP_R) ? _SYSTEM_TP_R : -1;
    }
    return trade.r; // BE-TP under flipping-be: journaled TP value
  }
  // be-fallback null chip → passthrough (matches pre-feature behavior).
  return trade.r;
}

// Outcome-aware single-trade simulator for the Partial Optimizer. Mirrors
// computeEffectiveRR personalised mode to keep Optimizer ↔ Dashboard
// numerically aligned on BE-TP / BE-SL.
//
//   - BE-TP : cap at beTriggerR (max R parsed from trade.beManagement via
//             _parseBeTriggerR). Legs above the trigger are credited 0R
//             (position closed at BE before the price retraced to them).
//             Returns 0R when no chip is parsable — matches dashboard.
//   - BE-SL : same closure mechanics as BE-TP. Cap at beTriggerR, 0R on
//             unparseable chip. Post-exit SL hit is irrelevant to the
//             plan payout since the position was already out.
//   - TP/SL : delegate to _ppSimTrade(rrMax, partials).
//
// No warning is emitted for unparseable chips here: computeEffectiveRR
// emits one per trade during dashboard render (rate-limited by
// discriminator), so a single console signal covers both surfaces.
function _poSimTradeBeAware(trade, rrMax, partials) {
  if (!partials || !partials.length) return _ppSimTrade(rrMax, partials);

  if (trade && (trade.outcome === 'BE-TP' || trade.outcome === 'BE-SL')) {
    // Routes through the global BE Management mode (be-fallback or
    // flipping-be). `rrMax` here is already the reach proxy chosen by the
    // caller (`_getTradeReachR` on the context-filtered dataset).
    return _resolveBeR(trade, partials, rrMax);
  }

  return _ppSimTrade(rrMax, partials);
}

// ══════════════════════════════════════════════════════════════════
// PARTIAL OPTIMIZER — brute-force exit strategy comparator
// ══════════════════════════════════════════════════════════════════
// Generates ~150-300 candidate exit plans (1 or 2 partials before TP final),
// simulates each on the active trade dataset, ranks by chosen metric, and
// presents results in a scatter (EV vs Stability) + ranking table + detail
// view. Reuses _ppSimTrade for path-equivalent leg simulation. Standalone
// state in window._poState — derives its trade dataset on demand via
// _poGetTradesAndRRMax (no shared mutable globals).

// Defensive registration of the chartjs-plugin-zoom UMD bundle. The plugin
// usually self-registers when loaded, but some bundles expose it under
// window.ChartZoom and need explicit Chart.register.
if (typeof Chart !== 'undefined' && typeof window.ChartZoom !== 'undefined') {
  try { Chart.register(window.ChartZoom); } catch (e) { /* already registered */ }
}

window._poState = window._poState || {
  built: false,
  models: [],
  results: [],
  baselineIdx: 0,
  selectedIdx: 0,
  lastTradesHash: '',
  config: {
    tpFinal: 2.4,
    partialMode: 'both',     // 'one' | 'two' | 'both'
    rankMode: 'totalR',      // totalR | ev | stability | compromise | dd | pf | wr
    rankDir:  'desc',        // 'asc' | 'desc' — direction du tri du Classement
    topN: 50,
    colorMode: 'type',       // 'type' | 'sig' | 'tpfinal'
    sweepMode: false,        // when true, generate models for all PO_RR_DIST_THRESHOLDS
    hideNonTop: false,       // when true, hide bubbles outside the active Top N
    yAxisMode: 'calmar',     // 'calmar' | 'stability' | 'reliability' | 'robust'
    hideCatastrophic: true,  // when true, hide models with ev < -0.3R (excluding the active baseline)
    // SL is fixed at -1R per R-multiples convention. Bootstrap always-on with
    // 500 iters (100 in sweep mode for performance). Both moved to constants
    // below — no longer surfaced in the Setup UI (v11).
  },
  hiddenTpFinals: new Set(), // TP final values hidden via legend click (sweep+tpfinal mode)
  equityBaselineBeFilter: false, // v12: apply BE Management filter to the equity baseline line
  hiddenPresetCurves: new Set(), // PR-D: 'P1' | 'P2' | 'P3' if hidden via legend click — persists across re-renders
  scatterChart: null,
  equityChart: null,
};

// Non-configurable simulator constants (v11). The dashboard reasons in
// R-multiples — SL is always 1R by convention. Bootstrap is always on with
// 500 iters (capped at 100 in sweep mode to keep ~880-model batches under 2s).
const PO_SL_DEFAULT = 1;
const PO_BOOTSTRAP_ITERS = 500;
const PO_BOOTSTRAP_ITERS_SWEEP = 100;

// Fixed cumulative thresholds for the RR Distribution block (mirrors the
// Partials Planner gchip pattern). Color follows the PP per-threshold gradient:
// low = green, mid = blue, high = gold / red.
const PO_RR_DIST_THRESHOLDS = [
  { lv: 1.0,  label: '≥ 1R',   col: 'var(--g)' },
  { lv: 2.0,  label: '≥ 2R',   col: 'var(--g)' },
  { lv: 2.4,  label: '≥ 2.4R', col: 'var(--b)' },
  { lv: 3.0,  label: '≥ 3R',   col: 'var(--b)' },
  { lv: 3.3,  label: '≥ 3.3R', col: 'var(--b)' },
  { lv: 5.0,  label: '≥ 5R',   col: 'var(--b)' },
  { lv: 7.0,  label: '≥ 7R',   col: 'var(--a)' },
  { lv: 10.0, label: '≥ 10R',  col: 'var(--r)' },
  { lv: 15.0, label: '≥ 15R',  col: 'var(--r)' },
  { lv: 20.0, label: '≥ 20R',  col: 'var(--r)' },
];

const _PO_TP1_GRID_1P = [1.0, 1.25, 1.5, 2.0, 2.5];
const _PO_SPLITS_1P = [
  [0.25, 0.75], [0.33, 0.67], [0.50, 0.50], [0.67, 0.33], [0.75, 0.25],
];
const _PO_TP1_GRID_2P = [1.0, 1.25, 1.5, 2.0];
const _PO_TP2_GRID_2P = [1.5, 2.0, 2.5, 3.0, 3.5, 4.0];
const _PO_SPLITS_2P = [
  [0.25, 0.25, 0.50],
  [0.33, 0.33, 0.34],
  [0.25, 0.50, 0.25],
  [0.50, 0.25, 0.25],
  [0.33, 0.50, 0.17],
];

function _poFmtR(v) {
  if (!Number.isFinite(v)) return '—';
  const s = v.toFixed(2);
  return v > 0 ? '+' + s + 'R' : s + 'R';
}
function _poFmtPct(v) {
  if (!Number.isFinite(v)) return '—';
  return (v * 100).toFixed(1) + '%';
}
function _poFmtNum(v, d = 2) {
  if (!Number.isFinite(v)) return '—';
  return v.toFixed(d);
}
function _poDeltaSpan(delta, suffix = 'R', invertSign = false) {
  if (!Number.isFinite(delta) || Math.abs(delta) < 1e-6) {
    return `<span class="po-delta po-delta-neutral">±0${suffix}</span>`;
  }
  const positive = invertSign ? delta < 0 : delta > 0;
  const cls = positive ? 'po-delta-good' : 'po-delta-bad';
  const sign = delta > 0 ? '+' : '';
  return `<span class="po-delta ${cls}">${sign}${delta.toFixed(2)}${suffix}</span>`;
}

// Build the candidate model list from current config.
// Baseline (Full TP) is always at index 0.
function _poGenerateGrid(config) {
  // SL fixed at PO_SL_DEFAULT (1R) since v11 — no longer in config.
  const sl = PO_SL_DEFAULT;
  const { tpFinal, partialMode, sweepMode } = config;
  const models = [];

  // List of TP finals to test. In sweep mode, iterate over all PO_RR_DIST_THRESHOLDS
  // values within [1.5, 20]. In single mode, just the configured tpFinal.
  const tpFinals = sweepMode
    ? PO_RR_DIST_THRESHOLDS.map(t => t.lv).filter(lv => lv >= 1.5 && lv <= 20)
    : [tpFinal];

  for (const tpf of tpFinals) {
    // Skip TP finals that produce no valid partial models for the active mode.
    // (Baseline is always added regardless — useful for cross-TP comparisons.)
    const validForOne = _PO_TP1_GRID_1P.some(tp1 => tp1 < tpf);
    const validForTwo = _PO_TP1_GRID_2P.some(tp1 =>
      _PO_TP2_GRID_2P.some(tp2 => tp1 < tp2 && tp2 < tpf)
    );

    // Baseline for this TP final.
    models.push({
      id: `baseline_${tpf}`,
      name: `Full TP ${tpf}R`,
      type: 'full',
      legs: [{ lv: tpf, pct: 1.0 }],
      sl, tpFinal: tpf,
    });

    if ((partialMode === 'one' || partialMode === 'both') && validForOne) {
      for (const tp1 of _PO_TP1_GRID_1P) {
        if (tp1 >= tpf) continue;
        for (const [p1, pf] of _PO_SPLITS_1P) {
          models.push({
            id: `1p_${tpf}_${tp1}_${Math.round(p1 * 100)}`,
            name: `${tp1}R/${tpf}R · ${Math.round(p1 * 100)}/${Math.round(pf * 100)}`,
            type: 'one',
            legs: [
              { lv: tp1, pct: p1 },
              { lv: tpf, pct: pf },
            ],
            sl, tpFinal: tpf,
          });
        }
      }
    }

    if ((partialMode === 'two' || partialMode === 'both') && validForTwo) {
      for (const tp1 of _PO_TP1_GRID_2P) {
        if (tp1 >= tpf) continue;
        for (const tp2 of _PO_TP2_GRID_2P) {
          if (tp2 <= tp1 || tp2 >= tpf) continue;
          for (const [p1, p2, pf] of _PO_SPLITS_2P) {
            models.push({
              id: `2p_${tpf}_${tp1}_${tp2}_${Math.round(p1 * 100)}_${Math.round(p2 * 100)}`,
              name: `${tp1}/${tp2}/${tpf}R · ${Math.round(p1 * 100)}/${Math.round(p2 * 100)}/${Math.round(pf * 100)}`,
              type: 'two',
              legs: [
                { lv: tp1, pct: p1 },
                { lv: tp2, pct: p2 },
                { lv: tpf, pct: pf },
              ],
              sl, tpFinal: tpf,
            });
          }
        }
      }
    }
  }

  return models;
}

// Best TP Final selector: for each tpFinal present in the results, average the
// EV of the top 20% non-baseline models that target it. Return the tpFinal
// whose top-20 average is highest. Used by the dedicated stat card.
function _poBestTpFinal(results) {
  const groupedByTpf = new Map();
  for (const r of results) {
    if (r.model.type === 'full') continue;
    const tpf = r.model.tpFinal;
    if (!groupedByTpf.has(tpf)) groupedByTpf.set(tpf, []);
    groupedByTpf.get(tpf).push(r.sim.ev);
  }
  let bestTpf = null, bestScore = -Infinity, bestN = 0;
  for (const [tpf, evs] of groupedByTpf) {
    if (!evs.length) continue;
    const sorted = evs.slice().sort((a, b) => b - a);
    const top20Count = Math.max(1, Math.floor(sorted.length * 0.2));
    const top20 = sorted.slice(0, top20Count);
    const avg = top20.reduce((a, b) => a + b, 0) / top20.length;
    if (avg > bestScore) { bestScore = avg; bestTpf = tpf; bestN = top20Count; }
  }
  return bestTpf !== null ? { tpf: bestTpf, avgEV: bestScore, n: bestN } : null;
}

// Color gradient indexed on PO_RR_DIST_THRESHOLDS — used when colorMode='tpfinal'.
function _poTpfColor(tpf) {
  const idx = PO_RR_DIST_THRESHOLDS.findIndex(t => t.lv === tpf);
  if (idx < 0) return tc('--dim') || '#6B8AB0';
  // Index → hue: low TPF green, mid blue, high amber, very high red.
  const palette = [
    tc('--g')    || '#5dd6a8',   // 1R
    tc('--g')    || '#5dd6a8',   // 2R
    tc('--b')    || '#5a9cf5',   // 2.4R
    tc('--b')    || '#5a9cf5',   // 3R
    tc('--b')    || '#5a9cf5',   // 3.3R
    tc('--b')    || '#5a9cf5',   // 5R
    tc('--a')    || '#f5c642',   // 7R
    tc('--r')    || '#e05a6e',   // 10R
    tc('--r')    || '#e05a6e',   // 15R
    tc('--r')    || '#e05a6e',   // 20R
  ];
  return palette[idx] || (tc('--dim') || '#6B8AB0');
}

// ── PR-C: Partial Optimizer preset slots (P1/P2/P3) ───────────────────
// Slots are scoped per dashboard preset (live in presetLiveFilters[id].poPresetSlots)
// and store only the model parameters. Stats are recomputed on every render against
// the currently filtered dataset — slots reflect the SAME params under DIFFERENT
// data conditions, by design.

const _PO_PRESET_SLOT_KEYS = ['P1', 'P2', 'P3'];

/** Returns the {P1, P2, P3} object for the active preset, initializing if absent. */
function _poGetPresetSlots() {
  const id = appState.presets?.activeId ?? null;
  const slot = getPresetLiveSlot(id);
  if (!slot.poPresetSlots) {
    slot.poPresetSlots = { P1: null, P2: null, P3: null };
  }
  return slot.poPresetSlots;
}

/** Saves a model to the given slot key (P1/P2/P3). Stores only params (tpFinal, legs,
 *  type, name). Persists immediately. Returns true on success. */
function _poSavePresetSlot(slotKey, model) {
  if (!_PO_PRESET_SLOT_KEYS.includes(slotKey)) return false;
  if (!model || !Array.isArray(model.legs) || !Number.isFinite(model.tpFinal)) return false;

  const slots = _poGetPresetSlots();
  slots[slotKey] = {
    tpFinal: model.tpFinal,
    legs: model.legs.map(l => ({ lv: l.lv, pct: l.pct })),
    type: model.type || 'full',
    name: model.name || `Slot ${slotKey}`,
  };
  try { savePresetLiveFilters(); } catch (e) {
    console.warn('[poPresetSlot] save failed:', e.message);
    return false;
  }
  return true;
}

/** Empties the given slot key. Persists. Returns true on success. */
function _poDeletePresetSlot(slotKey) {
  if (!_PO_PRESET_SLOT_KEYS.includes(slotKey)) return false;
  const slots = _poGetPresetSlots();
  slots[slotKey] = null;
  try { savePresetLiveFilters(); } catch (e) {
    console.warn('[poPresetSlot] delete failed:', e.message);
    return false;
  }
  // PR-D: cleanup hidden-curve state — if the slot is re-saved later, the
  // curve should reappear by default, not stay hidden from a previous toggle.
  if (window._poState?.hiddenPresetCurves) {
    window._poState.hiddenPresetCurves.delete(slotKey);
  }
  return true;
}

/** Recomputes the simulation result for a saved slot against the current filtered
 *  dataset. Returns { sim, vsBaseline, stability, model } or null if slot empty / no data. */
function _poSimulateSlotModel(slotKey) {
  const slots = _poGetPresetSlots();
  const stored = slots[slotKey];
  if (!stored) return null;

  const { trades, rrMaxArr } = _poGetTradesAndRRMax();
  if (!rrMaxArr.length) return null;

  // Reconstruct a model object compatible with _poSimulateModel.
  const model = {
    id: `slot_${slotKey}`,
    name: stored.name,
    type: stored.type,
    legs: stored.legs.map(l => ({ lv: l.lv, pct: l.pct })),
    sl: -1,
    tpFinal: stored.tpFinal,
  };

  const sim = _poSimulateModel(model, rrMaxArr, trades);
  if (!sim) return null;

  // Compute vsBaseline against the matching tpFinal Full-TP baseline if available
  // in the current results. Fallback: no comparison.
  const st = window._poState;
  let vsBaseline = null;
  if (st && Array.isArray(st.results)) {
    const baseline = st.results.find(r => r.model.type === 'full' && r.model.tpFinal === stored.tpFinal);
    if (baseline) {
      vsBaseline = _poComputeSavedSacrificed(sim.simR, baseline.sim.simR);
    }
  }

  return { sim, vsBaseline, stability: 0, model };
}

// Simulate one model on the rrMax array — returns per-trade R + aggregates.
function _poSimulateModel(model, rrMaxArr, trades) {
  const n = rrMaxArr.length;
  if (!n) return null;
  // BE-aware per-trade simulation when trades parity matches the rrMax array,
  // mirroring computeEffectiveRR's BE-TP/BE-SL handling. Without trades, fall
  // back to plain _ppSimTrade (back-compat for callers with rrMax-only arrays).
  const useBeAware = Array.isArray(trades) && trades.length === n;
  const simR = new Array(n);
  for (let i = 0; i < n; i++) {
    simR[i] = useBeAware
      ? _poSimTradeBeAware(trades[i], rrMaxArr[i], model.legs)
      : _ppSimTrade(rrMaxArr[i], model.legs);
  }

  let totalR = 0, posSum = 0, negSum = 0, posCount = 0;
  for (let i = 0; i < n; i++) {
    const r = simR[i];
    totalR += r;
    if (r > 0) { posSum += r; posCount++; }
    else if (r < 0) negSum += -r;
  }
  const ev = totalR / n;
  const wr = posCount / n;
  const pf = negSum > 0 ? posSum / negSum : (posSum > 0 ? 99 : 0);

  // Equity curve + max drawdown — iterated in CHRONOLOGICAL order (date+hour
  // with _rawRowIndex tiebreaker) so the PO Max DD aligns with `calcStats`'s
  // sticky-bar Max DD. Both surfaces converge through `_sortTradesChronological`'s
  // canonical, mode-independent ordering. Without this sort, PO would consume the
  // raw input order while `calcStats` sorted chronologically, producing different
  // equity-curve trough timing on datasets with same-day / same-hour clusters
  // (observed gap up to 1.75R on the user's 628-trade set).
  let order;
  if (useBeAware) {
    order = Array.from({ length: n }, (_, i) => i);
    order.sort((a, b) => {
      const ta = trades[a], tb = trades[b];
      if (ta.date !== tb.date) return ta.date < tb.date ? -1 : 1;
      const h = (ta.hour ?? 99) - (tb.hour ?? 99);
      if (h !== 0) return h;
      return (ta._rawRowIndex ?? 0) - (tb._rawRowIndex ?? 0);
    });
  } else {
    // No trades parity → can't sort chronologically. Preserve input order.
    order = Array.from({ length: n }, (_, i) => i);
  }
  const equity = new Array(n);
  let cum = 0, peak = 0, maxDD = 0;
  for (let i = 0; i < n; i++) {
    cum += simR[order[i]];
    equity[i] = cum;
    if (cum > peak) peak = cum;
    const dd = peak - cum;
    if (dd > maxDD) maxDD = dd;
  }

  // Mean / std for sharpe-like.
  let mean = ev, varSum = 0;
  for (let i = 0; i < n; i++) varSum += (simR[i] - mean) ** 2;
  const std = Math.sqrt(varSum / n);
  const sharpeLike = std > 0 ? mean / std : 0;

  // Rolling 50-trade WR — % of windows that close net positive.
  const W = 50;
  let rollPosWindows = 0, rollWindows = 0;
  if (n >= W) {
    let windowSum = 0;
    for (let i = 0; i < W; i++) windowSum += simR[i];
    if (windowSum > 0) rollPosWindows++;
    rollWindows = 1;
    for (let i = W; i < n; i++) {
      windowSum += simR[i] - simR[i - W];
      rollWindows++;
      if (windowSum > 0) rollPosWindows++;
    }
  }
  const rollWR = rollWindows > 0 ? rollPosWindows / rollWindows : (totalR > 0 ? 1 : 0);

  // Robustness check: EV with the top 5% of positive trades trimmed off.
  // Detects models whose performance hinges on a few outlier wins.
  const positiveDesc = simR.filter(v => v > 0).sort((a, b) => b - a);
  const trimCount = Math.floor(positiveDesc.length * 0.05);
  let trimSum = 0;
  for (let i = 0; i < trimCount; i++) trimSum += positiveDesc[i];
  const evRobust = (totalR - trimSum) / n;

  return { simR, totalR, ev, wr, pf, posSum, negSum, maxDD, sharpeLike, rollWR, equity, evRobust };
}

// Bootstrap N resamples with replacement on simR — returns mean + IC95%.
function _poBootstrap(simR, iters) {
  const n = simR.length;
  if (!n || iters <= 0) return null;
  const samples = new Array(iters);
  for (let k = 0; k < iters; k++) {
    let s = 0;
    for (let i = 0; i < n; i++) s += simR[(Math.random() * n) | 0];
    samples[k] = s / n;
  }
  samples.sort((a, b) => a - b);
  const sum = samples.reduce((a, b) => a + b, 0);
  const mean = sum / iters;
  const lowIdx = Math.max(0, Math.floor(iters * 0.025));
  const highIdx = Math.min(iters - 1, Math.ceil(iters * 0.975) - 1);
  // Bootstrap std-dev of the EV estimate — drives the reliability Y axis.
  let varSum = 0;
  for (let i = 0; i < iters; i++) varSum += (samples[i] - mean) ** 2;
  const stdEV = Math.sqrt(varSum / iters);
  return { mean, low: samples[lowIdx], high: samples[highIdx], stdEV };
}

// Compute the four Y-axis metrics in one pass (stability, calmar, reliability,
// robust). Each is normalized 0-100 within the active batch via min-max scaling.
// Stability formula is preserved for backwards compatibility (still surfaces
// in ranking + detail card). Must be called AFTER bootstrap so that
// r.bootstrap.stdEV is populated for the reliability score.
function _poComputeYMetrics(results) {
  if (!results.length) return;

  let sharpeMin = Infinity, sharpeMax = -Infinity;
  let ddMin = Infinity, ddMax = -Infinity;
  let rwrMin = Infinity, rwrMax = -Infinity;
  let calmarMin = Infinity, calmarMax = -Infinity;
  let stdMin = Infinity, stdMax = -Infinity;
  let robustMin = Infinity, robustMax = -Infinity;

  for (const r of results) {
    if (r.sim.sharpeLike < sharpeMin) sharpeMin = r.sim.sharpeLike;
    if (r.sim.sharpeLike > sharpeMax) sharpeMax = r.sim.sharpeLike;
    if (r.sim.maxDD < ddMin) ddMin = r.sim.maxDD;
    if (r.sim.maxDD > ddMax) ddMax = r.sim.maxDD;
    if (r.sim.rollWR < rwrMin) rwrMin = r.sim.rollWR;
    if (r.sim.rollWR > rwrMax) rwrMax = r.sim.rollWR;

    // Calmar = ev / relative DD. For losing models, take the negative magnitude
    // so they end up at the bottom of the score after normalization.
    const totalRabs = Math.max(Math.abs(r.sim.totalR), 1);
    const ddRel = r.sim.maxDD / totalRabs;
    const calmarBase = r.sim.ev / Math.max(ddRel, 0.01);
    r._calmarRaw = r.sim.totalR > 0 ? calmarBase : -Math.abs(calmarBase);
    if (r._calmarRaw < calmarMin) calmarMin = r._calmarRaw;
    if (r._calmarRaw > calmarMax) calmarMax = r._calmarRaw;

    const stdEV = r.bootstrap?.stdEV;
    if (Number.isFinite(stdEV)) {
      r._stdEVRaw = stdEV;
      if (stdEV < stdMin) stdMin = stdEV;
      if (stdEV > stdMax) stdMax = stdEV;
    } else {
      r._stdEVRaw = null;
    }

    r._robustRaw = Number.isFinite(r.sim.evRobust) ? r.sim.evRobust : r.sim.ev;
    if (r._robustRaw < robustMin) robustMin = r._robustRaw;
    if (r._robustRaw > robustMax) robustMax = r._robustRaw;
  }

  const span = (lo, hi) => Math.max(hi - lo, 1e-9);
  const sSpan = span(sharpeMin, sharpeMax);
  const dSpan = span(ddMin, ddMax);
  const rSpan = span(rwrMin, rwrMax);
  const calSpan = span(calmarMin, calmarMax);
  const robSpan = span(robustMin, robustMax);
  const hasStd = Number.isFinite(stdMin) && Number.isFinite(stdMax);

  // Reliability normalization via P5/P95 clamping (v7 fix). The raw stdEV
  // distribution is heavy-tailed: a single high-variance model would otherwise
  // compress the entire visible range. Clamping into [P5, P95] before
  // normalizing keeps the bulk of the bubbles spread over the full Y axis.
  let stdP5 = stdMin, stdP95 = stdMax;
  if (hasStd) {
    const stdSorted = results
      .map(r => r._stdEVRaw)
      .filter(v => Number.isFinite(v))
      .sort((a, b) => a - b);
    if (stdSorted.length >= 5) {
      stdP5  = stdSorted[Math.floor(stdSorted.length * 0.05)];
      stdP95 = stdSorted[Math.floor(stdSorted.length * 0.95)];
    }
  }
  const stdClampSpan = Math.max(stdP95 - stdP5, 1e-9);

  for (const r of results) {
    const sNorm = (r.sim.sharpeLike - sharpeMin) / sSpan;
    const dNorm = 1 - (r.sim.maxDD - ddMin) / dSpan;          // lower DD = better
    const rNorm = (r.sim.rollWR - rwrMin) / rSpan;
    r.stability = Math.round(((sNorm + dNorm + rNorm) / 3) * 100);

    r.calmarScore = Math.round(((r._calmarRaw - calmarMin) / calSpan) * 100);

    if (hasStd && r._stdEVRaw !== null) {
      const clamped = Math.max(stdP5, Math.min(stdP95, r._stdEVRaw));
      r.reliabilityScore = Math.round((1 - (clamped - stdP5) / stdClampSpan) * 100);
    } else {
      r.reliabilityScore = 50;
    }

    r.robustScore = Math.round(((r._robustRaw - robustMin) / robSpan) * 100);

    delete r._calmarRaw;
    delete r._stdEVRaw;
    delete r._robustRaw;
  }
}

// Compute R Saved / R Sacrificed / Net relative to baseline simR.
function _poComputeSavedSacrificed(simR, baselineSimR) {
  let saved = 0, sacrificed = 0;
  const n = simR.length;
  for (let i = 0; i < n; i++) {
    const d = simR[i] - baselineSimR[i];
    if (d > 0) saved += d;
    else if (d < 0) sacrificed += d;
  }
  return { saved, sacrificed, net: saved + sacrificed };
}

// v12: sync the Partial Optimizer's TP final from the Optimal RR Analysis
// active bubble. When the user activates an ORR bubble, the optimizer's
// TP final adopts that R level. When no ORR bubble is active, fallback to 2.4R.
// The user can still override manually — sync only fires on rrMinFilter change.
function _poSyncTPFinalFromORR() {
  const cfg = window._poState?.config;
  if (!cfg) return;
  const orrSelected = appState?.ui?.rrMinFilter;
  cfg.tpFinal = (typeof orrSelected === 'number' && orrSelected > 0) ? orrSelected : 2.4;
  const tpEl = document.getElementById('po-tpfinal');
  if (tpEl) tpEl.value = cfg.tpFinal;
}
window._poSyncTPFinalFromORR = _poSyncTPFinalFromORR;

// Returns BOTH the trades array and the rrMax array for the optimizer.
// The trades are needed for the BE-aware per-trade simulation in
// _poSimTradeBeAware. Derives both from the context-filtered dataset
// (BE Management filter applied without reintegration) using _getTradeReachR.
function _poGetTradesAndRRMax() {
  try {
    const trades = (typeof _getContextFiltered === 'function')
      ? _getContextFiltered(true)
      : (Array.isArray(appState?.trades?.items) ? appState.trades.items : []);
    return { trades: trades.slice(), rrMaxArr: trades.map(t => _getTradeReachR(t)) };
  } catch (e) {
    return { trades: [], rrMaxArr: [] };
  }
}

// Acquire the rrMax array for the Partial Optimizer. Thin wrapper around
// _poGetTradesAndRRMax for back-compat with call sites that don't need the
// trade array.
function _poAcquireRRMaxArr() {
  try {
    const trades = (typeof _getContextFiltered === 'function')
      ? _getContextFiltered(true)
      : (Array.isArray(appState?.trades?.items) ? appState.trades.items : []);
    return trades.map(t => _getTradeReachR(t));
  } catch (e) {
    return [];
  }
}

function _poTradesHash(rrMaxArr, config) {
  const n = rrMaxArr.length;
  let s = 0;
  for (let i = 0; i < n; i++) s += rrMaxArr[i];
  // beMode in the hash so a BE Management mode switch triggers a fresh
  // simulation pass (the rrMax sum alone wouldn't change but the per-trade
  // simR via _poSimTradeBeAware does).
  const beMode = (appState.ui && appState.ui.beMode) || 'be-fallback';
  return `${n}|${s.toFixed(4)}|${config.tpFinal}|${config.partialMode}|sweep:${config.sweepMode ? 1 : 0}|be:${beMode}`;
}

// Run the full pipeline: generate grid → simulate each → bootstrap → stability.
function _poRecompute() {
  const st = window._poState;
  // v13: pull both trades and rrMaxArr in one shot — trades feed the BE-TP
  // path-order correction inside _poSimulateModel.
  const { trades, rrMaxArr } = _poGetTradesAndRRMax();
  if (!rrMaxArr.length) {
    st.models = [];
    st.results = [];
    return false;
  }

  st.models = _poGenerateGrid(st.config);
  const results = [];
  for (let i = 0; i < st.models.length; i++) {
    const sim = _poSimulateModel(st.models[i], rrMaxArr, trades);
    if (!sim) continue;
    results.push({ idx: i, model: st.models[i], sim, stability: 0, vsBaseline: null, bootstrap: null });
  }

  // Build a map: tpFinal → baseline result. Each TP final has its own
  // Full-TP baseline so vsBaseline / significance compare against the same TPF.
  const baselineByTpf = new Map();
  for (const r of results) {
    if (r.model.type === 'full') baselineByTpf.set(r.model.tpFinal, r);
  }

  // R Saved / Sacrificed / Net per same-TP-final baseline.
  for (const r of results) {
    const baseline = baselineByTpf.get(r.model.tpFinal);
    if (!baseline) continue;
    r.vsBaseline = _poComputeSavedSacrificed(r.sim.simR, baseline.sim.simR);
  }

  // Bootstrap is always-on since v11. Iters fixed at constants — sweep mode
  // gets the lower cap (100) to keep ~880-model batches responsive.
  const iters = st.config.sweepMode ? PO_BOOTSTRAP_ITERS_SWEEP : PO_BOOTSTRAP_ITERS;
  for (const r of results) {
    r.bootstrap = _poBootstrap(r.sim.simR, iters);
  }
  // Significance per same-TP-final baseline.
  for (const r of results) {
    const baseline = baselineByTpf.get(r.model.tpFinal);
    if (r === baseline || !r.bootstrap || !baseline?.bootstrap) {
      r.significant = false;
      continue;
    }
    r.significant = r.bootstrap.low > baseline.bootstrap.mean;
  }

  // Active baseline for fallback display: in sweep mode use the configured
  // tpFinal's baseline (or first available), else the single model at index 0.
  if (st.config.sweepMode) {
    let bIdx = results.findIndex(r => r.model.type === 'full' && r.model.tpFinal === st.config.tpFinal);
    if (bIdx < 0) bIdx = results.findIndex(r => r.model.type === 'full');
    st.baselineIdx = bIdx < 0 ? 0 : bIdx;
  } else {
    st.baselineIdx = 0;
  }

  _poComputeYMetrics(results);

  st.results = results;
  st.lastTradesHash = _poTradesHash(rrMaxArr, st.config);
  if (st.selectedIdx >= results.length) st.selectedIdx = 0;
  return true;
}

function _poRankResults(results, mode, dir) {
  const sorted = results.slice();
  const score = (r) => {
    switch (mode) {
      case 'totalR':     return r.sim.totalR;
      case 'ev':         return r.sim.ev;
      case 'wr':         return r.sim.wr;
      case 'stability':  return r.stability;
      case 'compromise': return 0.6 * r.sim.ev + 0.004 * r.stability;
      // sim.maxDD is POSITIVE (peak - cum, ≥ 0). For "Min DD" (best = smallest
      // drawdown) we want the smallest maxDD first under desc — return -maxDD
      // so largest score (least negative) wins.
      case 'dd':         return -r.sim.maxDD;
      case 'pf':         return r.sim.pf;
      case 'netSaved':   return r.vsBaseline ? r.vsBaseline.net : 0;
      default:           return r.sim.totalR;
    }
  };
  // Direction multiplier: desc (default) = largest score first, asc = smallest
  // first. Previous code had this inverted, causing all stat cards to surface
  // the WORST model. JS sort: negative return → a before b. score(b) - score(a)
  // is negative when score(a) > score(b), so a comes first → descending ✓.
  const direction = dir === 'asc' ? -1 : 1;
  sorted.sort((a, b) => direction * (score(b) - score(a)));
  return sorted;
}

function _poTypeColor(type) {
  switch (type) {
    case 'full': return tc('--dim') || '#6B8AB0';
    case 'one':  return tc('--gold') || '#5a9cf5';
    case 'two':  return tc('--t') || '#3ec8d8';
    default:     return tc('--body') || '#b6ceee';
  }
}
function _poTypeLabel(type) {
  return type === 'full' ? 'Full TP' : type === 'one' ? '1 partial' : '2 partials';
}

// ══════════════════════════════════════════════════════
// PARTIAL OPTIMIZER — Internal layout editor (PR-5, Phase A)
// Custom drag/resize on a 12-col × 280-row CSS grid (#po-body).
// Pattern mirrors _mc2InitSectionLayoutEdit. Persists to localStorage.
// Hooks into the global _editMode flag via toggleEditMode.
// Phase A: 7 main blocks. Phase B (bandeau internal cards) = future PR-6.
// ══════════════════════════════════════════════════════
const _PO_INTERNAL_LAYOUT_KEY = 'po-section-layout-v1';
const _PO_INTERNAL_GRID_COLS = 12;
const _PO_INTERNAL_MIN = {
  rrdist:  { w: 3,  h: 6  },
  bandeau: { w: 6,  h: 8  },
  scatter: { w: 5,  h: 24 },
  detail:  { w: 3,  h: 24 },
  ranking: { w: 3,  h: 12 },
  equity:  { w: 4,  h: 12 },
  presets: { w: 6,  h: 10 },
};
// Defaults reflect the PR-4-bis layout (bandeau top-right, scatter compressed,
// Bilan full-left under RR-dist).
const _PO_DEFAULT_INTERNAL_LAYOUT = {
  rrdist:  { x: 1,  y: 1,   w: 4,  h: 36  },
  bandeau: { x: 5,  y: 1,   w: 8,  h: 36  },
  detail:  { x: 1,  y: 37,  w: 4,  h: 128 },
  scatter: { x: 5,  y: 37,  w: 8,  h: 128 },
  ranking: { x: 1,  y: 165, w: 4,  h: 60  },
  equity:  { x: 6,  y: 165, w: 6,  h: 60  },
  presets: { x: 1,  y: 225, w: 12, h: 56  },
};
let _poInternalEditBound = false;

function _poInternalCloneLayout(layout) {
  return Object.fromEntries(Object.entries(layout).map(([k, v]) => [k, { ...v }]));
}
function _poInternalRectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
function _poInternalClampSectionRect(key, rect) {
  const min = _PO_INTERNAL_MIN[key] || { w: 2, h: 4 };
  const w = Math.max(min.w, Math.min(_PO_INTERNAL_GRID_COLS, Math.round(rect.w || min.w)));
  const h = Math.max(min.h, Math.round(rect.h || min.h));
  const x = Math.max(1, Math.min(_PO_INTERNAL_GRID_COLS - w + 1, Math.round(rect.x || 1)));
  const y = Math.max(1, Math.round(rect.y || 1));
  return { x, y, w, h };
}
function _poInternalCompactLayout(layout) {
  const keys = Object.keys(layout).sort((a, b) => layout[a].y - layout[b].y || layout[a].x - layout[b].x);
  keys.forEach(key => {
    const rect = layout[key];
    let nextY = rect.y;
    while (nextY > 1) {
      const probe = { ...rect, y: nextY - 1 };
      const blocked = keys.some(other => other !== key && _poInternalRectsOverlap(probe, layout[other]));
      if (blocked) break;
      nextY -= 1;
    }
    rect.y = nextY;
  });
  return layout;
}
function _poInternalNormalizeLayout(raw) {
  const layout = _poInternalCloneLayout(_PO_DEFAULT_INTERNAL_LAYOUT);
  if (raw && typeof raw === 'object') {
    Object.keys(_PO_DEFAULT_INTERNAL_LAYOUT).forEach(key => {
      if (raw[key]) layout[key] = _poInternalClampSectionRect(key, raw[key]);
    });
  }
  const keys = Object.keys(layout).sort((a, b) => layout[a].y - layout[b].y || layout[a].x - layout[b].x);
  for (let i = 0; i < keys.length; i++) {
    for (let j = i + 1; j < keys.length; j++) {
      if (_poInternalRectsOverlap(layout[keys[i]], layout[keys[j]])) {
        layout[keys[j]].y = layout[keys[i]].y + layout[keys[i]].h;
      }
    }
  }
  return _poInternalCompactLayout(layout);
}
function _poInternalGetLayout() {
  try { return _poInternalNormalizeLayout(JSON.parse(localStorage.getItem(_PO_INTERNAL_LAYOUT_KEY))); }
  catch { return _poInternalCloneLayout(_PO_DEFAULT_INTERNAL_LAYOUT); }
}
function _poInternalSaveLayout(layout) {
  try { localStorage.setItem(_PO_INTERNAL_LAYOUT_KEY, JSON.stringify(_poInternalNormalizeLayout(layout))); } catch {}
}
function _poInternalSetSectionRect(layout, key, nextRect) {
  const next = _poInternalCloneLayout(layout);
  next[key] = _poInternalClampSectionRect(key, nextRect);
  const keys = Object.keys(next).filter(k => k !== key);
  let changed = true;
  while (changed) {
    changed = false;
    keys.forEach(other => {
      if (_poInternalRectsOverlap(next[key], next[other])) {
        next[other] = { ...next[other], y: next[key].y + next[key].h };
        changed = true;
      }
    });
  }
  return _poInternalCompactLayout(next);
}
function _poInternalApplyLayout() {
  const grid = document.getElementById('po-body');
  if (!grid) return;
  const layout = _poInternalGetLayout();
  let maxRow = 0;
  Object.keys(layout).forEach(key => {
    const block = grid.querySelector(`[data-po-section="${key}"]`);
    if (!block) return;
    const rect = layout[key];
    block.style.gridColumn = `${rect.x} / span ${rect.w}`;
    block.style.gridRow    = `${rect.y} / span ${rect.h}`;
    maxRow = Math.max(maxRow, rect.y + rect.h - 1);
  });
  // Drive total rows dynamically — lets the user grow blocks beyond default.
  grid.style.setProperty('--po-grid-rows', String(Math.max(280, maxRow)));
  // Ping Chart.js charts so they redraw at the new pixel size.
  requestAnimationFrame(() => {
    try { window._poState?.equityChart?.resize(); } catch {}
    try { window._poState?.scatterChart?.resize(); } catch {}
  });
}
function _poInternalResetLayout() {
  try { localStorage.removeItem(_PO_INTERNAL_LAYOUT_KEY); } catch {}
  _poInternalApplyLayout();
}
function _poInternalInitEdit() {
  if (_poInternalEditBound) return;
  const grid = document.getElementById('po-body');
  if (!grid) return;
  _poInternalEditBound = true;

  const getGridMetrics = () => {
    const rect = grid.getBoundingClientRect();
    const styles = getComputedStyle(grid);
    const colGap = parseFloat(styles.columnGap || styles.gap || '0') || 0;
    const rowGap = parseFloat(styles.rowGap    || styles.gap || '0') || 0;
    const usableW = Math.max(1, rect.width - colGap * (_PO_INTERNAL_GRID_COLS - 1));
    const colW = usableW / _PO_INTERNAL_GRID_COLS;
    const totalRows = parseFloat(styles.getPropertyValue('--po-grid-rows')) || 280;
    const usableH = Math.max(1, rect.height - rowGap * (totalRows - 1));
    const rowH = usableH / totalRows;
    return { rect, colW, rowH, colGap, rowGap };
  };
  const toGridPoint = (clientX, clientY) => {
    const { rect, colW, rowH, colGap, rowGap } = getGridMetrics();
    const colStep = colW + colGap;
    const rowStep = rowH + rowGap;
    return {
      x: Math.max(1, Math.min(_PO_INTERNAL_GRID_COLS, Math.round((clientX - rect.left) / Math.max(1, colStep)) + 1)),
      y: Math.max(1, Math.round((clientY - rect.top) / Math.max(1, rowStep)) + 1),
    };
  };

  const begin = (key, mode, startEvent, dir = 'se') => {
    if (!_editMode) return;
    startEvent.preventDefault();
    // Stop bubble so the outer GridStack's draggable doesn't also pick this up.
    startEvent.stopPropagation();
    const layout = _poInternalGetLayout();
    const start = layout[key];
    if (!start) return;
    const block = grid.querySelector(`[data-po-section="${key}"]`);
    block?.classList.add('is-dragging');

    const origin = toGridPoint(startEvent.clientX, startEvent.clientY);
    const s = { x: start.x, y: start.y, w: start.w, h: start.h };

    const onMove = e => {
      const p  = toGridPoint(e.clientX, e.clientY);
      const dx = p.x - origin.x;
      const dy = p.y - origin.y;
      let next;
      if (mode === 'move') {
        next = { x: s.x + dx, y: s.y + dy, w: s.w, h: s.h };
      } else {
        const min = _PO_INTERNAL_MIN[key] || { w: 2, h: 4 };
        let x = s.x, y = s.y, w = s.w, h = s.h;
        if (dir.includes('e')) w = Math.max(min.w, s.w + dx);
        if (dir.includes('s')) h = Math.max(min.h, s.h + dy);
        if (dir.includes('w')) { const cw = Math.max(min.w, s.w - dx); x = s.x + (s.w - cw); w = cw; }
        if (dir.includes('n')) { const ch = Math.max(min.h, s.h - dy); y = s.y + (s.h - ch); h = ch; }
        next = { x, y, w, h };
      }
      if (mode === 'resize') {
        const { rect, colW, colGap } = getGridMetrics();
        const colStep = colW + colGap;
        const nearRight = (rect.right - e.clientX) < Math.max(14, colStep * 0.6);
        if (dir.includes('e') && nearRight) next.w = _PO_INTERNAL_GRID_COLS - next.x + 1;
      }
      const nextLayout = _poInternalSetSectionRect(layout, key, next);
      _poInternalSaveLayout(nextLayout);
      _poInternalApplyLayout();
    };
    const onUp = () => {
      block?.classList.remove('is-dragging');
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup',   onUp);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup',   onUp);
  };

  grid.querySelectorAll('.po-internal-drag-handle').forEach(btn => {
    btn.onpointerdown = e => begin(btn.dataset.dragKey, 'move', e);
  });
  grid.querySelectorAll('[data-po-section] > .ui-resizable-handle').forEach(btn => {
    btn.onpointerdown = e => begin(btn.dataset.resizeKey, 'resize', e, btn.dataset.resizeDir || 'se');
  });

  const resetBtn = grid.querySelector('.po-internal-reset-btn');
  if (resetBtn) {
    resetBtn.addEventListener('click', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      _poInternalResetLayout();
    });
  }
}

