function _poWireScaffold() {
  const cfg = window._poState.config;
  const $ = (id) => document.getElementById(id);

  // Initial values from state. v11: SL/Bootstrap/Iters retirés (constants).
  const tpEl = $('po-tpfinal');      if (tpEl) { tpEl.value = cfg.tpFinal; tpEl.disabled = !!cfg.sweepMode; }
  const pmEl = $('po-partial-mode'); if (pmEl) pmEl.value = cfg.partialMode;
  const tnEl = $('po-top-n');        if (tnEl) tnEl.value = String(cfg.topN);
  const cmEl = $('po-color-mode');   if (cmEl) cmEl.value = cfg.colorMode;
  const sweepEl = $('po-sweep-mode'); if (sweepEl) sweepEl.checked = !!cfg.sweepMode;
  const yAxEl = $('po-yaxis');         if (yAxEl) yAxEl.value = cfg.yAxisMode || 'calmar';
  const hideCatEl = $('po-hide-catastrophic'); if (hideCatEl) hideCatEl.checked = !!cfg.hideCatastrophic;
  // v12: initial sync from Optimal RR — adopt whatever bubble was already active.
  _poSyncTPFinalFromORR();

  let debounceT = null;
  const debouncedRecompute = () => {
    clearTimeout(debounceT);
    debounceT = setTimeout(() => {
      _poRecompute();
      _poRender({ rerunSim: false });
    }, 300);
  };

  tpEl?.addEventListener('change', () => {
    cfg.tpFinal = Math.max(1.5, Math.min(20, parseFloat(tpEl.value) || 4));
    tpEl.value = cfg.tpFinal;
    debouncedRecompute();
  });
  pmEl?.addEventListener('change', () => {
    cfg.partialMode = pmEl.value;
    debouncedRecompute();
  });
  // Sortable column headers — click to set rankMode, reclick to toggle direction
  document.querySelectorAll('#po-ranking thead th.po-th-sortable').forEach(th => {
    th.addEventListener('click', () => {
      const newMode = th.getAttribute('data-po-sort');
      if (!newMode) return;
      if (cfg.rankMode === newMode) {
        cfg.rankDir = (cfg.rankDir === 'desc') ? 'asc' : 'desc';
      } else {
        cfg.rankMode = newMode;
        cfg.rankDir = 'desc';
      }
      _poRender({ rerunSim: false });
    });
  });
  tnEl?.addEventListener('change', () => {
    cfg.topN = tnEl.value === 'all' ? 'all' : (parseInt(tnEl.value, 10) || 50);
    _poRender({ rerunSim: false });
  });
  cmEl?.addEventListener('change', () => {
    cfg.colorMode = cmEl.value;
    if (cfg.colorMode !== 'tpfinal' && window._poState.hiddenTpFinals) {
      window._poState.hiddenTpFinals.clear();
    }
    _poRender({ rerunSim: false });
  });

  // Y-axis metric switch — re-renders scatter only (metrics already computed).
  // Special case: if user picks 'reliability' while bootstrap is OFF, auto-enable
  // bootstrap and trigger a recompute (stdEV is needed for reliability).
  // Y-axis switch — re-renders scatter only (metrics already computed).
  // Bootstrap is always-on (v11), so no auto-enable guard needed for reliability.
  yAxEl?.addEventListener('change', () => {
    cfg.yAxisMode = yAxEl.value || 'calmar';
    _poRenderScatter();
  });

  // Hide catastrophic toggle (EV < -0.3R)
  hideCatEl?.addEventListener('change', () => {
    cfg.hideCatastrophic = !!hideCatEl.checked;
    _poRenderScatter();
  });

  // Equity baseline BE Management filter toggle (v12). Re-renders only the
  // equity canvas — no recompute of the model batch.
  const equityBeEl = $('po-equity-be-filter');
  if (equityBeEl) {
    equityBeEl.checked = !!window._poState.equityBaselineBeFilter;
    equityBeEl.addEventListener('change', () => {
      window._poState.equityBaselineBeFilter = equityBeEl.checked;
      const st = window._poState;
      const sel = st.results[st.selectedIdx];
      const baseR = st.results[st.baselineIdx];
      if (sel && baseR) _poRenderEquity(sel, baseR);
    });
  }

  // Hide-non-top toggle button
  const hideBtn = $('po-hide-non-top');
  if (hideBtn) {
    hideBtn.classList.toggle('is-active', !!cfg.hideNonTop);
    hideBtn.addEventListener('click', () => {
      cfg.hideNonTop = !cfg.hideNonTop;
      hideBtn.classList.toggle('is-active', cfg.hideNonTop);
      _poRenderScatter();
    });
  }

  // Reset zoom button
  const zoomResetBtn = $('po-zoom-reset');
  if (zoomResetBtn) {
    zoomResetBtn.addEventListener('click', () => {
      const chart = window._poState?.scatterChart;
      if (chart && typeof chart.resetZoom === 'function') chart.resetZoom();
    });
  }

  // Legend click delegation: toggle TP final visibility (sweep + tpfinal mode).
  // Bound once via a flag so re-render of legend HTML doesn't multiply listeners.
  const legendEl = $('po-legend');
  if (legendEl && !legendEl._poToggleBound) {
    legendEl.addEventListener('click', (e) => {
      const item = e.target.closest('[data-action="po-toggle-tpf"]');
      if (!item) return;
      const tpf = parseFloat(item.dataset.tpf);
      if (!Number.isFinite(tpf)) return;
      const set = window._poState.hiddenTpFinals;
      if (!set) return;
      if (set.has(tpf)) set.delete(tpf);
      else set.add(tpf);
      _poRenderScatter();
    });
    legendEl._poToggleBound = true;
  }
  sweepEl?.addEventListener('change', () => {
    cfg.sweepMode = sweepEl.checked;
    // Visually grey out the TP Final input — its value is ignored in sweep mode.
    if (tpEl) tpEl.disabled = !!cfg.sweepMode;
    // Auto-switch the colorMode to keep the legend meaningful, but only if
    // the user is on the default 'type' / coming back to it. Don't override
    // if they actively chose 'sig' or 'tpfinal'.
    if (cfg.sweepMode && cfg.colorMode === 'type') {
      cfg.colorMode = 'tpfinal';
      if (cmEl) cmEl.value = 'tpfinal';
    } else if (!cfg.sweepMode && cfg.colorMode === 'tpfinal') {
      cfg.colorMode = 'type';
      if (cmEl) cmEl.value = 'type';
    }
    // Sweep toggle invalidates per-tpf legend hides.
    if (window._poState.hiddenTpFinals) window._poState.hiddenTpFinals.clear();
    debouncedRecompute();
  });
  $('po-recalc')?.addEventListener('click', () => {
    _poRecompute();
    _poRender({ rerunSim: false });
  });

  // Stat-card click → select that model. The 'tpfinal' card is a summary,
  // not a per-model selector — clicking it picks the best EV model among
  // the recommended TP final.
  document.querySelectorAll('.po-stat-card').forEach(card => {
    card.addEventListener('click', () => {
      const key = card.getAttribute('data-po-stat');
      const st = window._poState;
      if (!st.results.length) return;
      let pick = null;
      if (key === 'tpfinal') {
        if (!st.config.sweepMode) return;
        const best = _poBestTpFinal(st.results);
        if (!best) return;
        const candidates = st.results.filter(r => r.model.tpFinal === best.tpf && r.model.type !== 'full');
        if (!candidates.length) return;
        candidates.sort((a, b) => b.sim.ev - a.sim.ev);
        pick = candidates[0];
      } else {
        const mode = key === 'totalR' ? 'totalR'
          : key === 'ev' ? 'ev'
          : key === 'stability' ? 'stability'
          : key === 'compromise' ? 'compromise' : 'dd';
        const ranked = _poRankResults(st.results, mode);
        pick = ranked[0];
      }
      if (pick) {
        st.selectedIdx = pick.idx;
        _poRender({ rerunSim: false });
      }
    });
  });

  // RR-distribution chip click → open the trade drawer for that threshold.
  // Delegated on po-body so chips re-rendered later still respond.
  const body = document.getElementById('po-body');
  body?.addEventListener('click', (ev) => {
    const chip = ev.target.closest('.pp-gchip[data-action="po-rr-drawer"]');
    if (!chip) return;
    const lv = parseFloat(chip.dataset.lv);
    const label = chip.dataset.label;
    if (Number.isFinite(lv)) _poRRGchipDrawer(lv, label);
  });
}

function _poRenderScatter() {
  const st = window._poState;
  const canvas = document.getElementById('po-scatter');
  if (!canvas) return;
  if (!st.results.length) {
    if (st.scatterChart) { st.scatterChart.destroy(); st.scatterChart = null; }
    const ctx = canvas.getContext?.('2d');
    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
    return;
  }

  // Catastrophic filter: drop models with EV below -0.3R unless they are the
  // current baseline (which is a required reference even when poor).
  const PO_CATASTROPHIC_EV_THRESHOLD = -0.3;
  let workingResults = st.results;
  if (st.config.hideCatastrophic) {
    workingResults = workingResults.filter(r =>
      r.sim.ev >= PO_CATASTROPHIC_EV_THRESHOLD || r.idx === st.baselineIdx
    );
  }

  const ranked = _poRankResults(workingResults, st.config.rankMode);
  const top = (st.config.topN === 'all') ? ranked : ranked.slice(0, st.config.topN);
  const topSet = new Set(top.map(r => r.idx));
  const hiddenTpfs = (st.hiddenTpFinals instanceof Set) ? st.hiddenTpFinals : new Set();

  // Hide-non-top filter: when active, only Top N bubbles enter the datasets
  // (vs the default behavior where non-top are kept dim).
  const visibleResults = st.config.hideNonTop ? top : workingResults;

  // v7 migration: 'stability' was removed from the dropdown options. Any
  // persisted yAxisMode that points there silently falls back to calmar.
  const _PO_VALID_Y = new Set(['calmar', 'reliability', 'robust']);
  if (!_PO_VALID_Y.has(st.config.yAxisMode)) st.config.yAxisMode = 'calmar';

  // Dynamic Y-axis selector — picks the metric matching cfg.yAxisMode.
  const yValueOf = (r) => {
    switch (st.config.yAxisMode) {
      case 'reliability': return r.reliabilityScore;
      case 'robust':      return r.robustScore;
      case 'calmar':
      default:            return r.calmarScore;
    }
  };
  const yAxisTitle = ({
    calmar:      'Calmar score (profit / drawdown)',
    reliability: 'Fiabilité bootstrap',
    robust:      'Robustesse (sans outliers)',
  })[st.config.yAxisMode] || 'Calmar score';

  const datasets = [];
  // v12: power curve + wider range so small/big models are visibly distinct.
  // Range 3-28px (was 4-18). Exponent 0.85 dampens extreme |totalR| outliers.
  const sizeFor = (r) => {
    const absR = Math.abs(r.sim.totalR);
    return Math.max(3, Math.min(28, 3 + Math.pow(absR, 0.85) * 1.1));
  };
  const colorFor = (r) => {
    if (st.config.colorMode === 'sig') {
      if (r.idx === st.baselineIdx) return tc('--dim') || '#6B8AB0';
      return r.significant ? (tc('--g') || '#5dd6a8') : (tc('--text-muted') || tc('--dim') || '#6B8AB0');
    }
    if (st.config.colorMode === 'tpfinal') {
      return _poTpfColor(r.model.tpFinal);
    }
    return _poTypeColor(r.model.type);
  };

  const buildDS = (label, filter) => {
    const data = [], radii = [], cols = [], borders = [], borderWs = [];
    for (const r of visibleResults) {
      if (!filter(r)) continue;
      const inTop = topSet.has(r.idx);
      const isSel = r.idx === st.selectedIdx;
      data.push({ x: r.sim.ev, y: yValueOf(r), idx: r.idx });
      radii.push(sizeFor(r) * (isSel ? 1.4 : 1));
      const col = colorFor(r);
      // Dim non-top bubbles ONLY when hideNonTop is OFF (otherwise they wouldn't be visible at all).
      cols.push((inTop || st.config.hideNonTop) ? col : (col + '55'));
      // v12: thin dark border on every bubble keeps overlapping points distinct.
      borders.push(isSel ? (tc('--white') || '#e4f0ff') : 'rgba(0,0,0,0.25)');
      borderWs.push(isSel ? 2.5 : 0.5);
    }
    return {
      label,
      data,
      backgroundColor: cols,
      pointRadius: radii,
      pointHoverRadius: radii.map(r => r + 2),
      pointBorderColor: borders,
      pointBorderWidth: borderWs,
    };
  };

  if (st.config.colorMode === 'sig') {
    datasets.push(buildDS('Baseline', r => r.idx === st.baselineIdx));
    datasets.push(buildDS('Significant (IC95% > baseline)', r => r.idx !== st.baselineIdx && r.significant));
    datasets.push(buildDS('Non-significant', r => r.idx !== st.baselineIdx && !r.significant));
  } else if (st.config.colorMode === 'tpfinal') {
    // One dataset per distinct TP final actually present (and not legend-hidden).
    const presentTpfs = [...new Set(st.results.map(r => r.model.tpFinal))].sort((a, b) => a - b);
    for (const tpf of presentTpfs) {
      if (hiddenTpfs.has(tpf)) continue;
      datasets.push(buildDS(`≥ ${tpf}R`, r => r.model.tpFinal === tpf));
    }
  } else {
    datasets.push(buildDS('Full TP', r => r.model.type === 'full'));
    datasets.push(buildDS('1 partial', r => r.model.type === 'one'));
    datasets.push(buildDS('2 partials', r => r.model.type === 'two'));
  }

  if (st.scatterChart) { st.scatterChart.destroy(); st.scatterChart = null; }
  canvas.removeAttribute('width'); canvas.removeAttribute('height');
  const tipFs = (typeof _chartTipFs === 'function') ? _chartTipFs() : 11;

  // Axis padding: extend bounds by 10% of the data range so that bubbles at the
  // extremes never touch the chart edges. Floor with absolute minimums so
  // tightly-clustered batches still get visible breathing room. Bounds are
  // computed on the visible subset, so toggling hideNonTop / legend tpfs
  // re-frames the chart on what's actually displayed.
  const visibleForBounds = visibleResults.filter(r =>
    st.config.colorMode !== 'tpfinal' || !hiddenTpfs.has(r.model.tpFinal)
  );
  const boundsSrc = visibleForBounds.length ? visibleForBounds : workingResults;
  const xValues = boundsSrc.map(r => r.sim.ev);
  const yValues = boundsSrc.map(yValueOf);
  const xMin = Math.min(...xValues), xMax = Math.max(...xValues);
  const yMin = Math.min(...yValues), yMax = Math.max(...yValues);
  const xPad = Math.max((xMax - xMin) * 0.1, 0.02);
  const yPad = Math.max((yMax - yMin) * 0.1, 5);

  st.scatterChart = new Chart(canvas, {
    type: 'scatter',
    data: { datasets },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      onClick: (ev, els, chart) => {
        if (!els || !els.length) return;
        const e = els[0];
        const pt = chart.data.datasets[e.datasetIndex].data[e.index];
        if (pt && Number.isFinite(pt.idx)) {
          st.selectedIdx = pt.idx;
          _poRender({ rerunSim: false });
        }
      },
      onHover: (ev, els) => {
        const t = ev?.native?.target; if (t) t.style.cursor = (els && els.length) ? 'pointer' : 'default';
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          enabled: true,
          backgroundColor: tc('--surface-3') || '#182438',
          titleColor:      tc('--text-primary') || '#e4f0ff',
          bodyColor:       tc('--body') || '#b6ceee',
          borderColor:     tc('--accent-primary') || '#5a9cf5',
          borderWidth: 1,
          cornerRadius: 4,
          padding: 10,
          titleFont: { size: tipFs + 1, family: '"DM Mono",monospace', weight: '600' },
          bodyFont:  { size: tipFs,     family: '"DM Mono",monospace' },
          displayColors: false,
          caretSize: 6,
          intersect: true,    // tooltip n'apparaît que quand le curseur est PILE sur la bulle
          mode: 'nearest',
          callbacks: {
            label: (ctx) => {
              const pt = ctx.raw;
              const r = window._poState.results[pt.idx];
              if (!r) return '';
              const mode = window._poState.config.yAxisMode;
              const yVal = ({ calmar: r.calmarScore, reliability: r.reliabilityScore, robust: r.robustScore })[mode] ?? r.calmarScore;
              const yLbl = ({ calmar: 'Calmar', reliability: 'Fiab', robust: 'Robust' })[mode] || 'Calmar';
              return ` ${r.model.name} · EV ${_poFmtR(r.sim.ev)} · ${yLbl} ${yVal} · DD ${_poFmtR(r.sim.maxDD)}`;
            }
          }
        },
        zoom: {
          pan: {
            enabled: true,
            mode: 'xy',
            modifierKey: null,
            threshold: 5,   // <5px drag → click-through (selects bubble); >5px → pan
          },
          zoom: {
            wheel:  { enabled: true, speed: 0.1, modifierKey: null },
            pinch:  { enabled: true },
            mode:   'xy',
          },
          limits: {
            x: { min: 'original', max: 'original', minRange: 0.05 },
            y: { min: 'original', max: 'original', minRange: 5 },
          },
        },
      },
      scales: {
        x: {
          type: 'linear',
          min: xMin - xPad,
          max: xMax + xPad,
          title: { display: true, text: 'EV (R / trade)', color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
        },
        y: {
          type: 'linear',
          min: yMin - yPad,
          max: yMax + yPad,
          title: { display: true, text: yAxisTitle, color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
        },
      }
    }
  });

  // Legend. In tpfinal mode each item carries a data-action so the user can
  // toggle visibility (Chart.js native legend behaviour, replicated here).
  const legend = document.getElementById('po-legend');
  if (legend) {
    let items;
    if (st.config.colorMode === 'sig') {
      items = [
        { col: tc('--dim'),  lbl: 'Baseline (Full TP)' },
        { col: tc('--g'),    lbl: 'Significatif (IC95% > baseline)' },
        { col: tc('--text-muted') || tc('--dim'), lbl: 'Non-significatif' },
      ];
    } else if (st.config.colorMode === 'tpfinal') {
      const presentTpfs = [...new Set(st.results.map(r => r.model.tpFinal))].sort((a, b) => a - b);
      items = presentTpfs.map(tpf => ({
        col: _poTpfColor(tpf),
        lbl: `≥ ${tpf}R`,
        tpf,
        hidden: hiddenTpfs.has(tpf),
      }));
    } else {
      items = [
        { col: tc('--dim'),  lbl: 'Full TP' },
        { col: tc('--gold'), lbl: '1 partial' },
        { col: tc('--t'),    lbl: '2 partials' },
      ];
    }
    legend.innerHTML = items.map(i => {
      const hiddenCls = i.hidden ? ' po-legend-hidden' : '';
      const dataAttr = (i.tpf !== undefined) ? ` data-action="po-toggle-tpf" data-tpf="${i.tpf}"` : '';
      return `<span class="po-legend-item${hiddenCls}"${dataAttr}><span class="po-legend-dot" style="background:${i.col}"></span>${i.lbl}</span>`;
    }).join('') + ` <span class="po-legend-meta">Bulle = |Total R|</span>`;
  }

  // Count + optional filter tag (when catastrophic models are hidden).
  const filteredOut = st.results.length - workingResults.length;
  const countEl = document.getElementById('po-count');
  if (countEl) {
    const filterTag = filteredOut > 0
      ? ` <span class="po-count-filter">(-${filteredOut} cachés)</span>`
      : '';
    countEl.innerHTML = `${top.length} / ${workingResults.length} modèles${filterTag}`;
  }

  // Setup panel feedback (replaces legacy po-grid-meta from v9 and earlier).
  const modelsEl = document.getElementById('po-setup-models');
  if (modelsEl) {
    modelsEl.textContent = `${st.results.length} modèle${st.results.length > 1 ? 's' : ''}`;
  }
  const modeEl = document.getElementById('po-setup-mode');
  if (modeEl) {
    if (st.config.sweepMode) {
      const tpfsPresent = new Set(st.results.map(r => r.model.tpFinal)).size;
      modeEl.textContent = `sweep TP · ${tpfsPresent} TPFs`;
    } else {
      modeEl.textContent = 'single TP';
    }
  }
}

function _poRenderRanking() {
  const st = window._poState;
  const tbody = document.querySelector('#po-ranking tbody');
  if (!tbody) return;
  if (!st.results.length) { tbody.innerHTML = ''; return; }

  // PR-3: PF column was removed but legacy state may still have rankMode === 'pf'.
  // Fall back to 'totalR' to keep the sortable arrow visible.
  if (st.config.rankMode === 'pf') {
    st.config.rankMode = 'totalR';
    st.config.rankDir = 'desc';
  }

  const ranked = _poRankResults(st.results, st.config.rankMode, st.config.rankDir);
  const limit = Math.min(50, ranked.length);

  // Update sort arrow indicators on column headers
  const arrow = (st.config.rankDir === 'asc') ? '▲' : '▼';
  document.querySelectorAll('#po-ranking thead th.po-th-sortable').forEach(th => {
    const mode = th.getAttribute('data-po-sort');
    const arrowEl = th.querySelector('.po-th-arrow');
    if (arrowEl) {
      arrowEl.textContent = (mode === st.config.rankMode) ? ` ${arrow}` : '';
    }
    th.classList.toggle('is-sorted', mode === st.config.rankMode);
  });

  const rows = [];
  for (let i = 0; i < limit; i++) {
    const r = ranked[i];
    const isSel = r.idx === st.selectedIdx;
    const isBase = r.idx === st.baselineIdx;
    const rankPillCls = i === 0 ? 'is-gold' : i === 1 ? 'is-silver' : i === 2 ? 'is-bronze' : '';
    rows.push(`<tr class="po-row${isSel ? ' is-selected' : ''}${isBase ? ' is-baseline' : ''}" data-po-idx="${r.idx}">
      <td class="po-rank-cell"><span class="po-rank-pill ${rankPillCls}">${i + 1}</span></td>
      <td class="po-row-name">${r.model.name}</td>
      <td class="po-num-col ${_poKpiTone(r.sim.totalR, 'totalR')}">${_poFmtR(r.sim.totalR)}</td>
      <td class="po-num-col ${_poKpiTone(r.sim.wr, 'wr')}">${_poFmtPct(r.sim.wr)}</td>
      <td class="po-num-col ${_poKpiTone(r.sim.ev, 'ev')}">${_poFmtR(r.sim.ev)}</td>
      <td class="po-num-col ${_poKpiTone(r.sim.maxDD, 'dd')}">${_poFmtR(-r.sim.maxDD)}</td>
      <td class="po-num-col">${r.stability}</td>
    </tr>`);
  }
  tbody.innerHTML = rows.join('');
  tbody.querySelectorAll('.po-row').forEach(tr => {
    tr.addEventListener('click', () => {
      const idx = parseInt(tr.getAttribute('data-po-idx'), 10);
      if (Number.isFinite(idx)) {
        st.selectedIdx = idx;
        _poRender({ rerunSim: false });
      }
    });
  });
}

function _poRenderDetail() {
  const st = window._poState;
  const wrap = document.getElementById('po-detail');
  if (!wrap) return;
  if (!st.results.length) { wrap.innerHTML = ''; return; }

  const sel = st.results[st.selectedIdx] || st.results[0];
  const base = st.results[st.baselineIdx];
  if (!sel || !base) { wrap.innerHTML = ''; return; }

  const dEV  = sel.sim.ev - base.sim.ev;
  const dWR  = sel.sim.wr - base.sim.wr;
  const dPF  = sel.sim.pf - base.sim.pf;
  const dDD  = -(sel.sim.maxDD - base.sim.maxDD);   // lower = better, invert sign for display
  const dTot = sel.sim.totalR - base.sim.totalR;
  const dStab = sel.stability - base.stability;

  // Verdict heuristic: positive EV vs base + positive net = good. Negative EV = bad. Otherwise neutral.
  let verdictCls = 'po-verdict-neutral', verdictTxt = '≈ Comparable au baseline';
  if (sel.idx === st.baselineIdx) { verdictCls = 'po-verdict-neutral'; verdictTxt = 'Baseline (référence)'; }
  else if (dEV > 0.02 && (sel.vsBaseline?.net ?? 0) > 0) { verdictCls = 'po-verdict-good'; verdictTxt = '✓ Stratégie supérieure au Full TP'; }
  else if (dEV < -0.02 || (sel.vsBaseline?.net ?? 0) < -1) { verdictCls = 'po-verdict-bad'; verdictTxt = '✗ Stratégie inférieure au Full TP'; }

  const saved = sel.vsBaseline?.saved ?? 0;
  const sacri = sel.vsBaseline?.sacrificed ?? 0;
  const net   = sel.vsBaseline?.net ?? 0;

  // Bootstrap confidence approximation: visual % of where mean sits inside CI95.
  // Not a true p-value — readability over statistical purity.
  const ic = sel.bootstrap;
  let confPct = 50;
  let confBlock = '';
  if (ic && Number.isFinite(ic.low) && Number.isFinite(ic.high) && Number.isFinite(ic.mean)) {
    const span = ic.high - ic.low;
    const raw = span > 1e-9 ? ((ic.mean - ic.low) / span) * 100 : 50;
    confPct = Math.max(0, Math.min(100, Math.round(raw)));
    confBlock = `
      <div class="po-bilan-conf">
        <div class="po-bilan-conf-row">
          <span class="po-bilan-conf-lbl">Bootstrap confidence</span>
          <span class="po-bilan-conf-val">${confPct}%</span>
        </div>
        <div class="po-bilan-conf-bar"><div class="po-bilan-conf-fill" style="width:${confPct}%"></div></div>
        <div class="po-bilan-conf-meta">500 iterations · CI95% [${ic.low.toFixed(2)}R, ${ic.high.toFixed(2)}R]</div>
      </div>`;
  }

  const savedCls = _poKpiTone(saved,  'rSaved');
  const sacriCls = _poKpiTone(sacri,  'rSacrificed'); // valeurs négatives → red, descend la palette
  const netCls   = _poKpiTone(net,    'net');

  wrap.innerHTML = `
    <div class="po-bilan-card">
      <div class="po-bilan-hero">
        <span class="po-bilan-tag">Selected model</span>
        <div class="po-bilan-name">${sel.model.name}</div>
        <div class="po-bilan-sub">${verdictTxt}</div>
      </div>
      <div class="po-bilan-rows">
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Total R</span>
          <span class="po-bilan-row-val">
            <span class="${_poKpiTone(sel.sim.totalR, 'totalR')}">${_poFmtR(sel.sim.totalR)}</span>
            ${_poDeltaSpan(dTot)}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">EV</span>
          <span class="po-bilan-row-val">
            <span class="${_poKpiTone(sel.sim.ev, 'ev')}">${_poFmtR(sel.sim.ev)}</span>
            ${_poDeltaSpan(dEV)}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Win Rate</span>
          <span class="po-bilan-row-val">
            <span class="${_poKpiTone(sel.sim.wr, 'wr')}">${_poFmtPct(sel.sim.wr)}</span>
            ${_poDeltaSpan(dWR * 100, 'pp')}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Profit Factor</span>
          <span class="po-bilan-row-val">
            <span class="${_poKpiTone(sel.sim.pf, 'pf')}">${_poFmtNum(sel.sim.pf)}</span>
            ${_poDeltaSpan(dPF, '')}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Max Drawdown</span>
          <span class="po-bilan-row-val">
            <span class="${_poKpiTone(sel.sim.maxDD, 'dd')}">${_poFmtR(-sel.sim.maxDD)}</span>
            ${_poDeltaSpan(dDD)}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Stability</span>
          <span class="po-bilan-row-val">
            <span>${sel.stability}</span>
            ${_poDeltaSpan(dStab, '')}
          </span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">R Saved</span>
          <span class="po-bilan-row-val"><span class="${savedCls}">${_poFmtR(saved)}</span></span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">R Sacrificed</span>
          <span class="po-bilan-row-val"><span class="${sacriCls}">${_poFmtR(sacri)}</span></span>
        </div>
        <div class="po-bilan-row">
          <span class="po-bilan-row-lbl">Net</span>
          <span class="po-bilan-row-val"><span class="${netCls}">${_poFmtR(net)}</span></span>
        </div>
      </div>
      ${confBlock}
      <div class="po-bilan-foot">
        <button type="button" class="po-bilan-btn" id="po-btn-save-preset">
          <span class="po-bilan-btn-ic">💾</span><span>Save preset</span>
        </button>
        <button type="button" class="po-bilan-btn po-bilan-btn-primary" id="po-btn-apply-dashboard"
          ${sel.model.type === 'full' ? 'disabled title="Full TP models cannot be applied as Personalised. Switch to Fixed mode manually if needed."' : ''}>
          <span>Apply to Dashboard</span><span class="po-bilan-btn-arrow">→</span>
        </button>
      </div>
    </div>
  `;

  // Wire the Apply button (after innerHTML assignment).
  const applyBtn = document.getElementById('po-btn-apply-dashboard');
  if (applyBtn && sel.model.type !== 'full') {
    applyBtn.addEventListener('click', () => _poApplyToDashboard(sel));
  }

  // Wire the Save button — opens slot picker popup anchored to the button.
  const saveBtn = document.getElementById('po-btn-save-preset');
  if (saveBtn) {
    saveBtn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      _poOpenSavePopup(saveBtn, sel.model);
    });
  }

  // Equity curve is rendered into its own block (po-block-equity) every render.
  _poRenderEquity(sel, base);
}

// PR-B: push the selected PO model's params into appState.ui.tpConfig as a
// Personalised TP plan, with confirmation if one already exists. Stays on the
// Partial Optimizer section. Full TP models (type === 'full') are not
// supported — the button is disabled in those cases.
function _poApplyToDashboard(sel) {
  if (!sel || !sel.model) return;
  if (sel.model.type === 'full') return; // Defensive guard — button is disabled.

  const legs = sel.model.legs;
  if (!Array.isArray(legs) || legs.length < 2 || legs.length > 3) {
    console.warn('[poApply] Unexpected legs shape:', legs);
    return;
  }

  // Build the Personalised sub-config. tpCount = legs.length (each leg is a TP).
  // legs[i].lv is the R-multiple target; legs[i].pct is the fraction (0..1).
  // _isValidPersonalisedConfig requires tp1/tp2/tp3 keys all present even when
  // tpCount === 2 (tp3 is then ignored by the engine but the shape must be valid).
  const tpCount = legs.length;
  const newPersonalised = {
    tpCount,
    targets: {
      tp1: legs[0].lv,
      tp2: legs[1].lv,
      tp3: legs[2]?.lv ?? 3,
    },
    partials: {
      tp1: Math.round((legs[0].pct ?? 0) * 100),
      tp2: Math.round((legs[1].pct ?? 0) * 100),
      tp3: Math.round((legs[2]?.pct ?? 0) * 100),
    },
  };

  // Apply directly: write the new sub-config, then switch mode (which triggers
  // _saveTpConfig → render() → all widgets refresh). No confirmation — direct
  // application by user request (PR-B v2).
  const cfg = appState.ui.tpConfig;
  cfg.personalised = newPersonalised;
  if (typeof _setTpMode === 'function') _setTpMode('personalised');

  // Visual feedback on the button: temporarily change label.
  const btn = document.getElementById('po-btn-apply-dashboard');
  if (btn) {
    const original = btn.textContent;
    btn.textContent = '✓ Applied';
    btn.classList.add('is-applied');
    setTimeout(() => {
      // Re-check element still exists (the detail block may have been re-rendered).
      const stillThere = document.getElementById('po-btn-apply-dashboard');
      if (stillThere) {
        stillThere.textContent = original;
        stillThere.classList.remove('is-applied');
      }
    }, 1500);
  }
}

// ── PR-C 2/2: UI for P1/P2/P3 preset slots ────────────────────────────

/** Renders the 3 tiles (P1/P2/P3) in the .po-block-presets block. Called on
 *  every _poRender, so stats stay in sync with the current filtered dataset. */
function _poRenderPresetsBlock() {
  const wrap = document.getElementById('po-presets-grid');
  if (!wrap) return;

  const slots = _poGetPresetSlots();
  const tiles = _PO_PRESET_SLOT_KEYS.map(key => {
    const stored = slots[key];
    if (!stored) {
      // Empty tile: + button for quick-save with watermark and SVG plus icon
      return `
        <div class="po-preset-tile po-preset-tile-empty" data-po-slot="${key}" role="button" tabindex="0" aria-label="Save current model to ${key}">
          <span class="po-preset-tile-watermark" aria-hidden="true">${key}</span>
          <div class="po-preset-tile-empty-content">
            <div class="po-preset-tile-plus">
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            </div>
            <div class="po-preset-tile-hint">Quick save</div>
            <div class="po-preset-tile-sub">Click to save current model</div>
          </div>
        </div>
      `;
    }
    // Filled tile: name + 4 stats (EV/Total R with delta vs baseline, WR/DD without)
    // + Apply / Trash buttons. Deltas computed against the same-tpFinal Full TP baseline
    // present in current results — null if baseline not in scope.
    const result = _poSimulateSlotModel(key);
    const sim = result?.sim;
    const evTxt   = sim ? _poFmtR(sim.ev) : '—';
    const wrTxt   = sim ? _poFmtPct(sim.wr) : '—';
    const ddTxt   = sim ? _poFmtR(-sim.maxDD) : '—';
    const totTxt  = sim ? _poFmtR(sim.totalR) : '—';
    const isFull = stored.type === 'full';
    // 6-tier dynamic color classes — aligned on _poKpiTone palette.
    const evClass  = sim ? _poKpiTone(sim.ev,     'ev')     : '';
    const totClass = sim ? _poKpiTone(sim.totalR, 'totalR') : '';
    const wrClass  = sim ? _poKpiTone(sim.wr,     'wr')     : '';
    const ddClass  = sim ? _poKpiTone(sim.maxDD,  'dd')     : '';

    const st2 = window._poState;
    const baselineForSlot = (st2 && Array.isArray(st2.results))
      ? st2.results.find(r => r.model.type === 'full' && r.model.tpFinal === stored.tpFinal)
      : null;
    let evDeltaHTML = '', totDeltaHTML = '';
    if (sim && baselineForSlot) {
      const dEV  = sim.ev - baselineForSlot.sim.ev;
      const dTot = sim.totalR - baselineForSlot.sim.totalR;
      const evDeltaCls  = dEV  > 0.005 ? 'pos' : dEV  < -0.005 ? 'neg' : 'neutral';
      const totDeltaCls = dTot > 0.05  ? 'pos' : dTot < -0.05  ? 'neg' : 'neutral';
      const evArrow  = evDeltaCls  === 'pos' ? '▲' : evDeltaCls  === 'neg' ? '▼' : '•';
      const totArrow = totDeltaCls === 'pos' ? '▲' : totDeltaCls === 'neg' ? '▼' : '•';
      evDeltaHTML  = `<span class="po-preset-stat-delta ${evDeltaCls}">${evArrow}${dEV  >= 0 ? '+' : ''}${dEV.toFixed(2)}</span>`;
      totDeltaHTML = `<span class="po-preset-stat-delta ${totDeltaCls}">${totArrow}${dTot >= 0 ? '+' : ''}${dTot.toFixed(1)}</span>`;
    }

    const trashSVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>`;
    const typeLabel = stored.type === 'two' ? '2 Partials' : stored.type === 'one' ? '1 Partial' : 'Full TP';

    return `
      <div class="po-preset-tile po-preset-tile-filled" data-po-slot="${key}">
        <div class="po-preset-tile-head">
          <span class="po-preset-tile-badge" data-slot="${key}">${key}</span>
          <div class="po-preset-tile-head-actions">
            <button type="button" class="po-preset-btn-trash" data-po-slot-delete="${key}" aria-label="Delete ${key}" title="Delete ${key}">
              ${trashSVG}
            </button>
          </div>
        </div>
        <div class="po-preset-tile-name-block">
          <span class="po-preset-tile-name" title="${stored.name}">${stored.name}</span>
          <span class="po-preset-tile-type">${typeLabel}</span>
        </div>
        <div class="po-preset-tile-stats">
          <div class="po-preset-stat po-preset-stat-primary">
            <span class="po-preset-stat-lbl">EV</span>
            <div class="po-preset-stat-row">
              <span class="po-preset-stat-val ${evClass}">${evTxt}</span>
              ${evDeltaHTML}
            </div>
          </div>
          <div class="po-preset-stat po-preset-stat-primary">
            <span class="po-preset-stat-lbl">Total R</span>
            <div class="po-preset-stat-row">
              <span class="po-preset-stat-val ${totClass}">${totTxt}</span>
              ${totDeltaHTML}
            </div>
          </div>
          <div class="po-preset-stat">
            <span class="po-preset-stat-lbl">WR</span>
            <div class="po-preset-stat-row">
              <span class="po-preset-stat-val ${wrClass}">${wrTxt}</span>
            </div>
          </div>
          <div class="po-preset-stat">
            <span class="po-preset-stat-lbl">Max DD</span>
            <div class="po-preset-stat-row">
              <span class="po-preset-stat-val ${ddClass}">${ddTxt}</span>
            </div>
          </div>
        </div>
        <div class="po-preset-tile-actions">
          <button type="button" class="po-preset-btn-apply" data-po-slot-apply="${key}"
            ${isFull ? 'disabled title="Full TP models cannot be applied as Personalised."' : ''}>
            <span>Apply</span><span class="po-preset-btn-apply-arrow">→</span>
          </button>
        </div>
      </div>
    `;
  });

  wrap.innerHTML = tiles.join('');

  // Wire empty tiles: click = quick-save the currently selected model
  wrap.querySelectorAll('.po-preset-tile-empty').forEach(tile => {
    const key = tile.getAttribute('data-po-slot');
    const handler = () => {
      const st = window._poState;
      const sel = st?.results[st.selectedIdx];
      if (!sel) return;
      _poSavePresetSlot(key, sel.model);
      _poRenderPresetsBlock();
    };
    tile.addEventListener('click', handler);
    tile.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); handler(); }
    });
  });

  // Wire Apply buttons on filled tiles
  wrap.querySelectorAll('[data-po-slot-apply]').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const key = btn.getAttribute('data-po-slot-apply');
      const slots = _poGetPresetSlots();
      const stored = slots[key];
      if (!stored) return;
      // Build a model-like object for _poApplyToDashboard
      const fakeSel = {
        model: {
          type: stored.type,
          legs: stored.legs.map(l => ({ lv: l.lv, pct: l.pct })),
          tpFinal: stored.tpFinal,
          name: stored.name,
        },
      };
      _poApplyToDashboard(fakeSel);
    });
  });

  // Wire Trash buttons on filled tiles — open confirmation popup
  wrap.querySelectorAll('[data-po-slot-delete]').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const key = btn.getAttribute('data-po-slot-delete');
      _poOpenDeleteConfirmPopup(btn, key);
    });
  });
}

/** Removes any open PO popup. Idempotent. */
function _poCloseAllPopups() {
  document.querySelectorAll('.po-popup').forEach(el => el.remove());
  document.removeEventListener('click', _poCloseAllPopups);
  document.removeEventListener('keydown', _poPopupEscHandler);
}

function _poPopupEscHandler(ev) {
  if (ev.key === 'Escape') _poCloseAllPopups();
}

/** Positions a popup element near the given anchor button, using fixed positioning
 *  so the popup escapes any parent overflow:hidden. Auto-flips above/below if it
 *  would clip the viewport. */
function _poPositionPopup(popup, anchor) {
  // Append to body to escape parent overflow constraints
  document.body.appendChild(popup);
  // Measure
  const a = anchor.getBoundingClientRect();
  const p = popup.getBoundingClientRect();
  const margin = 6;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  // Default: below the anchor, left-aligned
  let top = a.bottom + margin;
  let left = a.left;

  // Flip above if overflow bottom
  if (top + p.height > vh - margin) {
    top = a.top - p.height - margin;
  }
  // Shift left if overflow right
  if (left + p.width > vw - margin) {
    left = vw - p.width - margin;
  }
  if (left < margin) left = margin;
  if (top < margin) top = margin;

  popup.style.position = 'fixed';
  popup.style.top = `${top}px`;
  popup.style.left = `${left}px`;
}

/** Opens the Save popup anchored to the Save button. Lists P1/P2/P3 with current
 *  state (empty / filled with summary). Click on a row → save the current model
 *  in that slot (overwrite without confirmation, the tile has its own trash). */
function _poOpenSavePopup(anchor, model) {
  _poCloseAllPopups();

  const slots = _poGetPresetSlots();
  const popup = document.createElement('div');
  popup.className = 'po-popup po-popup-save';
  popup.innerHTML = `
    <div class="po-popup-title">Save to slot</div>
    <div class="po-popup-rows">
      ${_PO_PRESET_SLOT_KEYS.map(key => {
        const stored = slots[key];
        const status = stored
          ? `<span class="po-popup-row-status filled">${stored.name}</span>`
          : `<span class="po-popup-row-status empty">empty</span>`;
        return `
          <button type="button" class="po-popup-row" data-po-popup-slot="${key}">
            <span class="po-popup-row-key">${key}</span>
            ${status}
          </button>
        `;
      }).join('')}
    </div>
  `;

  popup.querySelectorAll('[data-po-popup-slot]').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const key = btn.getAttribute('data-po-popup-slot');
      _poSavePresetSlot(key, model);
      _poCloseAllPopups();
      _poRenderPresetsBlock();
    });
  });

  // Prevent click-inside from closing the popup
  popup.addEventListener('click', (ev) => ev.stopPropagation());

  _poPositionPopup(popup, anchor);

  // Close on outside click / Escape (deferred so the current click doesn't trigger close)
  setTimeout(() => {
    document.addEventListener('click', _poCloseAllPopups);
    document.addEventListener('keydown', _poPopupEscHandler);
  }, 0);
}

/** Opens a confirmation popup for slot deletion, anchored to the trash button. */
function _poOpenDeleteConfirmPopup(anchor, slotKey) {
  _poCloseAllPopups();

  const popup = document.createElement('div');
  popup.className = 'po-popup po-popup-confirm';
  popup.innerHTML = `
    <div class="po-popup-title">Delete ${slotKey}?</div>
    <div class="po-popup-msg">This action cannot be undone.</div>
    <div class="po-popup-actions">
      <button type="button" class="po-popup-btn-cancel" data-po-popup-cancel>Cancel</button>
      <button type="button" class="po-popup-btn-danger" data-po-popup-confirm>Delete</button>
    </div>
  `;

  popup.querySelector('[data-po-popup-cancel]').addEventListener('click', (ev) => {
    ev.stopPropagation();
    _poCloseAllPopups();
  });
  popup.querySelector('[data-po-popup-confirm]').addEventListener('click', (ev) => {
    ev.stopPropagation();
    _poDeletePresetSlot(slotKey);
    _poCloseAllPopups();
    _poRenderPresetsBlock();
  });

  // Prevent click-inside from closing
  popup.addEventListener('click', (ev) => ev.stopPropagation());

  _poPositionPopup(popup, anchor);

  setTimeout(() => {
    document.addEventListener('click', _poCloseAllPopups);
    document.addEventListener('keydown', _poPopupEscHandler);
  }, 0);
}

function _poRenderEquity(sel, base) {
  const canvas = document.getElementById('po-equity');
  if (!canvas) return;
  const st = window._poState;
  if (st.equityChart) { st.equityChart.destroy(); st.equityChart = null; }

  // Optional toggle to re-simulate the baseline on a different sample.
  // The selected model keeps its existing simulation. The toggle answers
  // "à quoi ressemblerait ma baseline Full TP avec / sans le filtre BE
  // Management ?". Default uses base.sim.equity (= the strict-sample
  // simulation matching the model). When toggled, re-simulate on the
  // BE-reintegrated dataset (computed on demand via _ppBuildReachDataset).
  let baseEquityData = base.sim.equity;
  let baseLabel = 'Baseline (Full TP)';
  if (st.equityBaselineBeFilter) {
    try {
      const ctxTrades = (typeof _getContextFiltered === 'function') ? _getContextFiltered(true) : [];
      const { trades: altTrades } = (typeof _ppBuildReachDataset === 'function')
        ? _ppBuildReachDataset(ctxTrades)
        : { trades: ctxTrades };
      const altArr = altTrades.map(t => _getTradeReachR(t));
      if (altArr.length && altArr.length !== base.sim.equity.length) {
        const altSim = _poSimulateModel(base.model, altArr, altTrades);
        if (altSim) {
          baseEquityData = altSim.equity;
          baseLabel = `Baseline (BE reintegrated, n=${altArr.length})`;
        }
      }
    } catch (e) {
      console.warn('[PO] equity baseline BE-reintegration failed:', e.message);
    }
  }

  // PR-D: Recompute equity for each filled preset slot (P1/P2/P3).
  // Stats stored in slots are just params — equity is recomputed against the
  // current filtered dataset every render, so curves move with filters.
  const presetCurves = []; // [{ key, label, data, color }]
  const _PO_PRESET_COLORS = {
    P1: tc('--g')   || '#5dd6a8',
    P2: tc('--t')   || '#3ec8d8',
    P3: '#b478f0',
  };
  for (const key of _PO_PRESET_SLOT_KEYS) {
    const result = (typeof _poSimulateSlotModel === 'function') ? _poSimulateSlotModel(key) : null;
    if (!result || !result.sim || !Array.isArray(result.sim.equity)) continue;
    presetCurves.push({
      key,
      label: `${key} · ${result.model.name}`,
      data: result.sim.equity,
      color: _PO_PRESET_COLORS[key],
    });
  }

  // Labels go up to the longest of all curves so they align.
  const allLengths = [sel.sim.equity.length, baseEquityData.length, ...presetCurves.map(c => c.data.length)];
  const maxLen = Math.max(...allLengths);
  const labels = Array.from({ length: maxLen }, (_, i) => i + 1);
  canvas.removeAttribute('width'); canvas.removeAttribute('height');
  const tipFs = (typeof _chartTipFs === 'function') ? _chartTipFs() : 11;

  // Build the datasets array. Preset curves are appended after the 2 core ones.
  // Their hidden state is restored from st.hiddenPresetCurves (persists across renders).
  const datasets = [
    {
      label: 'Modèle',
      data: sel.sim.equity,
      borderColor: tc('--gold') || '#5a9cf5',
      backgroundColor: 'transparent',
      borderWidth: 2,
      pointRadius: 0,
      tension: 0.1,
    },
    {
      label: baseLabel,
      data: baseEquityData,
      borderColor: tc('--dim') || '#6B8AB0',
      backgroundColor: 'transparent',
      borderWidth: 1.5,
      borderDash: [4, 4],
      pointRadius: 0,
      tension: 0.1,
    },
  ];
  for (const curve of presetCurves) {
    datasets.push({
      label: curve.label,
      data: curve.data,
      borderColor: curve.color,
      backgroundColor: 'transparent',
      borderWidth: 1.5,
      pointRadius: 0,
      tension: 0.1,
      hidden: st.hiddenPresetCurves.has(curve.key),
      // Custom property to identify this dataset on legend toggle. Chart.js
      // ignores unknown keys but they remain accessible via dataset reference.
      _poPresetKey: curve.key,
    });
  }

  st.equityChart = new Chart(canvas, {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      plugins: {
        legend: {
          display: true,
          labels: { color: tc('--dim'), usePointStyle: true, font: { size: tipFs, family: '"DM Mono",monospace' } },
          // PR-D: custom onClick to persist preset-curve hide state across re-renders.
          // Default Chart.js behaviour is preserved for non-preset datasets.
          onClick: (e, legendItem, legend) => {
            const ci = legend.chart;
            const idx = legendItem.datasetIndex;
            const ds = ci.data.datasets[idx];
            const presetKey = ds && ds._poPresetKey;
            // Toggle visibility (mirrors default Chart.js behaviour)
            const meta = ci.getDatasetMeta(idx);
            meta.hidden = meta.hidden === null ? !ds.hidden : null;
            // If this is a preset dataset, persist the new state.
            if (presetKey && _PO_PRESET_SLOT_KEYS.includes(presetKey)) {
              const isNowHidden = meta.hidden === true || (meta.hidden === null && ds.hidden === true);
              if (isNowHidden) st.hiddenPresetCurves.add(presetKey);
              else st.hiddenPresetCurves.delete(presetKey);
            }
            ci.update();
          },
        },
        tooltip: { bodyFont: { size: tipFs }, titleFont: { size: tipFs } }
      },
      scales: {
        x: { display: false, grid: { display: false } },
        y: {
          title: { display: true, text: 'Cumulative R', color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
          grid: { color: tc('--line') },
          ticks: { color: tc('--dim'), font: { family: '"DM Mono",monospace' } },
        }
      }
    }
  });
}

/**
 * Returns a `po-v-*` CSS class for a KPI value, calibrated on the dashboard's
 * 6-tier thresholds (see _KPI_THRESHOLD_LEGENDS @ dashboard.js:8945).
 *
 * @param {number} value - The raw KPI value.
 * @param {string} kind  - One of: 'avgR' | 'ev' | 'totalR' | 'net' | 'rSaved' |
 *                          'rSacrificed' | 'pf' | 'wr' | 'dd'.
 *                         Default ('avgR') applies the R-multiple ladder.
 * @returns {string}     - CSS class name, or '' if value is not finite.
 */
function _poKpiTone(value, kind = 'avgR') {
  if (!Number.isFinite(value)) return '';

  if (kind === 'pf') {
    if (value < 1)    return 'po-v-red';
    if (value < 1.3)  return 'po-v-orange';
    if (value < 1.7)  return 'po-v-yellow';
    if (value < 2.2)  return 'po-v-green';
    if (value < 3)    return 'po-v-blue';
    return 'po-v-purple';
  }

  if (kind === 'wr') {
    // value in [0, 1]
    if (value < 0.40) return 'po-v-red';
    if (value < 0.45) return 'po-v-orange';
    if (value < 0.50) return 'po-v-yellow';
    if (value < 0.55) return 'po-v-green';
    if (value < 0.65) return 'po-v-blue';
    return 'po-v-purple';
  }

  if (kind === 'dd') {
    // value is positive (peak-to-trough drawdown in R, 0 = no DD)
    if (value <= 0)   return 'po-v-purple';
    if (value < 2)    return 'po-v-blue';
    if (value < 5)    return 'po-v-green';
    if (value < 10)   return 'po-v-yellow';
    if (value < 20)   return 'po-v-orange';
    return 'po-v-red';
  }

  // Default ladder for R-multiple values (avgR, ev, totalR, net, rSaved, rSacrificed)
  if (value < 0)      return 'po-v-red';
  if (value < 0.1)    return 'po-v-orange';
  if (value < 0.3)    return 'po-v-yellow';
  if (value < 0.6)    return 'po-v-green';
  if (value < 1.0)    return 'po-v-blue';
  return 'po-v-purple';
}

// LEGACY — kept temporarily for backward-compat. All callers should migrate to
// _poKpiTone. Remove in cleanup PR R9.
function _poColorClass(value, thresholdPos = 0.005, thresholdNeg = -0.005) {
  if (!Number.isFinite(value)) return '';
  if (value > thresholdPos) return 'po-v-pos';
  if (value < thresholdNeg) return 'po-v-neg';
  return 'po-v-neutral';
}

function _poRenderStatCards() {
  const st = window._poState;
  const cards = document.querySelectorAll('.po-stat-card');
  if (!cards.length || !st.results.length) return;

  // applyColor: function returning the value to color-classify (null = no coloring)
  // kind: KPI kind passed to _poKpiTone (null = no coloring)
  const setCard = (key, ranked, valFmt, applyColor, kind) => {
    const card = document.querySelector(`.po-stat-card[data-po-stat="${key}"]`);
    if (!card || !ranked.length) return;
    const top = ranked[0];
    const nameEl = card.querySelector('.po-stat-name');
    const valEl  = card.querySelector('.po-stat-val');
    if (nameEl) nameEl.textContent = top.model.name;
    if (valEl) {
      // Strip ALL po-v-* classes (legacy + new palette)
      valEl.classList.remove(
        'po-v-pos', 'po-v-neg', 'po-v-neutral',
        'po-v-red', 'po-v-orange', 'po-v-yellow', 'po-v-green', 'po-v-blue', 'po-v-purple'
      );
      if (key === 'compromise') {
        // Mixed coloring: EV dynamic, stability primary
        const evVal = top.sim.ev;
        const evCls = _poKpiTone(evVal, 'ev');
        valEl.innerHTML = `<span class="${evCls}">${_poFmtR(evVal)}</span> <span class="po-stat-val-secondary">· ${top.stability}</span>`;
      } else {
        valEl.textContent = valFmt(top);
        if (applyColor && kind) {
          const cls = _poKpiTone(applyColor(top), kind);
          if (cls) valEl.classList.add(cls);
        }
      }
    }
  };
  setCard('totalR',     _poRankResults(st.results, 'totalR'),     (r) => _poFmtR(r.sim.totalR),     (r) => r.sim.totalR,  'totalR');
  setCard('ev',         _poRankResults(st.results, 'ev'),         (r) => _poFmtR(r.sim.ev),         (r) => r.sim.ev,      'ev');
  setCard('stability',  _poRankResults(st.results, 'stability'),  (r) => `${r.stability}`,          null,                  null);
  setCard('compromise', _poRankResults(st.results, 'compromise'), null,                             null,                  null);
  setCard('dd',         _poRankResults(st.results, 'dd'),         (r) => _poFmtR(-r.sim.maxDD),     (r) => r.sim.maxDD,    'dd');

  // Best TP Final — only meaningful in sweep mode (otherwise all models share
  // a single TP final). AVG EV part colored dynamically like Total R.
  const tpfCard = document.querySelector('.po-stat-card[data-po-stat="tpfinal"]');
  if (tpfCard) {
    const nameEl = tpfCard.querySelector('.po-stat-name');
    const valEl  = tpfCard.querySelector('.po-stat-val');
    if (valEl) valEl.classList.remove(
      'po-v-pos', 'po-v-neg', 'po-v-neutral',
      'po-v-red', 'po-v-orange', 'po-v-yellow', 'po-v-green', 'po-v-blue', 'po-v-purple'
    );
    if (st.config.sweepMode) {
      const best = _poBestTpFinal(st.results);
      if (best) {
        if (nameEl) nameEl.textContent = `top 20% (n=${best.n})`;
        if (valEl) {
          valEl.textContent = `${best.tpf}R · ${_poFmtR(best.avgEV)}`;
          const cls = _poKpiTone(best.avgEV, 'ev');
          if (cls) valEl.classList.add(cls);
        }
      } else {
        if (nameEl) nameEl.textContent = '—';
        if (valEl) valEl.textContent = '—';
      }
    } else {
      if (nameEl) nameEl.textContent = '(sweep désactivé)';
      if (valEl) valEl.textContent = '—';
    }
  }
}

function _poRenderRRDist() {
  const wrap = document.getElementById('po-rr-gchips');
  const headCount = document.getElementById('po-rr-count');
  if (!wrap) return;
  const rrMaxArr = _poAcquireRRMaxArr();
  const n = rrMaxArr.length;
  if (headCount) headCount.textContent = `${n} trade${n > 1 ? 's' : ''}`;
  if (!n) { wrap.innerHTML = ''; return; }

  const html = PO_RR_DIST_THRESHOLDS.map(g => {
    let count = 0;
    for (let i = 0; i < n; i++) if (rrMaxArr[i] >= g.lv) count++;
    const pct = Math.round((count / n) * 100);
    return `<div class="pp-gchip" data-action="po-rr-drawer" data-lv="${g.lv}" data-label="${g.label}" style="cursor:pointer">
      <span class="pp-gchip-lbl" style="color:${g.col}">${g.label}</span>
      <div class="pp-gchip-track">
        <div class="pp-gchip-fill" style="width:${pct}%;background:color-mix(in srgb,${g.col} 45%,transparent)"></div>
      </div>
      <span class="pp-gchip-pct" style="color:${g.col}">${pct}% <span class="pp-gchip-count">·${count}</span></span>
    </div>`;
  }).join('');
  wrap.innerHTML = html;
}

// Open the trade drawer for a given threshold. Option A — simple filtering
// (no BE Management reintegration logic).
function _poRRGchipDrawer(lv, label) {
  const { trades: ctxTrades } = _poGetTradesAndRRMax();
  const trades = (ctxTrades || []).filter(t => {
    const reach = (typeof _getTradeReachR === 'function') ? _getTradeReachR(t) : t?.rrMax;
    return Number.isFinite(reach) && reach >= lv;
  });
  if (!trades.length) return;
  if (typeof openWidgetDrawer === 'function') {
    openWidgetDrawer(label, `${trades.length} trade${trades.length > 1 ? 's' : ''} · rrMax ≥ ${lv}R`, trades);
  }
}

// Top-level render entry. opts.rerunSim forces a full _poRecompute.
function _poRender(opts = {}) {
  const body = document.getElementById('po-body');
  if (!body) return;

  // Active section gate: don't waste cycles when partials section is hidden.
  const activeSection = appState?.ui?.activeSection;
  const isPartialsActive = (activeSection === 'partials');

  const st = window._poState;
  const rrMaxArr = _poAcquireRRMaxArr();
  const headN = document.getElementById('po-head-n');

  if (!rrMaxArr.length) {
    if (headN) headN.textContent = '0 trades';
    if (st.scatterChart) { st.scatterChart.destroy(); st.scatterChart = null; }
    if (st.equityChart)  { st.equityChart.destroy();  st.equityChart  = null; }
    if (typeof renderWidgetEmptyState === 'function') renderWidgetEmptyState('po-body');
    st.built = false;
    return;
  }

  if (!st.built) {
    _poBuildScaffold();
    st.built = true;
  }

  if (headN) headN.textContent = rrMaxArr.length + ' trades';

  // Recompute when forced, when no results yet, or when input fingerprint changed.
  const newHash = _poTradesHash(rrMaxArr, st.config);
  if (opts.rerunSim || !st.results.length || newHash !== st.lastTradesHash) {
    _poRecompute();
  }

  // Skip Chart.js renders when section hidden (canvases have 0 size).
  if (!isPartialsActive) return;

  _poRenderScatter();
  _poRenderRanking();
  _poRenderDetail();
  _poRenderStatCards();
  _poRenderRRDist();
  _poRenderPresetsBlock();
}

window._poRender = _poRender;

// ── Widget empty-state utilities ─────────────────────────────────────
// Each widget's render function calls one of these when the filtered dataset
// would produce nothing. Keeps the UX uniform ("No data matches current filters"
// with an icon) and handles canvas widgets via an absolute overlay.
const EMPTY_STATE_MSG = 'No data matches current filters';
function renderWidgetEmptyState(containerId, message = EMPTY_STATE_MSG) {
  const el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = `<div class="widget-empty-state">
    <div class="widget-empty-state-icon">∅</div>
    <div>${message}</div>
  </div>`;
}
function renderCanvasEmptyState(wrapperSelector, canvasIds = [], message = EMPTY_STATE_MSG) {
  const wrapper = document.querySelector(wrapperSelector);
  if (!wrapper) return;
  // Clear canvases so no stale drawing bleeds through the overlay
  canvasIds.forEach(id => {
    const c = document.getElementById(id);
    if (!c) return;
    const ctx = c.getContext?.('2d');
    if (ctx) ctx.clearRect(0, 0, c.width, c.height);
  });
  // Remove any existing overlay from a prior empty render
  wrapper.querySelectorAll(':scope > .widget-empty-state-overlay').forEach(n => n.remove());
  // Add fresh overlay
  const overlay = document.createElement('div');
  overlay.className = 'widget-empty-state widget-empty-state-overlay';
  overlay.innerHTML = `<div class="widget-empty-state-icon">∅</div><div>${message}</div>`;
  wrapper.appendChild(overlay);
}
function clearCanvasEmptyState(wrapperSelector) {
  const wrapper = document.querySelector(wrapperSelector);
  if (!wrapper) return;
  wrapper.querySelectorAll(':scope > .widget-empty-state-overlay').forEach(n => n.remove());
}

function renderCharts(filtered, stats) {
  syncMonthlyModeUi();

  drawCharts(filtered);
  drawDonut(stats);
  drawMonthly(filtered);
  _syncHardModeBtn();
  renderHeatmap(filtered);

  const absMax = 1.8;
  renderBars('bars-setup', groupByEV(filtered, t => setupDetailMode ? (t.setupDetail || t.setup) : t.setup, k => setupDetailMode ? k : (SETUP_SHORT[k] || k)), absMax, false, 'setup');
  renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session');
  renderDayBars(filtered);
  renderBars('bars-pair', groupByEV(filtered, t => t.pair), absMax, false, 'pair');
  renderObsBars(filtered);
  renderH4ObsBars(filtered);
}

function renderTables(filtered) {
  renderTable(filtered);
}

function renderPanels(filtered) {
  renderStreakAnalytics(filtered);
  renderHourBars(filtered);
  renderRecovery(filtered);
  if (typeof _poRender === 'function') _poRender();
  renderPairSession(filtered);
  renderCalendar(filtered);
  runMonteCarlo(filtered);

  if (typeof updateContextStrip === 'function') updateContextStrip();
  if (appState.filters.temporal.tf.compare) tfUpdateCompareUI();
  if (_gsReady) hideEmptyWidgets(filtered);
  if (_isMobile()) requestAnimationFrame(() => renderMobile());
}

function render() {
  // Phase 4 Bug 6: config-level diagnostic. When the active TP Management mode
  // has a global failure (mapping incomplete, partials sum != 100, rrMax not
  // mapped in Personalised), empty every widget + surface a banner rather than
  // silently display Fixed-fallback numbers that would mislead the user.
  // Per-trade edge cases stay silent inside computeEffectiveRR.
  const diag = _tpmConfigDiagnostic(appState.ui.tpConfig);
  if (diag) {
    _showTpmInvalidBanner(diag);
    const empty = [];
    renderDashboardChrome(empty);
    renderKpis(empty, null);
    renderCharts(empty, null);
    renderTables(empty);
    renderPanels(empty);
    renderOptimalRRWidget(empty);
    _rrSyncActiveFilterBadge();
    _persistSidebarState();
    return;
  }
  _hideTpmInvalidBanner();

  const filtered = getFiltered();
  const stats = calcStats(filtered);
  renderDashboardChrome(filtered);
  renderKpis(filtered, stats);
  renderCharts(filtered, stats);
  renderTables(filtered);
  renderPanels(filtered);
  // ORR widget gets its own filtered view — rrMinFilter must not shrink its input
  renderOptimalRRWidget(getFilteredForORR());
  _rrSyncActiveFilterBadge();
  _persistSidebarState();
}

