// ── Required columns (at least one alias must be present) ──
function openCsvOverlay() {
  const overlay = document.getElementById('csv-overlay');
  if (!overlay) return;
  // Idempotent: if already active, just focus the file input — don't re-stack.
  if (overlay.classList.contains('active')) {
    document.getElementById('csv-file-input')?.focus();
    return;
  }
  overlay.classList.add('active');
  _setText('csv-status', '');
  document.getElementById('csv-status')?.setAttribute('class', 'csv-status');
}
function closeCsvOverlay() {
  document.getElementById('csv-overlay')?.classList.remove('active');
  document.querySelectorAll('.csv-drop-box').forEach(b => b.classList.remove('dragover-box'));
}

// Drag events
document.addEventListener('DOMContentLoaded', () => {
  /* Silent cleanup of retired Partials Planner localStorage keys. */
  try {
    localStorage.removeItem('pp-custom-presets');
    localStorage.removeItem('pp-section-layout-v3');
  } catch (e) {}
  /* ── TP Management panel init (Phase 2.A) ── */
  _initTpmPanelListeners();
  _syncTpmRadios();
  _updateTpmBadge();
  _renderTpmModeBody();
  // Phase 3.A.final: first render of the Feature Requirements block. Subsequent
  // refreshes happen inside updateAttentionButton on every dashboard render.
  try { renderFeatureRequirementsBlock(); } catch (e) {}

  /* ── Sidebar collapse toggle ── */
  {
    const layout = document.querySelector('.layout');
    const toggle = document.getElementById('sidebar-toggle');
    const STORAGE_KEY = 'sidebarCollapsed';
    const sidebarW = () => getComputedStyle(document.documentElement).getPropertyValue('--sidebar-w').trim();

    const positionToggle = (collapsed) => {
      toggle.style.left = collapsed ? '0px' : sidebarW();
    };

    const set = (collapsed) => {
      layout.classList.toggle('sidebar-collapsed', collapsed);
      positionToggle(collapsed);
      try { localStorage.setItem(STORAGE_KEY, collapsed ? '1' : '0'); } catch {}
      // let gridstack / charts reflow
      setTimeout(() => window.dispatchEvent(new Event('resize')), 350);
    };

    toggle.addEventListener('click', () => set(!layout.classList.contains('sidebar-collapsed')));

    // restore persisted state
    try { if (localStorage.getItem(STORAGE_KEY) === '1') set(true); else positionToggle(false); } catch { positionToggle(false); }

    // reposition on resize (sidebar-w changes per breakpoint)
    window.addEventListener('resize', () => {
      if (!layout.classList.contains('sidebar-collapsed')) positionToggle(false);
    });
  }

  buildTypographyControls();
  _syncGhostUI();

  // Sidebar filter-group display order — apply saved order to the static
  // native filter-groups (customs are already rendered in order by
  // renderCustomFilterChips), then wire up the drag-to-reorder Sortables.
  // Sortables start disabled; toggleEditMode enables them.
  try { _applyNativeFilterOrder(); } catch (e) {}
  try { _initFilterSortables(); } catch (e) {}
  try { _initPresetSortable(); } catch (e) {}
  try { _installContextStripObserver(); } catch (e) {}
  // Sync heatmap threshold buttons with persisted values
  document.querySelectorAll('#sd-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _heatmapThreshold);
  });
  document.querySelectorAll('#ps-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _hourHeatmapThreshold);
  });
  // Restore colorblind-mode preference and wire the toggle. Class lives on
  // <html> (documentElement) so :root.colorblind-mode wins in the cascade
  // and tc() reads the override when drawing canvas charts.
  {
    const cbEl = document.getElementById('colorblind-toggle');
    let cbOn = false;
    try { cbOn = localStorage.getItem('colorblind_mode') === '1'; } catch (e) {}
    if (cbOn) {
      document.documentElement.classList.add('colorblind-mode');
      if (cbEl) cbEl.checked = true;
    }
    cbEl?.addEventListener('change', function () {
      document.documentElement.classList.toggle('colorblind-mode', this.checked);
      try { localStorage.setItem('colorblind_mode', this.checked ? '1' : '0'); } catch (e) {}
      if (typeof render === 'function') render();
    });
  }
  const overlay = document.getElementById('csv-overlay');
  const box     = document.getElementById('csv-drop-box');
  if (!overlay || !box) return;

  overlay.addEventListener('dragover', e => {
    e.preventDefault();
    overlay.classList.add('dragover');
    box.classList.add('dragover-box');
  });
  overlay.addEventListener('dragleave', e => {
    if (!overlay.contains(e.relatedTarget)) {
      overlay.classList.remove('dragover');
      box.classList.remove('dragover-box');
    }
  });
  overlay.addEventListener('drop', e => {
    e.preventDefault();
    overlay.classList.remove('dragover');
    box.classList.remove('dragover-box');
    const file = e.dataTransfer?.files?.[0];
    if (file) handleCsvFile(file);
  });
  box.addEventListener('click', e => {
    const nonClick = ['INPUT','BUTTON','LABEL','A'];
    if (!nonClick.includes(e.target.tagName)) {
      document.getElementById('csv-file-input').click();
    }
  });
});

document.addEventListener('dragenter', e => {
  if (e.dataTransfer?.types?.includes('Files')) openCsvOverlay();
});

function csvStatus(msg, type = 'info') {
  const el = document.getElementById('csv-status');
  if (!el) return;
  el.textContent = msg;
  el.className = 'csv-status ' + type;
}

function handleCsvFile(file) {
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  if (ext !== 'csv' && file.type !== 'text/csv' && !file.type.includes('text')) {
    csvStatus('⚠ Unsupported format — .csv file required', 'err');
    return;
  }
  if (file.size > 10 * 1024 * 1024) {
    csvStatus('⚠ File too large (max 10 MB)', 'err');
    return;
  }
  csvStatus('⏳ Reading file…', 'info');
  const reader = new FileReader();
  reader.onload  = e => processCsvText(e.target.result, file.name);
  reader.onerror = () => csvStatus('⚠ Unable to read file', 'err');
  reader.readAsText(file, 'UTF-8');
}

/** Notion exports occasionally wrap each CSV line in outer quotes with internal
 *  `""` escapes (RFC 4180 mis-applied). Detect that shape strictly and unwrap
 *  so downstream parsers see normal CSV. Conservative: only acts when BOTH
 *  anchors AND at least one internal `""` sequence are present, to avoid
 *  false positives on legit single-quoted single-column lines. */
function _unwrapOverQuotedLine(line) {
  if (typeof line !== 'string') return line;
  const t = line.trim();
  if (t.length <= 2) return line;
  if (!t.startsWith('"') || !t.endsWith('"')) return line;
  if (!t.includes('""')) return line;
  return t.slice(1, -1).replace(/""/g, '"');
}

function processCsvText(text, filename, opts = {}) {
  try {
    // Strip UTF-8 BOM at text level FIRST — it precedes the leading " on Notion
    // exports, so the over-wrap detection below would miss it otherwise.
    if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

    // Detect Notion-style over-wrapped lines (whole line bracketed by " with ""
    // escapes). Normalize every line when present so the format-detection and
    // CSV parsers below see standard RFC 4180.
    const firstLineRaw = text.split(/\r?\n/)[0] || '';
    const trimmedFirst = firstLineRaw.trim();
    const isOverWrapped = trimmedFirst.startsWith('"')
                       && trimmedFirst.endsWith('"')
                       && trimmedFirst.includes('""')
                       && trimmedFirst.length > 2;
    if (isOverWrapped) {
      text = text.split(/\r?\n/).map(_unwrapOverQuotedLine).join('\n');
    }

    // ── Detect format ──
    const isFlippingMarket = text.includes('Résultat TP 1') || text.includes('Resultat TP 1') || (text.includes('M15 Type') && text.includes('Obstacles M15'));
    const isProTemplate = !isFlippingMarket && text.includes('Position Result') && text.includes('H4 Obstacles') && text.includes('Session');
    const isBeginner    = !isFlippingMarket && !isProTemplate && text.includes('Position Result');
    if (!isFlippingMarket && !isProTemplate && !isBeginner) {
      csvStatus(
        '⚠ Format not recognized\n' +
        'Header must contain "Résultat TP 1" (Flipping Market) or "Position Result" (Pro / Beginner)',
        'err'
      );
      return;
    }
    const result = isFlippingMarket ? parseFlippingMarketCSV(text) : isProTemplate ? parseProTemplateCSV(text) : parseBeginnerCSV(text);

    if (!result.ok) {
      csvStatus(result.error, 'err');
      return;
    }
    const { trades, warnings } = result;
    const fmt = isFlippingMarket ? ' [Flipping Market M15]' : isProTemplate ? ' [Pro Template]' : ' [Beginner]';
    if (warnings.length) {
      csvStatus(`✓ ${trades.length} trades imported${fmt}\n` + warnings.join('\n'), 'ok');
    } else {
      csvStatus(`✓ ${trades.length} trades imported${fmt}`, 'ok');
    }
    _csvFormat = isFlippingMarket ? 'flipping' : isProTemplate ? 'pro' : 'beginner';

    // Cache the raw text + headers so the user can later remap columns without re-uploading.
    _lastCsvRawText  = text;
    _lastCsvFilename = filename || '';
    try {
      const allLines = text.replace(/\r\n/g, '\n').split('\n').filter(l => l.trim());
      const firstLine = allLines[0] || '';
      _lastCsvHeaders = splitCsvLine(firstLine, ',').map(h => h.trim().replace(/^["']|["']$/g, '').replace(/^\uFEFF/, ''));
      // Capture raw rows as {header: value} objects so the auto-detect scan
      // can read the original CSV regardless of which props are declared.
      _lastCsvRows = allLines.slice(1).map(line => {
        const cols = splitCsvLine(line, ',').map(c => c.trim().replace(/^["']|["']$/g, ''));
        const row = {};
        _lastCsvHeaders.forEach((h, i) => { row[h] = cols[i] ?? ''; });
        return row;
      });
    } catch (e) { _lastCsvHeaders = []; _lastCsvRows = []; }

    if (opts.preserveState && opts.savedState) {
      // Remap re-parse: inject without resetting filters/layout
      _injectTrades(trades, 'CSV', opts.savedState);
      _cachedCSVTrades = trades.filter(t => t.pair && t.pair.trim()).slice();
      csvDataActive = true;
      setSourceIndicator('csv');
      showDataStatus('CSV — ' + appState.trades.totalOverride + ' trades', 'csv');
    } else {
      injectParsedTrades(trades, filename, _csvFormat);
      try { triggerDataHubFirstImportPulse(); } catch (e) {}
      // Persist the raw CSV so the dashboard can restore CSV mode on reload.
      // Sidebar filter state + TPM config are already persisted separately.
      // Wrap in try/catch: raw CSV can be multi-MB and hit QuotaExceededError.
      try {
        localStorage.setItem(CSV_CACHE_KEY, JSON.stringify({
          rawText: text,
          filename: filename || '',
          format: _csvFormat,
          savedAt: Date.now(),
        }));
      } catch (qe) {
        // Quota fallback: drop the raw text, keep metadata only. Next reload
        // will fall through to demo mode cleanly (the restore path checks
        // for rawText presence).
        try {
          localStorage.setItem(CSV_CACHE_KEY, JSON.stringify({
            rawText: '',
            filename: filename || '',
            format: _csvFormat,
            savedAt: Date.now(),
            _quotaExceeded: true,
          }));
        } catch (e2) { /* give up silently */ }
      }
      // Default behavior: CLOSE the Data Hub panel after a successful fresh
      // import so the dashboard widgets become immediately visible. The
      // Health/guide view was relevant during setup; once data is in, it's
      // noise. The user can re-open the hub manually if they need Mapping
      // or Health. Silent no-op if the hub wasn't open.
      if (typeof dataHubOpen !== 'undefined' && dataHubOpen) {
        try { toggleDataHub(); } catch (e) {}
      }
      // Also close the Guide panel (independent of Data Hub) and route the
      // user to Global Overview. Users land on the Guide when they click the
      // CSV source button before importing; after a successful import the
      // Guide is stale context. Skipped for opts.preserveState (column-remap
      // re-parses) — those must leave the user's current section alone.
      try { _closeGuidePanel(); } catch (e) {}
      try { if (typeof setSection === 'function') setSection('global'); } catch (e) {}
      // Belt-and-braces: ensure widgets reflect the new trade set. injectParsedTrades
      // already triggers a render, but a trailing call guarantees the CONTEXT strip
      // counter + chip badges reconcile with the freshly loaded trades.
      if (typeof render === 'function') { try { render(); } catch (e) {} }
    }
  } catch (err) {
    csvStatus('⚠ Parse error: ' + err.message, 'err');
  }
}

// ── Re-parse the cached CSV text after a column-override change.
// Preserves filter state, layout, and data-source indicator so remapping
// feels in-place rather than a fresh import. ──
function _reparseCsvWithOverrides() {
  if (!_lastCsvRawText) return false;
  const savedState = _saveFilterState();
  processCsvText(_lastCsvRawText, _lastCsvFilename, { preserveState: true, savedState });
  return true;
}

// ── CSV validation helpers ──
// Returns labels of every required column whose index is -1
function _checkMissingCols(required) {
  return required.filter(c => c.index === -1).map(c => c.label);
}
// Formats a multi-line error message listing each missing column
function _missingColsError(missing, formatName) {
  return `⚠ Missing required columns (${formatName}):\n` +
    missing.map(m => '  • ' + m).join('\n');
}

// ── Flipping Market M15 parser (journal principal + export Notion) ──
// TODO(Phase 3): detect optional beManagement column (currently API-only).
function parseFlippingMarketCSV(text) {
  const raw   = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const lines = raw.split('\n').filter(l=>l.trim());
  if (lines.length<2) return {ok:false,error:'\u26a0 Empty file'};
  const headers = splitCsvLine(lines[0],',').map(h=>h.trim().replace(/^["']|["']$/g,''));

  const iDate       = _colFirst(headers,'date');
  const iPair       = _colAny(headers,'pair','actif');   // journal = 'Pair', ancien = 'Actif'
  const iSetup      = _colForDim(headers,'setup','m15 type');
  const iSetupDetail= _colAny(headers,'m15 type détail','m15 type detail','m15 type détails','m15 type details','m15 type d\xe9tail','m15 type d\xe9tails');
  const iSession    = _colForDim(headers,'session','session');
  const iJour       = _colForDim(headers,'day','jour');
  const iResultat   = _colAny(headers,'résultat tp 1','resultat tp 1');
  const iRR         = _colFirst(headers,'rr tp 1');
  const iRRMax      = _colAny(headers,'rr max','rr max ','rr max atteint','rr max atteint ');
  // Multi TP (Phase 3): override-only, no format default. null when not mapped or empty.
  const iTp1Rr      = _colForDim(headers,'tp1_rr');
  const iTp2Rr      = _colForDim(headers,'tp2_rr');
  const iTp3Rr      = _colForDim(headers,'tp3_rr');
  const iObsM15     = _colForDim(headers,'obstacles','obstacles m15');
  const iObsH4      = _colForDim(headers,'h4','obstacles h4');
  const iType       = _colFirst(headers,'type de trade');
  const iBadFeeling = _colFirst(headers,'bad feeling');
  const iOrdre      = _colAny(headers,'ordre','order');  // journal = 'Order', ancien = 'Ordre'
  const iNotionUrl  = _colForDim(headers, 'notionUrl', 'notion url', 'url notion', 'page url', 'notion', 'url');
  const iHour       = _hourColForDim(headers);
  // Screenshot/image columns: Notion "M15 Before" / "H4 Before" / "M15 After" —
  // either a Files property exported as plain URL, or a simple URL property
  // (TV share link). All 3 are user-remappable via the Mapping panel under
  // dim keys img_m15 / img_h4_before / img_m15_after; defaults preserve the
  // legacy auto-detection for unmapped CSVs.
  const iImgM15     = (() => {
    const override = _csvColumnOverrides && _csvColumnOverrides.img_m15;
    if (override != null && override !== '') {
      const idx = _colFirst(headers, override);
      if (idx >= 0) return idx;
    }
    // Prefer explicit screenshot column names, including 'TV M15 Before' (TV-URL
    // convention), then fall back to standalone 'M15' / 'M15 Before' header.
    const named = _colAny(headers,'tv m15 before','screenshot m15','m15 screenshot','image m15','m15 image','photo m15','m15 photo','m15 before');
    if (named >= 0) return named;
    // Exact standalone 'M15' or 'M15 Before' header (must not already be claimed by m15 type columns)
    const idx = headers.findIndex(h => { const v = h.trim().toLowerCase(); return v === 'm15' || v === 'm15 before'; });
    return (idx >= 0 && idx !== iSetup && idx !== iSetupDetail) ? idx : -1;
  })();
  const iImgH4Before = _colForDim(headers, 'img_h4_before', 'tv h4 before', 'h4 before', 'h4before', 'screenshot h4', 'h4 screenshot', 'image h4', 'h4 image');
  const iImgM15After = _colForDim(headers, 'img_m15_after', 'tv m15 after', 'm15 after', 'm15after', 'm15 after screenshot', 'screenshot m15 after');

  const missing = _checkMissingCols([
    { label: 'Résultat TP 1', index: iResultat },
    { label: 'RR TP 1',       index: iRR },
    { label: 'Date',           index: iDate },
  ]);
  if (missing.length) return { ok: false, error: _missingColsError(missing, 'Flipping Market M15') };

  const trades = [], warnings = [];
  let skippedOutcome = 0, skippedDate = 0;

  for (let i=1;i<lines.length;i++) {
    const line=lines[i].trim(); if(!line) continue;
    const cols=splitCsvLine(line,',');
    const get=idx=>(idx<0||idx>=cols.length)?'':cols[idx].trim().replace(/^["']|["']$/g,'');

    const typeRaw = get(iType) || '';
    const typeVal = typeRaw.toLowerCase();
    const isInvalide = typeVal.includes('invalide');
    const isBad      = _isBadFeeling(get(iBadFeeling));

    const outcome=_mapOutcome(get(iResultat));
    if (!outcome) { skippedOutcome++; continue; }

    const date=_parseDate(get(iDate));
    if (!date||date.length<7) { skippedDate++; continue; }

    trades.push({
      date, month:date.slice(0,7),
      pair:        get(iPair)|| '',
      setup:       get(iSetup)||'',
      setupDetail: get(iSetupDetail)||'',
      session:     _normSession(get(iSession)),
      day:         get(iJour)||'',             // already French in journal
      obstacles:   _parseObs(get(iObsM15)),
      h4:          _parseObs(get(iObsH4)),
      outcome,
      r:           _mapR(outcome, get(iRR)),
      rrMax:       iRRMax >= 0 ? _parseNumeric(get(iRRMax)) : null,
      tp1_rr:      iTp1Rr >= 0 ? _parseNumeric(get(iTp1Rr)) : null,
      tp2_rr:      iTp2Rr >= 0 ? _parseNumeric(get(iTp2Rr)) : null,
      tp3_rr:      iTp3Rr >= 0 ? _parseNumeric(get(iTp3Rr)) : null,
      direction:   get(iOrdre)||'',
      tradeType:   typeRaw ? typeRaw.split(',').map(s => s.trim()).filter(Boolean) : [],
      badFeeling:  isBad,
      invalide:    isInvalide,
      hour:        iHour >= 0 ? _parseHourValue(get(iHour)) : null,
      // Route image cells through _normalizeTvImageUrl: TV /x/<ID>/ share URLs
      // are rewritten to the deterministic S3 PNG path; anything else (Notion
      // signed S3, direct image URLs, custom hosts) passes through untouched.
      // The *Orig pair stores the original TV page URL (or '') for lightbox
      // fallback when the snapshot PNG 404s.
      ...(() => {
        const a = _normalizeTvImageUrl(iImgM15     >= 0 ? get(iImgM15)     : '');
        const b = _normalizeTvImageUrl(iImgH4Before >= 0 ? get(iImgH4Before) : '');
        const c = _normalizeTvImageUrl(iImgM15After >= 0 ? get(iImgM15After) : '');
        return {
          imgM15:      a.url, imgM15Orig:      a.origLink,
          imgH4Before: b.url, imgH4BeforeOrig: b.origLink,
          imgM15After: c.url, imgM15AfterOrig: c.origLink,
        };
      })(),
      notionUrl:   iNotionUrl  >= 0 ? get(iNotionUrl)  : '',
      extras:      _collectCustomExtrasFromCSV(headers, get),
      _rawRowIndex: i - 1,
    });
  }

  if (skippedOutcome > 0) warnings.push(`${skippedOutcome} row${skippedOutcome > 1 ? 's' : ''} skipped: unrecognized outcome value`);
  if (skippedDate > 0)    warnings.push(`${skippedDate} row${skippedDate > 1 ? 's' : ''} skipped: missing or invalid date`);
  if (!trades.length) return { ok: false, error: '⚠ No valid trades found in file' };
  return { ok: true, trades, warnings };
}


// ── Pro Template parser ──
// TODO(Phase 3): detect optional beManagement column (currently API-only).
function parseProTemplateCSV(text) {
  const raw   = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const lines = raw.split('\n').filter(l=>l.trim());
  if (lines.length<2) return {ok:false,error:'\u26a0 Empty file'};
  const headers=splitCsvLine(lines[0],',').map(h=>h.trim().replace(/^["']|["']$/g,''));
  const iPair   =_colLast(headers,'pair');      // last occurrence = full pair name
  const iResult =_colFirst(headers,'position result');
  const iType   =_colFirst(headers,'position type');
  const iDate   =_colFirst(headers,'date');
  const iRR     =_colFirst(headers,'rr tp 1');
  const iRRMax  =_colAny(headers,'rr max','rr max ','rr max atteint','rr max atteint ');
  // Multi TP (Phase 3): override-only, no format default. null when not mapped or empty.
  const iTp1Rr  =_colForDim(headers,'tp1_rr');
  const iTp2Rr  =_colForDim(headers,'tp2_rr');
  const iTp3Rr  =_colForDim(headers,'tp3_rr');
  const iSetup  =_colForDim(headers,'setup','m15 confirmation / continu');
  const iSess   =_colForDim(headers,'session','session');
  const iDay    =_colForDim(headers,'day','day');
  const iObsM15 =_colForDim(headers,'obstacles','m15 obstacles');
  const iObsH4  =_colForDim(headers,'h4','h4 obstacles');
  const iBad    =_colFirst(headers,'bad feeling');
  const iOrder  =_colFirst(headers,'order');
  const iNotionUrl=_colForDim(headers, 'notionUrl', 'notion url', 'url notion', 'page url', 'notion', 'url');
  const iHour   = _hourColForDim(headers);
  // Screenshot/image columns: remappable via Mapping panel. Explicit aliases only —
  // unlike Flipping Market we do NOT fall back to a standalone 'M15' header,
  // because Pro Template exports commonly include a Notion Files column named
  // 'M15' whose cells are filenames (e.g. "Capture_decran_....png") rather than
  // URLs — picking it would produce broken <img> links.
  const iImgM15     = _colForDim(headers, 'img_m15', 'tv m15 before', 'm15 before', 'screenshot m15', 'm15 screenshot', 'image m15', 'm15 image', 'photo m15', 'm15 photo');
  const iImgH4Before= _colForDim(headers, 'img_h4_before', 'tv h4 before', 'h4 before', 'h4before', 'screenshot h4', 'h4 screenshot', 'image h4', 'h4 image');
  const iImgM15After= _colForDim(headers, 'img_m15_after', 'tv m15 after', 'm15 after', 'm15after', 'm15 after screenshot', 'screenshot m15 after');
  const missing = _checkMissingCols([
    { label: 'Position Result', index: iResult },
    { label: 'RR TP 1',         index: iRR },
    { label: 'Date',             index: iDate },
  ]);
  if (missing.length) return { ok: false, error: _missingColsError(missing, 'Pro Template') };

  const trades = [], warnings = [];
  let skippedOutcome = 0, skippedDate = 0;
  for (let i=1;i<lines.length;i++) {
    const cols=splitCsvLine(lines[i],',');
    const get=idx=>(idx<0||idx>=cols.length)?'':cols[idx].trim().replace(/^["']|["']$/g,'');
    const isInvalide = iType>=0 && get(iType).toLowerCase()==='invalid';
    const outcome=_mapOutcome(get(iResult));
    if (!outcome) { skippedOutcome++; continue; }
    const date=_parseDate(get(iDate));
    if (!date||date.length<7) { skippedDate++; continue; }
    trades.push({
      date,month:date.slice(0,7),
      pair:     get(iPair).trim()|| '',
      setup:    get(iSetup),
      session:  _normSession(get(iSess)),
      day:      _normDay(get(iDay)),
      obstacles:_parseObs(get(iObsM15)),
      h4:       _parseObs(get(iObsH4)),
      outcome,  r:_mapR(outcome,get(iRR)), rrMax: iRRMax >= 0 ? _parseNumeric(get(iRRMax)) : null, direction:get(iOrder),
      tp1_rr: iTp1Rr >= 0 ? _parseNumeric(get(iTp1Rr)) : null,
      tp2_rr: iTp2Rr >= 0 ? _parseNumeric(get(iTp2Rr)) : null,
      tp3_rr: iTp3Rr >= 0 ? _parseNumeric(get(iTp3Rr)) : null,
      badFeeling: _isBadFeeling(get(iBad)),
      invalide:   isInvalide,
      hour:       iHour >= 0 ? _parseHourValue(get(iHour)) : null,
      notionUrl:  iNotionUrl >= 0 ? get(iNotionUrl) : '',
      // TV-share URL normalization: see parser comment above _TV_SHARE_RE.
      ...(() => {
        const a = _normalizeTvImageUrl(iImgM15     >= 0 ? get(iImgM15)     : '');
        const b = _normalizeTvImageUrl(iImgH4Before >= 0 ? get(iImgH4Before) : '');
        const c = _normalizeTvImageUrl(iImgM15After >= 0 ? get(iImgM15After) : '');
        return {
          imgM15:      a.url, imgM15Orig:      a.origLink,
          imgH4Before: b.url, imgH4BeforeOrig: b.origLink,
          imgM15After: c.url, imgM15AfterOrig: c.origLink,
        };
      })(),
      extras:     _collectCustomExtrasFromCSV(headers, get),
      _rawRowIndex: i - 1,
    });
  }
  if (skippedOutcome > 0) warnings.push(`${skippedOutcome} row${skippedOutcome > 1 ? 's' : ''} skipped: unrecognized outcome value`);
  if (skippedDate > 0)    warnings.push(`${skippedDate} row${skippedDate > 1 ? 's' : ''} skipped: missing or invalid date`);
  if (!trades.length) return { ok: false, error: '⚠ No valid trades found in file' };
  return { ok: true, trades, warnings };
}



// ── Beginner parser ──
