const THEME_STORAGE_KEY  = 'flipping_dashboard_theme';
const BAR_COLOR_MODE_KEY  = 'flipping_bar_color_mode';

// 'quality' = threshold-based on avg R | 'binary' = positive/negative
let barColorMode = localStorage.getItem(BAR_COLOR_MODE_KEY) || 'quality';

// ── Bar hover tooltip (uses unified utip system) ──
function _buildBarTipHTML(label, n, oc) {
  const [tpN, tpR, slN, slR, betpN, betpR, beslN, beslR] = oc.split(',').map(Number);
  const wr = n > 0 ? ((tpN + betpN) / n * 100).toFixed(0) : 0;
  const fmt = v => (v >= 0 ? '+' : '') + v.toFixed(2) + 'R';
  const beRows = `
      <span style="color:#2962ff">BE-TP</span><span style="color:#2962ff;text-align:right">×${betpN}</span><span style="color:#2962ff;text-align:right">${fmt(betpR)}</span>
      <span style="color:#b478f0">BE-SL</span><span style="color:#b478f0;text-align:right">×${beslN}</span><span style="color:#b478f0;text-align:right">${fmt(beslR)}</span>`;
  return `
    <div class="utip-header">${label} <span class="utip-header-sub">×${n}</span></div>
    <div class="utip-grid">
      <span style="color:var(--g)">TP</span><span style="color:var(--g);text-align:right">×${tpN}</span><span style="color:var(--g);text-align:right">${fmt(tpR)}</span>
      <span style="color:var(--r)">SL</span><span style="color:var(--r);text-align:right">×${slN}</span><span style="color:var(--r);text-align:right">${fmt(slR)}</span>
      ${beRows}
    </div>
    <div class="utip-divider"></div>
    <div class="utip-row">
      <span class="utip-label">Win Rate</span>
      <span style="color:${+wr >= 50 ? 'var(--g)' : 'var(--r)'};font-weight:700">${wr}%</span>
    </div>
    ${(() => {
      if (!showBE) {
        const net = tpR + slR;
        return `<div class="utip-row">
      <span class="utip-label">Net Result</span>
      <span style="color:${net >= 0 ? 'var(--g)' : 'var(--r)'};font-weight:700">${fmt(net)}</span>
    </div>`;
      } else {
        const netTP  = tpR + betpR;
        const netSL  = slR + beslR;
        const total  = netTP + netSL;
        return `<div class="utip-row">
      <span class="utip-label">Net TP</span>
      <span style="color:${netTP >= 0 ? 'var(--g)' : 'var(--r)'}">${fmt(netTP)}</span>
    </div>
    <div class="utip-row">
      <span class="utip-label">Net SL</span>
      <span style="color:${netSL >= 0 ? 'var(--g)' : 'var(--r)'}">${fmt(netSL)}</span>
    </div>
    <div class="utip-row">
      <span class="utip-label">Total Net</span>
      <span style="color:${total >= 0 ? 'var(--g)' : 'var(--r)'};font-weight:700">${fmt(total)}</span>
    </div>`;
      }
    })()}`;
}
function _showBarTip(e) {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  const oc = row.dataset.barOc;
  if (!oc) return;
  showUtip(e, _buildBarTipHTML(row.dataset.barLabel || '—', parseInt(row.dataset.barN) || 0, oc));
}
function _hideBarTip() { hideUtip(); }

// Global delegated listeners for bar hover tooltip
document.addEventListener('mouseover', e => {
  // Always-on tooltip for obstacle bars
  if (e.target.closest?.('.tip-always')) { _showBarTip(e); return; }
  // Tooltip for regular bar rows
  if (!e.target.closest?.('.bar-list')) return;
  _showBarTip(e);
});
document.addEventListener('mousemove', e => {
  if (_utip && _utip.classList.contains('visible')) _posUtip(e.clientX, e.clientY);
});
document.addEventListener('mouseout', e => {
  if (!_utip || !_utip.classList.contains('visible')) return;
  const fromAlways = e.target.closest?.('.tip-always');
  const fromHover  = e.target.closest?.('.bar-list');
  if (fromAlways && !e.relatedTarget?.closest?.('.tip-always')) { hideUtip(); return; }
  if (fromHover  && !e.relatedTarget?.closest?.('.bar-list')) hideUtip();
});

// ── Delegated click handler: opens shared drawer on bar-row click ──
document.addEventListener('click', e => {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  // Find the container (direct parent must have an ID like 'bars-*')
  const list = row.parentElement;
  if (!list || !list.id) return;
  _openDrawerFromBarRow(list.id, row);
});

/* Filter currently-visible trades to those matching the clicked bar and open the drawer */
function _openDrawerFromBarRow(containerId, row) {
  const rawKey = row.dataset.barRawkey || row.dataset.barLabel;
  if (!rawKey) return;
  const label    = row.dataset.barLabel || rawKey;
  const filtered = getFiltered();
  let trades;
  switch (containerId) {
    case 'bars-setup':
      // Respect setupDetailMode: raw key is the actual grouped value
      trades = filtered.filter(t => (setupDetailMode ? (t.setupDetail||t.setup) : t.setup) === rawKey);
      break;
    case 'bars-session':
      trades = filtered.filter(t => t.session === rawKey);
      break;
    case 'bars-pair':
      trades = filtered.filter(t => t.pair === rawKey);
      break;
    case 'bars-day':
      trades = filtered.filter(t => t.day === rawKey);
      break;
    case 'bars-obs':
      trades = filtered.filter(t => Array.isArray(t.obstacles) && t.obstacles.includes(rawKey));
      break;
    case 'bars-h4obs':
      trades = filtered.filter(t => Array.isArray(t.h4) && t.h4.includes(rawKey));
      break;
    case 'bars-hour': {
      const h = parseInt(rawKey, 10);
      trades = isNaN(h) ? [] : filtered.filter(t => t.hour === h);
      break;
    }
    default:
      return;
  }
  if (!trades || !trades.length) return;

  // Highlight the clicked bar-row with a gold border
  document.querySelectorAll('.bar-row.lb-active').forEach(r => r.classList.remove('lb-active'));
  row.classList.add('lb-active');

  openWidgetDrawer(label, null, trades);
}

// ── Right-click context menu on bar charts: Include / Exclude ──
// Maps container IDs to chip filter keys (sidebar filters, NOT preset additional filters)
const _BAR_CONTAINER_TO_CHIP = {
  'bars-setup': 'setup', 'bars-session': 'session', 'bars-pair': 'pair',
  'bars-day': 'day', 'bars-obs': 'obstacles', 'bars-h4obs': 'h4obs',
  'bars-hour': 'hour',
};

document.addEventListener('contextmenu', e => {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  const list = row.parentElement;
  if (!list || !list.id) return;
  const chipKey = _BAR_CONTAINER_TO_CHIP[list.id];
  if (!chipKey) return;
  const rawKey = row.dataset.barRawkey || row.dataset.barLabel;
  if (!rawKey) return;
  e.preventDefault();
  _showBarContextMenu(chipKey, rawKey, row.dataset.barLabel || rawKey, e);
});

function _showBarContextMenu(chipKey, rawKey, displayLabel, event) {
  _closeBarContextMenu();
  const entry = appState.filters.chips[chipKey];
  if (!entry) return;

  const isIncluded = entry.included.has(rawKey);
  const isExcluded = entry.excluded.has(rawKey);

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  menu.innerHTML = `
    <div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(displayLabel)}</div>
    <div class="layout-slot-menu-sep"></div>
    <button class="layout-slot-menu-item bcm-include${isIncluded ? ' bcm-active' : ''}" type="button" data-act="include">
      <span class="lsm-icon">＋</span><span>${isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>
    <button class="layout-slot-menu-item bcm-exclude${isExcluded ? ' bcm-active' : ''}" type="button" data-act="exclude">
      <span class="lsm-icon">−</span><span>${isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>
  `;
  document.body.appendChild(menu);

  // Position near the click
  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    _closeBarContextMenu();
    invalidateFilterCache();

    if (act === 'include') {
      if (isIncluded) {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
      } else {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
        entry.included.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'include';
      }
    } else if (act === 'exclude') {
      if (isExcluded) {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
      } else {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
        entry.excluded.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'exclude';
      }
    }
    _syncChipModeButtons(chipKey);
    // Phase 3 : bar context menu mute un chip live → sync slot preset actif.
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  // Close on outside click / Escape
  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

function _closeBarContextMenu() {
  document.getElementById('bar-ctx-menu')?.remove();
}

// Cell-combo context menu for heatmaps (Pair × Session, Session × Day).
// comboType: 'sessionDay' | 'pairSession'. comboKey: "A|B" string.
function _showCellComboContextMenu(comboType, comboKey, cellLabel, event) {
  _closeBarContextMenu();
  const entry = appState.filters.comboFilters?.[comboType];
  if (!entry) return;

  const isIncluded = entry.included.has(comboKey);
  const isExcluded = entry.excluded.has(comboKey);

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  menu.innerHTML = `
    <div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(cellLabel)}</div>
    <div class="layout-slot-menu-sep"></div>
    <button class="layout-slot-menu-item bcm-include${isIncluded ? ' bcm-active' : ''}" type="button" data-act="include">
      <span class="lsm-icon">＋</span><span>${isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>
    <button class="layout-slot-menu-item bcm-exclude${isExcluded ? ' bcm-active' : ''}" type="button" data-act="exclude">
      <span class="lsm-icon">−</span><span>${isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>
  `;
  document.body.appendChild(menu);

  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    _closeBarContextMenu();
    invalidateFilterCache();
    if (act === 'include') {
      if (isIncluded) entry.included.delete(comboKey);
      else { entry.excluded.delete(comboKey); entry.included.add(comboKey); }
    } else if (act === 'exclude') {
      if (isExcluded) entry.excluded.delete(comboKey);
      else { entry.included.delete(comboKey); entry.excluded.add(comboKey); }
    }
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

// Multi-dimension version used by heatmap cells (Pair × Session, Session × Day).
// `dims` = array of { chipKey, rawKey, displayLabel, dimLabel }
function _showHeatmapContextMenu(dims, cellLabel, event) {
  _closeBarContextMenu();
  if (!dims || !dims.length) return;

  // _resolveChipEntry routes 'custom:<key>' chipKeys to appState.filters.customChips
  // while leaving native chip keys on appState.filters.chips — enables future
  // Phase 2 widgets grouped by a custom prop to invoke this menu transparently.
  const dimStates = dims.map(d => {
    const entry = _resolveChipEntry(d.chipKey);
    return entry ? {
      ...d,
      entry,
      isIncluded: entry.included.has(d.rawKey),
      isExcluded: entry.excluded.has(d.rawKey),
    } : null;
  }).filter(Boolean);
  if (!dimStates.length) return;

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  let html = `<div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(cellLabel)}</div>`;
  dimStates.forEach((ds, i) => {
    html += '<div class="layout-slot-menu-sep"></div>';
    html += `<div style="padding:3px 12px 2px;font-size:9px;color:var(--mute)">${_escapeHtml(ds.dimLabel || ds.chipKey)}: ${_escapeHtml(ds.displayLabel)}</div>`;
    html += `<button class="layout-slot-menu-item bcm-include${ds.isIncluded ? ' bcm-active' : ''}" type="button" data-dim="${i}" data-act="include">
      <span class="lsm-icon">＋</span><span>${ds.isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>`;
    html += `<button class="layout-slot-menu-item bcm-exclude${ds.isExcluded ? ' bcm-active' : ''}" type="button" data-dim="${i}" data-act="exclude">
      <span class="lsm-icon">−</span><span>${ds.isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>`;
  });
  menu.innerHTML = html;
  document.body.appendChild(menu);

  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    const di = parseInt(btn.dataset.dim, 10);
    const ds = dimStates[di];
    if (!ds) return;
    _closeBarContextMenu();
    invalidateFilterCache();
    const { entry, rawKey, isIncluded, isExcluded } = ds;
    if (act === 'include') {
      if (isIncluded) { entry.included.delete(rawKey); entry.includedFromPreset?.delete(rawKey); }
      else {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
        entry.included.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'include';
      }
    } else if (act === 'exclude') {
      if (isExcluded) { entry.excluded.delete(rawKey); entry.excludedFromPreset?.delete(rawKey); }
      else {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
        entry.excluded.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'exclude';
      }
    }
    _syncChipModeButtons(ds.chipKey);
    // Phase 3 : multi-dim context menu mute un chip live → sync slot actif.
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

function _initBarModeUI() {
  document.getElementById('bmt-total')?.classList.toggle('active', barMode === 'total');
  document.getElementById('bmt-ev')   ?.classList.toggle('active', barMode === 'ev');
  document.getElementById('bmt-wr')   ?.classList.toggle('active', barMode === 'wr');
  document.getElementById('mob-bmt-total')?.classList.toggle('active', barMode === 'total');
  document.getElementById('mob-bmt-ev')   ?.classList.toggle('active', barMode === 'ev');
}

function _initBarViewUI() {
  document.getElementById('bvt-global')?.classList.toggle('active', barView === 'global');
  document.getElementById('bvt-split') ?.classList.toggle('active', barView === 'split');
  document.getElementById('mob-bvt-global')?.classList.toggle('active', barView === 'global');
  document.getElementById('mob-bvt-split') ?.classList.toggle('active', barView === 'split');
}

function setBarColorMode(mode) {
  barColorMode = mode;
  localStorage.setItem(BAR_COLOR_MODE_KEY, mode);
  // Update radio UI
  document.querySelectorAll('input[name="barColorMode"]').forEach(r => {
    r.checked = (r.value === mode);
  });
  // Re-render all bar charts
  const filtered = getFiltered();
  const absMax = 1.8;
  renderBars('bars-setup',   groupByEV(filtered, t => setupDetailMode ? (t.setupDetail||t.setup) : t.setup, k => setupDetailMode ? k : (SETUP_SHORT[k]||k)), absMax, false, 'setup');
  renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session');
  renderBars('bars-pair',    groupByEV(filtered, t => t.pair),   absMax, false, 'pair');
  renderDayBars(filtered);
  renderObsBars(filtered);
  renderH4ObsBars(filtered);
  renderHourBars(filtered);
  if (_isMobile()) {
    drawMobilePair(filtered);
    drawMobileSetup(filtered);
    drawMobileObs(filtered);
    drawMobileMonthly2(filtered);
  }
}

function _initBarColorModeUI() {
  document.querySelectorAll('input[name="barColorMode"]').forEach(r => {
    r.checked = (r.value === barColorMode);
  });
}

